def fmt_bdt_precise(bdt_amount):
    """✅ BDT amount কে পয়সা-precision সহ (কোনো rounding/truncation ছাড়া) স্ট্রিং
    হিসেবে ফেরত দেয়। পূর্ণ সংখ্যা হলে দশমিক ছাড়া (যেমন 1259), আর পয়সা থাকলে
    ঠিক ২ ঘর দশমিক সহ (যেমন 1259.50) দেখায় — int() দিয়ে truncate করলে
    যেভাবে পয়সার অংশ হারিয়ে যেত, সেটা এড়াতে এই হেল্পার ব্যবহার করা হয়।"""
    try:
        val = round(float(bdt_amount), 2)
    except (TypeError, ValueError):
        return str(bdt_amount)
    if val == int(val):
        return str(int(val))
    return f"{val:.2f}"

def bdt_to_usd_str(bdt_amount):
    """
    ✅ Multiple Currency Display: BDT amount কে USD এ কনভার্ট করে
    "$X.XX" স্ট্রিং হিসেবে ফেরত দেয়। admin-সেট USD→BDT rate (get_usd_bdt_rate)
    ব্যবহার করে হিসাব করা হয় (এখনো Binance deposit এর জন্য ব্যবহৃত একই রেট)।
    """
    try:
        usd = float(bdt_amount) / get_usd_bdt_rate()
        return f"${usd:.2f}"
    except (TypeError, ValueError, ZeroDivisionError):
        return "$0.00"

def with_usd_equiv(user_id, bdt_amount):
    """
    ✅ শুধু non-Bangla (international/en) ইউজারদের জন্য BDT এর পাশে
    "(≈ $X.XX)" USD equivalent যোগ করে। বাংলা ইউজারদের জন্য খালি
    স্ট্রিং রিটার্ন করে, যাতে বার্তা আগের মতোই থাকে।
    """
    try:
        lang_u = _lang_cache.get(str(user_id), "en")
    except Exception:
        lang_u = "en"
    if lang_u == "bn":
        return ""
    return f" (≈ {bdt_to_usd_str(bdt_amount)})"

