        v = st.get("developer_username")
        if v:
            DEVELOPER_USERNAME = str(v)
        v = st.get("livechat_username")
        if v:
            LIVECHAT_USERNAME = str(v)
        v = st.get("binance_id")
        if v:
            BINANCE_ID = str(v)
        v = st.get("binance_pay_uid")
