    try:
        if db is None:
            db = load_db()
        v = (db.get("settings", {}) or {}).get("maintenance_mode", False)
        if isinstance(v, str):
            return v.strip().lower() in ("1", "true", "on", "yes")
        return bool(v)
    except Exception:
        return False  # DB সমস্যা হলে বট বন্ধ করে দিও না (fail-open)

