#    Admin price সেট না করা পর্যন্ত ইউজার এগুলো দেখে না। নাম/MB/Price সবই admin বদলাতে পারে।
NINEPROXY_DEFAULT_PACKAGES = [
    {"name": "20MB",  "mb": 20,   "price": 0},
    {"name": "50MB",  "mb": 50,   "price": 0},
    {"name": "100MB", "mb": 100,  "price": 0},
    {"name": "200MB", "mb": 200,  "price": 0},
    {"name": "500MB", "mb": 500,  "price": 0},
    {"name": "1GB",   "mb": 1024, "price": 0},
    {"name": "2GB",   "mb": 2048, "price": 0},
]

def get_nineproxy_api_packages(db=None):
    """Admin-সেট করা 9Proxy API প্যাকেজ লিস্ট — প্রতিটা {"name","mb","price"}।
    লিস্ট ফাঁকা ও আগে কখনো ডিফল্ট বসানো না হলে ৭টা ডিফল্ট প্যাকেজ বসে যায়।"""
    if db is None:
        db = load_db()
    packages = list(db.get("nineproxy_api_packages") or [])
    if not packages and not (db.get("settings", {}) or {}).get("nineproxy_api_defaults_seeded"):
        packages = [dict(p) for p in NINEPROXY_DEFAULT_PACKAGES]
        try:
            db["nineproxy_api_packages"] = packages
            db.setdefault("settings", {})["nineproxy_api_defaults_seeded"] = True
            update_db_path("/nineproxy_api_packages", packages)
            update_db_path("/settings/nineproxy_api_defaults_seeded", True)
        except Exception as e:
            logging.error(f"nineproxy default packages seed error: {e}")
    return packages


def save_nineproxy_api_packages(packages):
    db = load_db()
    db["nineproxy_api_packages"] = packages
    update_db_path("/nineproxy_api_packages", packages)
    _update_db_cache_in_place(db)


def get_nineproxy_gateway(db=None):
    """Admin panel থেকে সেট করা 9Proxy Gateway Host:Port — DB তে সেট করা থাকলে সেটাই
    ব্যবহার হবে, না থাকলে env var (NINEPROXY_GATEWAY_HOST/PORT) ফলব্যাক হিসেবে
    ব্যবহার হয়। রিটার্ন করে (host, port) — দুটোই string, না থাকলে খালি স্ট্রিং।"""
    if db is None:
        db = load_db()
    settings = db.get("settings", {})
    host = (settings.get("nineproxy_gateway_host") or NINEPROXY_GATEWAY_HOST or "").strip()
    port = (settings.get("nineproxy_gateway_port") or NINEPROXY_GATEWAY_PORT or "").strip()
    return host, port


def set_nineproxy_gateway(host, port):
    db = load_db()
    if "settings" not in db:
        db["settings"] = {}
    db["settings"]["nineproxy_gateway_host"] = (host or "").strip()
    db["settings"]["nineproxy_gateway_port"] = (port or "").strip()
    update_db_path("/settings/nineproxy_gateway_host", db["settings"]["nineproxy_gateway_host"])
    update_db_path("/settings/nineproxy_gateway_port", db["settings"]["nineproxy_gateway_port"])
    _update_db_cache_in_place(db)


# ⚠️ 9Proxy API HARD LIMIT: POST /client/v1/subs/create কে "amount_traffic"
# তে 1,000,000,000 bytes (= 1000MB, ~1GB) এর কমে কিছু পাঠালে ওরা নিজেরাই
# "Params validation failed: amount_traffic must be greater than or equal to
# 1000000000" error দেয় (সরাসরি live API response থেকে confirmed) — মানে
# প্রতিটা sub-account এ ন্যূনতম ১০০০MB (~1GB) traffic allocate করতেই হবে,
# 100mb/200mb/500mb এর মতো ছোট amount এই endpoint bypass করার কোনো উপায় নেই।
# তাই এখানে MB→bytes conversion 9Proxy এর নিজের unit (1 MB = 1,000,000 bytes,
# decimal) অনুযায়ী করা হচ্ছে — এই সংখ্যা থেকেই তাদের 1,000,000,000 = 1000×10^6
# limit টা মিলে যায়।
NINEPROXY_BYTES_PER_MB = 1_000_000
NINEPROXY_MIN_AMOUNT_TRAFFIC_BYTES = 1_000_000_000
NINEPROXY_MIN_MB = NINEPROXY_MIN_AMOUNT_TRAFFIC_BYTES // NINEPROXY_BYTES_PER_MB  # = 1000


def _nineproxy_api_err_detail(data, resp):
    """API error response থেকে message + (থাকলে) errors[] একসাথে জুড়ে একটা readable string বানায় —
    ডিফল্ট শুধু 'message' দেখালে অনেক সময় আসল কারণ (কোন field ভুল) বোঝা যায় না।"""
    msg = (data.get("message") or f"API error (status {resp.status_code})").strip()
    errs = data.get("errors")
    if errs:
        if isinstance(errs, (list, tuple)):
            extra = " | ".join(str(e) for e in errs if e)
        else:
            extra = str(errs)
        if extra:
            msg = f"{msg}: {extra}"
    return msg


def nineproxy_get_traffic_plans():
    """9Proxy account এ বর্তমানে থাকা bandwidth package/traffic plan গুলোর লিস্ট আনে
    (GET /client/v1/account/get-balance-data)। sub-account বানানোর সময় কোন প্যাকেজ
    থেকে bandwidth কাটা হবে তার জন্য একটা 'traffic_plan_id' পাঠানো বাধ্যতামূলক —
    9Proxy ড্যাশবোর্ডেও sub-account বানানোর সময় "Select the traffic package you
    want to deduct from" ধাপটা থাকে, API তেও একই নিয়ম কাজ করে।
    রিটার্ন করে (traffic_plan_list, error_message)।"""
    if not NINEPROXY_API_KEY:
        return [], "⚠️ 9Proxy API key এখনো এডমিন সেট করেননি।"
    try:
        resp = http_requests.get(
            f"{NINEPROXY_BASE_URL}/client/v1/account/get-balance-data",
            params={"api-key": NINEPROXY_API_KEY},
            timeout=20,
        )
        try:
            data = resp.json()
        except Exception:
            logging.warning(
                f"nineproxy_get_traffic_plans non-JSON response: "
                f"status={resp.status_code} body={resp.text[:300]}"
            )
            return [], "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"
        if not resp.ok or data.get("success") is False:
            return [], _nineproxy_api_err_detail(data, resp)
        traffic_data = ((data.get("result") or {}).get("traffic_data")) or []
        return traffic_data, None
    except http_requests.exceptions.Timeout:
        return [], "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"nineproxy_get_traffic_plans error: {e}")
        return [], str(e)


def nineproxy_create_subaccount(mb, note=""):
    """9Proxy Public API (POST /client/v1/subs/create) দিয়ে নতুন sub-account
    তৈরি করে — username 9Proxy নিজে জেনারেট করে, password বট নিজে বসিয়ে দেয়।
    ⚠️ FIX: শুধু amount_traffic পাঠালে 9Proxy API "Params validation failed"
    error দেয় — কারণ কোন bandwidth package (traffic_plan_id) থেকে এই MB
    কাটা হবে সেটাও পাঠাতে হয় (ড্যাশবোর্ডেও এই ধাপ বাধ্যতামূলক)। তাই এখানে
    আগে account এর active traffic plan গুলো (get-balance-data) চেক করে,
    যথেষ্ট bandwidth আছে এমন একটা প্যাকেজ বেছে নিয়ে সেই id দিয়ে create কল করা হয়।
    রিটার্ন করে (username, password, error_message)।"""
    if not NINEPROXY_API_KEY:
        return None, None, "⚠️ 9Proxy API key এখনো এডমিন সেট করেননি। এডমিনের সাথে যোগাযোগ করুন।"

    needed_bytes = int(round(float(mb) * NINEPROXY_BYTES_PER_MB))  # MB → bytes (9Proxy এর নিজের unit অনুযায়ী)

    # ⚠️ 9Proxy hard limit — এর নিচে API নিজেই reject করে দেয় (দেখুন উপরের কমেন্ট)
    if needed_bytes < NINEPROXY_MIN_AMOUNT_TRAFFIC_BYTES:
        return None, None, (
            f"⚠️ 9Proxy API তে প্রতি sub-account এ ন্যূনতম {NINEPROXY_MIN_MB}MB (~1GB) "
            f"traffic লাগে — এই প্যাকেজ ({mb}MB) এর থেকে কম। এডমিনকে জানিয়ে প্যাকেজের "
            f"MB কমপক্ষে {NINEPROXY_MIN_MB} করতে বলুন।"
        )

    plans, perr = nineproxy_get_traffic_plans()
    if perr:
        return None, None, f"Traffic plan তথ্য আনতে ব্যর্থ হয়েছে: {perr}"

    # status: 1 = available। যেই প্যাকেজে যথেষ্ট bandwidth বাকি আছে তার মধ্যে
    # সবচেয়ে কম amount ওয়ালাটা বেছে নাও, যাতে ছোট/প্রায়-শেষ প্যাকেজ গুলো আগে শেষ হয়ে যায়।
    usable = [
        p for p in plans
        if p.get("status") == 1 and int(p.get("amount") or 0) >= needed_bytes
    ]
    usable.sort(key=lambda p: int(p.get("amount") or 0))
    if not usable:
        return None, None, (
            "⚠️ এডমিনের 9Proxy একাউন্টে যথেষ্ট bandwidth সহ কোনো active traffic "
            "package পাওয়া যায়নি। এডমিনকে জানিয়ে নতুন প্যাকেজ কিনতে বলুন।"
        )
    plan_id = usable[0].get("id")

    # ✅ Username 9Proxy নিজে যেকোনো একটা জেনারেট করে দেয় (আমাদের হাতে নেই),
    # কিন্তু Password সবসময় একটাই ফিক্সড রাখা হচ্ছে — এডমিনের চাহিদা অনুযায়ী,
    # প্রতিটা sub-account এই একই password দিয়ে ডেলিভার হবে।
    # ⚠️ FIX: 9Proxy API এর নিজস্ব validation rule — password এ কমপক্ষে ১টা
    # letter ও ১টা number থাকতেই হবে। শুধু "virtualshop" (সব অক্ষর) এ এই
    # validation fail করে, তাই শেষে "1" যোগ করা হয়েছে।
    password = "virtualshop1"
    try:
        resp = http_requests.post(
            f"{NINEPROXY_BASE_URL}/client/v1/subs/create",
            params={"api-key": NINEPROXY_API_KEY},
            json={
                "password": password,
                "note": note or "Telegram Bot Order",
                "amount_traffic": needed_bytes,
                "traffic_plan_id": plan_id,
                "auto_add_traffic": 0,
            },
            timeout=30,
        )
        try:
            data = resp.json()
        except Exception:
            logging.warning(
                f"nineproxy_create_subaccount non-JSON response: "
                f"status={resp.status_code} body={resp.text[:300]}"
            )
            return None, None, "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"

        if not resp.ok or data.get("success") is False:
            logging.warning(f"nineproxy_create_subaccount failed: status={resp.status_code} body={data}")
            return None, None, _nineproxy_api_err_detail(data, resp)

        result = data.get("result") or {}
        username = result.get("username")
        if not username:
            return None, None, "9Proxy থেকে username পাওয়া যায়নি।"
        return username, password, None
    except http_requests.exceptions.Timeout:
        return None, None, "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"nineproxy_create_subaccount error: {e}")
        return None, None, str(e)


# ═══════════════════════════════════════════════════════════
# ⚡ 9PROXY — SUB-USER (User-Pass) CREATE — কাস্টমার নিজের ইচ্ছামতো
#    Username ও Password দিয়ে দেয়, বট শুধু 9Proxy এর
#    POST /client/v1/user-passes/create দিয়ে সেটা create করে।
# ✅ এই endpoint টা "/client/v1/subs/create" এর মতো ন্যূনতম ১০০০MB
#    বাধ্যতামূলক না (usage_cap বাইটে সরাসরি পাঠানো যায়) — তাই
#    100MB/200MB এর মতো ছোট প্যাকেজেও কাজ করে।
# ডকুমেন্টেশন: https://docs.9proxy.com/developers/public-api/api-for-user-pass
# ═══════════════════════════════════════════════════════════
def nineproxy_create_userpass(username, password, mb, note=""):
    """9Proxy Public API (POST /client/v1/user-passes/create) দিয়ে কাস্টমারের
    দেওয়া username+password নিয়ে নতুন sub-user (User-Pass) তৈরি করে।
    রিটার্ন করে (username, password, error_message)।"""
    if not NINEPROXY_API_KEY:
        return None, None, "⚠️ 9Proxy API key এখনো এডমিন সেট করেননি। এডমিনের সাথে যোগাযোগ করুন।"

    usage_cap_bytes = int(round(float(mb) * NINEPROXY_BYTES_PER_MB))  # MB → bytes (9Proxy এর নিজের unit অনুযায়ী)

    try:
        resp = http_requests.post(
            f"{NINEPROXY_BASE_URL}/client/v1/user-passes/create",
            params={"api-key": NINEPROXY_API_KEY},
            json={
                "user_name": username,
                "use_key": password,
                "status": 1,           # 1 = active
                "note": note or "Telegram Bot Order",
                "usage_cap": usage_cap_bytes,
                "ip_usage_cap": -1,    # -1 = unlimited IP
            },
            timeout=30,
        )
        try:
            data = resp.json()
        except Exception:
            logging.warning(
                f"nineproxy_create_userpass non-JSON response: "
                f"status={resp.status_code} body={resp.text[:300]}"
            )
            return None, None, "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"

        if not resp.ok or data.get("success") is False:
            logging.warning(f"nineproxy_create_userpass failed: status={resp.status_code} body={data}")
            return None, None, _nineproxy_api_err_detail(data, resp)

        result = data.get("result") or {}
        out_username = result.get("user_name") or username
        out_password = result.get("use_key") or password
        return out_username, out_password, None
    except http_requests.exceptions.Timeout:
        return None, None, "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"nineproxy_create_userpass error: {e}")
        return None, None, str(e)


# ═══════════════════════════════════════════════════════════
# ⚡ 711PROXY.COM ENTERPRISE API (EAPI) — SUB-ACCOUNT AUTO-DELIVERY
# ✅ 9Proxy এর মতোই — Admin panel থেকে API ON করলে "7️⃣ 711Proxy" বাটনে
#    ক্লিক করলে local stock এর বদলে admin-সেট করা প্যাকেজ (নাম+দাম) দেখাবে।
#    প্যাকেজে ক্লিক করলেই সাথে সাথে 711Proxy EAPI (POST /eapi/order/) দিয়ে
#    নতুন sub-account তৈরি হয়ে ডেলিভার হয়ে যাবে — কাস্টমারকে কোনো
#    username/password চাওয়া হয় না, 711Proxy নিজেই username/passwd/host/port
#    সবকিছু জেনারেট করে রেসপন্সে পাঠায় (9Proxy থেকে সহজ — আলাদা Gateway
#    Host/Port এডমিনকে বসাতে হয় না)।
# ⚠️ Bearer টোকেন: 711Proxy EAPI এর নিজস্ব "GET TOKEN" এন্ডপয়েন্ট দিয়ে
#    জেনারেট হওয়া Authorization টোকেন Admin Panel → 711Proxy API Settings →
#    🔑 Token সেট করুন থেকে বসাতে হবে (মেয়াদ শেষ হলে আবার নতুন করে বসাতে হবে)।
# ডকুমেন্টেশন রেফারেন্স (Apifox): xtp11ekplq.apifox.cn (EAPI → Create Order)
# ═══════════════════════════════════════════════════════════
P711PROXY_BASE_URL = os.environ.get('P711PROXY_BASE_URL', 'https://server.711proxy.com')
P711PROXY_BYTES_PER_MB = 1_000_000  # 711Proxy "flow" প্যারামিটার বাইটে (decimal MB, ঠিক 9Proxy এর মতোই)
P711PROXY_TOKEN_TTL_SECONDS = 12 * 3600  # ক্যাশ করা টোকেন ১২ ঘণ্টা পর নিজে থেকেই রিফ্রেশ হবে
import time as _p711_time


def is_p711proxy_api_enabled(db=None):
    """Admin panel থেকে 711Proxy sub-account API চালু আছে কিনা।"""
    if db is None:
        db = load_db()
    return bool(db.get("settings", {}).get("p711proxy_api_enabled", False))


def set_p711proxy_api_enabled(enabled: bool):
    db = load_db()
    if "settings" not in db:
        db["settings"] = {}
    db["settings"]["p711proxy_api_enabled"] = bool(enabled)
    update_db_path("/settings/p711proxy_api_enabled", bool(enabled))
    _update_db_cache_in_place(db)


def get_p711proxy_credentials(db=None):
    """Admin-সেট করা 711Proxy লগইন username/password — 'GET TOKEN' এন্ডপয়েন্টে
    পাঠানোর জন্য। এগুলো দিয়েই bot নিজে থেকে Bearer token জেনারেট করে, admin কে
    আলাদা করে কোনো টোকেন কপি-পেস্ট করতে হয় না।"""
    if db is None:
        db = load_db()
    settings = db.get("settings", {})
    username = (settings.get("p711proxy_username") or os.environ.get('P711PROXY_USERNAME', '') or "").strip()
    passwd = (settings.get("p711proxy_passwd") or os.environ.get('P711PROXY_PASSWD', '') or "").strip()
    return username, passwd


def set_p711proxy_credentials(username, passwd):
    db = load_db()
    if "settings" not in db:
        db["settings"] = {}
    db["settings"]["p711proxy_username"] = (username or "").strip()
    db["settings"]["p711proxy_passwd"] = (passwd or "").strip()
    # নতুন credentials সেট হলে আগের ক্যাশ করা টোকেন বাতিল করে দেওয়া হচ্ছে,
    # যাতে পরের অর্ডারেই নতুন credentials দিয়ে ফ্রেশ টোকেন আনা হয়।
    db["settings"]["p711proxy_token"] = ""
    db["settings"]["p711proxy_token_ts"] = 0
    update_db_path("/settings/p711proxy_username", db["settings"]["p711proxy_username"])
    update_db_path("/settings/p711proxy_passwd", db["settings"]["p711proxy_passwd"])
    update_db_path("/settings/p711proxy_token", "")
    update_db_path("/settings/p711proxy_token_ts", 0)
    _update_db_cache_in_place(db)


def _save_p711proxy_token_cache(token):
    db = load_db()
    if "settings" not in db:
        db["settings"] = {}
    db["settings"]["p711proxy_token"] = token
    db["settings"]["p711proxy_token_ts"] = _p711_time.time()
    update_db_path("/settings/p711proxy_token", token)
    update_db_path("/settings/p711proxy_token_ts", db["settings"]["p711proxy_token_ts"])
    _update_db_cache_in_place(db)


def p711proxy_fetch_new_token(username, passwd):
    """711Proxy EAPI 'GET TOKEN' এন্ডপয়েন্ট (POST /eapi/token/) দিয়ে সরাসরি
    username/password পাঠিয়ে নতুন Bearer token আনে। রিটার্ন করে
    (token, error_message)।"""
    if not username or not passwd:
        return None, "⚠️ 711Proxy username/password এখনো এডমিন সেট করেননি।"
    try:
        resp = http_requests.post(
            f"{P711PROXY_BASE_URL}/eapi/token/",
            headers={"Content-Type": "application/json"},
            json={"username": username, "passwd": passwd},
            timeout=20,
        )
        try:
            data = resp.json()
        except Exception:
            logging.warning(
                f"p711proxy_fetch_new_token non-JSON response: "
                f"status={resp.status_code} body={resp.text[:300]}"
            )
            return None, "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"

        results = data.get("results")
        token = None
        if isinstance(results, dict):
            token = results.get("token")
        elif isinstance(results, str) and results:
            token = results
        code = data.get("code")
        if not resp.ok or (code not in (0, 200, None)) or not token:
            msg = data.get("message") or data.get("msg") or data.get("error") or f"Token fetch failed (status {resp.status_code})"
            logging.warning(f"p711proxy_fetch_new_token failed: status={resp.status_code} body={data}")
            return None, str(msg).strip()
        return str(token).strip(), None
    except http_requests.exceptions.Timeout:
        return None, "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"p711proxy_fetch_new_token error: {e}")
        return None, str(e)


def get_p711proxy_token(db=None, force_refresh=False):
    """ক্যাশ করা টোকেন (TTL এর মধ্যে) থাকলে সেটাই রিটার্ন করে; না থাকলে, মেয়াদ
    শেষ হয়ে গেলে, বা force_refresh=True হলে — admin-সেট করা username/password
    দিয়ে 711Proxy 'GET TOKEN' এন্ডপয়েন্ট থেকে bot নিজে নতুন টোকেন এনে DB তে
    ক্যাশ করে রাখে। Admin কে ম্যানুয়ালি কিছু করতে হয় না।"""
    if db is None:
        db = load_db()
    settings = db.get("settings", {})
    cached_token = (settings.get("p711proxy_token") or "").strip()
    fetched_at = settings.get("p711proxy_token_ts") or 0
    age = _p711_time.time() - fetched_at

    if cached_token and not force_refresh and age < P711PROXY_TOKEN_TTL_SECONDS:
        return cached_token

    username, passwd = get_p711proxy_credentials(db)
    if not username or not passwd:
        # কোনো credentials সেট করা নেই — পুরোনো ক্যাশ করা টোকেন থাকলে সেটাই fallback
        return cached_token

    new_token, err = p711proxy_fetch_new_token(username, passwd)
    if new_token:
        _save_p711proxy_token_cache(new_token)
        return new_token

    logging.warning(f"get_p711proxy_token auto-refresh failed: {err}")
    return cached_token  # রিফ্রেশ ব্যর্থ হলে পুরোনো টোকেন থাকলে সেটাই ব্যবহার করার চেষ্টা


