def _p711proxy_api_err_detail(data, resp):
    """API error response থেকে readable error message বানায় (msg/error/code সব চেক করে)।"""
    msg = data.get("msg") or data.get("error") or f"API error (status {resp.status_code})"
    return str(msg).strip()


def p711proxy_get_balance(force_refresh_token=False):
    """711Proxy Enterprise EAPI (GET /eapi/balance/) দিয়ে EAPI Enterprise
    package-এর অবশিষ্ট flow (Bytes) চেক করে। এটা ওয়েবসাইট ড্যাশবোর্ডের
    "Residential Proxies-GB" balance থেকে আলাদা একটা pool হতে পারে — অর্ডার
    ফেইল হলে (যেমন "flow not enough") এখান থেকেই আসল কারণ বোঝা যাবে।
    রিটার্ন করে (flow_balance_bytes, error_message)।"""
    username_cred, passwd_cred = get_p711proxy_credentials()
    if not username_cred or not passwd_cred:
        return None, "⚠️ 711Proxy username/password এখনো এডমিন সেট করেননি।"

    token = get_p711proxy_token(force_refresh=force_refresh_token)
    if not token:
        return None, "⚠️ 711Proxy থেকে টোকেন আনা যায়নি (username/password ভুল হতে পারে)।"

    def _call(use_token):
        return http_requests.get(
            f"{P711PROXY_BASE_URL}/eapi/balance/",
            headers={"Authorization": f"Bearer {use_token}"},
            timeout=20,
        )

    try:
        resp = _call(token)
        try:
            data = resp.json()
        except Exception:
            return None, "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"

        err_text = str(data.get("msg") or data.get("error") or "").lower()
        looks_like_auth_issue = resp.status_code in (401, 403) or "token" in err_text or "auth" in err_text
        if looks_like_auth_issue and not force_refresh_token:
            return p711proxy_get_balance(force_refresh_token=True)

        code = data.get("code")
        if not resp.ok or code not in (0, 200, None) or data.get("flow_balance") is None:
            return None, _p711proxy_api_err_detail(data, resp)

        return int(data.get("flow_balance")), None
    except http_requests.exceptions.Timeout:
        return None, "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"p711proxy_get_balance error: {e}")
        return None, str(e)


def p711proxy_create_order(mb, host=None):
    """711Proxy Enterprise API (POST /eapi/order/) দিয়ে নতুন sub-account/order
    তৈরি করে — username, password, host, port সবকিছুই 711Proxy নিজে জেনারেট
    করে রেসপন্সে পাঠায় (কোনো কাস্টমার ইনপুট লাগে না)।
    রিটার্ন করে (result_dict, error_message) — result_dict এ থাকে:
    username, passwd, host, port, proto, order_no, un।"""
    username_cred, passwd_cred = get_p711proxy_credentials()
    token = get_p711proxy_token()
    if not username_cred or not passwd_cred:
        return None, "⚠️ 711Proxy API username/password এখনো এডমিন সেট করেননি। এডমিনের সাথে যোগাযোগ করুন।"
    if not token:
        return None, "⚠️ 711Proxy থেকে টোকেন আনা যায়নি (username/password ভুল হতে পারে)। এডমিনের সাথে যোগাযোগ করুন।"

    flow_bytes = int(round(float(mb) * P711PROXY_BYTES_PER_MB))
    body = {"flow": str(flow_bytes)}
    use_host = (host or get_p711proxy_host() or "").strip()
    if use_host:
        body["host"] = use_host

    def _call_order_api(use_token):
        return http_requests.post(
            f"{P711PROXY_BASE_URL}/eapi/order/",
            headers={
                "Authorization": f"Bearer {use_token}",
                "Content-Type": "application/json",
            },
            json=body,
            timeout=30,
        )

    try:
        resp = _call_order_api(token)
        try:
            data = resp.json()
        except Exception:
            data = {}

        # ✅ টোকেনের মেয়াদ শেষ হয়ে গেলে বা invalid হলে (401/403, বা error
        # মেসেজে "token" শব্দ থাকলে) — bot নিজে থেকেই নতুন টোকেন এনে ঠিক
        # একবার আবার চেষ্টা করে, admin কে কিছু করতে হয় না।
        err_text = str((data or {}).get("message") or (data or {}).get("msg") or (data or {}).get("error") or "").lower()
        looks_like_auth_issue = resp.status_code in (401, 403) or "token" in err_text or "auth" in err_text
        if looks_like_auth_issue:
            fresh_token = get_p711proxy_token(force_refresh=True)
            if fresh_token and fresh_token != token:
                resp = _call_order_api(fresh_token)
                try:
                    data = resp.json()
                except Exception:
                    logging.warning(
                        f"p711proxy_create_order non-JSON response after token refresh: "
                        f"status={resp.status_code} body={resp.text[:300]}"
                    )
                    return None, "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"

        code = data.get("code")
        # ✅ 711Proxy EAPI success convention: code 0/200 এবং error খালি/null,
        # সাথে username/passwd থাকতেই হবে — এর যেকোনোটা মিস হলে error ধরা হচ্ছে।
        if not resp.ok or data.get("error") or code not in (0, 200, None) or not data.get("username"):
            logging.warning(f"p711proxy_create_order failed: status={resp.status_code} body={data}")
            return None, _p711proxy_api_err_detail(data, resp)

        result_username = data.get("username")
        result_passwd = data.get("passwd")
        if not result_username or not result_passwd:
            return None, "711Proxy থেকে username/password পাওয়া যায়নি।"

        return {
            "username": result_username,
            "passwd": result_passwd,
            "host": data.get("host") or use_host,
            "port": data.get("port"),
            "proto": data.get("proto"),
            "order_no": data.get("order_no"),
            "un": data.get("un"),
        }, None
    except http_requests.exceptions.Timeout:
        return None, "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"p711proxy_create_order error: {e}")
        return None, str(e)


