def _realproxy_friendly_error(raw_err):
    """API থেকে আসা error key কে বাংলা মেসেজে রূপান্তর করে (না পেলে raw টাই রিটার্ন করে)।"""
    key = str(raw_err).strip().strip("'").upper() if raw_err else ""
    if key in REALPROXY_ERROR_MESSAGES:
        return REALPROXY_ERROR_MESSAGES[key]
    # অজানা/টেকনিক্যাল error (HTTP কোড, সাইট/API ডিটেইল) ইউজারকে দেখানো হয় না — শুধু লগে থাকে
    logging.warning(f"realproxy raw error hidden from user: {str(raw_err)[:300]}")
    return "সাময়িক সমস্যা হয়েছে, একটু পরে আবার চেষ্টা করুন।"

# JWT token in-memory cache — লগইন প্রতিবার না করে token রিইউজ করা হয়
# (token ৬০ মিনিটে expire হয়, expire_at এর ৫ মিনিট আগেই re-login করা হবে)
_realproxy_token_cache = {"token": None, "expire_at": 0}
_realproxy_lock = threading.Lock()

# 🆕 লগইন/নেটওয়ার্ক ফেইলিউর হলে আগে শুধু Railway log এ যেত, Admin কে টেলিগ্রামে
# জানানো হতো না — ফলে "buy হচ্ছে না" রিপোর্ট আসা পর্যন্ত কারণ বোঝা যেত না।
# এখন এসবও Admin কে জানানো হবে, তবে বারবার একই এরর দিয়ে স্প্যাম না করার জন্য
# একটা সহজ cooldown (৫ মিনিট) রাখা হয়েছে।
_realproxy_admin_alert_ts = {"login": 0, "network": 0}
_REALPROXY_ADMIN_ALERT_COOLDOWN = 300  # সেকেন্ড

def _realproxy_alert_admin(kind, message):
    now_ts = _time_module.time()
    last = _realproxy_admin_alert_ts.get(kind, 0)
    if now_ts - last < _REALPROXY_ADMIN_ALERT_COOLDOWN:
        return
    _realproxy_admin_alert_ts[kind] = now_ts
    try:
        bot.send_message(ADMIN_ID, message)
    except Exception:
        pass


def realproxy_login(force=False):
    """
    /login কল করে JWT token নেয় ও cache করে।
    Return: token string অথবা None (fail হলে)
    """
    if not REALPROXY_BASE_URL or not REALPROXY_EMAIL or not REALPROXY_PASSWORD:
        logging.warning("REALPROXY_BASE_URL / REALPROXY_EMAIL / REALPROXY_PASSWORD সেট করা নেই")
        _realproxy_alert_admin("login", "⚠️ Real Proxy কনফিগার করা নেই — REALPROXY_BASE_URL/EMAIL/PASSWORD environment variable চেক করুন। এই কারণেই কোনো ইউজার Real Proxy কিনতে পারছে না।")
        return None
    with _realproxy_lock:
        now_ts = _time_module.time()
        if not force and _realproxy_token_cache["token"] and _realproxy_token_cache["expire_at"] - _REALPROXY_TOKEN_REFRESH_MARGIN > now_ts:
            return _realproxy_token_cache["token"]
        try:
            resp = http_requests.post(
                f"{REALPROXY_BASE_URL}/login",
                json={"email": REALPROXY_EMAIL, "password": REALPROXY_PASSWORD},
                timeout=10
            )
            data = resp.json()
            token = data.get("token")
            expire_at = data.get("expire_at")
            if not token:
                logging.error(f"realproxy_login failed: {data}")
                _realproxy_alert_admin("login", f"⚠️ Real Proxy লগইন ব্যর্থ হয়েছে: {data}\n\nEmail/Password ভুল হতে পারে, বা Mega Panel account এ সমস্যা থাকতে পারে — এই কারণে কোনো ইউজার Real Proxy কিনতে পারছে না, যতক্ষণ না এটা ঠিক হয়।")
                return None
            _realproxy_token_cache["token"] = token
            # ⚠️ Mega Panel token ~১৫ মিনিট inactivity তে expire হয়ে যায়।
            # expire_at না থাকলে conservative ধরে নাও ১০ মিনিট পরে expire হবে,
            # যাতে margin সহ ৫ মিনিটেই re-login ট্রিগার হয় (guideline: 10-12 মিনিট পরপর রিফ্রেশ)
            _realproxy_token_cache["expire_at"] = float(expire_at) if expire_at else now_ts + 600
            return token
        except Exception as e:
            logging.error(f"realproxy_login error: {e}")
            _realproxy_alert_admin("login", f"⚠️ Real Proxy লগইন করতে গিয়ে এরর: {e}\n\nMega Panel সার্ভার ডাউন থাকতে পারে বা নেটওয়ার্ক সমস্যা — এই কারণে কোনো ইউজার Real Proxy কিনতে পারছে না।")
            return None


def realproxy_request(method, path, params=None, json_data=None, _retry=True):
    """
    Real Proxy API তে authenticated request পাঠায়। Token expire/401 হলে
    একবার re-login করে আবার চেষ্টা করে।
    Return: (success: bool, data: dict/list, error_msg: str)
    """
    if not REALPROXY_BASE_URL:
        return False, None, "REALPROXY_BASE_URL সেট করা নেই।"
    token = realproxy_login()
    if not token:
        return False, None, "Real Proxy লগইন ব্যর্থ — email/password/base URL চেক করুন।"
    try:
        resp = http_requests.request(
            method, f"{REALPROXY_BASE_URL}{path}",
            headers={"Authorization": f"Bearer {token}"},
            params=params, json=json_data, timeout=15
        )
        if resp.status_code == 401 and _retry:
            realproxy_login(force=True)
            return realproxy_request(method, path, params=params, json_data=json_data, _retry=False)
        try:
            data = resp.json()
        except Exception:
            return False, None, f"HTTP {resp.status_code}: {resp.text[:200]}"
        if resp.status_code >= 400 or (isinstance(data, dict) and data.get("result") is False):
            err = data.get("message") or data.get("error") or str(data) if isinstance(data, dict) else str(data)
            return False, data, err
        return True, data, ""
    except Exception as e:
        logging.error(f"realproxy_request error [{method} {path}]: {e}")
        _realproxy_alert_admin("network", f"⚠️ Real Proxy API ({method} {path}) কল করতে গিয়ে নেটওয়ার্ক/টাইমআউট এরর: {e}")
        return False, None, str(e)


def realproxy_get_packages():
    ok, data, err = realproxy_request("GET", "/packages")
    return data if ok and isinstance(data, list) else []

# ⛔ এই কীওয়ার্ড থাকা প্যাকেজ (Injection Package, Turbo Injection Package)
# ইউজারকে দেখানো হবে না — বাটন থেকে বাদ।
REALPROXY_HIDDEN_PACKAGE_KEYWORDS = ["injection"]

def realproxy_get_visible_packages():
    """realproxy_get_packages() এর রেজাল্ট থেকে hidden কীওয়ার্ড থাকা প্যাকেজ বাদ দিয়ে রিটার্ন করে।"""
    packages = realproxy_get_packages()
    return [
        p for p in packages
        if not any(kw in str(p.get("package_name", "")).lower() for kw in REALPROXY_HIDDEN_PACKAGE_KEYWORDS)
    ]

def realproxy_get_countries(pkg_id, return_error=False):
    ok, data, err = realproxy_request("GET", "/countries", params={"pkg_id": pkg_id})
    result = data if ok and isinstance(data, list) else []
    if return_error:
        return result, (not ok), err
    return result

def realproxy_get_cities(country_id, pkg_id, return_error=False):
    ok, data, err = realproxy_request("GET", "/cities", params={"country_id": country_id, "pkg_id": pkg_id})
    result = data if ok and isinstance(data, list) else []
    if return_error:
        return result, (not ok), err
    return result

def realproxy_get_service_providers(city_id, pkg_id):
    ok, data, err = realproxy_request("GET", "/service-providers", params={"city_id": city_id, "pkg_id": pkg_id})
    return data if ok and isinstance(data, list) else []

def realproxy_get_prices(pkg_id):
    ok, data, err = realproxy_request("GET", "/prices", params={"pkg_id": pkg_id})
    return data if ok and isinstance(data, list) else []

def realproxy_get_parent_proxies(pkg_id, service_provider_city_id=None, country_id=None, city_id=None, offset=0, _all_pages=True, return_error=False):
    """
    /parent-proxies থেকে parent proxy লিস্ট আনে।

    ⚠️ এই API paginated (offset mandatory, একবারে সীমিত সংখ্যক রেজাল্ট রিটার্ন করে)।
    আগে শুধু offset=0 (প্রথম page) ফেচ করা হতো — ফলে available proxy গুলো যদি ২য়/৩য়
    page-এ থাকতো, bot সেগুলো দেখতেই পেতো না আর ভুলভাবে "No proxy available" দেখাতো,
    যদিও আসলে available proxy বটে ছিল।

    এখন _all_pages=True (default) হলে খালি page না পাওয়া পর্যন্ত সব page ঘুরে সম্পূর্ণ
    লিস্ট জোগাড় করে রিটার্ন করে।

    🔧 BUG FIX: আগে API call ব্যর্থ হলে (token/network/param error) সেটা silently
    খালি লিস্ট হিসেবে ট্রিট হতো — ফলে ইউজার "No proxy available" দেখতো, যদিও
    আসল কারণ ছিল API error, না যে সত্যিই কোনো proxy ছিল না। এখন
    return_error=True দিলে (all_results, had_error, last_err_msg) — তিনটা রিটার্ন
    করে, যাতে caller real error আর genuine empty-stock আলাদা করে দেখাতে পারে।

    🔧 CRITICAL BUG FIX: production লগে দেখা গেছে service_provider_city_id দিয়ে
    filter করার সময় বারবার (একাধিক ভিন্ন provider ও package জুড়ে) ঠিক ০টা রেজাল্ট
    আসছিল, যদিও official Real Proxy bot একই account-এ একই city/provider এর জন্য
    real stock দেখাচ্ছিল। কারণ — শুধু service_provider_city_id একা পাঠানো হচ্ছিল,
    সাথে country_id/city_id (যেগুলো doc অনুযায়ী optional কিন্তু bot ততক্ষণে ইউজারের
    থেকে already জানে) পাঠানো হচ্ছিল না, ফলে সার্ভার-সাইড filter সঠিকভাবে scope
    করতে পারছিল না এবং খালি রেজাল্ট দিচ্ছিল। এখন country_id ও city_id (যদি দেওয়া
    থাকে) সবসময় service_provider_city_id এর সাথে একত্রে পাঠানো হচ্ছে।
    """
    all_results = []
    had_error = False
    last_err = ""
    current_offset = offset
    while True:
        params = {"offset": current_offset, "pkg_id": pkg_id}
        if country_id is not None:
            params["country_id"] = country_id
        if city_id is not None:
            params["city_id"] = city_id
        if service_provider_city_id is not None:
            params["service_provider_city_id"] = service_provider_city_id
        ok, data, err = realproxy_request("GET", "/parent-proxies", params=params)
        if not ok:
            had_error = True
            last_err = err
            logging.error(f"realproxy_get_parent_proxies API error [offset={current_offset}, pkg_id={pkg_id}, country_id={country_id}, city_id={city_id}, service_provider_city_id={service_provider_city_id}]: {err}")
            break
        # 🔧 CRITICAL BUG FIX: doc বলে /parent-proxies সরাসরি একটা bare JSON array
        # রিটার্ন করে ([{...},{...}]), কিন্তু বাস্তব API সম্ভবত সেটাকে একটা wrapper
        # object এর ভিতরে দেয় (যেমন {"result":true,"data":[...]})। আগে কোড শুধু
        # bare array আশা করতো — dict আসলে সেটাকে silently "0 আইটেম" ধরে নিতো, ফলে
        # সত্যিকারের data থাকা সত্ত্বেও প্রতিবার "0 raw parents" দেখাতো। এখন dict
        # আসলে সাধারণ wrapper key গুলো (data/result/proxies/parent_proxies/items/list)
        # চেক করে ভিতরের array বের করার চেষ্টা করা হচ্ছে।
        if isinstance(data, list):
            page = data
        elif isinstance(data, dict):
            page = None
            for key in ("data", "result", "proxies", "parent_proxies", "items", "list", "parents"):
                val = data.get(key)
                if isinstance(val, list):
                    page = val
                    break
            if page is None:
                # 🆕 অজানা shape — raw response admin কে একবার পাঠাও (debug এর জন্য),
                # যাতে সঠিক key বের করে code ঠিক করা যায় curl ছাড়াই।
                _realproxy_alert_admin(
                    "unknown_shape",
                    f"🔍 DEBUG: /parent-proxies থেকে অপ্রত্যাশিত response shape এসেছে "
                    f"(pkg_id={pkg_id}, country_id={country_id}, city_id={city_id}, "
                    f"service_provider_city_id={service_provider_city_id}):\n\n"
                    f"<code>{str(data)[:1500]}</code>\n\n"
                    f"এই রেসপন্সটা আমাকে (Claude কে) পাঠাও — সঠিক key বের করে ফিক্স করে দেব।"
                )
                page = []
        else:
            page = []
        if not page:
            break
        all_results.extend(page)
        if not _all_pages:
            break
        current_offset += len(page)
        if current_offset > 5000:  # সেফটি ক্যাপ — কোনো bug থাকলেও infinite loop যেন না হয়
            logging.warning("realproxy_get_parent_proxies: safety cap hit, stopping pagination")
            break
    if return_error:
        return all_results, had_error, last_err
    return all_results


def _rp_is_parent_usable(p):
    """
    একটা parent proxy এখন request করার মতো usable কিনা — ডিফেন্সিভভাবে চেক করে।

    🔧 BUG FIX: আগে শর্ত ছিল `p.get("is_available") and p.get("status") == "ACTIVE"`
    — এক্স্যাক্টলি "ACTIVE" (case-sensitive) আর is_available সরাসরি True না হলেই
    বাদ পড়ে যেত। কিন্তু API স্পেক অনুযায়ী "is_available" শুধু তখনই False হওয়া উচিত
    যখন সত্যিই নতুন proxy account রিকোয়েস্ট করা যাবে না (usage ফুল) — status field
    কখনো lowercase আসলে বা key মিসিং থাকলে valid parent-ও silently বাদ পড়ে
    "No proxy available" দেখাতো। এখন:
      • status থাকলে case-insensitive চেক করা হয়, আর explicit "OUT_OF_SVC" ছাড়া বাকি
        সব (বা status মিসিং) কে active ধরা হয়।
      • is_available key একদমই missing থাকলে (None, key নেই) সেটাকে available ধরা
        হয় — শুধু explicit False/0 থাকলেই বাদ দেওয়া হয়।
    """
    status = str(p.get("status") or "").strip().upper()
    if status == "OUT_OF_SVC":
        return False
    is_avail = p.get("is_available")
    if is_avail is False or is_avail == 0:
        return False
    return True


# ═══════════════════════════════════════════════════════════
# 📊 LIVE STOCK — Country/City/Provider ধাপে শুধু সেগুলোই দেখাও যেগুলোতে
# এই মুহূর্তে অন্তত ১টা usable parent proxy আছে। যেগুলোতে স্টক নেই সেগুলো
# funnel থেকেই বাদ পড়বে, যাতে ইউজার dead-end কম্বিনেশনে গিয়ে
# "No proxy available" না দেখে।
# ═══════════════════════════════════════════════════════════
_rp_stock_cache = {}  # pkg_id(str) → {"ts":..., "had_error":..., "available_city_ids":set, "available_spc_ids":set, "city_country_map":dict}
_rp_stock_cache_lock = threading.Lock()
_RP_STOCK_CACHE_TTL = 60  # সেকেন্ড — খুব ঘন ঘন হলে API load বাড়বে, খুব বেশি হলে স্টক stale দেখাবে

def realproxy_get_live_stock(pkg_id, force=False):
    """
    একটা package এর জন্য সম্পূর্ণ available parent-proxy ইনভেন্টরি + city→country
    ম্যাপিং বের করে cache করে রাখে (TTL সহ)। Country/City/Provider — প্রতিটা ধাপে
    এই ডেটা দিয়েই ফিল্টার করা হবে যাতে খালি কম্বিনেশন দেখানো না হয়।
    """
    pkg_key = str(pkg_id)
    now = _time_module.time()
    if not force:
        with _rp_stock_cache_lock:
            cached = _rp_stock_cache.get(pkg_key)
            if cached and now - cached["ts"] < _RP_STOCK_CACHE_TTL:
                return cached

    # সব parent proxy আনো (কোনো city/provider filter ছাড়া, সব page মিলিয়ে)
    raw_parents, had_error, err = realproxy_get_parent_proxies(pkg_id, service_provider_city_id=None, return_error=True)
    available = [p for p in raw_parents if _rp_is_parent_usable(p)]
    available_city_ids = {str(p.get("city_id")) for p in available if p.get("city_id") is not None}
    available_spc_ids = {str(p.get("service_provider_city_id")) for p in available if p.get("service_provider_city_id") is not None}

    # city_id → country_id ম্যাপ — শুধু তখনই বানাও যখন অন্তত ১টা city তে স্টক আছে
    # (পুরোপুরি স্টক-আউট হলে খামোখা প্রতিটা country এর cities fetch করার দরকার নেই)
    #
    # 🔧 BUG FIX: আগে /countries বা /cities কল মাঝপথে fail করলে (network glitch,
    # rate-limit, timeout) সেটা silently ignore হয়ে যেত, ফলে city_country_map
    # অসম্পূর্ণ থেকে যেত এবং যেসব country-তে আসলে স্টক ছিল সেগুলোও bad map এর
    # কারণে বাদ পড়ে "No country currently has proxies available" ভুলভাবে দেখাতো।
    # এখন এরকম কোনো fetch fail করলে পুরো stock check-কেই had_error=True ধরা হয়,
    # যাতে caller ভুল "stock নেই" মেসেজের বদলে আনফিল্টার্ড লিস্ট দেখায় বা error জানায়।
    city_country_map = {}
    map_build_error = False
    if available_city_ids and not had_error:
        countries, c_err, c_errmsg = realproxy_get_countries(pkg_id, return_error=True)
        if c_err:
            map_build_error = True
            last_map_err = c_errmsg
        else:
            last_map_err = ""
            for c in countries:
                cid = c.get("id")
                if cid is None:
                    continue
                cities, ci_err, ci_errmsg = realproxy_get_cities(cid, pkg_id, return_error=True)
                if ci_err:
                    map_build_error = True
                    last_map_err = ci_errmsg
                    continue
                for city in cities:
                    city_id = city.get("id")
                    if city_id is not None:
                        city_country_map[str(city_id)] = str(cid)
        if map_build_error:
            had_error = True
            err = err or last_map_err or "city/country ম্যাপ বানাতে সমস্যা হয়েছে।"

    result = {
        "ts": now,
        "had_error": had_error,
        "err": err,
        "available_city_ids": available_city_ids,
        "available_spc_ids": available_spc_ids,
        "city_country_map": city_country_map,
        # 🆕 DIAGNOSTIC COUNTS — "No country available" আসলে API থেকে সত্যিই ০টা
        # parent proxy এসেছে (real stock-out) নাকি parent proxy এসেছে কিন্তু filter/map
        # এ কোথাও বাদ পড়ে গেছে সেটা আলাদা করে বোঝার জন্য। কোনো লজিক পরিবর্তন করে না।
        "raw_parent_count": len(raw_parents),
        "usable_parent_count": len(available),
    }
    with _rp_stock_cache_lock:
        _rp_stock_cache[pkg_key] = result
    return result


def realproxy_create_proxy(parent_proxy_id, package_id, protocol, duration, username=None, password=None, ip_addr=None):
    """
    POST /proxies — নতুন প্রক্সি অ্যাকাউন্ট তৈরি করে।

    🔧 CRITICAL BUG FIX (আগের রাউন্ড): এই ফাংশনের `def` লাইনটাই মিসিং ছিল, ফলে
    NameError দিয়ে ক্র্যাশ করতো এবং প্রক্সি কেনা কখনোই সম্পন্ন হতো না। সেটা ফিক্সড।

    🔧 CRITICAL BUG FIX (নতুন): API doc-এর Endpoints শীট অনুযায়ী /proxies (POST)
    এর Mandatory params হলো parent_proxy_id, package_id, protocol, duration —
    কিন্তু body তে package_id কখনোই পাঠানো হচ্ছিল না। এই কারণেই "New Proxy"
    বাটনে ক্লিক করে country/city/provider/proxy/username/password/duration সব
    ধাপ পার হয়ে Confirm চাপার পরেও Real Proxy সার্ভার request reject করতো
    (PACKAGE_NOT_FOUND_BY_ID বা silent {"result": false}) এবং ইউজার কোনো প্রক্সি
    পেতো না। এখন state এ রাখা pkg_id-টা body তে package_id হিসেবে পাঠানো হচ্ছে।
    """
    body = {
        "parent_proxy_id": parent_proxy_id,
        "package_id": package_id,
        "protocol": protocol,
        "duration": duration,
    }
    if username: body["username"] = username
    if password: body["password"] = password
    if ip_addr:  body["ip_addr"] = ip_addr
    return realproxy_request("POST", "/proxies", json_data=body)

def realproxy_get_proxy_details(proxy_id):
    """GET /proxies/{id} — একটা নির্দিষ্ট প্রক্সি অ্যাকাউন্টের বর্তমান ডিটেইলস আনে (My Proxy ফিচারের জন্য)।"""
    ok, data, err = realproxy_request("GET", f"/proxies/{proxy_id}")
    return data if ok and isinstance(data, dict) else None

def realproxy_modify_proxy(proxy_id, parent_proxy_id, protocol, password=None, ip_addresses=None):
    """PUT /proxies/{id} — বিদ্যমান প্রক্সি অ্যাকাউন্টকে নতুন parent proxy তে migrate করে (লোকেশন চেঞ্জ,
    নতুন IP জেনারেট হয়) — মেয়াদ (expiry) অপরিবর্তিত থাকে, ব্যালেন্স কাটা হয় না।"""
    body = {"parent_proxy_id": parent_proxy_id, "protocol": protocol}
    if password:     body["password"] = password
    if ip_addresses: body["ip_addresses"] = ip_addresses
    return realproxy_request("PUT", f"/proxies/{proxy_id}", json_data=body)

def realproxy_renew_proxy(proxy_id, duration):
    """POST /proxies/{id}/renew — বিদ্যমান প্রক্সির মেয়াদ বাড়ায়। ব্যালেন্স কাটে (Affect Balance = Yes, doc অনুযায়ী),
    কিন্তু IP/লোকেশন অপরিবর্তিত থাকে। duration ফরম্যাট create_proxy এর মতোই:
    >=1.0 হলে দিন হিসেবে ধরা হয় (1=১দিন, 7=১সপ্তাহ...), <1.0 হলে ঘন্টা (÷100, যেমন 0.02=২ঘন্টা)।"""
    return realproxy_request("POST", f"/proxies/{proxy_id}/renew", json_data={"duration": duration})

def realproxy_check_username(username):
    """
    GET /check-username দিয়ে চেক করে ইউজারনেমটা আগে থেকে কারো নেওয়া কিনা।
    Return: "AVAILABLE" / "ALREADY_USER" / None (error হলে)
    """
    ok, data, err = realproxy_request("GET", "/check-username", params={"username": username})
    if ok and isinstance(data, dict):
        return data.get("result")
    return None

def realproxy_get_balance():
    ok, data, err = realproxy_request("GET", "/balance")
    if ok and isinstance(data, dict):
        return data.get("balance", 0)
    return None

def get_proxy_usd_bdt_rate(db=None):
    """Admin panel থেকে সেট করা Real Proxy এর জন্য আলাদা USD→BDT rate।
    সেট না থাকলে default হিসেবে সাধারণ USD_TO_BDT_RATE ব্যবহার হবে।"""
    if db is None:
        db = load_db()
    return db.get("settings", {}).get("proxy_usd_bdt_rate", USD_TO_BDT_RATE)


