# 💎 PREMIUM (CUSTOM) EMOJI — সর্বত্র (v2)
# ──────────────────────────────────────────────────────
# কী কী কভার করে (host.py এর অন্য কোনো জায়গা এডিট ছাড়াই):
#   • সব মেসেজ টেক্সট  — HTML parse_mode হোক বা সাধারণ টেক্সট
#   • সব ক্যাপশন (photo/document/video/animation)
#   • সব INLINE বাটন (বর্তমান ও ভবিষ্যতের)  — শুরুর emoji → আইকন
#   • সব REPLY KEYBOARD বাটন (বর্তমান ও ভবিষ্যতের) — শুরুর emoji → আইকন
#   • ইউজার বাটনে ট্যাপ করলে যে টেক্সট আসে, সেটা আগের টেক্সটে ফিরিয়ে দেয়,
#     তাই আপনার সব button-matching কোড আগের মতোই কাজ করে।
#   • Telegram কোনো কারণে reject করলে অটো সাধারণ emoji তে ফিরে যায়
#     (বট কখনো মেসেজ পাঠানো বন্ধ করবে না)।
# ══════════════════════════════════════════════════════
import re as _pe_re
import json as _pe_json
import time as _pe_time
import threading as _pe_threading

_PE_MAP = {}                 # {"🛍": "emoji_id"}  (FE0F ছাড়া key)
_PE_PATTERN = None
_PE_STATE = {"icons": True, "err": "", "conv": 0, "hook": "none"}  # icons: Telegram reject করলে False
_PE_TLS = _pe_threading.local()
_PE_LOCK = _pe_threading.Lock()
_PE_BTN_TEXT = {}            # reply বাটন: {আইকন-ছাড়া টেক্সট: আসল টেক্সট}
_PE_BTN_NEW = {}             # MySQL এ সেভ হওয়ার অপেক্ষায়
_PE_BTN_SAVED = [0]
_PE_BTN_MAX_SAVED = 3000
_PE_BTN_MAX_MEM = 20000
_PE_TAG_RE = _pe_re.compile(r'(<[^>]*>)')


# ── helpers ─────────────────────────────────────────────
def _pe_key(ch):
    return ch.replace("\ufe0f", "").strip()


def _pe_hex(ch):
    return "-".join(f"{ord(c):x}" for c in ch)


def _pe_unhex(h):
    return "".join(chr(int(x, 16)) for x in h.split("-"))


def _pe_rebuild():
    global _PE_PATTERN
    keys = sorted(_PE_MAP, key=len, reverse=True)
    if not keys:
        _PE_PATTERN = None
        return
    alts = ["".join(_pe_re.escape(c) + "\ufe0f?" for c in k) for k in keys]
    _PE_PATTERN = _pe_re.compile("(?:" + "|".join(alts) + ")")


def load_premium_emojis(saved, btn_map=None):
    """Startup এ MySQL থেকে লোড: saved={hexkey: emoji_id}, btn_map={hex(text): original}"""
    if isinstance(saved, dict):
        for h, i in saved.items():
            if i:
                try:
                    _PE_MAP[_pe_unhex(h)] = str(i)
                except Exception:
                    pass
    _pe_rebuild()
    if isinstance(btn_map, dict):
        for h, orig in btn_map.items():
            try:
                _PE_BTN_TEXT[bytes.fromhex(h).decode("utf-8")] = orig
                _PE_BTN_SAVED[0] += 1
            except Exception:
                pass


def _pe_save(key, emoji_id):
    try:
        update_db_path(f"/settings/premium_emojis/{_pe_hex(key)}", emoji_id)
    except Exception as e:
        logging.error(f"premium emoji save error: {e}")


def _pe_save_all():
    """পুরো map একবারে সেভ (এক write) — MySQL quota বাঁচাতে।"""
    try:
        update_db_path("/settings/premium_emojis",
                       {_pe_hex(k): v for k, v in _PE_MAP.items()})
    except Exception as e:
        logging.error(f"premium emoji bulk save error: {e}")


def _pe_btn_flusher():
    """নতুন reply-বাটন টেক্সট ম্যাপিং ব্যাচ করে MySQL এ রাখে (রিস্টার্টের পরেও
    ইউজারের পুরোনো কিবোর্ড কাজ করবে)।"""
    while True:
        _pe_time.sleep(30)
        try:
            with _PE_LOCK:
                batch = dict(_PE_BTN_NEW)
                _PE_BTN_NEW.clear()
            for stripped, orig in batch.items():
                if _PE_BTN_SAVED[0] >= _PE_BTN_MAX_SAVED:
                    break
                update_db_path(
                    f"/settings/premium_btn_map/{stripped.encode('utf-8').hex()}", orig)
                _PE_BTN_SAVED[0] += 1
        except Exception as e:
            logging.error(f"premium btn map flush error: {e}")


_pe_threading.Thread(target=_pe_btn_flusher, daemon=True).start()


# ── মেসেজ টেক্সট ────────────────────────────────────────
def _pe_html(text):
    """HTML টেক্সটের ট্যাগের বাইরের emoji গুলো <tg-emoji> এ মুড়ে দেয়।"""
    if not _PE_PATTERN or not isinstance(text, str) or "<tg-emoji" in text:
        return text
    parts = _PE_TAG_RE.split(text)
    for i in range(0, len(parts), 2):     # জোড় index = ট্যাগের বাইরের অংশ
        parts[i] = _PE_PATTERN.sub(
            lambda m: '<tg-emoji emoji-id="%s">%s</tg-emoji>'
                      % (_PE_MAP[_pe_key(m.group(0))], m.group(0)),
            parts[i])
    return "".join(parts)


def _pe_entities(text):
    """সাধারণ (parse_mode ছাড়া) টেক্সটের জন্য custom_emoji entity লিস্ট।"""
    if not _PE_PATTERN or not isinstance(text, str):
        return None
    ents, last, off = [], 0, 0
    try:
        for m in _PE_PATTERN.finditer(text):
            off += len(text[last:m.start()].encode("utf-16-le")) // 2
            ln = len(m.group(0).encode("utf-16-le")) // 2
            ents.append(types.MessageEntity(
                "custom_emoji", off, ln,
                custom_emoji_id=_PE_MAP[_pe_key(m.group(0))]))
            off += ln
            last = m.end()
    except Exception:
        return None
    if not ents or len(ents) > 100:
        return None
    return ents


def _pe_err_is_emoji(e):
    s = str(e).lower()
    return ("emoji" in s or "icon" in s or "entit" in s
            or "document_invalid" in s or "button" in s)


def _pe_chat_is_admin(fn_name, args, kwargs):
    """পাঠানো/এডিটের গন্তব্য চ্যাট অ্যাডমিন কিনা (বাটন কনভার্টে অ্যাডমিন-অটো মোডের জন্য)।"""
    try:
        cid = kwargs.get("chat_id")
        if cid is None:
            idx = 1 if fn_name in ("edit_message_text", "edit_message_caption") else 0
            if len(args) > idx:
                cid = args[idx]
        return bool(cid is not None and not isinstance(cid, str) and is_admin(cid))
    except Exception:
        return False


def _pe_with_ctx(fn, inner):
    name = getattr(fn, "__name__", "")

    def wrapper(*args, **kwargs):
        prev = getattr(_PE_TLS, "admin", False)
        _PE_TLS.admin = _pe_chat_is_admin(name, args, kwargs)
        try:
            return inner(*args, **kwargs)
        finally:
            _PE_TLS.admin = prev
    return wrapper


def _pe_wrap(fn, text_idx, text_field, ent_field):
    def _inner(*args, **kwargs):
        if not _PE_PATTERN and not _PBI_MAP:
            return fn(*args, **kwargs)
        a, k = list(args), dict(kwargs)
        pm = k.get("parse_mode")
        if pm is not None and str(pm).upper() != "HTML":
            pm = "other"

        def conv(val):
            if pm == "other":
                return val, None
            if pm is not None:
                return _pe_html(val), None
            if k.get(ent_field):
                return val, None
            return val, _pe_entities(val)

        try:
            if text_idx is not None and len(a) > text_idx and isinstance(a[text_idx], str):
                a[text_idx], ents = conv(a[text_idx])
                if ents:
                    k[ent_field] = ents
            elif isinstance(k.get(text_field), str):
                k[text_field], ents = conv(k[text_field])
                if ents:
                    k[ent_field] = ents
        except Exception:
            a, k = list(args), dict(kwargs)

        try:
            return fn(*a, **k)
        except Exception as e:
            if not _pe_err_is_emoji(e):
                raise
            # ধাপ ১: টেক্সট প্রিমিয়াম রেখে শুধু বাটন আইকন বন্ধ করে চেষ্টা
            if k.get("reply_markup") is not None and _PE_STATE["icons"]:
                _PE_TLS.off = True
                try:
                    r = fn(*a, **k)
                    _PE_STATE["icons"] = False
                    _PE_STATE["err"] = str(e)[:300]
                    logging.error("⚠️ Telegram বাটন আইকন (icon_custom_emoji_id) নিচ্ছে না "
                                  f"— বাটন আইকন বন্ধ করা হলো: {e}")
                    return r
                except Exception:
                    pass
                finally:
                    _PE_TLS.off = False
            # ধাপ ২: সবকিছু আগের মতো সাধারণ অবস্থায়
            _PE_TLS.off = True
            try:
                return fn(*args, **kwargs)
            finally:
                _PE_TLS.off = False
    return _pe_with_ctx(fn, _inner)


