_GM_EMAIL_RE = re.compile(r"^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$")
_GM_ZW_RE = re.compile(r"[\u200b\u200c\u200d\u2060\ufeff]")
_GM_LINE_FALLBACK_RE = re.compile(r"^([^\s|,;:]+@[^\s|,;:]+)\s*[|,;:\t ]\s*(.+)$")
_GM_TOKEN_RE = re.compile(r"^[A-Za-z0-9_\-]{10,60}$")

# ── ⬇️ gmail_system.py থেকে হুবহু কপি করা অংশ (IMAP, পার্সার, কোড খোঁজা) ──
