def _gm_decode(v):
    try:
        return str(make_header(decode_header(v or "")))
    except Exception:
        return str(v or "")

def _gm_html_to_text(h):
    h = re.sub(r"(?is)<(script|style).*?</\1>", "", h)
    h = re.sub(r'(?is)<a[^>]+href=["\']([^"\']+)["\'][^>]*>(.*?)</a>',
               lambda m: f"{re.sub(r'<[^>]+>', '', m.group(2)).strip()} ({m.group(1)})" if m.group(1).startswith("http") else m.group(2), h)
    h = re.sub(r"(?i)<br\s*/?>|</p>|</div>|</tr>|</h\d>", "\n", h)
    h = re.sub(r"<[^>]+>", "", h)
    return _gm_html.unescape(h)

def _gm_body(msg):
    plain, html_part = "", ""
    for part in msg.walk():
        if part.get_content_maintype() == "multipart" or part.get_filename():
            continue
        ctype = part.get_content_type()
        if ctype not in ("text/plain", "text/html"):
            continue
        try:
            payload = part.get_payload(decode=True) or b""
            text = payload.decode(part.get_content_charset() or "utf-8", errors="replace")
        except Exception:
            continue
        if ctype == "text/plain" and not plain:
            plain = text
        elif ctype == "text/html" and not html_part:
            html_part = text
    body = plain.strip() or _gm_html_to_text(html_part)
    body = re.sub(r"[ \t\u200b\u200c\u200d\u2060\u00ad\u034f]+", " ", body)
    body = re.sub(r"\n\s*\n\s*\n+", "\n\n", body)
    return body.strip()

def _gm_search_criteria(domains):
    crit = ["FROM", f'"{domains[-1]}"']
    for d in reversed(domains[:-1]):
        crit = ["OR", "FROM", f'"{d}"'] + crit
    return crit

def _gm_sender_ok(platform_key, msg):
    """🔒 কঠোর যাচাই: মেইলের আসল From ঠিকানার ডোমেইন এই সার্ভিসের অনুমোদিত ডোমেইনের সাথে মিলতে হবে।
    (IMAP FROM সার্চ ডিসপ্লে-নেম/ঢিলেঢালা মিলও ধরে — তাই অন্য সার্ভিসের মেইল যেন কোনোভাবেই না ঢোকে)"""
    try:
        from email.utils import parseaddr as _pa
        addr = _pa(_gm_decode(msg.get("From")))[1].strip().lower()
        if "@" not in addr:
            return False
        dom = addr.rsplit("@", 1)[1]
        for d in GMAIL_SENDERS.get(platform_key, []):
            d = d.lstrip("@").lower()
            if "." not in d:                       # যেমন "locanto" — ডোমেইনের ভেতরে থাকলেই চলবে
                if d in dom:
                    return True
            elif dom == d or dom.endswith("." + d):
                return True
    except Exception:
        pass
    return False

def _gm_extract_code(platform_key, subject, body):
    rx = re.compile(_GM_CODE_RE.get(platform_key, r"(?<![\d.])(\d{4,8})(?![\d.])"))
    for src in (subject, body):
        for m in rx.finditer(src or ""):
            val = m.group(1)
            if len(val) == 4 and val.startswith(("19", "20")):   # সাল (2026 ইত্যাদি) বাদ
                continue
            return val
    return None

def _gm_parse(msg, box, platform_key):
    try:
        dt = parsedate_to_datetime(msg.get("Date"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=_gm_timezone.utc)
    except Exception:
        dt = datetime.min.replace(tzinfo=_gm_timezone.utc)
    subject = _gm_decode(msg.get("Subject"))
    body = _gm_body(msg)
    return {"dt": dt, "from": _gm_decode(msg.get("From")), "subject": subject,
            "date": msg.get("Date", ""), "body": body,
            "code": _gm_extract_code(platform_key, subject, body), "spam": box != "INBOX"}

def gmail_fetch_many(address, app_password, platform_key, limit=GM_SCAN_LAST):
    """list — ওই platform_key এর প্রেরকের সর্বশেষ `limit` টা email (নতুন -> পুরোনো)।
    লগইন/নেটওয়ার্ক সমস্যায় Exception ছোড়ে।"""
    domains = GMAIL_SENDERS.get(platform_key) or []
    if not domains:
        raise ValueError("platform unknown")
    try:
        M = imaplib.IMAP4_SSL("imap.gmail.com", 993, timeout=25)
    except TypeError:
        M = imaplib.IMAP4_SSL("imap.gmail.com", 993)
    found = []
    try:
        M.login(address, re.sub(r"\s+", "", app_password))
        for box in GMAIL_BOXES:
            try:
                st, _ = M.select(f'"{box}"', readonly=True)
                if st != "OK":
                    continue
                st, data = M.uid("SEARCH", None, *_gm_search_criteria(domains))
                uids = (data[0] or b"").split() if st == "OK" else []
                for uid_ in uids[-limit:]:
                    st, fetched = M.uid("FETCH", uid_, "(RFC822)")
                    raw = next((x[1] for x in (fetched or []) if isinstance(x, tuple)), None)
                    if raw:
                        _m = _email_pkg.message_from_bytes(raw)
                        if not _gm_sender_ok(platform_key, _m):
                            continue                  # 🔒 অন্য সার্ভিসের/ভুয়া প্রেরকের মেইল — দেখানো হবে না
                        found.append(_gm_parse(_m, box, platform_key))
            except imaplib.IMAP4.error:
                continue
    finally:
        try:
            M.logout()
        except Exception:
            pass
    found.sort(key=lambda r: r["dt"], reverse=True)
    return found

def gmail_fetch_latest(address, app_password, platform_key):
    """(dict|None) — সর্বশেষ email (OTP কোডসহ হলে সেটাকেই অগ্রাধিকার)।"""
    found = gmail_fetch_many(address, app_password, platform_key, GM_SCAN_LAST)
    if not found:
        return None
    with_code = [r for r in found if r["code"]]
    return with_code[0] if with_code else found[0]
