# 📥 স্টক লাইন পার্স  (name@gmail.com|app_password)
# ───────────────────────────────────────────────────────────────────────────
def _gm_parse_line(line):
    """`email|app_password` লাইন -> (email, password) বা None।
    App Password এর মাঝে স্পেস থাকলেও চলে। `|` না থাকলে `email:pass`, `email,pass`, `email;pass`, ট্যাব/স্পেস চলে।"""
    line = _GM_ZW_RE.sub("", str(line or "")).strip()
    if not line:
        return None
    if "|" in line:
        parts = line.split("|", 2)
        em, pw = parts[0].strip(), parts[1].strip()
    else:
        m = _GM_LINE_FALLBACK_RE.match(line)
        if not m:
            return None
        em, pw = m.group(1).strip(), m.group(2).strip()
    if not em or not pw or not _GM_EMAIL_RE.match(em):
        return None
    return em, pw


def _gm_row_to_item(cells):
    """স্টক শিটের একটা row (cells) -> (email, password) বা None।
    ১ cell এ `email|pass` অথবা ২ cell এ (Email | App Password) দুটোই চলে।"""
    cs = [_GM_ZW_RE.sub("", str(c)).strip() for c in (cells or []) if c is not None and str(c).strip()]
    if not cs:
        return None
    if len(cs) == 1:
        return _gm_parse_line(cs[0])
    if "@" in cs[0] and "|" not in cs[0] and _GM_EMAIL_RE.match(cs[0]) and cs[1]:
        return cs[0], cs[1]
    return _gm_parse_line("|".join(cs))


def _gm_ekey(addr):
    return _gm_hashlib.sha1(str(addr).strip().lower().encode("utf-8")).hexdigest()[:24]


# ───────────────────────────────────────────────────────────────────────────
# 💾 DB (MySQL bot_data) — কেনা মেইল, ইউজার ইনডেক্স, বিক্রি-হওয়া মেইলের সেট
# ───────────────────────────────────────────────────────────────────────────
def _gm_sold_set(plat):
    d = _mysql_get_key(f"gm_sold:{plat}")
    return set(d.keys()) if isinstance(d, dict) else set()


def _gm_save_items(uid, plat, items, order_id, life_min=0):
    """items=[(email,password)] -> [(token,email)] ; item + user-index + sold সেট লেখে।"""
    now = int(_gm_time.time())
    exp = now + int(life_min) * 60 if life_min and int(life_min) > 0 else 0     # ⏳ 0 = মেয়াদ নেই
    saved = []
    for em, pw in items:
        tok = _gm_secrets.token_urlsafe(18)
        rec = {"u": str(uid), "e": em, "p": pw, "k": plat, "o": order_id, "t": now}
        if exp:
            rec["x"] = exp
        _mysql_set_key(f"gm_item:{tok}", rec)
        saved.append((tok, em))
    idx = {tok: ({"e": em, "k": plat, "t": now, "x": exp} if exp else {"e": em, "k": plat, "t": now})
           for tok, em in saved}
    sold = {_gm_ekey(em): 1 for _t, em in saved}
    r1 = _mysql_atomic_rw(f"gm_user:{uid}", lambda cur: {**(cur if isinstance(cur, dict) else {}), **idx})
    r2 = _mysql_atomic_rw(f"gm_sold:{plat}", lambda cur: {**(cur if isinstance(cur, dict) else {}), **sold})
    if r1 is None or r2 is None:
        raise RuntimeError("gmail save: DB write failed")
    return saved


def _gm_rollback(uid, plat, saved):
    """ডেলিভারি ব্যর্থ হলে — সদ্য লেখা রেকর্ড মুছে ফেলে।"""
    try:
        toks = {t for t, _e in saved}
        eks = {_gm_ekey(e) for _t, e in saved}
        for tok in toks:
            _mysql_delete_key(f"gm_item:{tok}")
        _mysql_atomic_rw(f"gm_user:{uid}", lambda cur: {k: v for k, v in (cur or {}).items() if k not in toks})
        _mysql_atomic_rw(f"gm_sold:{plat}", lambda cur: {k: v for k, v in (cur or {}).items() if k not in eks})
    except Exception as e:
        logging.error(f"gmail rollback error: {e}")


def _gm_get_item(tok):
    if not tok or not _GM_TOKEN_RE.match(str(tok)):
        return None
    it = _mysql_get_key(f"gm_item:{tok}")
    return it if isinstance(it, dict) else None


def _gm_user_items(uid, plat=None):
    """ইউজারের কেনা মেইল [(token, email, platform_key, ts)] পুরোনো -> নতুন"""
    d = _mysql_get_key(f"gm_user:{uid}")
    out = []
    if isinstance(d, dict):
        for tok, v in d.items():
            if isinstance(v, dict) and (plat is None or v.get("k") == plat):
                out.append((tok, v.get("e", ""), v.get("k"), v.get("t", 0)))
    out.sort(key=lambda x: x[3])
    return out


# ───────────────────────────────────────────────────────────────────────────
# ⏳ MAIL LIFETIME (মেয়াদ) — প্রতিটা Gmail API সার্ভিসের জন্য আলাদা সময় (Admin সেট করে)
# ───────────────────────────────────────────────────────────────────────────
#  • কেনার মুহূর্ত থেকে মেয়াদ গোনা শুরু। মেয়াদ শেষ হলে 🔑 Get OTP ও 📬 Mail inbox বন্ধ → "Mail Expire"
#  • মেয়াদ কেনার সময়ই item এ লেখা হয় ("x" = expire timestamp) — পরে admin সময় বদলালে
#    আগে কেনা মেইলে প্রভাব পড়ে না, শুধু নতুন কেনায় প্রযোজ্য হয়
#  • 0 = Unlimited (মেয়াদ নেই)। এই আপডেটের আগে কেনা মেইলে "x" নেই → মেয়াদ নেই (আগের মতোই চলবে)
#  • সেটিং MySQL bot_data এর `gm_life` row এ থাকে: {"gm_facebook": 60, "gm_telegram": 30, ...} (মিনিটে)
GM_LIFE_KEY = "gm_life"
GM_LIFE_MAX_MIN = 60 * 24 * 365            # সর্বোচ্চ ১ বছর
GM_LIFE_PRESETS = [(30, "30m"), (60, "1h"), (180, "3h"), (360, "6h"),
                   (720, "12h"), (1440, "1d"), (4320, "3d"), (10080, "7d")]
_GM_LIFE_TTL = 20                          # সেকেন্ড — বারবার MySQL read এড়াতে ছোট cache
_gm_life_cache = [0.0, {}]


def _gm_life_all(force=False):
    """{platform_key: minutes} — ২০ সেকেন্ড cache; admin সেট করলে সাথে সাথে invalidate হয়।"""
    now = _gm_time.time()
    if not force and now - _gm_life_cache[0] < _GM_LIFE_TTL:
        return _gm_life_cache[1]
    try:
        d = _mysql_get_key(GM_LIFE_KEY)
    except Exception as e:
        logging.error(f"gm_life read error: {e}")
        return _gm_life_cache[1]
    d = d if isinstance(d, dict) else {}
    _gm_life_cache[0], _gm_life_cache[1] = now, d
    return d


def _gm_life_minutes(plat, cfg=None):
    """এই সার্ভিসের মেয়াদ (মিনিট)। 0 = Unlimited।"""
    cfg = _gm_life_all() if cfg is None else cfg
    try:
        return max(0, min(int(cfg.get(plat, 0) or 0), GM_LIFE_MAX_MIN))
    except Exception:
        return 0


def _gm_life_apply(key, minutes):
    """key = platform key অথবা "ALL" (সব সার্ভিসে একসাথে)। মিনিট রিটার্ন করে; DB ব্যর্থ হলে Exception।"""
    minutes = max(0, min(int(minutes), GM_LIFE_MAX_MIN))
    keys = list(GMAIL_PLATFORMS.keys()) if key == "ALL" else [key]
    keys = [k for k in keys if k in GMAIL_PLATFORMS]
    if not keys:
        raise ValueError("unknown platform")
    r = _mysql_atomic_rw(GM_LIFE_KEY, lambda cur: {**(cur if isinstance(cur, dict) else {}), **{k: minutes for k in keys}})
    if r is None:
        raise RuntimeError("gm_life write failed")
    _gm_life_cache[0], _gm_life_cache[1] = _gm_time.time(), r
    return minutes


def _gm_fmt_life(minutes, short=False):
    m = int(minutes or 0)
    if m <= 0:
        return "∞" if short else "Unlimited"
    d, rem = divmod(m, 1440)
    h, mi = divmod(rem, 60)
    if short:
        parts = (f"{d}d" if d else "", f"{h}h" if h else "", f"{mi}m" if mi else "")
    else:
        parts = (f"{d} দিন" if d else "", f"{h} ঘণ্টা" if h else "", f"{mi} মিনিট" if mi else "")
    return " ".join(p for p in parts if p)


def _gm_parse_duration(text):
    """'30' (শুধু সংখ্যা = মিনিট) / '30m' / '1h' / '2h30m' / '1d' / '0' / 'unlimited' -> মিনিট (int) বা None।"""
    s_ = str(text or "").strip().lower().replace(" ", "")
    s_ = s_.translate(str.maketrans("০১২৩৪৫৬৭৮৯", "0123456789"))
    if s_ in ("0", "off", "unlimited", "none", "no", "∞"):
        return 0
    if s_.isdigit():
        v = int(s_)
    else:
        m = re.fullmatch(r"(?:(\d+)d)?(?:(\d+)h)?(?:(\d+)m(?:in)?)?", s_)
        if not m or not any(m.groups()):
            return None
        v = int(m.group(1) or 0) * 1440 + int(m.group(2) or 0) * 60 + int(m.group(3) or 0)
    return v if 0 <= v <= GM_LIFE_MAX_MIN else None


def _gm_expire_ts(rec):
    try:
        return int((rec or {}).get("x") or 0)
    except Exception:
        return 0


def _gm_is_expired(rec):
    """rec = gm_item বা gm_user index এর এন্ট্রি (dict)। "x" না থাকলে কখনো expire হয় না।"""
    x = _gm_expire_ts(rec)
    return x > 0 and _gm_time.time() >= x


def _gm_seconds_left(rec):
    """বাকি সেকেন্ড; মেয়াদ না থাকলে None।"""
    x = _gm_expire_ts(rec)
    if x <= 0:
        return None
    return max(0, int(x - _gm_time.time()))


def _gm_fmt_left(sec):
    return _gm_fmt_life(max(1, (int(sec) + 59) // 60), short=True)


def _gm_expired_text(item):
    plat = item.get("k")
    try:
        life_min = max(0, (int(item.get("x") or 0) - int(item.get("t") or 0)) // 60)
    except Exception:
        life_min = 0
    life_part = f" (<b>{_gm_e(_gm_fmt_life(life_min))}</b>)" if life_min else ""
    return ("⌛ <b>Mail Expire!</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
            f"📮 <code>{_gm_e(item.get('e', ''))}</code>\n"
            f"🛍️ সার্ভিস: <b>{_gm_e(_gm_pname(plat))}</b>\n\n"
            f"এই মেইলের ব্যবহারের সময়{life_part} শেষ হয়ে গেছে — এখন আর <b>OTP</b> বা <b>Mail Inbox</b> দেখা যাবে না।\n"
            "নতুন মেইল দরকার হলে শপ থেকে আবার কিনুন।")



# ───────────────────────────────────────────────────────────────────────────
# 🔑 GET OTP — ইনলাইন বাটন + রেজাল্ট মেসেজ + হ্যান্ডলার
# ───────────────────────────────────────────────────────────────────────────
_gm_last = {}            # uid -> শেষ চেক করা token (🔄 Check again এর জন্য)
_gm_cooldown = {}        # uid -> শেষ চেকের সময়
GM_COOLDOWN_SEC = 5
GM_BULK_SEND_DELAY = 0.1


def _gm_refresh_inline():
    kb = types.InlineKeyboardMarkup()
    kb.row(InlineBtn("🔄 Check again", style="primary", callback_data="gm_refresh"))
    return kb


def _gm_found_inline(tok, code=None):
    """OTP পাওয়া গেলে: [🔑 কোড (চাপলে কপি)] + [📬 Mail inbox (Mini App)]"""
    kb = types.InlineKeyboardMarkup()
    btns = []
    if code:
        try:
            btns.append(InlineBtn(f"🔑 {code}", style="success", copy_text=types.CopyTextButton(text=str(code))))
        except Exception:
            pass      # পুরোনো telebot এ copy_text নেই — মেসেজেই কোড দেখানো হয়
    url = _gm_inbox_url(tok) if tok else ""
    if url:
        btns.append(InlineBtn("📬 Mail inbox", style="primary", web_app=types.WebAppInfo(url=url)))
    if btns:
        kb.row(*btns)
    return kb


def _gm_item_inline(tok, otp_first=False):
    """ক্রেতার মেইলের নিচের ইনলাইন বাটন: 📬 Mail inbox ও 🔑 Get OTP পাশাপাশি।"""
    kb = types.InlineKeyboardMarkup()
    otp_btn = InlineBtn("🔑 Get OTP", style="success", callback_data=f"gm_otp|{tok}")
    url = _gm_inbox_url(tok)
    if url:
        inbox_btn = InlineBtn("📬 Mail inbox", style="primary", web_app=types.WebAppInfo(url=url))
        kb.row(*([otp_btn, inbox_btn] if otp_first else [inbox_btn, otp_btn]))
    else:
        kb.row(otp_btn)
    return kb


def _gm_show(chat_id, edit_id, text, kb=None):
    """"⏳ খোঁজা হচ্ছে" মেসেজটাকেই ফলাফলে বদলে দেয় (ডিলিট করে না)।
    ⚠️ কেন: ওই মেসেজের সাথে Buy মেনুর Reply Keyboard লাগানো থাকে — Telegram এ কীবোর্ডসহ মেসেজ
    ডিলিট করলে কীবোর্ডও চলে যায়। তাই ডিলিট নয়, edit। edit ব্যর্থ হলে নতুন মেসেজ পাঠানো হয়।"""
    markup = kb if (kb is not None and getattr(kb, "keyboard", None)) else None
    if edit_id:
        try:
            bot.edit_message_text(text, chat_id, edit_id, parse_mode="HTML", reply_markup=markup)
            return
        except Exception as e:
            if "not modified" in str(e).lower():
                return
            logging.warning(f"_gm_show edit failed, sending new: {e}")
    bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=markup)


def _gm_send_result(chat_id, address, plat, res, tok, edit_id=None):
    text = (f"📨 <b>{_gm_e(_gm_pname(plat))} — Latest Email</b>\n"
            f"📮 <b>Gmail:</b> <code>{_gm_e(address)}</code>\n"
            f"👤 <b>From:</b> {_gm_e(res['from'])}\n"
            f"📝 <b>Subject:</b> {_gm_e(res['subject'])}\n"
            f"🗓️ <b>Date:</b> {_gm_e(res['date'])}\n")
    if res.get("spam"):
        text += "📁 <i>(Spam ফোল্ডারে ছিল)</i>\n"
    kb = _gm_found_inline(tok, res.get("code"))
    if res.get("code"):
        has_copy = any(getattr(b, "copy_text", None) for row in getattr(kb, "keyboard", []) for b in row)
        text += "🔑 <b>Code</b> 👇" if has_copy else f"🔑 <b>Code:</b> <code>{_gm_e(res['code'])}</code>"
        _gm_show(chat_id, edit_id, text, kb)
        return
    # কোড না থাকলে email এর টেক্সটও দেখানো হয়
    text += "\n━━━━━━━━━━━━━━\n"
    body = res.get("body") or "(কোনো টেক্সট নেই)"
    chunks, limit = [], 3500
    while body:
        chunks.append(body[:limit])
        body = body[limit:]
    for i, c in enumerate(chunks):
        last = (i == len(chunks) - 1)
        msg_text = (text if i == 0 else "") + _gm_e(c)
        if i == 0:
            _gm_show(chat_id, edit_id, msg_text, kb if last else None)
        else:
            bot.send_message(chat_id, msg_text, parse_mode="HTML", reply_markup=kb if last else None)


def _gm_run_otp(chat_id, uid, tok, restore_kb=None):
    """ক্রেতা যে সার্ভিসের জন্য মেইলটি কিনেছে শুধু সেই সার্ভিসের সর্বশেষ OTP/email আনে।
    শুধু মেইলের মালিক (যে কিনেছে) নিজেই পাবে।"""
    uid = str(uid)
    item = _gm_get_item(tok)
    if not item or str(item.get("u")) != uid:
        bot.send_message(chat_id, "⚠️ এই মেইলটি আপনার কেনা মেইলের তালিকায় নেই।", reply_markup=restore_kb)
        return
    if _gm_is_expired(item):                      # ⏳ মেয়াদ শেষ → OTP দেওয়া হবে না
        bot.send_message(chat_id, _gm_expired_text(item), parse_mode="HTML", reply_markup=restore_kb)
        return
    plat = item.get("k")
    if plat not in GMAIL_SENDERS:
        bot.send_message(chat_id, "⚠️ এই মেইলের প্ল্যাটফর্ম চেনা যায়নি। এডমিনের সাথে যোগাযোগ করুন।", reply_markup=restore_kb)
        return
    now = _gm_time.time()
    if now - _gm_cooldown.get(uid, 0) < GM_COOLDOWN_SEC:
        bot.send_message(chat_id, "⏳ একটু অপেক্ষা করে আবার চেষ্টা করুন।", reply_markup=restore_kb)
        return
    _gm_cooldown[uid] = now
    address, app_pw = item.get("e", ""), item.get("p", "")
    _gm_last[uid] = tok
    wait = bot.send_message(chat_id, "⏳ ইনবক্সে খোঁজা হচ্ছে…", reply_markup=restore_kb)
    try:
        res = gmail_fetch_latest(address, app_pw, plat)
    except imaplib.IMAP4.error as e:
        logging.warning(f"⚠️ Gmail login/IMAP error for {address}: {e}")
        try:
            bot.send_message(ADMIN_ID, f"⚠️ Gmail লগইন ব্যর্থ: <code>{_gm_e(address)}</code>\nApp Password / IMAP চেক করুন।", parse_mode="HTML")
        except Exception:
            pass
        res = "ERR"
    except Exception as e:
        logging.warning(f"⚠️ Gmail fetch error for {address}: {e}")
        res = "ERR"
    # ⚠️ wait মেসেজ ডিলিট করা যাবে না (ওতে Buy মেনুর কীবোর্ড লাগানো — ডিলিট করলে কীবোর্ড চলে যায়)
    wid = getattr(wait, "message_id", None)
    if res == "ERR":
        _gm_show(chat_id, wid, "❌ এখন মেইল চেক করা যাচ্ছে না। কিছুক্ষণ পরে আবার চেষ্টা করুন।", _gm_refresh_inline())
        return
    if not res:
        _gm_show(chat_id, wid, f"📭 এই মেইলে এখনও {_gm_e(_gm_pname(plat))} এর কোনো email আসেনি।\nকিছুক্ষণ পর আবার চেক করুন 👇",
                 _gm_refresh_inline())
        return
    _gm_send_result(chat_id, address, plat, res, tok, edit_id=wid)


def _gm_restore_kb_for(uid):
    """ইউজার এখন Gmail প্রোডাক্ট মেনুতে থাকলে সেই কীবোর্ড (নইলে None — কীবোর্ড বদলাবে না)"""
    pn = _pending_product_cache.get(str(uid))
    return get_product_buy_keyboard(str(uid), pn) if _gm_is_product(pn) else None


def _gm_banned(uid):
    try:
        return str(uid) in load_db().get("banned_users", {})
    except Exception:
        return False


@bot.callback_query_handler(func=lambda c: (c.data or "").startswith("gm_otp|"))
def cb_gmail_otp(call):
    """🔑 Get OTP ইনলাইন বাটন — বাটনের টোকেন যে মেইলের শুধু সেটারই OTP (শুধু ক্রেতা নিজে)"""
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    uid = str(call.from_user.id)
    if _gm_banned(uid):
        return
    tok = call.data.split("|", 1)[1]
    _EXECUTOR.submit(_gm_run_otp, call.message.chat.id, uid, tok, _gm_restore_kb_for(uid))


@bot.callback_query_handler(func=lambda c: c.data == "gm_refresh")
def cb_gmail_refresh(call):
    uid = str(call.from_user.id)
    tok = _gm_last.get(uid)
    if not tok:
        bot.answer_callback_query(call.id, "আবার 📩 Get OTP চাপুন।", show_alert=True)
        return
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    if _gm_banned(uid):
        return
    _EXECUTOR.submit(_gm_run_otp, call.message.chat.id, uid, tok, _gm_restore_kb_for(uid))


def _gm_get_otp_entry(user_id, product_name):
    """কীবোর্ডের 📩 Get OTP (Gmail প্রোডাক্ট মেনুতে) — শুধু এই সার্ভিসের জন্য কেনা মেইলগুলো
    INLINE বাটনে দেখায়। অন্য সার্ভিসের মেইল/OTP এখানে আসে না। মেইল টাইপ করতে হয় না।"""
    user_id = str(user_id)
    cur_plat = _gm_key_of(product_name)
    meta = GMAIL_PLATFORMS.get(cur_plat, {})
    svc = f"{meta.get('emoji', '')} {meta.get('name', 'Email')}".strip()
    mine = _gm_user_items(user_id, cur_plat)            # 🔒 শুধু এই সার্ভিসের (পুরোনো -> নতুন)
    kb = get_product_buy_keyboard(user_id, product_name)
    if not mine:
        bot.send_message(user_id,
                         f"⚠️ আপনি এখনও <b>{_gm_e(meta.get('name', 'এই সার্ভিস'))}</b> এর জন্য কোনো মেইল কেনেননি।\n"
                         "আগে মেইল কিনুন, তারপর Get OTP চাপুন।",
                         parse_mode="HTML", reply_markup=kb)
        return
    mine = mine[::-1]                                   # নতুন আগে
    inline = types.InlineKeyboardMarkup()
    _idx = _mysql_get_key(f"gm_user:{user_id}")
    _idx = _idx if isinstance(_idx, dict) else {}
    for tok, em, _pl, _ts in mine[:15]:
        _rec = _idx.get(tok)
        if _gm_is_expired(_rec):                  # ⌛ মেয়াদ শেষ
            inline.row(InlineBtn(f"⌛ Expired • {em}"[:64].strip(), style="danger", callback_data=f"gm_otp|{tok}"))
            continue
        _left = _gm_seconds_left(_rec)
        _tag = f" ⏳{_gm_fmt_left(_left)}" if _left is not None else ""
        inline.row(InlineBtn(f"{meta.get('emoji', '')} {meta.get('name', '')}{_tag} • {em}"[:64].strip(), style="primary",
                             callback_data=f"gm_otp|{tok}"))
    extra = f"\n<i>(সর্বশেষ {len(mine[:15])} টা দেখানো হয়েছে)</i>" if len(mine) > 15 else ""
    bot.send_message(user_id,
                     f"🔑 <b>Get OTP — {_gm_e(svc)}</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\nকোন মেইলের OTP লাগবে? বাটনে চাপুন 👇" + extra,
                     parse_mode="HTML", reply_markup=inline)


def _gm_email_step(message, product_name):
    uid = str(message.chat.id)
    text = (message.text or "").strip()
    kb = get_product_buy_keyboard(uid, product_name)
    if text in ("🔙 Back", "Back", "❌ Cancel") or text.startswith("/"):
        show_product_detail_with_subnav(uid, product_name, load_db(), origin="gmail")
        return
    if not _GM_EMAIL_RE.match(text):
        bot.send_message(uid, "⚠️ সঠিক মেইল ঠিকানা লিখুন (যেমন: name@gmail.com)। আবার চেষ্টা করতে 📩 Get OTP চাপুন।", reply_markup=kb)
        return
    plat = _gm_key_of(product_name)
    cand = [t for t, e, _p, _ts in _gm_user_items(uid, plat) if e.strip().lower() == text.lower()]
    if not cand:
        bot.send_message(uid, "⚠️ এই মেইলটি আপনার কেনা মেইলের তালিকায় নেই। যে মেইল কিনেছেন সেটাই দিন।", reply_markup=kb)
        return
    _EXECUTOR.submit(_gm_run_otp, uid, uid, cand[-1], kb)


