def _gm_restore_stock(product_name, header, items):
    """নেওয়া কিন্তু বিক্রি না-হওয়া মেইলগুলো আবার স্টকের সামনে ফেরত দেয়।"""
    if not items:
        return
    import csv as _csv, io as _io
    hdr = header or ["Email", "App Password"]
    buf = _io.StringIO()
    w = _csv.writer(buf, lineterminator="\n")
    w.writerow(hdr)
    for em, pw in items:
        w.writerow([f"{em}|{pw}"] if len(hdr) == 1 else [em, pw] + [""] * max(0, len(hdr) - 2))
    stream = BytesIO(buf.getvalue().encode("utf-8"))
    try:
        _restore_stock_file(product_name, stream)
    finally:
        invalidate_stock_cache(product_name)


def _gm_send_items(user_id, order_id, saved, kb, life_min=0):
    """Single: মেইল + ইনলাইন বাটন। Bulk: প্রতিটা মেইল আলাদা মেসেজে + বাটন (কোনো ফাইল নয়)।"""
    life_line = (f"⏳ <b>মেয়াদ:</b> <code>{_gm_fmt_life(life_min)}</code> (কেনার পর থেকে) — এরপর <b>Mail Expire</b> হয়ে যাবে\n\n"
                 if life_min and life_min > 0 else "")
    if len(saved) == 1:
        tok, em = saved[0]
        bot.send_message(
            user_id,
            "📮 <b>Your Gmail:</b>\n\n"
            f"<code>{_gm_e(em)}</code>\n\n"
            "👉 এই মেইল দিয়ে অ্যাকাউন্ট খুলে কোড/মেইল আসার পর <b>🔑 Get OTP</b> বাটনে চাপুন।\n\n"
            f"{life_line}"
            f"🆔 <b>Order:</b> <code>{order_id}</code>\n"
            "⚠️ <i>Please save this info!</i>",
            parse_mode="HTML", reply_markup=_gm_item_inline(tok))
        return
    bot.send_message(
        user_id,
        f"📮 মেইলগুলো নিচে দেওয়া হলো ({len(saved)} pcs) — প্রতিটার নিচে <b>Get OTP</b> ও <b>Mail Inbox</b> বাটন আছে।\n\n"
        f"{life_line}"
        f"🆔 <b>Order:</b> <code>{order_id}</code>\n"
        "⚠️ <i>Please save this info!</i>", parse_mode="HTML")
    for tok, em in saved:
        for _attempt in range(3):
            try:
                bot.send_message(user_id, f"📧 <b>Email:</b> <code>{_gm_e(em)}</code>",
                                 parse_mode="HTML", reply_markup=_gm_item_inline(tok, otp_first=True))
                break
            except Exception as e:
                if "429" in str(e) or "Too Many" in str(e):
                    _gm_time.sleep(3)
                    continue
                raise
        _gm_time.sleep(GM_BULK_SEND_DELAY)
    bot.send_message(user_id, "🎛️ নিচের বাটন থেকে বেছে নিন", reply_markup=kb)


def _gm_purchase(user_id, product_name, quantity, price, total_price, show_name,
                 current_balance, db, order_id, current_time, discount_percent=0, promo_code=None):
    """Gmail প্রোডাক্ট কেনা। process_purchase এর user-lock/in-flight ধরা অবস্থায় ডাকা হয়।
    সফল হলে True (balance কেটে অর্ডার সেভ হয়েছে), নইলে False (balance কাটেনি)।"""
    import csv as _csv, io as _io
    user_id = str(user_id)
    quantity = int(quantity)
    plat = _gm_key_of(product_name)
    kb = get_product_buy_keyboard(user_id, product_name)
    life_min = _gm_life_minutes(plat)          # ⏳ এই কেনার মেয়াদ (মিনিট) — কেনার মুহূর্তেই ফিক্সড

    if total_price <= 0:
        bot.send_message(user_id,
            f"⚠️ <b>Price Error!</b>\n\n<b>{_gm_e(show_name)}</b> এর price সেট করা নেই।\nAdmin কে জানান।\n\n📞 @{SUPPORT_USERNAME}",
            parse_mode="HTML", reply_markup=get_main_menu(user_id))
        logging.error(f"gmail purchase: zero price for {product_name}, user {user_id}")
        return False

    got, header = [], None
    with get_stock_lock(product_name):
        stock = get_stock_count(product_name)
        if stock < quantity:
            bot.send_message(user_id, t(user_id, "insufficient_stock", qty=quantity, stock=stock),
                             reply_markup=get_main_menu(user_id), parse_mode="HTML")
            return False
        try:
            sold = _gm_sold_set(plat)
            guard = 0
            while len(got) < quantity and guard < 8:
                guard += 1
                sf = read_stock_file(product_name, quantity - len(got))
                if sf is None:
                    break
                sf.seek(0)
                rows = list(_csv.reader(_io.StringIO(sf.read().decode("utf-8-sig"))))
                if len(rows) < 2:
                    break
                header = header or rows[0]
                for r in rows[1:]:
                    it = _gm_row_to_item(r)
                    if not it:
                        continue                      # ভুল ফরম্যাটের লাইন বাদ
                    ek = _gm_ekey(it[0])
                    if ek in sold:
                        continue                      # এই সার্ভিসে আগেই বিক্রি হওয়া মেইল বাদ
                    sold.add(ek)
                    got.append(it)
        except Exception as e:
            logging.error(f"gmail stock read error: {e}\n{traceback.format_exc()}")
            _gm_restore_stock(product_name, header, got)
            bot.send_message(user_id, t(user_id, "file_error"), reply_markup=get_main_menu(user_id), parse_mode="HTML")
            return False
        if len(got) < quantity:
            _gm_restore_stock(product_name, header, got)
            bot.send_message(user_id, t(user_id, "insufficient_stock", qty=quantity, stock=get_stock_count(product_name)),
                             reply_markup=get_main_menu(user_id), parse_mode="HTML")
            return False
        try:
            saved = _gm_save_items(user_id, plat, got, order_id, life_min=life_min)
        except Exception as e:
            logging.error(f"gmail save error: {e}\n{traceback.format_exc()}")
            _gm_restore_stock(product_name, header, got)
            bot.send_message(user_id, t(user_id, "file_error"), reply_markup=get_main_menu(user_id), parse_mode="HTML")
            return False

    # ── ডেলিভারি (স্টক লক ছাড়া) ──
    new_balance = round(current_balance - total_price, 2)
    try:
        bot.send_message(user_id,
            t(user_id, "purchase_success", order_id=order_id, product=show_name, qty=quantity,
              price=price, total=total_price, bal=new_balance, date=current_time,
              usd=with_usd_equiv(user_id, new_balance)),
            parse_mode="HTML")
    except Exception as e:
        logging.error(f"gmail success-msg send error: {e}")
        _gm_rollback(user_id, plat, saved)
        with get_stock_lock(product_name):
            _gm_restore_stock(product_name, header, got)
        bot.send_message(user_id, "❌ <b>Delivery ব্যর্থ হয়েছে!</b>\n\nআপনার balance কাটা হয়নি। আবার চেষ্টা করুন।",
                         parse_mode="HTML", reply_markup=get_main_menu(user_id))
        return False
    try:
        _gm_send_items(user_id, order_id, saved, kb, life_min=life_min)
    except Exception as e:
        logging.error(f"gmail delivery error: {e}\n{traceback.format_exc()}")
        try:
            bot.send_message(user_id, "⚠️ কিছু মেইল পাঠাতে সমস্যা হয়েছে। 📩 Get OTP বাটন চেপে আপনার কেনা মেইল দেখুন।", reply_markup=kb)
        except Exception:
            pass

    # ── balance কাটো ও অর্ডার সেভ ──
    db["users"][user_id]["balance"] = new_balance
    _update_db_cache_in_place(db)
    order_entry = {
        "id": order_id, "product_name": show_name, "quantity": quantity,
        "price_per_unit": price, "total": total_price,
        "date": current_time, "status": "completed", "source": "gmail"
    }
    if discount_percent > 0:
        order_entry["discount_percent"] = discount_percent
    if promo_code:
        order_entry["promo_code"] = promo_code
    orders_list = _normalize_orders_list(db["users"][user_id].get("orders", []))
    orders_list.append(order_entry)
    db["users"][user_id]["orders"] = orders_list
    update_db_path(f"/users/{user_id}", db["users"][user_id])
    return True


# ───────────────────────────────────────────────────────────────────────────
# 📤 অ্যাডমিন স্টক আপলোড (Upload Stock) — Gmail প্রোডাক্টের জন্য
# ───────────────────────────────────────────────────────────────────────────
_GM_STOCK_HEADER = ["Email", "App Password"]


def _gm_normalize_stock_file(product_name):
    """আগের স্টক ফাইলের heading `Email | App Password` না হলে (যেমন .txt এর `Data`) এক ফরম্যাটে আনে।"""
    path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
    if not os.path.exists(path):
        return
    with get_stock_lock(product_name):
        wb = openpyxl.load_workbook(path)
        ws = wb.active
        allr = [[_stock_cell_text(c) for c in r] for r in ws.iter_rows(values_only=False)]
        wb.close()
        if not allr:
            return
        if [h.strip().lower() for h in allr[0][:2]] == ["email", "app password"] and len([h for h in allr[0] if h]) == 2:
            return
        items = []
        for r in allr:                       # heading সহ সব row দেখা হয় (heading ছাড়া ফাইলও চলে)
            it = _gm_row_to_item(r)
            if it:
                items.append(it)
        out = openpyxl.Workbook()
        o = out.active
        o.append(_GM_STOCK_HEADER)
        for em, pw in items:
            o.append([em, pw])
        out.save(path)
        out.close()
    invalidate_stock_cache(product_name)


def _gm_stock_upload(admin_uid, product_name, data_bytes, filename, quiet=False, stats=None):
    """Admin এর ফাইল (.txt/.csv/.xlsx) -> ফরম্যাট যাচাই + ডুপ্লিকেট বাদ -> স্টকে merge।
    Return: (merge_mode, added_count, old_count) — stock_merge_upload_bytes এর মতোই।"""
    import csv as _csv, io as _io
    plat = _gm_key_of(product_name)
    rows, _kind = _stock_rows_from_upload(data_bytes, filename)
    _gm_normalize_stock_file(product_name)
    seen = _gm_sold_set(plat)
    path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
    if os.path.exists(path):
        wb = openpyxl.load_workbook(path, read_only=True)
        for i, r in enumerate(wb.active.iter_rows(values_only=True)):
            if i == 0:
                continue
            it = _gm_row_to_item(["" if c is None else str(c) for c in r])
            if it:
                seen.add(_gm_ekey(it[0]))
        wb.close()
    out, dup, bad = [], 0, 0
    for r in rows:
        cells = [c for c in r if str(c).strip()]
        if not cells:
            continue
        it = _gm_row_to_item(r)
        if not it:
            first = str(cells[0]).strip().lower()
            if "@" not in first and first in ("email", "gmail", "mail", "email|app password", "data"):
                continue                      # heading row
            bad += 1
            continue
        ek = _gm_ekey(it[0])
        if ek in seen:
            dup += 1
            continue
        seen.add(ek)
        out.append(it)
    if stats is not None:
        stats.update(added=len(out), dup=dup, bad=bad)
    if not out:
        raise ValueError(f"কোনো নতুন সঠিক `email|app_password` লাইন পাওয়া যায়নি (ডুপ্লিকেট/বিক্রি-হওয়া: {dup}, ভুল ফরম্যাট: {bad})")
    buf = _io.StringIO()
    w = _csv.writer(buf, lineterminator="\n")
    w.writerow(_GM_STOCK_HEADER)
    for em, pw in out:
        w.writerow([em, pw])
    res = stock_merge_upload_bytes(product_name, buf.getvalue().encode("utf-8"), "gmail_stock.csv")
    if (dup or bad) and not quiet:
        try:
            bot.send_message(admin_uid,
                f"ℹ️ <b>Gmail স্টক ফিল্টার:</b> ✅ নতুন {len(out)} টা যোগ হয়েছে।\n"
                f"♻️ ডুপ্লিকেট / এই সার্ভিসে আগেই বিক্রি হওয়া / স্টকে আগে থেকেই আছে: <b>{dup}</b> টা বাদ\n"
                f"⚠️ ভুল ফরম্যাট (name@gmail.com|app_password নয়): <b>{bad}</b> টা বাদ",
                parse_mode="HTML")
        except Exception:
            pass
    return res


# ───────────────────────────────────────────────────────────────────────────
# 📮 BULK API GMAIL STOCK — একটা ফাইল আপলোড দিলে Gmail API এর সব সার্ভিসেই স্টক যোগ হয়
#    (একই Gmail একাধিক সার্ভিসে আলাদাভাবে বিক্রি হতে পারে — প্রতি সার্ভিসের sold-সেট আলাদা,
#    তাই প্রতিটা সার্ভিসে ডুপ্লিকেট/বিক্রি-হওয়া মেইল নিজ নিজ সার্ভিসে আলাদাভাবে ফিল্টার হয়)
# ───────────────────────────────────────────────────────────────────────────
def _gm_bulk_stock_prompt(user_id):
    """অ্যাডমিন প্যানেলের 📮 Bulk API Gmail Stock বাটন → ফাইল চাওয়া হয়।"""
    msg = bot.send_message(
        user_id,
        "📮 <b>Bulk API Gmail Stock</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"📎 <b>.txt / .csv / .xlsx</b> ফাইল পাঠান — স্টক <b>সব {len(GMAIL_PLATFORMS)}টা সার্ভিসে</b> একসাথে যোগ হবে।\n\n"
        "📝 ফরম্যাট (প্রতি লাইনে ১টা): <code>name@gmail.com|app_password</code>\n"
        "<i>ডুপ্লিকেট ও ভুল লাইন নিজে থেকে বাদ যাবে।</i>",
        parse_mode="HTML", reply_markup=get_cancel_button(user_id))
    bot.register_next_step_handler(msg, _gm_bulk_stock_step)


def _gm_bulk_stock_step(message):
    user_id = str(message.chat.id)
    if (message.text or "") in ("❌ Cancel", "❌ বাতিল"):
        show_admin_panel(user_id); return
    if not is_admin(user_id):
        return
    if message.content_type != "document":
        msg = bot.send_message(user_id, "❌ <b>একটা .txt / .csv / .xlsx ফাইল পাঠান!</b>",
                               parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, _gm_bulk_stock_step); return
    if not _is_stock_upload_name(message.document.file_name):
        msg = bot.send_message(user_id, "❌ <b>ভুল ফরম্যাট!</b> শুধু .xlsx, .csv বা .txt।",
                               parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, _gm_bulk_stock_step); return
    try:
        info = bot.get_file(message.document.file_id)
        data = bot.download_file(info.file_path)
    except Exception as e:
        logging.error(f"gm bulk stock download error: {e}")
        bot.send_message(user_id, f"❌ ফাইল ডাউনলোড করা যায়নি: {_gm_e(e)}", parse_mode="HTML",
                         reply_markup=get_main_menu(user_id))
        return
    wait = bot.send_message(user_id, f"⏳ <b>{len(GMAIL_PLATFORMS)}টা সার্ভিসে স্টক যোগ হচ্ছে…</b>", parse_mode="HTML")
    _EXECUTOR.submit(_gm_bulk_stock_run, user_id, data, message.document.file_name, wait.message_id)


def _gm_bulk_stock_run(user_id, data, filename, wait_msg_id=None):
    db = load_db()
    lines, total_added, ok_services, skipped = [], 0, 0, 0
    bad_total = None
    for key, meta in GMAIL_PLATFORMS.items():
        pn = meta["product"]
        if pn not in db.get("products", {}):
            skipped += 1                      # admin এই সার্ভিসের প্রোডাক্ট ডিলিট করে রাখলে বাদ
            continue
        st = {}
        label = f"{meta['emoji']} {_gm_e(meta['name'])}"
        try:
            _gm_stock_upload(user_id, pn, data, filename, quiet=True, stats=st)
            added = st.get("added", 0)
            total_added += added
            ok_services += 1
            lines.append(f"{label}: <b>+{added}</b>  (মোট <code>{get_stock_count(pn)}</code>)")
        except ValueError:
            lines.append(f"{label}: নতুন কিছু নেই <i>(সব ডুপ্লিকেট/বিক্রিত)</i>")
        except Exception as e:
            logging.error(f"gm bulk stock error for {pn}: {e}\n{traceback.format_exc()}")
            lines.append(f"{label}: ❌ error")
        if bad_total is None and "bad" in st:
            bad_total = st["bad"]
    try:
        if wait_msg_id:
            bot.delete_message(user_id, wait_msg_id)
    except Exception:
        pass
    head = (f"✅ <b>Bulk Gmail Stock সম্পন্ন</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
            f"📄 ফাইল: <code>{_gm_e(filename)}</code>\n"
            f"📦 স্টক যোগ হয়েছে: <b>{ok_services}</b> টা সার্ভিসে | মোট <b>+{total_added}</b> pcs\n")
    if bad_total:
        head += f"⚠️ ভুল ফরম্যাট (email|app_password নয়): <b>{bad_total}</b> লাইন বাদ\n"
    if skipped:
        head += f"ℹ️ {skipped}টা সার্ভিসের প্রোডাক্ট নেই — বাদ গেছে\n"
    text = head + "\n" + "\n".join(lines)
    try:
        bot.send_message(user_id, text[:4000], parse_mode="HTML", reply_markup=get_main_menu(user_id))
    except Exception as e:
        logging.error(f"gm bulk stock summary send error: {e}")


