def _firebase_to_list(value, default_type):
    """
    MySQL DB list/array কে dict হিসেবে return করে।
    এখানে যদি value None হয় তাহলে default দিই।
    list টাইপের field গুলো (banned_users, verified_trxids, blocked_trxids)
    MySQL এ dict আকারে আসতে পারে — এগুলোকে list এ convert করি।
    """
    if value is None:
        return default_type() if callable(default_type) else default_type
    if isinstance(default_type, list) or default_type is list:
        if isinstance(value, dict):
            return list(value.values())
        if isinstance(value, list):
            return [v for v in value if v is not None]
        return []
    return value

def save_db(data, _async=True):
    """MySQL Database তে পুরো DB save করো।
    ⚡ FAST: cache invalidate না করে নতুন data দিয়ে cache update করো।
    পরের load_db() MySQL hit করবে না — instant response।

    ⚠️ WARNING: এই function পুরো DB (~10MB) write করে — MySQL এ ভারী load পড়ে।
    ছোট changes এর জন্য update_db_path() বা patch_db_path() ব্যবহার করো।
    যেমন: update_db_path(f"/users/{user_id}", db["users"][user_id])
    """
    _update_db_cache_in_place(data)
    if _async:
        _EXECUTOR.submit(_save_db_sync, data)
        return True
    return _save_db_sync(data)

def _update_db_cache_in_place(data):
    """Cache invalidate না করে নতুন data দিয়ে সরাসরি update করো।
    Section cache ও update করো।
    """
    global _db_cache, _db_cache_time
    now_ts = _time_module.time()
    with _section_cache_lock:
        # Section cache এ relevant keys update করো
        for section in ("users", "deposits", "config", "txn"):
            keys = _get_section_keys(section)
            section_update = {k: data[k] for k in keys if k in data}
            if section_update:
                existing = _section_cache.get(section)
                if existing:
                    merged = dict(existing[0])
                    merged.update(section_update)
                    _section_cache[section] = (merged, now_ts)
                else:
                    _section_cache[section] = (section_update, now_ts)
        # _db_cache backward compat
        new_cache = {}
        for k, v in data.items():
            if isinstance(v, dict):
                new_cache[k] = dict(v)
            elif isinstance(v, list):
                new_cache[k] = list(v)
            else:
                new_cache[k] = v
        _db_cache = new_cache
        _db_cache_time = now_ts

def _save_db_sync(data):
    """Synchronous MySQL save — background thread এ চলে।"""
    try:
        upload = {}
        for key, val in data.items():
            if isinstance(val, list):
                upload[key] = {str(i): v for i, v in enumerate(val)} if val else {}
            else:
                upload[key] = val
        _fb_ref("/").set(upload)
        return True
    except Exception as e:
        logging.error(f"MySQL save_db error: {e}")
        tmp_file = DB_FILE + ".tmp"
        try:
            with open(tmp_file, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=4, ensure_ascii=False)
            os.replace(tmp_file, DB_FILE)
        except:
            pass
        return False

# ✅ নামে "/" থাকলে (যেমন "Netflix 1/2 Month") path-based write ভেঙে যেত → price/description save হতো না।
#    এই helper নিরাপদ নামে আগের মতো path write করে, বিপজ্জনক নামে পুরো section dict লেখে।
def _safe_set_key(section, name, value):
    """section = 'products' | 'product_details'; value = নতুন মান।"""
    db = load_db()
    db.setdefault(section, {})[name] = value
    if "/" in str(name) or str(name).strip() != str(name) or not str(name):
        update_db_path(f"/{section}", db[section])
    else:
        update_db_path(f"/{section}/{name}", value)

def _safe_set_subkey(section, name, sub, value):
    db = load_db()
    d = db.setdefault(section, {}).setdefault(name, {})
    if not isinstance(d, dict):
        d = db[section][name] = {}
    d[sub] = value
    if "/" in str(name):
        update_db_path(f"/{section}", db[section])
    else:
        update_db_path(f"/{section}/{name}/{sub}", value)

def update_db_path(path, value, _async=True):
    """MySQL এর specific path শুধু update করো (পুরো DB write না করে)।
    ⚡ FAST: cache invalidate না করে — পরের load_db() instant থাকবে।
    """
    # path থেকে top-level key বের করে cache update করো
    _patch_cache_for_path(path, value)
    if _async:
        _EXECUTOR.submit(_update_db_path_sync, path, value)
        return True
    return _update_db_path_sync(path, value)

def _patch_cache_for_path(path, value):
    """Cache তে specific path update করো — section cache এ directly patch।
    ✅ FIX: 3-level deep path যেমন /users/{id}/balance সরাসরি patch করো।
    """
    global _db_cache
    parts = [p for p in path.strip("/").split("/") if p]
    if not parts:
        return
    top = parts[0]
    section = _get_section_name(top)

    with _section_cache_lock:
        cached = _section_cache.get(section)
        if cached:
            sec_data = cached[0]
            if len(parts) == 1:
                # /users → পুরো top-level replace
                sec_data[top] = value
            elif len(parts) == 2 and top in sec_data and isinstance(sec_data[top], dict):
                # /users/12345 → user object replace
                sec_data[top][parts[1]] = value
            elif (len(parts) == 3
                  and top in sec_data
                  and isinstance(sec_data.get(top), dict)
                  and isinstance(sec_data[top].get(parts[1]), dict)):
                # /users/12345/balance → শুধু balance field update
                sec_data[top][parts[1]][parts[2]] = value
            else:
                # অজানা deep path — এই section invalidate করো
                _section_cache.pop(section, None)
                return
            # _db_cache ও sync করো (backward compat)
            if _db_cache is not None:
                if len(parts) == 1:
                    _db_cache[top] = value
                elif len(parts) == 2 and top in _db_cache and isinstance(_db_cache[top], dict):
                    _db_cache[top][parts[1]] = value
                elif (len(parts) == 3 and top in _db_cache
                      and isinstance(_db_cache.get(top), dict)
                      and isinstance(_db_cache[top].get(parts[1]), dict)):
                    _db_cache[top][parts[1]][parts[2]] = value

def _update_db_path_sync(path, value):
    try:
        if isinstance(value, list):
            value = {str(i): v for i, v in enumerate(value)} if value else {}
        _fb_ref(path).set(value)
        return True
    except Exception as e:
        logging.error(f"MySQL update_db_path error [{path}]: {e}")
        return False

def patch_db_path(path, updates: dict):
    """MySQL এর specific path এ partial update (merge) করো।
    ⚡ FAST: cache তে সাথে সাথে merge করো — load_db() instant থাকবে।
    """
    # Cache তে locally merge করো
    parts = [p for p in path.strip("/").split("/") if p]
    if _db_cache is not None and len(parts) <= 2:
        with _db_cache_lock:
            if _db_cache is not None:
                top = parts[0]
                if len(parts) == 1:
                    if isinstance(_db_cache.get(top), dict):
                        _db_cache[top].update(updates)
                elif len(parts) == 2:
                    if isinstance(_db_cache.get(top), dict) and isinstance(_db_cache[top].get(parts[1]), dict):
                        _db_cache[top][parts[1]].update(updates)
    else:
        _invalidate_db_cache()
    try:
        _EXECUTOR.submit(_fb_ref(path).update, updates)
        return True
    except Exception as e:
        logging.error(f"MySQL patch_db_path error [{path}]: {e}")
        return False

def log_action(action, user_id, details=""):
    logging.info(f"[{get_now()}] User: {user_id} | Action: {action} | Details: {details}")

# ===========================
# DB CACHE — Section-wise আলাদা cache (MySQL download ~95% কম)
# ===========================
# ┌─────────────────────────────────────────────────────────────┐
# │  Section         │ Size    │ TTL    │ কারণ                  │
# │  users           │ 1.44MB  │ 600s   │ সবচেয়ে বড়, কম বদলায় │
# │  deposit_requests│ 182KB   │ 120s   │ দ্রুত update দরকার    │
# │  config (products│         │        │                       │
# │  settings,promo) │ ~50KB   │ 600s   │ খুব কম বদলায়         │
# │  transactions    │ ~40KB   │ 300s   │ medium frequency      │
# └─────────────────────────────────────────────────────────────┘
import copy as _copy_mod

# Section grouping
_SECTION_USERS       = {"users"}
_SECTION_DEPOSITS    = {"deposit_requests", "dollar_orders"}
_SECTION_CONFIG      = {"products", "product_details", "settings", "promo_codes",
                        "promo_usage", "flash_sales", "sub_products", "product_buttons",
                        "bulkmail_products", "hotmail143_products", "api_dashboard",
                        "banned_users", "extra_admins", "tickets",
                        "vpn_products_3d", "vpn_products_6d", "vpn_products_14d", "vpn_products_30d",
                        "proxy_products_abc", "proxy_products_cli", "proxy_products_9proxy",
                        "proxy_products_711proxy",
                        "proxy_products_owl", "proxy_products_p5", "proxy_products_p6", "proxy_products_p7", "proxy_products_p8", "proxy_products_p9", "proxy_products_p10",
                        "nineproxy_api_packages", "p711proxy_api_packages"}
_SECTION_TXN         = {"sms_pending_trxids", "verified_trxids", "verified_trxids_dates",
                        "trx_attempts", "blocked_trxids", "_pending_refer"}

_TTL_USERS    = 600   # 10 মিনিট — balance update_db_path দিয়ে in-place হয়
_TTL_DEPOSITS = 120   # 2 মিনিট — deposit status দ্রুত দেখাবে
_TTL_CONFIG   = 600   # 10 মিনিট — products/settings খুব কম বদলায়
_TTL_TXN      = 300   # 5 মিনিট

# section_name → (data_dict, timestamp)
_section_cache = {}
_section_cache_lock = threading.Lock()

# backward compat — পুরনো code এর জন্য
_DB_CACHE_TTL = 300
_db_cache = None
_db_cache_time = 0
_db_cache_lock = _section_cache_lock

def _get_section_name(key):
    """key থেকে section নাম বের করো।"""
    if key in _SECTION_USERS:    return "users"
    if key in _SECTION_DEPOSITS: return "deposits"
    if key in _SECTION_TXN:      return "txn"
    return "config"

def _get_section_ttl(section):
    return {"users": _TTL_USERS, "deposits": _TTL_DEPOSITS,
            "config": _TTL_CONFIG, "txn": _TTL_TXN}.get(section, 300)

def _get_section_keys(section):
    return {"users": _SECTION_USERS, "deposits": _SECTION_DEPOSITS,
            "config": _SECTION_CONFIG, "txn": _SECTION_TXN}.get(section, set())

def _load_one_key(key):
    """একটা single DB key MySQL থেকে fetch করো (helper — parallel এ চালানোর জন্য)।"""
    try:
        raw = _fb_ref(f"/{key}").get()
        default_val = _DB_DEFAULT.get(key)
        if raw is None:
            return (list(default_val) if isinstance(default_val, list)
                    else dict(default_val) if isinstance(default_val, dict)
                    else (default_val if default_val is not None else {}))
        elif isinstance(default_val, list):
            return _firebase_to_list(raw, list)
        else:
            return raw
    except Exception as e:
        logging.error(f"MySQL load_section key [{key}] error: {e}")
        default_val = _DB_DEFAULT.get(key)
        return (list(default_val) if isinstance(default_val, list)
                else dict(default_val) if isinstance(default_val, dict)
                else (default_val if default_val is not None else {}))

def _load_section(section):
    """একটা section MySQL থেকে load করো — key গুলো parallel এ fetch হয়, sequentially না।
    আগে 'config' section এর ২২টা key একটার পর একটা নেটওয়ার্ক কল করত (প্রতিটা key = ১টা
    round-trip) — cache miss হলে এই ধারাবাহিক অপেক্ষাই main menu / বাটন লোড হতে দেরির
    আসল কারণ ছিল। এখন সব key একসাথে parallel থ্রেডে (বিদ্যমান _EXECUTOR pool ব্যবহার করে)
    fetch হয়, তাই মোট সময় লাগে সবচেয়ে ধীর একটা key এর সমান, ২২টার সমষ্টির সমান না।"""
    keys = list(_get_section_keys(section))
    result = {}
    if len(keys) <= 1:
        for key in keys:
            result[key] = _load_one_key(key)
        return result
    futures = {_EXECUTOR.submit(_load_one_key, key): key for key in keys}
    for future in as_completed(futures):
        key = futures[future]
        result[key] = future.result()
    return result

def _get_cached_section(section):
    """Cache থেকে section নাও, expire হলে MySQL থেকে reload।"""
    now_ts = _time_module.time()
    ttl = _get_section_ttl(section)

    # Fast path — lock ছাড়া
    cached = _section_cache.get(section)
    if cached and (now_ts - cached[1]) < ttl:
        return dict(cached[0])

    with _section_cache_lock:
        cached = _section_cache.get(section)
        if cached and (now_ts - cached[1]) < ttl:
            return dict(cached[0])
        data = _load_section(section)
        _section_cache[section] = (data, now_ts)
        return dict(data)

# ═══════════════════════════════════════════════════════════
# ⚡ CACHE WARMER — idle থাকার পর প্রথম ক্লিকে delay বন্ধ করার ফিক্স
# ═══════════════════════════════════════════════════════════
# সমস্যা: প্রতিটা section এর TTL (120s-600s) শেষ হয়ে গেলে, ইউজার যখন
# অনেকক্ষণ পর প্রথম বাটনে ক্লিক করে, ঠিক সেই request-টাই MySQL থেকে
# fresh data আনার জন্য block হয়ে যায় — ফলে ওই একটা ক্লিকেই noticeable
# delay আসে (network round-trip ইউজারকে wait করায়)।
#
# ফিক্স: একটা background thread প্রতি 20 সেকেন্ডে প্রতিটা section এর
# cache age চেক করে, TTL শেষ হওয়ার আগেই (buffer সহ) নিজে থেকে refresh
# করে রাখে। ফলে ইউজারের request কখনোই cold MySQL fetch এর জন্য wait
# করে না — সবসময় already-warm cache থেকে instant response পায়।
_CACHE_WARM_BUFFER = 20   # TTL শেষ হওয়ার এই কয় সেকেন্ড আগেই refresh করো
_CACHE_WARM_INTERVAL = 20  # কত সেকেন্ড পর পর চেক করবে

def cache_warmer_worker():
    """Background thread — সব section এর cache কে TTL expire হওয়ার আগেই
    proactively refresh করে রাখে, যাতে ইউজারের বাটন ক্লিক কখনো cold
    MySQL fetch এর জন্য আটকে না থাকে (idle এর পরের প্রথম ক্লিকেও fast)।"""
    while True:
        try:
            now_ts = _time_module.time()
            for section in ("users", "deposits", "config", "txn"):
                ttl = _get_section_ttl(section)
                cached = _section_cache.get(section)
                age = (now_ts - cached[1]) if cached else None
                needs_refresh = (cached is None) or (age >= (ttl - _CACHE_WARM_BUFFER))
                if needs_refresh:
                    data = _load_section(section)
                    with _section_cache_lock:
                        _section_cache[section] = (data, _time_module.time())
        except Exception as e:
            logging.error(f"cache_warmer_worker error: {e}")
        _time_module.sleep(_CACHE_WARM_INTERVAL)

def load_db():
    """MySQL থেকে DB load করো — section-wise cache।
    প্রতিটা section আলাদাভাবে cache হয়, মোট download ~95% কম।
    """
    result = {}
    for section in ("users", "deposits", "config", "txn"):
        section_data = _get_cached_section(section)
        result.update(section_data)

    # _DB_DEFAULT এ যেসব key আছে কিন্তু কোনো section এ নেই
    for key, default_val in _DB_DEFAULT.items():
        if key not in result:
            result[key] = (list(default_val) if isinstance(default_val, list)
                           else dict(default_val) if isinstance(default_val, dict)
                           else default_val)

    # ✅ SAFETY NET: list-টাইপ field (banned_users, verified_trxids, blocked_trxids)
    # কোনো কারণে cache patch এর ফলে dict হয়ে গেলে এখানেই আবার list এ ফিরিয়ে আনো।
    # নাহলে .append()/.remove() মতো list-only অপারেশন crash করে (যেমন ban/unban বাগ)।
    for key, default_val in _DB_DEFAULT.items():
        if isinstance(default_val, list) and isinstance(result.get(key), dict):
            result[key] = list(result[key].values())

    # backward compat: _db_cache update করো
    global _db_cache, _db_cache_time
    _db_cache = result
    _db_cache_time = _time_module.time()
    return result

def _invalidate_db_cache():
    """DB write হওয়ার পর cache clear করো।"""
    global _db_cache, _db_cache_time
    with _section_cache_lock:
        _db_cache = None
        _db_cache_time = 0
        # Section cache ও clear করো
        _section_cache.clear()

def _invalidate_section_for_key(key):
    """Specific key এর section cache clear করো।"""
    section = _get_section_name(key)
    with _section_cache_lock:
        _section_cache.pop(section, None)

# ═══════════════════════════════════════════════════════════
# 👑 ADMIN MANAGEMENT — Multi-Admin Support
# ═══════════════════════════════════════════════════════════
# ADMIN_ID (owner) সবসময় admin থাকবে এবং কখনো remove করা যাবে না।
# তার পাশাপাশি Admin Panel → "👑 Admin Management" থেকে owner চাইলে
# আরো Chat ID কে admin বানাতে পারবে (Add) বা admin তালিকা থেকে
# সরিয়ে দিতে পারবে (Delete)। এই extra admin গুলোর chat_id list
# MySQL এ /extra_admins path এ targeted-write দিয়ে save হয়।
# ═══════════════════════════════════════════════════════════
_admin_list_cache = {"ids": None, "time": 0}
_ADMIN_LIST_CACHE_TTL = 20  # 20s — Add/Remove করার সাথে সাথে দ্রুত reflect হবে

def get_extra_admins():
    """DB থেকে extra_admins (owner ADMIN_ID বাদে) list রিটার্ন করে — string chat_id list।"""
    now_ts = _time_module.time()
    if _admin_list_cache["ids"] is not None and (now_ts - _admin_list_cache["time"]) < _ADMIN_LIST_CACHE_TTL:
        return _admin_list_cache["ids"]
    try:
        db = load_db()
        extra = db.get("extra_admins", [])
        if isinstance(extra, dict):
            extra = list(extra.values())
        extra = [str(a) for a in extra if a]
    except Exception:
        extra = []
    _admin_list_cache["ids"] = extra
    _admin_list_cache["time"] = now_ts
    return extra

def _invalidate_admin_list_cache():
    _admin_list_cache["ids"] = None
    _admin_list_cache["time"] = 0

def is_admin(user_id):
    """মূল Owner (ADMIN_ID) অথবা Admin Management থেকে যোগ করা যেকোনো
    extra admin হলে True — Admin Panel/কমান্ডের সব জায়গায় এটা দিয়ে check করো।"""
    uid = str(user_id)
    if uid == str(ADMIN_ID):
        return True
    return uid in get_extra_admins()

def is_owner(user_id):
    """শুধুমাত্র মূল Owner (ADMIN_ID)। Admin Management ফিচার (Add/Delete Admin)
    শুধু owner ব্যবহার করতে পারবে — যাতে কোনো added admin নিজে নিজে আরো
    admin বানিয়ে/সরিয়ে ফেলতে না পারে।"""
    return str(user_id) == str(ADMIN_ID)

# ===========================
# SUBSCRIPTION CHECK (with cache — Telegram API call কমাতে)
# ===========================

_sub_cache = {}          # {uid: (True/False, timestamp)}
_SUB_CACHE_TTL = 120     # 120s cache — background এ refresh হয়, তাই বেশি রাখলেও সমস্যা নেই
_sub_cache_lock = threading.Lock()
_sub_refresh_inflight = set()   # ⚡ একই uid এর জন্য একসাথে একাধিক background refresh আটকাতে
_sub_refresh_inflight_lock = threading.Lock()

def _refresh_sub_cache_background(uid_str):
    """Stale cache-কে ব্যাকগ্রাউন্ডে (thread pool এ) রিফ্রেশ করে — কোনো ইউজারকে
    এর জন্য অপেক্ষা করতে হয় না। একই uid এর জন্য একসাথে একাধিকবার submit
    হওয়া আটকানো হয়েছে (in-flight guard)।"""
    with _sub_refresh_inflight_lock:
        if uid_str in _sub_refresh_inflight:
            return
        _sub_refresh_inflight.add(uid_str)
    try:
        _refresh_sub_cache_sync(uid_str)
    finally:
        with _sub_refresh_inflight_lock:
            _sub_refresh_inflight.discard(uid_str)

def is_subscribed(uid):
    """
    Subscription check — cache সহ, stale-while-revalidate।
    ⚡ FIX (slow keyboard button response): আগে cache 30s এ expire হলেই প্রতিটা
    keyboard বাটন ক্লিকে bot সরাসরি (synchronous) Telegram getChatMember API
    কল করত এবং সেই রেসপন্স না আসা পর্যন্ত ইউজারকে আটকে রাখত (worst-case
    per-channel timeout পর্যন্ত ৩ সেকেন্ড) — এই কারণেই মাঝে মাঝে বাটন ক্লিকে
    দেরি হতো। এখন cache-এ কোনো ভ্যালু থাকলে (এমনকি stale/expired হলেও) সেটা
    সাথে সাথেই রিটার্ন হয় (0ms), আর expired হলে ব্যাকগ্রাউন্ডে (thread pool এ)
    পরের বারের জন্য fresh check চালানো হয় — ইউজারের ক্লিকের রেসপন্স কখনোই
    Telegram API কলের জন্য আটকে থাকে না। শুধু একদম প্রথমবার (কোনো cache-ই
    নেই) synchronous চেক হয়, যাতে না-জয়েন করা ইউজার সাথে সাথেই ধরা পড়ে।
    """
    uid_str = str(uid)
    now_ts  = _time_module.time()

    cached = _sub_cache.get(uid_str)
    if cached:
        age = now_ts - cached[1]
        if age >= _SUB_CACHE_TTL:
            # ⚡ Stale — ব্যাকগ্রাউন্ডে রিফ্রেশ করো, কিন্তু ইউজারকে আটকে রেখো না
            _EXECUTOR.submit(_refresh_sub_cache_background, uid_str)
        return cached[0]  # ⚡ instant — 0ms (fresh বা stale, দুই ক্ষেত্রেই)

    # কোনো cache-ই নেই (একদম প্রথম ইন্টার‍্যাকশন) — শুধু তখনই sync check
    return _refresh_sub_cache_sync(uid_str)

def _refresh_sub_cache_sync(uid_str):
    """Subscription check — সব channel parallel এ check করো (fast)।
    API error হলে True ধরো — subscribed user কে block করবে না।
    শুধু explicitly 'left' বা 'kicked' হলেই False।
    """
    # ⚡ সব channel একসাথে parallel check — sequential loop এর চেয়ে fast
    results = [True] * len(CHANNELS)

    def _check_one(idx, ch):
        try:
            status = bot.get_chat_member(ch["id"], uid_str).status
            if status in ("left", "kicked"):
                results[idx] = False
        except Exception as _e:
            logging.warning(f"sub_check API error uid={uid_str} ch={ch['id']}: {_e}")
            results[idx] = True  # error → assume subscribed
            # 🆕 FIX: ভুল Channel ID বা bot channel এ Admin না থাকলে এই error
            # *প্রতিটা* ইউজারের চেকেই বারবার হয় — মানে force-join পুরোপুরি silently
            # bypass হয়ে যায়, কিন্তু আগে কোথাও admin কে জানানো হতো না। এখন এই
            # misconfiguration ধরা পড়লে admin কে (বেশি স্প্যাম এড়াতে সর্বোচ্চ
            # ১৫ মিনিটে ১বার) সরাসরি মেসেজ করে জানানো হয়।
            _notify_admin_channel_misconfig(ch)

    threads = []
    for i, ch in enumerate(CHANNELS):
        t = threading.Thread(target=_check_one, args=(i, ch), daemon=True)
        t.start()
        threads.append(t)
    for t in threads:
        t.join(timeout=3)  # max 3s wait per check

    result = all(results)
    _sub_cache[uid_str] = (result, _time_module.time())
    return result

_channel_misconfig_alert_lock = threading.Lock()
_channel_misconfig_last_alert = {}  # channel_id(str) → last alert unix timestamp

def _notify_admin_channel_misconfig(ch):
    """একই চ্যানেলের জন্য বারবার মেসেজ না পাঠিয়ে ১৫ মিনিটে সর্বোচ্চ ১বার admin কে
    জানায় যে force-join এর subscription check fail করছে — সম্ভবত ভুল Channel ID
    অথবা বট ওই চ্যানেলে Admin না থাকার কারণে। ঠিক করতে /channelcheck কমান্ড আছে।"""
    ch_id = str(ch.get("id"))
    now_ts = _time_module.time()
    with _channel_misconfig_alert_lock:
        last = _channel_misconfig_last_alert.get(ch_id, 0)
        if now_ts - last < 900:  # 15 মিনিট cooldown
            return
        _channel_misconfig_last_alert[ch_id] = now_ts
    try:
        bot.send_message(
            ADMIN_ID,
            f"⚠️ <b>Force-Join Channel Error!</b>\n\n"
            f"Channel <code>{ch_id}</code> এর subscription check বারবার fail করছে — "
            f"এর মানে এই চ্যানেলের জন্য force-join কাজ করছে না (সবাইকে ভুলভাবে "
            f"'joined' ধরে নেওয়া হচ্ছে)।\n\n"
            f"সম্ভাব্য কারণ:\n"
            f"• Channel ID ভুল/ভাঙা\n"
            f"• বট এই চ্যানেলে Admin না\n\n"
            f"বিস্তারিত দেখতে <code>/channelcheck</code> কমান্ড চালান।",
            parse_mode="HTML"
        )
    except Exception as _e:
        logging.error(f"_notify_admin_channel_misconfig: alert send failed: {_e}")

def _refresh_sub_cache(uid_str):
    """Background refresh — return value ignore করা হয়।"""
    _refresh_sub_cache_sync(uid_str)

def invalidate_sub_cache(uid):
    """User join verify করলে cache clear করো।"""
    _sub_cache.pop(str(uid), None)

def get_join_markup(user_id):
    lang = get_user_lang(user_id)
    markup = types.InlineKeyboardMarkup(row_width=1)
    for i, ch in enumerate(CHANNELS, 1):
        markup.add(InlineBtn(
            LANG[lang]["join_channel_btn"].format(n=i), style="success", url=ch['link']))
    markup.add(InlineBtn(LANG[lang]["verify_join"], style="success", callback_data="check_join"))
    return markup

# 🆕 FIX (force-join gap): এতদিন এই subscription check শুধু catch-all callback
# handler (`func=lambda call: True`, একদম সবার শেষে fallback হিসেবে) এর ভেতরে ছিল।
# কিন্তু pyTelegramBotAPI প্রথম যেই handler match করে শুধু সেটাই কল করে, তারপর
# বাকিগুলো আর চেক করে না (break হয়ে যায়)। allvpn_, admin_vpn_, rp_/rpm_,
# edumail_, dep_method_, deposit_start ইত্যাদি prefix-ভিত্তিক আলাদা
# callback_query_handler গুলো catch-all এর *আগে* register হওয়ায় সেগুলোতে ক্লিক
# করলে subscription check-ই রান হতো না — ফলে join না করা বা channel থেকে বের
# হয়ে যাওয়া ইউজারও শপ/VPN/Real Proxy/Edu Mail/Deposit বাটনগুলো ব্যবহার করে
# ফেলতে পারত। এই shared helper ফাংশনটা এখন প্রতিটা আলাদা handler এর একদম
# শুরুতে বসানো হয়েছে যাতে "যেকোনো বাটনে ক্লিক" করলেই join enforce হয়।
def enforce_join_gate(user_id, call, db=None):
    """Admin বাদে সব callback এ channel-join enforce করে।
    Subscribed (বা admin) হলে True রিটার্ন করে — handler স্বাভাবিকভাবে চলবে।
    Join করা না থাকলে join-prompt পাঠিয়ে False রিটার্ন করে — caller-কে
    সাথে সাথেই return করে দিতে হবে, আর কোনো কাজ না করে।"""
    if is_admin(user_id):
        return True
    if is_subscribed(user_id):
        return True

    try:
        bot.delete_message(user_id, call.message.message_id)
    except Exception:
        pass

    if db is None:
        db = load_db()
    _lang_now = db.get("users", {}).get(user_id, {}).get("lang", "en")
    _join_markup = types.InlineKeyboardMarkup(row_width=1)
    for i, ch in enumerate(CHANNELS, 1):
        _btn_text = LANG.get(_lang_now, LANG["en"])["join_channel_btn"].format(n=i)
        _join_markup.add(InlineBtn(_btn_text, style="primary", url=ch["link"]))
    _join_markup.add(InlineBtn(
        LANG.get(_lang_now, LANG["en"])["verify_join"], style="success", callback_data="check_join"))
    try:
        bot.send_message(user_id,
            LANG.get(_lang_now, LANG["en"])["join_channels"],
            reply_markup=_join_markup, parse_mode="HTML")
    except Exception as _e:
        logging.warning(f"enforce_join_gate: join prompt send failed uid={user_id}: {_e}")
    return False

