# ===========================
# STOCK COUNT CACHE — বারবার disk read বন্ধ করে
# ===========================
_stock_count_cache = {}        # {product_name: (count, timestamp)}
_STOCK_CACHE_TTL = 60          # ⚡ 60 সেকেন্ড — fresh stock + disk I/O কম (optimized)

# 🔌 API-connected প্রোডাক্টের স্টক: API timeout/error (-1) হলে আগে "0 = Out of Stock (লাল)"
# ধরে ৬০ সেকেন্ড cache হতো। এখন শেষ জানা ভালো স্টক ব্যবহার হয়, ব্যর্থতা মাত্র ৮ সেকেন্ড
# cache থাকে, আর স্টক অজানা থাকলে বাটন লাল না হয়ে নীল (নিরপেক্ষ) থাকে।
_stock_api_last_good = {}      # {product_name: শেষ সফল API count}
_stock_api_unknown = set()     # যাদের API স্টক এই মুহূর্তে আনা যায়নি
_STOCK_FAIL_TTL = 8            # ব্যর্থ চেক কত সেকেন্ড cache থাকবে

def _resolve_api_count(product_name, api_count):
    if api_count is None or api_count < 0:
        _stock_api_unknown.add(product_name)
        return _stock_api_last_good.get(product_name, 0)
    _stock_api_unknown.discard(product_name)
    _stock_api_last_good[product_name] = api_count
    return api_count

def _stock_cache_put(product_name, total, now_ts):
    if product_name in _stock_api_unknown:
        # ব্যর্থ হলে অল্প সময়ের cache — যাতে পরের বার দ্রুত আবার চেষ্টা হয়
        _stock_count_cache[product_name] = (total, now_ts - (_STOCK_CACHE_TTL - _STOCK_FAIL_TTL))
    else:
        _stock_count_cache[product_name] = (total, now_ts)

def get_stock_count(product_name):
    now_ts = _time_module.time()
    cached = _stock_count_cache.get(product_name)
    if cached and (now_ts - cached[1]) < _STOCK_CACHE_TTL:
        return cached[0]

    # ─── Bulkmail product ───
    if is_bulkmail_product(product_name):
        product_id = API_PRODUCTS[product_name]["product_id"]
        api_count  = _resolve_api_count(product_name, bulkmail_get_stock(product_id))

        # Local xlsx stock ও চেক করো (admin extra stock upload করতে পারে)
        local_count = 0
        local_path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
        if os.path.exists(local_path):
            try:
                wb = openpyxl.load_workbook(local_path, read_only=True)
                ws = wb.active
                for row_idx, row in enumerate(ws.iter_rows(values_only=True), start=1):
                    if row_idx == 1: continue
                    if any(cell is not None and str(cell).strip() != "" for cell in row):
                        local_count += 1
                wb.close()
            except Exception:
                pass

        total = api_count + local_count
        _stock_cache_put(product_name, total, now_ts)
        return total

    # ─── CodeCraft (codecraftdeveloper.com) product ───
    if is_codecraft_product(product_name):
        product_id = API_PRODUCTS[product_name]["product_id"]
        api_count  = _resolve_api_count(product_name, codecraft_get_stock(product_id))

        # Local xlsx stock ও চেক করো (admin extra stock upload করতে পারে)
        local_count = 0
        local_path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
        if os.path.exists(local_path):
            try:
                wb = openpyxl.load_workbook(local_path, read_only=True)
                ws = wb.active
                for row_idx, row in enumerate(ws.iter_rows(values_only=True), start=1):
                    if row_idx == 1: continue
                    if any(cell is not None and str(cell).strip() != "" for cell in row):
                        local_count += 1
                wb.close()
            except Exception:
                pass

        total = api_count + local_count
        _stock_cache_put(product_name, total, now_ts)
        return total

    # API Product হলে hotmail143 থেকে stock নাও
    # এবং admin local xlsx upload করলে সেটাও যোগ করো
    if product_name in API_PRODUCTS:
        api_conf = API_PRODUCTS[product_name]
        api_count = _resolve_api_count(product_name, hotmail143_get_stock(api_conf["product_type"], api_conf["account_type"]))

        # Local xlsx stock ও চেক করো (admin extra stock upload করতে পারে)
        local_count = 0
        local_path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
        if os.path.exists(local_path):
            try:
                wb = openpyxl.load_workbook(local_path, read_only=True)
                ws = wb.active
                for row_idx, row in enumerate(ws.iter_rows(values_only=True), start=1):
                    if row_idx == 1:
                        continue
                    if any(cell is not None and str(cell).strip() != "" for cell in row):
                        local_count += 1
                wb.close()
            except Exception:
                pass

        total = api_count + local_count
        _stock_cache_put(product_name, total, now_ts)
        return total

    path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
    if not os.path.exists(path):
        _stock_count_cache[product_name] = (0, now_ts)
        return 0
    try:
        wb = openpyxl.load_workbook(path, read_only=True)
        ws = wb.active
        count = 0
        for row_idx, row in enumerate(ws.iter_rows(values_only=True), start=1):
            if row_idx == 1:
                continue  # 1st row = heading, skip করো
            # Row এর সব cell None বা empty string হলে skip
            if any(cell is not None and str(cell).strip() != "" for cell in row):
                count += 1
        wb.close()
        _stock_count_cache[product_name] = (count, now_ts)
        return count
    except Exception as e:
        logging.error(f"Stock count error for {product_name}: {str(e)}")
        return 0

def invalidate_stock_cache(product_name):
    """Stock write হলে cache clear করো। Sub-product গুলোও clear হবে।"""
    _stock_count_cache.pop(product_name, None)
    prefix = product_name + "__"
    for k in [k for k in list(_stock_count_cache.keys()) if k.startswith(prefix)]:
        _stock_count_cache.pop(k, None)


# ═══════════════════════════════════════════════════════════
# 📄 STOCK SHEET HELPERS — heading অনুযায়ী ডেলিভারি + link → plain text
# ═══════════════════════════════════════════════════════════
_HYPERLINK_FORMULA_RE = re.compile(r'^=\s*HYPERLINK\(\s*"([^"]*)"', re.I)

def _hx(x):
    """Telegram HTML এর জন্য safe escape।"""
    import html as _h
    return _h.escape(str(x), quote=False)

_HYPERLINK_FORMULA_FULL_RE = re.compile(
    r'^=\s*HYPERLINK\(\s*"([^"]*)"\s*(?:,\s*"([^"]*)")?', re.I)

def _stock_cell_text(cell):
    """Sheet cell → plain text — সেলে যা লেখা (দেখা যায়) হুবহু সেটাই।
    ✅ FIX: আগে hyperlink থাকলে তার target (যেমন http://proxy.h143.xyz) নেওয়া হতো,
    ফলে stock/delivery তে বাড়তি http:// চলে আসত। এখন সেলের নিজের লেখাই অগ্রাধিকার পায়।
    hyperlink target শুধু তখনই নেওয়া হয় যখন সেল আসলে খালি।
    8080.0 → 8080; None → ''।"""
    try:
        v = cell.value
    except Exception:
        return ""
    # =HYPERLINK("url","দেখানো লেখা") → দেখানো লেখা; লেখা না থাকলে url
    if isinstance(v, str):
        m = _HYPERLINK_FORMULA_FULL_RE.match(v.strip())
        if m:
            shown = (m.group(2) or "").strip()
            if shown:
                return shown
            if m.group(1).strip():
                return m.group(1).strip()
    # সাধারণ সেল → যা লেখা আছে তাই (কোনো http:// যোগ/বদল নয়)
    if v is not None:
        if isinstance(v, bool):
            return str(v)
        if isinstance(v, float) and v.is_integer():
            return str(int(v))
        txt = str(v).strip()
        if txt:
            return txt
    # সেল খালি কিন্তু hyperlink আছে → শেষ ভরসা হিসেবে link
    try:
        hl = cell.hyperlink
        if hl is not None and getattr(hl, "target", None):
            return str(hl.target).strip()
    except Exception:
        pass
    return ""

def _stock_normalize_ws(ws):
    """Worksheet এর সব hyperlink/HYPERLINK-formula cell কে plain text এ বদলে দেয়
    (row delete করলে hyperlink ref এলোমেলো হওয়া ঠেকাতে)।"""
    try:
        for row in ws.iter_rows():
            for c in row:
                has_link = False
                try:
                    has_link = c.hyperlink is not None
                except Exception:
                    pass
                if has_link or (isinstance(c.value, str) and c.value.strip().upper().startswith("=HYPERLINK")):
                    t = _stock_cell_text(c)
                    try:
                        c.hyperlink = None
                    except Exception:
                        pass
                    c.value = t
        try:
            ws._hyperlinks = []
        except Exception:
            pass
    except Exception as e:
        logging.error(f"_stock_normalize_ws error: {e}")

STOCK_UPLOAD_EXTS = (".xlsx", ".csv", ".txt")

# ✅ Admin এর price/MB ইনপুট parse — বাংলা অঙ্ক (৫০), "৳", "BDT", "tk", স্পেস সহ লিখলেও চলবে
_BN_DIGITS = str.maketrans("০১২৩৪৫৬৭৮৯", "0123456789")
def _parse_num_text(text):
    t = str(text or "").translate(_BN_DIGITS).strip()
    t = re.sub(r"(?i)(bdt|taka|tk|usd|\$|৳|টাকা)", "", t).strip()
    t = t.replace(",", ".").replace(" ", "")
    return float(t)

def _is_stock_upload_name(fname):
    """Stock আপলোডে অনুমোদিত ফাইল (.xlsx / .csv / .txt) কিনা চেক করে।"""
    return str(fname or "").strip().lower().endswith(STOCK_UPLOAD_EXTS)

def _stock_decode_text(data_bytes):
    """CSV/TXT bytes → str (UTF-8 BOM সহ/ছাড়া, ব্যর্থ হলে cp1252/latin-1)।"""
    for enc in ("utf-8-sig", "utf-16", "cp1252", "latin-1"):
        try:
            return data_bytes.decode(enc)
        except Exception:
            continue
    return data_bytes.decode("utf-8", errors="ignore")

def _stock_rows_from_upload(data_bytes, filename=None):
    """আপলোড করা ফাইল (.xlsx/.csv/.txt) থেকে rows (list of list of str) বানায়।
    Return: (rows, kind)  — kind = 'xlsx' | 'csv' | 'txt'
      • xlsx : আগের মতোই (hyperlink → plain text)
      • csv  : delimiter অটো-ডিটেক্ট (, ; TAB |), 1st row = heading ধরা হয়
      • txt  : প্রতিটা লাইন = ১টা pcs (পুরো লাইনটাই এক cell, heading ধরা হয় না)
    ফাইলের নাম না থাকলে বা এক্সটেনশন মিললে না — content দেখে (zip signature) xlsx চেনা হয়।"""
    import csv as _csv
    ext = os.path.splitext(str(filename or "").lower())[1]
    if ext not in STOCK_UPLOAD_EXTS:
        ext = ".xlsx" if data_bytes[:2] == b"PK" else ".txt"

    if ext == ".xlsx":
        wb = openpyxl.load_workbook(BytesIO(data_bytes))
        ws = wb.active
        rows = [[_stock_cell_text(c) for c in r] for r in ws.iter_rows(values_only=False)]
        wb.close()
        return rows, "xlsx"

    text = _stock_decode_text(data_bytes).replace("\r\n", "\n").replace("\r", "\n")

    if ext == ".csv":
        lines = [ln for ln in text.split("\n") if ln.strip()]
        sample = "\n".join(lines[:20])
        try:
            dialect = _csv.Sniffer().sniff(sample, delimiters=",;\t|")
            delim = dialect.delimiter
        except Exception:
            delim = ","
        rows = [[(c or "").strip() for c in r] for r in _csv.reader(lines, delimiter=delim)]
        return rows, "csv"

    # .txt — প্রতি লাইন = ১টা pcs
    rows = [[ln.strip()] for ln in text.split("\n") if ln.strip()]
    return rows, "txt"

