def stock_merge_upload_bytes(product_name, data_bytes, filename=None):
    """Admin এর আপলোড করা .xlsx / .csv / .txt ফাইল কে product এর stock এ heading অনুযায়ী merge/save করে।
      • sheet এর heading যা আছে হুবহু সেটাই stock এর heading হয়
      • আগের stock এ অন্য heading থাকলে নাম ধরে column মিলিয়ে বসায় (নতুন heading হলে নতুন column)
      • link/hyperlink সব plain text URL হিসেবে সেভ হয়
    Return: (merge_mode, added_count, old_count)"""
    rows, _src_kind = _stock_rows_from_upload(data_bytes, filename)
    while rows and not any(rows[0]):
        rows.pop(0)
    if not rows:
        raise ValueError("Empty sheet")

    first = [c for c in rows[0] if c]
    # ✅ প্রথম row নিজেই host:port:user:pass হলে সেটা heading না — data। সব row একই
    #    ফরম্যাটে (১ cell = host:port:user:pass) নর্মালাইজ করে সংরক্ষণ হবে।
    _proxy_mode = _parse_proxy_line(rows[0]) is not None
    if _proxy_mode:
        _norm = []
        for _r in rows:
            _pp = _parse_proxy_line(_r)
            if _pp:
                _norm.append([":".join(_pp)])
            else:
                _raw = ":".join(c for c in _r if c)
                if _raw:
                    _norm.append([_raw])
        rows = _norm
        first = []
    new_has_header = (not _proxy_mode) and bool(first) and all(
        not c.replace('.', '', 1).isdigit() and not c.lower().startswith(("http://", "https://"))
        for c in first)
    # .txt তে কখনো heading ধরা হয় না — প্রতিটা লাইনই ১টা pcs
    if _src_kind == "txt":
        new_has_header = False
    if new_has_header:
        headers = list(rows[0]); data_rows = rows[1:]
    elif _proxy_mode:
        headers = [PROXY_STOCK_HEADER]; data_rows = rows
    else:
        width = max(len(r) for r in rows)
        headers = ["Data"] + [f"Col{i}" for i in range(2, width + 1)]
        data_rows = rows
    data_rows = [r for r in data_rows if any(r)]
    width = max([len(headers)] + [len(r) for r in data_rows])
    headers = headers + [""] * (width - len(headers))
    headers = [h if h else f"Col{i+1}" for i, h in enumerate(headers)]

    os.makedirs(STOCK_DIR, exist_ok=True)
    path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
    with get_stock_lock(product_name):
        ex_headers, ex_count, wb, ws = [], 0, None, None
        if os.path.exists(path):
            wb = openpyxl.load_workbook(path)
            ws = wb.active
            _stock_normalize_ws(ws)
            allr = list(ws.iter_rows(values_only=False))
            if allr:
                ex_headers = [_stock_cell_text(c) for c in allr[0]]
                ex_count = sum(1 for r in allr[1:] if any(_stock_cell_text(c) for c in r))
        if wb is not None and ex_count > 0:
            # ── আগের stock আছে → heading নাম ধরে মেলাও ──
            ex_headers = [h if h else f"Col{i+1}" for i, h in enumerate(ex_headers)]
            # heading ছাড়া .txt/.csv হলে → আগের stock এর heading এর সাথে column ক্রমে বসাও
            # (না হলে "Data" নামে আলাদা নতুন column তৈরি হয়ে ডেলিভারি এলোমেলো হতো)
            if (_src_kind in ("txt", "csv") or _proxy_mode) and not new_has_header:
                headers = (ex_headers + [f"Col{i+1}" for i in range(len(ex_headers), len(headers))])[:len(headers)]
            for i, h in enumerate(ex_headers):
                ws.cell(row=1, column=i + 1, value=h)
            col_of = {h.lower(): i for i, h in enumerate(ex_headers)}
            for h in headers:
                if h.lower() not in col_of:
                    ex_headers.append(h)
                    col_of[h.lower()] = len(ex_headers) - 1
                    ws.cell(row=1, column=len(ex_headers), value=h)
            for r in data_rows:
                out = [""] * len(ex_headers)
                for i, v in enumerate(r):
                    if i < len(headers):
                        out[col_of[headers[i].lower()]] = v
                ws.append(out)
            wb.save(path); wb.close()
            merge_mode, old_count = True, ex_count
        else:
            # ── নতুন / খালি stock → sheet এর heading দিয়েই নতুন ফাইল ──
            if wb is not None:
                wb.close()
            out_wb = openpyxl.Workbook()
            out_ws = out_wb.active
            out_ws.append(headers)
            for r in data_rows:
                out_ws.append(list(r) + [""] * (len(headers) - len(r)))
            out_wb.save(path); out_wb.close()
            merge_mode, old_count = False, 0
    invalidate_stock_cache(product_name)
    return merge_mode, len(data_rows), old_count

def read_single_account_text(product_name):
    """
    Buy One এর জন্য: xlsx থেকে ১টা row পড়ে heading অনুযায়ী
    account details text হিসেবে return করে।
    Return: (account_dict, headers) or (None, None)
    """
    path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
    try:
        if not os.path.exists(path):
            return None, None
        wb = openpyxl.load_workbook(path)
        ws = wb.active
        all_rows = list(ws.iter_rows(min_row=1, values_only=True))
        wb.close()
        if len(all_rows) < 2:
            return None, None
        headers = [str(h).strip() if h is not None else "" for h in all_rows[0]]
        # প্রথম non-empty data row খোঁজো
        for row in all_rows[1:]:
            if any(cell is not None and str(cell).strip() != "" for cell in row):
                account = {headers[i]: (str(row[i]).strip() if row[i] is not None else "") for i in range(len(headers))}
                return account, headers
        return None, None
    except Exception as e:
        logging.error(f"read_single_account_text error: {e}")
        return None, None


def _stock_plain_value(v):
    """Raw cell value → plain text (=HYPERLINK(...) → দেখানো লেখা/URL; 8080.0 → 8080; None → '')।"""
    if v is None:
        return ""
    if isinstance(v, str):
        m = _HYPERLINK_FORMULA_FULL_RE.match(v.strip())
        if m:
            shown = (m.group(2) or "").strip()
            if shown:
                return shown
            if m.group(1).strip():
                return m.group(1).strip()
        return v.strip()
    if isinstance(v, bool):
        return str(v)
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v).strip()


def read_stock_file(product_name, quantity):
    """
    xlsx stock file থেকে `quantity` টা row পড়ে:
      - CSV (plain text, BOM-less UTF-8) হিসেবে BytesIO return করে
      - 1st row = heading (fixed — product এর column নাম)
      - Data rows = plain values, কোনো formatting নেই
      - পড়া rows গুলো xlsx থেকে বাদ দেয় (stock কমে)

    ⚡ SPEED: আগে পুরো workbook cell-object সহ লোড করে প্রতিটা row আলাদা delete_rows()
    করা হতো (O(n²)) — 500/1000+ pcs এ অনেক ধীর ছিল। এখন read_only streaming দিয়ে একবার
    পড়া হয়, আর বাকি rows write_only mode এ একবারে নতুন ফাইলে লিখে atomic replace করা হয়।
    """
    import csv as _csv
    path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
    try:
        if not os.path.exists(path):
            return None
        quantity = int(quantity)
        wb = openpyxl.load_workbook(path, read_only=True)
        ws = wb.active

        header_raw = None
        collected_rows = []     # delivered (plain text)
        remaining_rows = []     # stock এ থেকে যাবে (plain text, খালি row বাদ)
        for ri, row in enumerate(ws.iter_rows(values_only=True), start=1):
            if ri == 1:
                header_raw = list(row)
                continue
            if not any(c is not None and str(c).strip() != "" for c in row):
                continue
            if len(collected_rows) < quantity:
                collected_rows.append([_stock_plain_value(c) for c in row])
            else:
                remaining_rows.append([_stock_plain_value(c) for c in row])
        wb.close()

        if header_raw is None or not collected_rows:
            return None
        header_data = [_stock_plain_value(c) for c in header_raw]

        # বাকি stock নতুন ফাইলে একবারে লিখে atomic replace
        tmp_path = path + ".tmp"
        out_wb = openpyxl.Workbook(write_only=True)
        out_ws = out_wb.create_sheet(title="Sheet1")
        out_ws.append(header_data)
        for r in remaining_rows:
            out_ws.append(r)
        out_wb.save(tmp_path)
        out_wb.close()
        os.replace(tmp_path, path)
        invalidate_stock_cache(product_name)

        # CSV তৈরি করো — plain UTF-8, BOM ছাড়া
        import io as _io
        text_stream = _io.StringIO()
        writer = _csv.writer(text_stream, lineterminator="\n")
        writer.writerow(header_data)
        n_cols = len(header_data)
        for row in collected_rows:
            padded = (list(row) + [""] * max(0, n_cols - len(row)))[:n_cols]
            writer.writerow(padded)

        stream = BytesIO(text_stream.getvalue().encode("utf-8"))
        stream.seek(0)
        return stream

    except Exception as e:
        logging.error(f"Stock file read error: {str(e)}\n{traceback.format_exc()}")
        return None

def _restore_stock_file(product_name, csv_stream):
    """
    Delivery ব্যর্থ হলে read_stock_file এ মুছে যাওয়া rows
    আবার xlsx এ সামনে (row 2 থেকে) ঢুকিয়ে দাও।
    ⚡ insert_rows() লুপ বাদ — একবারে নতুন ফাইল লিখে atomic replace।
    """
    import csv as _csv, io as _io
    path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
    try:
        csv_stream.seek(0)
        text = csv_stream.read().decode("utf-8")
        reader = list(_csv.reader(_io.StringIO(text)))
        if len(reader) < 2:
            return
        header    = reader[0]
        data_rows = reader[1:]

        existing = []
        if os.path.exists(path):
            wb = openpyxl.load_workbook(path, read_only=True)
            ws = wb.active
            for ri, row in enumerate(ws.iter_rows(values_only=True), start=1):
                if ri == 1:
                    continue
                if any(c is not None and str(c).strip() != "" for c in row):
                    existing.append(list(row))
            wb.close()

        tmp_path = path + ".tmp"
        out_wb = openpyxl.Workbook(write_only=True)
        out_ws = out_wb.create_sheet(title="Sheet1")
        out_ws.append(header)
        for r in data_rows:
            out_ws.append(r)
        for r in existing:
            out_ws.append(r)
        out_wb.save(tmp_path)
        out_wb.close()
        os.replace(tmp_path, path)
        invalidate_stock_cache(product_name)
        logging.info(f"Stock restored: {product_name} | {len(data_rows)} rows returned")
    except Exception as e:
        logging.error(f"_restore_stock_file error ({product_name}): {e}")

