def get_buy_proxy_menu(uid):
    """Buy Proxy সাবমেনু — Real Proxy / All VPN / GB Proxy / ISP Proxy + Back।
    ✅ পুরনো প্রতিটা প্রোভাইডার (9Proxy/711Proxy/Owl/ABC/Cli/...) আলাদা কীবোর্ড
    বাটন হিসেবে না থেকে এখন "GB Proxy" বাটনের ভেতরে ইনলাইন বাটন হিসেবে থাকে
    (দেখুন get_gb_proxy_inline_menu) — buy flow অপরিবর্তিত।
    ✅ Admin যেই বাটন Off করে রাখবে সেটা এখানে দেখানো হবে না।
    ✅ Admin rename করে থাকলে সেই নতুন নাম দেখাবে (kb_label)।"""
    markup = types.ReplyKeyboardMarkup(row_width=2, resize_keyboard=True)
    roles_in_order = ["proxy_real", "proxy_allvpn", "proxy_gb", "proxy_isp", "proxy_checker"]
    row = []
    for role in roles_in_order:
        if not is_kb_button_enabled(role):
            continue
        row.append(KbBtn(kb_label(role), role=role))
        if len(row) == 2:
            markup.add(*row)
            row = []
    if row:
        markup.add(*row)
    markup.add(KbBtn(LANG[get_user_lang(uid)].get("back", "🔙 Back"), role="back"))
    return markup

def handle_buy_proxy(user_id, db=None):
    """Buy Proxy বাটন হ্যান্ডলার — প্রোভাইডার সিলেকশন সাবমেনু দেখায়।"""
    lang = get_user_lang(user_id, db)
    if lang == "bn":
        msg = "🌐 <b>Buy Proxy</b>\n\nনিচে থেকে একটা প্রোভাইডার বেছে নিন 👇"
    else:
        msg = "🌐 <b>Buy Proxy</b>\n\nChoose a provider below 👇"
    bot.send_message(user_id, msg, parse_mode="HTML", reply_markup=get_buy_proxy_menu(user_id))

def handle_proxy_provider_selected(user_id, provider_label, db=None):
    """একটা নির্দিষ্ট প্রোক্সি প্রোভাইডার বাটনে ক্লিক করলে — Real Proxy হলে
    আসল API flow শুরু হবে, All VPN হলে ক্যাটাগরি মেনু দেখাবে, বাকিগুলো এখনো placeholder।"""
    lang = get_user_lang(user_id, db)
    if provider_label == kb_label("proxy_real"):
        start_realproxy_flow(user_id, db)
        return
    if provider_label == kb_label("proxy_allvpn"):
        show_allvpn_categories(user_id, lang)
        return
    # ── GB Proxy — 9Proxy/711Proxy/Owl/ABC/Cli/... সব প্রোভাইডার বাটন এখন এই
    #    একটা কীবোর্ড বাটনের ভেতরে ইনলাইন বাটন হিসেবে দেখানো হয় (নিচে
    #    show_gb_proxy_menu) — buy flow (show_proxy_provider_products) অপরিবর্তিত। ──
    if provider_label == kb_label("proxy_gb"):
        show_gb_proxy_menu(user_id, lang)
        return
    # ── ISP Proxy — Admin-যোগ করা ISP প্রোভাইডারগুলো ইনলাইন বাটন হিসেবে দেখায়।
    #    কোনো প্রোভাইডার না থাকলে নিচের generic "coming soon" ব্লক চলবে। ──
    if provider_label == kb_label("proxy_isp"):
        if show_isp_proxy_menu(user_id, lang):
            return
    if lang == "bn":
        msg = f"🌐 <b>{provider_label}</b>\n\nএই প্রোভাইডারের ফিচারটি শীঘ্রই আসছে! 🚧"
    else:
        msg = f"🌐 <b>{provider_label}</b>\n\nThis provider is coming soon! 🚧"
    bot.send_message(user_id, msg, parse_mode="HTML")


