# 🛡️ ALL VPN — CATEGORY SELECTION (3/6/14/30 days + Cancel)
# ✅ প্রোডাক্ট নাম/দাম/স্টক এখন placeholder না — DB থেকে dynamic লোড হয়
#    Admin Panel > 🛡️ All VPN Management থেকে Admin এইগুলো Add/Edit/Delete
#    করতে পারবেন। ক্রেতা প্রোডাক্ট সিলেক্ট করলে বটের normal single/bulk buy
#    ও delivery engine (show_product_detail_with_subnav) reuse হয়।
# ═══════════════════════════════════════════════════════════
ALLVPN_CATEGORIES = [
    ("Vpn 3days",  "allvpn_cat_3d"),
    ("Vpn 7days",  "allvpn_cat_6d"),
    ("Vpn14days",  "allvpn_cat_14d"),
    ("Vpn 30days", "allvpn_cat_30d"),
]
ALLVPN_CAT_KEYS   = [cb for _label, cb in ALLVPN_CATEGORIES]
ALLVPN_CAT_LABELS = dict(ALLVPN_CATEGORIES)

# cat_data → DB এর top-level list key (banned_users/verified_trxids এর মতো একই প্যাটার্ন —
# top-level list হিসেবে রাখা হয়েছে যাতে bot restart / cache reload এর পরও ঠিকভাবে list থাকে)
VPN_CAT_DB_KEY = {
    "allvpn_cat_3d":  "vpn_products_3d",
    "allvpn_cat_6d":  "vpn_products_6d",
    "allvpn_cat_14d": "vpn_products_14d",
    "allvpn_cat_30d": "vpn_products_30d",
}


def _vpn_display_name(product_name, cat_data=None):
    """
    ✅ FIX: VPN প্রোডাক্টের internal storage key তে uniqueness/filtering এর
    জন্য ক্যাটাগরি প্রিফিক্স ("Vpn 3days - ", পুরনো "VPN - " ইত্যাদি) থাকে,
    কিন্তু অ্যাডমিন/ইউজারকে দেখানোর সময় সেই প্রিফিক্স ছাড়া — অ্যাডমিন যেই
    নাম টাইপ করেছিলেন ঠিক সেটাই — দেখানো হয়। এই ফাংশনটা প্রিফিক্স বাদ
    দিয়ে আসল নামটা রিটার্ন করে (storage key কখনো বদলায় না)।
    """
    if not isinstance(product_name, str):
        return product_name
    if cat_data:
        cat_label = ALLVPN_CAT_LABELS.get(cat_data)
        if cat_label and product_name.startswith(cat_label + " - "):
            return product_name[len(cat_label) + 3:]
    # cat_data না দেওয়া থাকলে (বা মিলে না গেলে) যেকোনো পরিচিত ক্যাটাগরি
    # প্রিফিক্স বা পুরনো/legacy "VPN - " প্রিফিক্স চেক করো
    for lbl in ALLVPN_CAT_LABELS.values():
        p = lbl + " - "
        if product_name.startswith(p):
            product_name = product_name[len(p):]
            break
    else:
        if product_name.startswith("VPN - "):
            product_name = product_name[len("VPN - "):]
    # ✅ (একই নামে একাধিক Add ফিচার) — একই নামে দ্বিতীয়/তৃতীয়... বার Add করলে
    # internal storage key ইউনিক রাখতে শেষে " ‡2", " ‡3" ইত্যাদি সাফিক্স জোড়া
    # হয় (দেখুন _vpn_unique_product_key)। ইউজার/অ্যাডমিনকে দেখানোর সময় এই
    # সাফিক্সটা বাদ দিয়ে দেওয়া হয়, যাতে সব বাটনে একই নাম দেখায়।
    product_name = re.sub(r" ‡\d+$", "", product_name)
    return product_name


def _vpn_unique_product_key(db, cat_data, name):
    """
    ✅ (একই নামে একাধিক Add বাটন ফিচার) — আগে একই নামে দ্বিতীয়বার Add করতে
    গেলে "প্রোডাক্ট আগেই আছে" এরর দিয়ে ব্লক করে দিতো। এখন এর বদলে, নাম
    আগে থেকে থাকলে internal storage key তে অদৃশ্য একটা সাফিক্স (" ‡2",
    " ‡3"...) জুড়ে ইউনিক key বানানো হয় — যাতে একই নামে চাইলে যতগুলো ইচ্ছা
    আলাদা আলাদা স্টক/দামসহ Add করা যায়, কিন্তু ইউজারের কাছে সবগুলোই একই
    নামে দেখা যায় (_vpn_display_name এই সাফিক্স বাদ দিয়ে দেখায়)।
    """
    cat_label = ALLVPN_CAT_LABELS.get(cat_data, "VPN")
    base = f"{cat_label} - {name}"
    products = db.get("products", {})
    if base not in products:
        return base
    n = 2
    while f"{base} ‡{n}" in products:
        n += 1
    return f"{base} ‡{n}"


def get_vpn_products(db, cat_data):
    """একটা VPN ক্যাটাগরির ভিতরের প্রোডাক্ট নামের লিস্ট (DB থেকে) — order-preserving।"""
    key = VPN_CAT_DB_KEY.get(cat_data)
    if not key:
        return []
    return list(db.get(key) or [])


def _vpn_save_category_list(db, cat_data, product_list):
    """একটা ক্যাটাগরির প্রোডাক্ট-লিস্ট DB তে targeted-write করো (top-level list key)।"""
    key = VPN_CAT_DB_KEY.get(cat_data)
    if not key:
        return
    db[key] = product_list
    update_db_path(f"/{key}", product_list)


def _vpn_delete_product_everywhere(db, cat_data, product_name):
    """একটা VPN প্রোডাক্ট সম্পূর্ণ ডিলিট করো — category list, price, details, stock file — সব জায়গা থেকে।"""
    products = get_vpn_products(db, cat_data)
    if product_name in products:
        products.remove(product_name)
        _vpn_save_category_list(db, cat_data, products)
    if product_name in db.get("products", {}):
        del db["products"][product_name]
        _EXECUTOR.submit(lambda: _fb_ref(f"/products/{product_name}").delete())
    if product_name in db.get("product_details", {}):
        del db["product_details"][product_name]
        _EXECUTOR.submit(lambda: _fb_ref(f"/product_details/{product_name}").delete())
    _update_db_cache_in_place(db)
    try:
        stock_path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
        if os.path.exists(stock_path):
            os.remove(stock_path)
    except Exception:
        pass
    invalidate_stock_cache(product_name)


def _allvpn_products_view(cat_data, lang, db=None):
    """একটা ক্যাটাগরির (3d/6d/14d/30d) প্রোডাক্ট লিস্ট (নাম—দাম—স্টক) + Back/Cancel বাটন সহ মার্কআপ বানায়।"""
    if db is None:
        db = load_db()
    cat_label = ALLVPN_CAT_LABELS.get(cat_data, "VPN")
    products = get_vpn_products(db, cat_data)
    if lang == "bn":
        title = f"🛡 <b>{cat_label}</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        title += "একটা প্রোডাক্ট বেছে নিন:" if products else "⚠️ এই ক্যাটাগরিতে এখনো কোনো প্রোডাক্ট যোগ করা হয়নি।"
    else:
        title = f"🛡 <b>{cat_label}</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        title += "Select a product:" if products else "⚠️ No products added in this category yet."
    markup = types.InlineKeyboardMarkup(row_width=2)
    prod_btns = []
    for i, name in enumerate(products, start=1):
        price = float(db.get("products", {}).get(name) or 0)
        stock = get_stock_count(name)
        stock_icon = "✅" if stock > 0 else "🔴"
        price_txt = str(int(price)) if price == int(price) else f"{price:.2f}"
        label = f"{_vpn_display_name(name, cat_data)} — {price_txt}BDT ({stock_icon}{stock}pcs)"
        prod_btns.append(InlineBtn(label, style=_stock_style(stock), callback_data=f"{cat_data}_p{i}"))
    markup.add(*prod_btns)  # 2 by 2 — এক সারিতে ২টা
    markup.add(
        InlineBtn("🔙 ব্যাক" if lang == "bn" else "🔙 Back",
                   style=_ik("inline_proxy_back"), callback_data="allvpn_back_cat"),
        InlineBtn("❌ ক্যানসেল" if lang == "bn" else "❌ Cancel",
                   style=_ik("inline_proxy_cancel"), callback_data="allvpn_cancel"),
    )
    return title, markup

def _allvpn_categories_view(lang):
    """Categories টাইটেল + ইনলাইন মার্কআপ বানায়।
    ক্যাটাগরি বাটনগুলো 2 by 2 দেখানো হয়, Cancel বাটন সবার নিচে আলাদা সারিতে।"""
    if lang == "bn":
        title = "🏷 <b>Categories</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\nএকটা ক্যাটাগরি বেছে নিন:"
    else:
        title = "🏷 <b>Categories</b>\n┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\nSelect a category:"
    markup = types.InlineKeyboardMarkup(row_width=2)
    cat_btns = [InlineBtn(label, style=_ik(_VPN_CAT_COLOR_ROLE.get(cb, "inline_vpn_3d")), callback_data=cb) for label, cb in ALLVPN_CATEGORIES]
    markup.add(*cat_btns)  # 2 by 2 — এক সারিতে ২টা
    markup.add(InlineBtn(
        "❌ ক্যানসেল" if lang == "bn" else "❌ Cancel",
        style=_ik("inline_proxy_cancel"), callback_data="allvpn_cancel"))  # Cancel বাটন — নিচে আলাদা সারিতে
    return title, markup

def show_allvpn_categories(user_id, lang=None):
    """🛡️ All VPN বাটনে ক্লিক করলে ক্যাটাগরি মেনু (নতুন মেসেজ হিসেবে) পাঠায়।"""
    if lang is None:
        lang = get_user_lang(user_id)
    title, markup = _allvpn_categories_view(lang)
    bot.send_message(user_id, title, parse_mode="HTML", reply_markup=markup)

@bot.callback_query_handler(func=lambda call: call.data.startswith("allvpn_"))
def handle_allvpn_callback(call):
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_allvpn_callback_worker, call)

def _handle_allvpn_callback_worker(call):
    # 🆕 FIX: top-level try/except যোগ করা হলো — আগে কোনো unexpected exception হলে
    # background thread এ silently swallow হয়ে যেত (ইউজার কিছুই দেখতো না, admin ও জানতো না)।
    try:
        _handle_allvpn_callback_worker_impl(call)
    except Exception as e:
        _cw_generic_crash_handler(call, "handle_allvpn_callback", e)

def _handle_allvpn_callback_worker_impl(call):
    user_id = str(call.message.chat.id)
    if not enforce_join_gate(user_id, call):
        return
    data = call.data
    lang = get_user_lang(user_id)
    db = load_db()

    if data == "allvpn_cancel":
        try:
            bot.edit_message_text(
                "❌ ক্যানসেল করা হয়েছে।" if lang == "bn" else "❌ Cancelled.",
                chat_id=call.message.chat.id, message_id=call.message.message_id,
                parse_mode="HTML")
        except Exception:
            try:
                bot.delete_message(call.message.chat.id, call.message.message_id)
            except Exception:
                pass
        return

    # ক্যাটাগরি বাটনে ক্লিক করলে (Vpn 3days/6days/14days/30days) → প্রোডাক্ট সাব-মেনু দেখাও
    if data in ALLVPN_CAT_KEYS:
        title, markup = _allvpn_products_view(data, lang, db)
        try:
            bot.edit_message_text(title, chat_id=call.message.chat.id,
                                   message_id=call.message.message_id,
                                   parse_mode="HTML", reply_markup=markup)
        except Exception:
            bot.send_message(user_id, title, parse_mode="HTML", reply_markup=markup)
        return

    # প্রোডাক্ট সাব-মেনু থেকে Back বাটনে ক্লিক করলে → ক্যাটাগরি লিস্টে ফিরে যাও
    if data == "allvpn_back_cat":
        title, markup = _allvpn_categories_view(lang)
        try:
            bot.edit_message_text(title, chat_id=call.message.chat.id,
                                   message_id=call.message.message_id,
                                   parse_mode="HTML", reply_markup=markup)
        except Exception:
            bot.send_message(user_id, title, parse_mode="HTML", reply_markup=markup)
        return

    # একটা নির্দিষ্ট প্রোডাক্ট বাটনে ক্লিক করলে (যেমন allvpn_cat_3d_p2)
    # → normal প্রোডাক্ট ডিটেইল (নাম/দাম/স্টক + single/bulk buy বাটন) দেখাও —
    #    বটের বিদ্যমান delivery engine (show_product_detail_with_subnav) reuse করা হচ্ছে
    # ✅ FIX: আগে এখানে লিস্ট মেসেজটা delete করে নতুন মেসেজ পাঠানো হতো —
    # এখন delete না করে edit_message_id পাস করে একই মেসেজেই product detail
    # দেখানো হচ্ছে (নাম থেকে ক্যাটাগরি প্রিফিক্স বাদ দিয়ে, display_name দিয়ে)।
    for cat_data in ALLVPN_CAT_KEYS:
        prefix = cat_data + "_p"
        if data.startswith(prefix):
            products = get_vpn_products(db, cat_data)
            try:
                idx = int(data[len(prefix):])
                prod_name = products[idx - 1]
            except Exception:
                return
            # ✅ FIX: এই product detail টা "Buy Proxy → All VPN" থেকে আসছে,
            # তাই "🔙 Back" চাপলে Shop Now মেনুতে না গিয়ে Buy Proxy মেনুতে যাবে
            show_product_detail_with_subnav(
                user_id, prod_name, db,
                display_name=_vpn_display_name(prod_name, cat_data),
                edit_message_id=call.message.message_id,
                origin="buy_proxy",
            )
            return


# ═══════════════════════════════════════════════════════════
# 🛠️ ALL VPN MANAGEMENT — Admin Panel Section
# ✅ Admin এখান থেকে প্রতিটা ক্যাটাগরির (3d/6d/14d/30d) প্রোডাক্ট
#    Add / Edit Price / Add Stock / Delete করতে পারবেন।
# ⚠️ NOTE: এই হ্যান্ডলারগুলো main "func=lambda call: True" catch-all
#    handler এর আগে define করা — pyTelegramBotAPI প্রথম matching
#    handler টাই কল করে, তাই এখানেই "admin_vpn_" prefix গুলো ধরতে হবে।
# ═══════════════════════════════════════════════════════════
_vpn_admin_sessions = {}  # ADMIN_ID(str) → {"idx_map": {str(i): (cat_data, product_name)}, "cat": cat_data}

def _vpn_admin_guard(call):
    return is_admin(call.message.chat.id)

def show_vpn_admin_categories(chat_id, edit_message_id=None):
    markup = types.InlineKeyboardMarkup(row_width=1)
    db = load_db()
    for label, cb in ALLVPN_CATEGORIES:
        count = len(get_vpn_products(db, cb))
        markup.add(InlineBtn(f"🛡️ {label} ({count} products)", style="primary",
                              callback_data=f"admin_vpn_cat_{cb}"))
    markup.add(InlineBtn("🔙 Back to Admin Panel", style="primary", callback_data="admin_vpn_back_panel"))
    text = "🛡️ <b>All VPN Management</b>\n\nএকটা ক্যাটাগরি বেছে নিন 👇"
    if edit_message_id:
        try:
            bot.edit_message_text(text, chat_id=chat_id, message_id=edit_message_id,
                                   parse_mode="HTML", reply_markup=markup)
            return
        except Exception:
            pass
    bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=markup)

def show_vpn_admin_product_list(chat_id, cat_data, edit_message_id=None):
    db = load_db()
    cat_label = ALLVPN_CAT_LABELS.get(cat_data, "VPN")
    products = get_vpn_products(db, cat_data)
    idx_map = {}
    markup = types.InlineKeyboardMarkup(row_width=1)
    for i, name in enumerate(products, start=1):
        idx_map[str(i)] = (cat_data, name)
        price = float(db.get("products", {}).get(name) or 0)
        stock = get_stock_count(name)
        markup.add(InlineBtn(f"⚙️ {_vpn_display_name(name, cat_data)} — {price:.0f}BDT | 📦{stock}pcs",
                              style="primary", callback_data=f"admin_vpn_prod_{i}"))
    _vpn_admin_sessions[str(ADMIN_ID)] = {"idx_map": idx_map, "cat": cat_data}
    if products:
        markup.add(InlineBtn("📦 Bulk Stock — সবগুলোতে (count + content)", style="success",
                              callback_data=f"admin_vpn_bulkstock_{cat_data}"))
    markup.add(InlineBtn("➕ Add New Product", style="success", callback_data=f"admin_vpn_add_{cat_data}"))
    markup.add(InlineBtn("🔙 Back to Categories", style="primary", callback_data="admin_vpn_manage"))
    text = (f"🛡️ <b>{cat_label} — Products</b>\n\n"
            f"{'কোনো প্রোডাক্ট নেই।' if not products else 'এডিট করার জন্য একটা প্রোডাক্ট বেছে নিন:'}")
    if edit_message_id:
        try:
            bot.edit_message_text(text, chat_id=chat_id, message_id=edit_message_id,
                                   parse_mode="HTML", reply_markup=markup)
            return
        except Exception:
            pass
    bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=markup)

def show_vpn_admin_product_detail(chat_id, idx, edit_message_id=None):
    sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
    entry = sess.get("idx_map", {}).get(idx)
    if not entry:
        bot.send_message(chat_id, "❌ Session expired! আবার Category তে ঢুকুন।")
        show_vpn_admin_categories(chat_id); return
    cat_data, name = entry
    db = load_db()
    price = float(db.get("products", {}).get(name) or 0)
    stock = get_stock_count(name)
    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(InlineBtn("✏️ Edit Price", style="primary", callback_data=f"admin_vpn_editprice_{idx}"))
    markup.add(InlineBtn("➕ Quick Add Stock (count + content)", style="success",
                          callback_data=f"admin_vpn_quickstock_{idx}"))
    markup.add(InlineBtn("📤 Upload Stock (.xlsx/.csv/.txt)", style="primary",
                          callback_data=f"admin_vpn_uploadstock_{idx}"))
    markup.add(InlineBtn("🗑️ Delete Product", style="danger", callback_data=f"admin_vpn_delconfirm_{idx}"))
    markup.add(InlineBtn("🔙 Back to List", style="primary", callback_data=f"admin_vpn_cat_{cat_data}"))
    text = (f"🛡️ <b>{_vpn_display_name(name, cat_data)}</b>\n\n"
            f"💵 <b>Price:</b> {price} BDT\n"
            f"📦 <b>Stock:</b> {stock} pcs\n\n"
            f"একটা অপশন বেছে নিন 👇")
    if edit_message_id:
        try:
            bot.edit_message_text(text, chat_id=chat_id, message_id=edit_message_id,
                                   parse_mode="HTML", reply_markup=markup)
            return
        except Exception:
            pass
    bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("admin_vpn_") or call.data == "admin_vpn_manage")
def handle_admin_vpn_callback(call):
    if not _vpn_admin_guard(call):
        bot.answer_callback_query(call.id, "❌ Admin access only!", show_alert=True)
        return
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_admin_vpn_callback_worker, call)

def _handle_admin_vpn_callback_worker(call):
    try:
        _handle_admin_vpn_callback_worker_impl(call)
    except Exception as e:
        _cw_generic_crash_handler(call, "handle_admin_vpn_callback", e)

def _handle_admin_vpn_callback_worker_impl(call):
    chat_id = call.message.chat.id
    mid = call.message.message_id
    if not enforce_join_gate(str(chat_id), call):
        return
    data = call.data

    if data == "admin_vpn_manage":
        show_vpn_admin_categories(chat_id, mid); return

    if data == "admin_vpn_back_panel":
        try:
            bot.delete_message(chat_id, mid)
        except Exception:
            pass
        show_admin_panel(str(chat_id)); return

    if data.startswith("admin_vpn_cat_"):
        cat_data = data[len("admin_vpn_cat_"):]
        show_vpn_admin_product_list(chat_id, cat_data, mid); return

    if data.startswith("admin_vpn_add_"):
        cat_data = data[len("admin_vpn_add_"):]
        msg = bot.send_message(chat_id,
            f"🆕 <b>{ALLVPN_CAT_LABELS.get(cat_data,'VPN')} — নতুন প্রোডাক্টের নাম লিখুন:</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_add_step1(m, cat_data))
        return

    # 🆕 Bulk Stock — এই ক্যাটাগরির সবগুলো (বর্তমান + ভবিষ্যতে অ্যাড হওয়া) প্রোডাক্টে
    # একই সাথে count+content stock করার জন্য। প্রতিটা প্রোডাক্টের পুরনো
    # single-item "Quick Add Stock" বাটন (admin_vpn_quickstock_) আগের মতোই আলাদাভাবে কাজ করবে।
    if data.startswith("admin_vpn_bulkstock_"):
        cat_data = data[len("admin_vpn_bulkstock_"):]
        products = get_vpn_products(load_db(), cat_data)
        if not products:
            bot.answer_callback_query(call.id, "❌ এই ক্যাটাগরিতে কোনো প্রোডাক্ট নেই!", show_alert=True); return
        cat_label = ALLVPN_CAT_LABELS.get(cat_data, "VPN")
        msg = bot.send_message(chat_id,
            f"🔢 <b>'{cat_label}' ক্যাটাগরির সবগুলো ({len(products)}টা) প্রোডাক্টে কত pcs করে stock যোগ করবেন?</b>\n\n"
            f"⚠️ প্রতিটা প্রোডাক্টে আলাদাভাবে এই সংখ্যক pcs যোগ হবে (existing stock এর সাথে যোগ হবে, রিপ্লেস হবে না)।\n\n"
            f"(শুধু সংখ্যা লিখুন, যেমন: 10)",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_bulkstock_step1(m, cat_data))
        return

    if data.startswith("admin_vpn_prod_"):
        idx = data[len("admin_vpn_prod_"):]
        show_vpn_admin_product_detail(chat_id, idx, mid); return

    if data.startswith("admin_vpn_editprice_"):
        idx = data[len("admin_vpn_editprice_"):]
        sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
        entry = sess.get("idx_map", {}).get(idx)
        if not entry:
            bot.answer_callback_query(call.id, "❌ Session expired!", show_alert=True); return
        cat_data, name = entry
        msg = bot.send_message(chat_id,
            f"💰 <b>'{_vpn_display_name(name, cat_data)}' এর নতুন Price লিখুন (BDT):</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_editprice_step(m, idx))
        return

    if data.startswith("admin_vpn_quickstock_"):
        idx = data[len("admin_vpn_quickstock_"):]
        sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
        entry = sess.get("idx_map", {}).get(idx)
        if not entry:
            bot.answer_callback_query(call.id, "❌ Session expired!", show_alert=True); return
        cat_data, name = entry
        msg = bot.send_message(chat_id,
            f"🔢 <b>'{_vpn_display_name(name, cat_data)}' এ কত pcs stock যোগ করবেন?</b>\n\n(শুধু সংখ্যা লিখুন, যেমন: 10)",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_quickstock_step1(m, idx))
        return

    if data.startswith("admin_vpn_uploadstock_"):
        idx = data[len("admin_vpn_uploadstock_"):]
        sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
        entry = sess.get("idx_map", {}).get(idx)
        if not entry:
            bot.answer_callback_query(call.id, "❌ Session expired!", show_alert=True); return
        cat_data, name = entry
        msg = bot.send_message(chat_id,
            f"📎 <b>'{_vpn_display_name(name, cat_data)}' এর জন্য .xlsx / .csv / .txt stock file পাঠান</b>\n\n"
            f"(প্রতিটা row = ১টা pcs — Admin এর নিজের format এ heading + data)",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_upload_stock_step2(m, name))
        return

    if data.startswith("admin_vpn_delconfirm_"):
        idx = data[len("admin_vpn_delconfirm_"):]
        sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
        entry = sess.get("idx_map", {}).get(idx)
        if not entry:
            bot.answer_callback_query(call.id, "❌ Session expired!", show_alert=True); return
        cat_data, name = entry
        markup = types.InlineKeyboardMarkup(row_width=2)
        markup.add(
            InlineBtn("✅ হ্যাঁ, Delete করো", style="danger", callback_data=f"admin_vpn_delyes_{idx}"),
            InlineBtn("❌ না, Cancel", style="primary", callback_data=f"admin_vpn_prod_{idx}"),
        )
        bot.send_message(chat_id,
            f"⚠️ <b>নিশ্চিত করুন</b>\n\n🗑️ <b>{_vpn_display_name(name, cat_data)}</b> চিরতরে ডিলিট করবেন?\n"
            f"এর price, stock — সব মুছে যাবে!",
            parse_mode="HTML", reply_markup=markup)
        return

    if data.startswith("admin_vpn_delyes_"):
        idx = data[len("admin_vpn_delyes_"):]
        sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
        entry = sess.get("idx_map", {}).get(idx)
        if not entry:
            bot.answer_callback_query(call.id, "❌ Session expired!", show_alert=True); return
        cat_data, name = entry
        db = load_db()
        _vpn_delete_product_everywhere(db, cat_data, name)
        bot.send_message(chat_id, f"✅ <b>'{_vpn_display_name(name, cat_data)}' ডিলিট করা হয়েছে।</b>", parse_mode="HTML")
        show_vpn_admin_product_list(chat_id, cat_data)
        return


def admin_vpn_add_step1(message, cat_data):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_vpn_admin_categories(chat_id); return
    name = (message.text or "").strip()
    if not name:
        msg = bot.send_message(chat_id, "❌ <b>নাম খালি রাখা যাবে না!</b> আবার লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_add_step1(m, cat_data)); return
    # ✅ ইউনিক প্রোডাক্ট key — category label prefix সহ (কালেকশনের সাথে collision এড়াতে)।
    # ✅ FIX: আগে একই নামে দ্বিতীয়বার Add করতে গেলে ব্লক করে দিতো — এখন একই
    # নামে চাইলে একাধিকবার Add করা যায় (_vpn_unique_product_key নিজে থেকে
    # আড়ালে ইউনিক করে দেয়, ইউজারের কাছে নামটা একই দেখায়)।
    db = load_db()
    product_name = _vpn_unique_product_key(db, cat_data, name)
    msg = bot.send_message(chat_id,
        f"💰 <b>'{name}' এর Price লিখুন (BDT):</b>",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_vpn_add_step2(m, cat_data, product_name))

def admin_vpn_add_step2(message, cat_data, product_name):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_vpn_admin_categories(chat_id); return
    try:
        price = _parse_num_text(message.text)
        if price <= 0:
            raise ValueError
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid price!</b> একটা সংখ্যা লিখুন (যেমন: 100):",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_add_step2(m, cat_data, product_name)); return
    msg = bot.send_message(chat_id,
        f"🔢 <b>'{_vpn_display_name(product_name, cat_data)}' এ শুরুতে কত pcs stock দিতে চান?</b>\n\n"
        f"(সংখ্যা লিখুন, স্টক ছাড়া শুরু করতে চাইলে <code>0</code> লিখুন)",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_vpn_add_step3(m, cat_data, product_name, price))

def admin_vpn_add_step3(message, cat_data, product_name, price):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_vpn_admin_categories(chat_id); return
    try:
        qty = int((message.text or "").strip())
        if qty < 0:
            raise ValueError
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid number!</b> একটা সংখ্যা লিখুন (যেমন: 10, বা 0):",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_add_step3(m, cat_data, product_name, price)); return

    if qty == 0:
        db = load_db()
        db["products"][product_name] = price
        update_db_path(f"/products/{product_name}", price)
        products = get_vpn_products(db, cat_data)
        products.append(product_name)
        _vpn_save_category_list(db, cat_data, products)
        bot.send_message(chat_id,
            f"✅ <b>নতুন VPN Product যোগ হয়েছে!</b>\n\n"
            f"📦 {_vpn_display_name(product_name, cat_data)}\n💵 {price} BDT\n📦 Stock: 0 pcs",
            parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
        show_vpn_admin_product_list(chat_id, cat_data)
        return

    msg = bot.send_message(chat_id,
        f"📝 <b>প্রতি pcs এর সাথে যাওয়া Delivery টেক্সট লিখুন</b>\n\n"
        f"<i>উদাহরণ: VPN Config Link: https://... | ID: xxxx | Pass: xxxx</i>\n\n"
        f"(সব {qty} pcs এর জন্য একই টেক্সট যাবে — না চাইলে <code>skip</code> লিখুন)",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_vpn_add_step4(m, cat_data, product_name, price, qty))

def admin_vpn_add_step4(message, cat_data, product_name, price, qty):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_vpn_admin_categories(chat_id); return
    content_text = "" if (message.text or "").strip().lower() == "skip" else (message.text or "").strip()
    db = load_db()
    db["products"][product_name] = price
    update_db_path(f"/products/{product_name}", price)
    products = get_vpn_products(db, cat_data)
    products.append(product_name)
    _vpn_save_category_list(db, cat_data, products)
    _vpn_write_quick_stock(product_name, qty, content_text or "VPN Access — Contact Support")
    bot.send_message(chat_id,
        f"✅ <b>নতুন VPN Product যোগ হয়েছে!</b>\n\n"
        f"📦 {_vpn_display_name(product_name, cat_data)}\n💵 {price} BDT\n📦 Stock: {qty} pcs",
        parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    show_vpn_admin_product_list(chat_id, cat_data)

def admin_vpn_editprice_step(message, idx):
    chat_id = message.chat.id
    sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
    entry = sess.get("idx_map", {}).get(idx)
    if not entry:
        bot.send_message(chat_id, "❌ Session expired! আবার Category তে ঢুকুন।"); return
    cat_data, name = entry
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_vpn_admin_product_list(chat_id, cat_data); return
    try:
        price = _parse_num_text(message.text)
        if price <= 0:
            raise ValueError
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid price!</b> একটা সংখ্যা লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_editprice_step(m, idx)); return
    db = load_db()
    db["products"][name] = price
    update_db_path(f"/products/{name}", price)
    bot.send_message(chat_id, f"✅ <b>'{_vpn_display_name(name, cat_data)}' এর নতুন Price: {price} BDT</b>",
        parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    show_vpn_admin_product_list(chat_id, cat_data)

def _vpn_write_quick_stock(product_name, qty, content_text):
    """একই content_text দিয়ে qty সংখ্যক row generate করে xlsx stock file এ append/merge করে —
    Single-column xlsx: heading='VPN Info', প্রতি row = content_text।"""
    stock_lock = get_stock_lock(product_name)
    with stock_lock:
        path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
        if os.path.exists(path):
            wb = openpyxl.load_workbook(path)
            ws = wb.active
        else:
            wb = openpyxl.Workbook()
            ws = wb.active
            ws.append(["VPN Info"])
        for _ in range(qty):
            ws.append([content_text])
        wb.save(path)
        wb.close()
    invalidate_stock_cache(product_name)

def admin_vpn_bulkstock_step1(message, cat_data):
    """🆕 Bulk Stock (ধাপ ১) — ক্যাটাগরির সবগুলো প্রোডাক্টের জন্য common qty নেয়।"""
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_vpn_admin_product_list(chat_id, cat_data); return
    try:
        qty = int((message.text or "").strip())
        if qty <= 0:
            raise ValueError
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid number!</b> একটা সংখ্যা লিখুন (যেমন: 10):",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_bulkstock_step1(m, cat_data)); return
    cat_label = ALLVPN_CAT_LABELS.get(cat_data, "VPN")
    msg = bot.send_message(chat_id,
        f"📝 <b>'{cat_label}' ক্যাটাগরির সবগুলো প্রোডাক্টের প্রতি pcs এর সাথে যাওয়া Delivery টেক্সট লিখুন</b>\n\n"
        f"<i>উদাহরণ: VPN Config Link: https://... | ID: xxxx | Pass: xxxx</i>\n\n"
        f"(সবগুলো প্রোডাক্টের {qty} pcs এর জন্যই একই টেক্সট যাবে — না চাইলে <code>skip</code> লিখুন)",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_vpn_bulkstock_step2(m, cat_data, qty))

def admin_vpn_bulkstock_step2(message, cat_data, qty):
    """🆕 Bulk Stock (ধাপ ২) — content নিয়ে ক্যাটাগরির প্রতিটা প্রোডাক্টে আলাদাভাবে
    একই qty + content দিয়ে stock write করে (single-item quick-stock এর মতোই,
    শুধু একসাথে সবগুলো প্রোডাক্টের জন্য লুপ করে)।"""
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_vpn_admin_product_list(chat_id, cat_data); return
    content_text = "" if (message.text or "").strip().lower() == "skip" else (message.text or "").strip()
    db = load_db()
    products = get_vpn_products(db, cat_data)
    cat_label = ALLVPN_CAT_LABELS.get(cat_data, "VPN")
    if not products:
        bot.send_message(chat_id, f"❌ <b>'{cat_label}' ক্যাটাগরিতে কোনো প্রোডাক্ট নেই!</b>",
            parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
        show_vpn_admin_categories(chat_id); return

    done, failed = 0, []
    for name in products:
        try:
            _vpn_write_quick_stock(name, qty, content_text or "VPN Access — Contact Support")
            done += 1
        except Exception as e:
            failed.append(name)
            logging.error(f"admin_vpn_bulkstock_step2: failed for {name}: {e}")

    summary = f"✅ <b>'{cat_label}' ক্যাটাগরির {done}টা প্রোডাক্টে {qty} pcs করে stock যোগ হয়েছে!</b>"
    if failed:
        failed_names = ", ".join(_vpn_display_name(n, cat_data) for n in failed)
        summary += f"\n\n⚠️ {len(failed)}টা প্রোডাক্টে ব্যর্থ হয়েছে: {failed_names}"
    bot.send_message(chat_id, summary, parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    show_vpn_admin_product_list(chat_id, cat_data)

def admin_vpn_quickstock_step1(message, idx):
    chat_id = message.chat.id
    sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
    entry = sess.get("idx_map", {}).get(idx)
    if not entry:
        bot.send_message(chat_id, "❌ Session expired! আবার Category তে ঢুকুন।"); return
    cat_data, name = entry
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_vpn_admin_product_list(chat_id, cat_data); return
    try:
        qty = int((message.text or "").strip())
        if qty <= 0:
            raise ValueError
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid number!</b> একটা সংখ্যা লিখুন (যেমন: 10):",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_vpn_quickstock_step1(m, idx)); return
    msg = bot.send_message(chat_id,
        f"📝 <b>প্রতি pcs এর সাথে যাওয়া Delivery টেক্সট লিখুন</b>\n\n"
        f"<i>উদাহরণ: VPN Config Link: https://... | ID: xxxx | Pass: xxxx</i>\n\n"
        f"(সব {qty} pcs এর জন্য একই টেক্সট যাবে — না চাইলে <code>skip</code> লিখুন)",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_vpn_quickstock_step2(m, idx, qty))

def admin_vpn_quickstock_step2(message, idx, qty):
    chat_id = message.chat.id
    sess = _vpn_admin_sessions.get(str(ADMIN_ID), {})
