# ═══════════════════════════════════════════════════════════
# ➕ CUSTOM PROXY PROVIDERS — Admin নিজেই নতুন প্রোভাইডার যোগ/মুছতে পারবে
# settings/custom_proxy_providers = {"proxy_c1": "🔥 My Proxy", ...}
# ═══════════════════════════════════════════════════════════
def _register_custom_proxy_provider(key, label):
    """Runtime এ একটা custom provider সব রেজিস্ট্রিতে যোগ করো (idempotent)।"""
    global _PROXY_PROVIDER_PREFIXES
    if key in PROXY_PROVIDER_LABELS:
        return
    db_key = f"proxy_products_{key[len('proxy_'):]}"
    KB_BUTTON_ROLES[key] = (label, "primary")
    _KB_ROLE_COLORS[key] = "primary"
    PROXY_PROVIDERS.append((key, label))
    PROXY_PROVIDER_KEYS.append(key)
    PROXY_PROVIDER_LABELS[key] = label
    PROXY_PROVIDER_DB_KEY[key] = db_key
    _DB_DEFAULT.setdefault(db_key, [])
    _SECTION_CONFIG.add(db_key)
    if db_key not in _DATA_LOAD_ALLOWED_KEYS:
        _DATA_LOAD_ALLOWED_KEYS.append(db_key)
    _PROXY_PROVIDER_PREFIXES = None  # prefix cache নতুন করে তৈরি হবে


def _unregister_custom_proxy_provider(key):
    global _PROXY_PROVIDER_PREFIXES
    KB_BUTTON_ROLES.pop(key, None)
    _KB_ROLE_COLORS.pop(key, None)
    PROXY_PROVIDERS[:] = [(k, l) for k, l in PROXY_PROVIDERS if k != key]
    PROXY_PROVIDER_KEYS[:] = [k for k in PROXY_PROVIDER_KEYS if k != key]
    PROXY_PROVIDER_LABELS.pop(key, None)
    db_key = PROXY_PROVIDER_DB_KEY.pop(key, None)
    if db_key:
        _DB_DEFAULT.pop(db_key, None)
        _SECTION_CONFIG.discard(db_key)
        if db_key in _DATA_LOAD_ALLOWED_KEYS:
            _DATA_LOAD_ALLOWED_KEYS.remove(db_key)
    _KB_ROLE_LABELS.pop(key, None)
    _KB_ROLE_DISABLED.discard(key)
    _PROXY_PROVIDER_PREFIXES = None


# ═══════════════════════════════════════════════════════════
# 🏢 ISP PROXY PROVIDERS — Admin নিজেই ISP প্রোভাইডার যোগ/মুছতে পারবে
# settings/custom_isp_providers = {"proxy_i1": "My ISP", ...}
# ✅ GB Proxy এর মতো একই engine (নাম/দাম/sheet-heading stock/buy/delivery)
#    reuse হয়; শুধু key আলাদা (proxy_i<N>) আর দেখায় "ISP Proxy" বাটনের ভেতরে।
# ═══════════════════════════════════════════════════════════
_ISP_KEY_RE = re.compile(r"^proxy_i\d+$")
_ISP_BAD_NAME_CHARS = set('.$#[]/\\')
_isp_pending_desc = {}   # product_name → description (add-flow চলাকালীন)

def _is_isp_provider(key):
    return bool(isinstance(key, str) and _ISP_KEY_RE.match(key))

def get_custom_isp_providers(db=None):
    if db is None:
        db = load_db()
    cp = db.get("settings", {}).get("custom_isp_providers", {})
    return dict(cp) if isinstance(cp, dict) else {}

def _is_custom_proxy_provider(key):
    return key in get_custom_proxy_providers() or key in get_custom_isp_providers()

def get_custom_proxy_providers(db=None):
    if db is None:
        db = load_db()
    cp = db.get("settings", {}).get("custom_proxy_providers", {})
    return dict(cp) if isinstance(cp, dict) else {}


def _init_custom_proxy_providers():
    """Startup এ সেভ করা custom provider গুলো রেজিস্টার করো (অবশ্যই label/disabled
    load করার আগে)।"""
    try:
        saved = get_custom_proxy_providers()
        for key, label in saved.items():
            if key.startswith("proxy_c") and label:
                _register_custom_proxy_provider(key, label)
        _isp_saved = get_custom_isp_providers()
        for key, label in _isp_saved.items():
            if _is_isp_provider(key) and label:
                _register_custom_proxy_provider(key, label)
        saved = dict(saved, **_isp_saved)
        if saved:
            _invalidate_db_cache()  # নতুন section key গুলো সহ আবার load হবে
        print(f"✅ Custom proxy providers loaded: {list(saved.values()) or '(none)'}")
    except Exception as e:
        logging.error(f"_init_custom_proxy_providers error: {e}")


def admin_add_proxy_provider_step(message):
    """Admin এর পাঠানো নাম দিয়ে নতুন provider তৈরি করো।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return
    name = (message.text or "").strip()
    existing = [kb_label(k).strip().lower() for k in PROXY_PROVIDER_KEYS]
    err = None
    if not name or len(name) > 40:
        err = "❌ <b>নাম খালি রাখা যাবে না এবং ৪০ ক্যারেক্টারের কম হতে হবে।</b>"
    elif name.lower() in existing:
        err = "❌ <b>এই নামে আগে থেকেই একটা প্রোভাইডার আছে।</b>"
    if err:
        msg = bot.send_message(user_id, err + "\nআবার নাম পাঠান:",
                               parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_add_proxy_provider_step); return

    db = load_db()
    custom = get_custom_proxy_providers(db)
    nums = [int(k[len("proxy_c"):]) for k in custom if k[len("proxy_c"):].isdigit()]
    key = f"proxy_c{(max(nums) + 1) if nums else 1}"
    custom[key] = name
    db.setdefault("settings", {})["custom_proxy_providers"] = custom
    update_db_path("/settings/custom_proxy_providers", custom)
    _register_custom_proxy_provider(key, name)
    _invalidate_db_cache()
    try:
        auto_init_proxy_provider_products()  # ডিফল্ট Package 1-4 তৈরি
    except Exception as e:
        logging.error(f"auto init for new provider failed: {e}")
    bot.send_message(user_id,
        f"✅ <b>নতুন প্রোভাইডার যোগ হয়েছে:</b> {name}\n\n"
        f"এখন GB Proxy মেনুতে দেখা যাবে। প্রোডাক্টের নাম/দাম/স্টক Proxy Provider Management থেকে সেট করুন।",
        parse_mode="HTML")
    show_proxyprov_kb_admin_list(user_id)


