# 📦 GB PROXY — কীবোর্ড বাটন "GB Proxy" ক্লিক করলে এই ইনলাইন মেনু আসবে,
#    যেখানে 9Proxy/711Proxy/Owl Proxy/ABC Proxy/Cli Proxy/... সব প্রোভাইডার
#    ইনলাইন বাটন হিসেবে দেখানো হয়। কোনো একটা বাটনে ক্লিক করলে সেই প্রোভাইডারের
#    normal buy flow-ই চলবে (show_proxy_provider_products — অপরিবর্তিত)।
#    ✅ ভবিষ্যতে নতুন প্রোভাইডার PROXY_PROVIDERS লিস্টে যোগ করলেই এখানে
#    অটোমেটিক ইনলাইন বাটন হিসেবে চলে আসবে — আলাদা কোনো কোড বদলাতে হবে না।
#    ✅ Admin কোনো প্রোভাইডার Off করে রাখলে (is_kb_button_enabled) সেটা এখানেও
#    লুকানো থাকবে, আর rename/emoji করা থাকলে সেটাই দেখাবে (kb_label)।
# ═══════════════════════════════════════════════════════════
def get_gb_proxy_inline_menu(lang):
    """GB Proxy বাটনের ইনলাইন সাবমেনু — প্রোভাইডার বাটনগুলো 2 by 2 + Cancel।"""
    markup = types.InlineKeyboardMarkup(row_width=2)
    provider_btns = []
    for provider_key in PROXY_PROVIDER_KEYS:
        if _is_isp_provider(provider_key):
            continue  # ISP প্রোভাইডার শুধু "ISP Proxy" মেনুতে দেখাবে
        if not is_kb_button_enabled(provider_key):
            continue
        provider_btns.append(
            InlineBtn(kb_label(provider_key), style=_ik(provider_key), callback_data=f"gbproxy_go_{provider_key}")
        )
    markup.add(*provider_btns)
    markup.add(
        InlineBtn("❌ ক্যানসেল" if lang == "bn" else "❌ Cancel",
                   style=_ik("inline_proxy_cancel"), callback_data="gbproxy_cancel"),
    )
    return markup

def show_gb_proxy_menu(user_id, lang=None):
    """"📦 GB Proxy" কীবোর্ড বাটনে ক্লিক করলে প্রোভাইডার সিলেকশন ইনলাইন মেনু পাঠায়।"""
    if lang is None:
        lang = get_user_lang(user_id)
    if lang == "bn":
        msg = "📦 <b>GB Proxy</b>\n\nনিচে থেকে একটা প্রোভাইডার বেছে নিন 👇"
    else:
        msg = "📦 <b>GB Proxy</b>\n\nChoose a provider below 👇"
    bot.send_message(user_id, msg, parse_mode="HTML", reply_markup=get_gb_proxy_inline_menu(lang))


@bot.callback_query_handler(func=lambda call: (
    call.data.startswith("gbproxy_go_") or call.data == "gbproxy_cancel"
))
def handle_gb_proxy_menu_callback(call):
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_gb_proxy_menu_worker, call)

def _handle_gb_proxy_menu_worker(call):
    try:
        _handle_gb_proxy_menu_worker_impl(call)
    except Exception as e:
        _cw_generic_crash_handler(call, "handle_gb_proxy_menu_callback", e)

def _handle_gb_proxy_menu_worker_impl(call):
    user_id = str(call.message.chat.id)
    if not enforce_join_gate(user_id, call):
        return
    lang = get_user_lang(user_id)
    data = call.data

    if data == "gbproxy_cancel":
        try:
            bot.edit_message_text(
                "❌ ক্যানসেল করা হয়েছে।" if lang == "bn" else "❌ Cancelled.",
                chat_id=call.message.chat.id, message_id=call.message.message_id,
                parse_mode="HTML")
        except Exception:
            try:
                bot.delete_message(call.message.chat.id, call.message.message_id)
            except Exception:
                pass
        return

    provider_key = data[len("gbproxy_go_"):]
    if provider_key not in PROXY_PROVIDER_KEYS:
        return
    show_proxy_provider_products(user_id, provider_key, lang, edit_message_id=call.message.message_id)


@bot.callback_query_handler(func=lambda call: (
    any(call.data.startswith(f"{_k}_p") for _k in PROXY_PROVIDER_KEYS)
    or call.data in ("proxyprov_back", "proxyprov_cancel")
))
def handle_proxy_provider_products_callback(call):
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_proxy_provider_products_worker, call)


def _handle_proxy_provider_products_worker(call):
    try:
        _handle_proxy_provider_products_worker_impl(call)
    except Exception as e:
        _cw_generic_crash_handler(call, "handle_proxy_provider_products_callback", e)

def _handle_proxy_provider_products_worker_impl(call):
    user_id = str(call.message.chat.id)
    if not enforce_join_gate(user_id, call):
        return
    data = call.data
    lang = get_user_lang(user_id)
    db = load_db()

    if data == "proxyprov_cancel":
        try:
            bot.edit_message_text(
                "❌ ক্যানসেল করা হয়েছে।" if lang == "bn" else "❌ Cancelled.",
                chat_id=call.message.chat.id, message_id=call.message.message_id,
                parse_mode="HTML")
        except Exception:
            try:
                bot.delete_message(call.message.chat.id, call.message.message_id)
            except Exception:
                pass
        return

    if data == "proxyprov_back":
        try:
            bot.delete_message(call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        handle_buy_proxy(user_id, db)
        return

    # একটা নির্দিষ্ট প্রোডাক্ট বাটনে ক্লিক করলে (যেমন proxy_abc_p2) → normal
    # প্রোডাক্ট ডিটেইল (নাম/দাম/স্টক + single/bulk buy বাটন) দেখাও — বটের
    # বিদ্যমান delivery engine (show_product_detail_with_subnav) reuse করা হচ্ছে
    for provider_key in PROXY_PROVIDER_KEYS:
        prefix = provider_key + "_p"
        if data.startswith(prefix):
            products = get_proxy_products(db, provider_key)
            try:
                idx = int(data[len(prefix):])
                prod_name = products[idx - 1]
            except Exception:
                return
            show_product_detail_with_subnav(
                user_id, prod_name, db,
                display_name=_proxy_display_name(prod_name, provider_key),
                edit_message_id=call.message.message_id,
                origin="buy_proxy",
            )
            return


