def _nineproxyapi_back_label(lang):
    return "🔙 ব্যাক" if lang == "bn" else "🔙 Back"


def _nineproxyapi_step_markup(lang, rand_label, rand_callback):
    """Username/Password ধাপের জন্য ইনলাইন কীবোর্ড — শুধু একটা 🎲 Random বাটন।
    ✅ 🔙 Back বাটন এখন আর ইনলাইন না — persistent keyboard (reply) বাটন হিসেবে
    আলাদাভাবে পাঠানো হয় (দেখুন _nineproxyapi_credential_back_markup /
    _nineproxyapi_send_back_keyboard)। পুরো ফ্লো (প্যাকেজ ক্লিক → Username →
    Password) এখনো একটামাত্র মেসেজ বারবার এডিট করেই চলে — শুধু ফাইনাল
    ডেলিভারিটাই নতুন মেসেজ হিসেবে আসে।"""
    markup = types.InlineKeyboardMarkup()
    markup.add(InlineBtn(rand_label, style="success", callback_data=rand_callback))
    return markup


def _nineproxyapi_credential_back_markup(lang):
    """✅ Username/Password ধাপের Back বাটন — আগে ইনলাইন বাটন ছিল, এখন persistent
    keyboard (reply) বাটন। কাজ ঠিক আগের মতোই (একধাপ পিছনে/বাতিল), শুধু UI বদলেছে।"""
    markup = types.ReplyKeyboardMarkup(resize_keyboard=True)
    markup.add(KbBtn(_nineproxyapi_back_label(lang), role="back"))
    return markup


def _nineproxyapi_send_back_keyboard(user_id, lang):
    """Username ধাপ শুরু হওয়ার সময় persistent keyboard Back বাটন পাঠায় — edit
    করা মেসেজে reply-keyboard যোগ করা যায় না বলে ছোট্ট একটা আলাদা মেসেজে
    (deposit/realproxy ফ্লোর একই প্যাটার্নে)। এই একই কীবোর্ড Password ধাপেও
    কাজ করে (persistent, নতুন করে পাঠানোর দরকার নেই)।"""
    try:
        bot.send_message(user_id, "👇", reply_markup=_nineproxyapi_credential_back_markup(lang))
    except Exception as e:
        logging.error(f"_nineproxyapi_send_back_keyboard failed: {e}")


