def _nineproxyapi_update_step(user_id, state, text, markup=None):
    """ফ্লো'র একটামাত্র ট্র্যাক করা মেসেজ এডিট করে পরের ধাপ দেখায়। এডিট ব্যর্থ
    হলে (মেসেজ খুব পুরনো/ডিলিট হয়ে গেছে ইত্যাদি) fallback হিসেবে নতুন মেসেজ
    পাঠায় এবং state["msg_id"] নতুন মেসেজে আপডেট করে দেয়।"""
    chat_id = state.get("chat_id") or user_id
    msg_id = state.get("msg_id")
    if msg_id:
        try:
            bot.edit_message_text(text, chat_id=chat_id, message_id=msg_id,
                                   parse_mode="HTML", reply_markup=markup)
            return
        except Exception:
            pass
    sent = bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)
    state["chat_id"] = user_id
    state["msg_id"] = sent.message_id


def _nineproxyapi_loading_text(lang):
    return "⏳ <b>লোড হচ্ছে...</b>" if lang == "bn" else "⏳ <b>Loading...</b>"


def _nineproxyapi_show_loading_then(user_id, state, lang, final_text, final_markup=None, delay=0.7):
    """ধাপ পরিবর্তনের সময় ট্র্যাক করা মেসেজে একটা ছোট্ট "⏳ Loading..." মুহূর্ত
    দেখায়, তারপর আসল পরবর্তী ধাপের কনটেন্টে এডিট করে — যাতে প্যাকেজ ক্লিক থেকে
    শুরু করে পুরো proxy generate ফ্লো জুড়েই ইউজার বুঝতে পারে কিছু একটা
    প্রসেস হচ্ছে। এডিট ব্যর্থ হলে নীরবে বাদ দিয়ে সরাসরি ফাইনাল কনটেন্ট
    দেখানো হয় (_nineproxyapi_update_step এর নিজস্ব fallback দিয়ে)।"""
    chat_id = state.get("chat_id") or user_id
    msg_id = state.get("msg_id")
    if msg_id:
        try:
            bot.edit_message_text(_nineproxyapi_loading_text(lang), chat_id=chat_id, message_id=msg_id, parse_mode="HTML")
            import time as _nineproxyapi_time
            _nineproxyapi_time.sleep(delay)
        except Exception:
            pass
    _nineproxyapi_update_step(user_id, state, final_text, final_markup)


