@bot.callback_query_handler(func=lambda call: call.data.startswith("admin_nineproxyapi_") or call.data == "admin_nineproxyapi_manage")
def handle_admin_nineproxyapi_callback(call):
    if not _nineproxyapi_admin_guard(call):
        bot.answer_callback_query(call.id, "❌ Admin access only!", show_alert=True)
        return
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_admin_nineproxyapi_callback_worker, call)


def _handle_admin_nineproxyapi_callback_worker(call):
    try:
        _handle_admin_nineproxyapi_callback_worker_impl(call)
    except Exception as e:
        _cw_generic_crash_handler(call, "handle_admin_nineproxyapi_callback", e)


def _handle_admin_nineproxyapi_callback_worker_impl(call):
    chat_id = call.message.chat.id
    mid = call.message.message_id
    if not enforce_join_gate(str(chat_id), call):
        return
    data = call.data

    if data == "admin_nineproxyapi_manage":
        show_nineproxyapi_admin_panel(chat_id, mid); return

    # 📦 Bulk Generate — প্যাকেজ বাছাই
    if data == "admin_nineproxyapi_bulk":
        packages = get_nineproxy_api_packages()
        if not packages:
            bot.send_message(chat_id, "❌ <b>কোনো প্যাকেজ নেই!</b> আগে একটা প্যাকেজ যোগ করুন।", parse_mode="HTML"); return
        markup = types.InlineKeyboardMarkup(row_width=1)
        for i, pkg in enumerate(packages, start=1):
            markup.add(InlineBtn(f"📦 {pkg.get('name','Package')} — {pkg.get('mb',0)}MB",
                                 style="primary", callback_data=f"admin_nineproxyapi_bulkpkg_{i}"))
        markup.add(InlineBtn("🔙 Back", style="primary", callback_data="admin_nineproxyapi_manage"))
        bot.send_message(chat_id, "📦 <b>Bulk Generate</b>\n\nকোন প্যাকেজ থেকে বানাবেন?",
                         parse_mode="HTML", reply_markup=markup)
        return

    # 📦 Bulk Generate — কতগুলো (quantity) জিজ্ঞেস করো
    if data.startswith("admin_nineproxyapi_bulkpkg_"):
        idx = data[len("admin_nineproxyapi_bulkpkg_"):]
        packages = get_nineproxy_api_packages()
        try:
            pkg = packages[int(idx) - 1]
        except Exception:
            bot.send_message(chat_id, "❌ প্যাকেজ পাওয়া যায়নি!"); return
        gw_host, gw_port = get_nineproxy_gateway()
        if not gw_host or not gw_port:
            bot.send_message(chat_id, "⚠️ <b>আগে 🖥 Server/Port সেট করুন</b> — না হলে sheet এ Server/Port ফাঁকা থাকবে।",
                             parse_mode="HTML"); return
        msg = bot.send_message(chat_id,
            f"📦 <b>{pkg.get('name','Package')}</b> — {pkg.get('mb',0)}MB\n\n"
            f"কতগুলো (pcs) generate করবেন? <i>(১ – {NINEPROXY_BULK_MAX})</i>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_bulk_qty_step(m, int(idx)))
        return

    if data == "admin_nineproxyapi_toggle":
        db = load_db()
        current = is_nineproxy_api_enabled(db)
        set_nineproxy_api_enabled(not current)
        show_nineproxyapi_admin_panel(chat_id, mid); return

    if data == "admin_nineproxyapi_setgateway":
        msg = bot.send_message(chat_id,
            "🖥 <b>9Proxy Gateway Host লিখুন</b>\n\n<i>উদাহরণ: gate.9proxy.com</i>\n\n"
            "<i>(এটা আপনার 9Proxy ড্যাশবোর্ডের Get Proxy → User-Pass Auth প্যানেলে দেখানো Host)</i>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_nineproxyapi_setgateway_host_step)
        return

    if data == "admin_nineproxyapi_add":
        msg = bot.send_message(chat_id,
            "🆕 <b>নতুন প্যাকেজের নাম লিখুন</b>\n\n<i>উদাহরণ: 100MB Package</i>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_nineproxyapi_add_step1)
        return

    if data.startswith("admin_nineproxyapi_pkg_"):
        idx = data[len("admin_nineproxyapi_pkg_"):]
        show_nineproxyapi_admin_package_detail(chat_id, idx, mid); return

    if data.startswith("admin_nineproxyapi_rename_"):
        idx = data[len("admin_nineproxyapi_rename_"):]
        msg = bot.send_message(chat_id, "✏️ <b>নতুন নাম লিখুন:</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_rename_step(m, idx))
        return

    if data.startswith("admin_nineproxyapi_editmb_"):
        idx = data[len("admin_nineproxyapi_editmb_"):]
        msg = bot.send_message(chat_id, "📶 <b>নতুন MB লিখুন (শুধু সংখ্যা, যেমন: 200):</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_editmb_step(m, idx))
        return

    if data.startswith("admin_nineproxyapi_editprice_"):
        idx = data[len("admin_nineproxyapi_editprice_"):]
        msg = bot.send_message(chat_id, "💰 <b>নতুন Price লিখুন (BDT):</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_editprice_step(m, idx))
        return

    if data.startswith("admin_nineproxyapi_delconfirm_"):
        idx = data[len("admin_nineproxyapi_delconfirm_"):]
        markup = types.InlineKeyboardMarkup(row_width=2)
        markup.add(
            InlineBtn("✅ হ্যাঁ, Delete করো", style="danger", callback_data=f"admin_nineproxyapi_delyes_{idx}"),
            InlineBtn("❌ না, Cancel", style="primary", callback_data=f"admin_nineproxyapi_pkg_{idx}"),
        )
        bot.send_message(chat_id, "⚠️ <b>নিশ্চিত করুন</b>\n\n🗑️ এই প্যাকেজটা চিরতরে ডিলিট করবেন?",
            parse_mode="HTML", reply_markup=markup)
        return

    if data.startswith("admin_nineproxyapi_delyes_"):
        idx = data[len("admin_nineproxyapi_delyes_"):]
        packages = get_nineproxy_api_packages()
        try:
            i = int(idx) - 1
            packages.pop(i)
        except Exception:
            pass
        save_nineproxy_api_packages(packages)
        bot.send_message(chat_id, "✅ <b>প্যাকেজ ডিলিট করা হয়েছে।</b>", parse_mode="HTML")
        show_nineproxyapi_admin_panel(chat_id); return


def admin_nineproxyapi_setgateway_host_step(message):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_nineproxyapi_admin_panel(chat_id); return
    host = (message.text or "").strip()
    if not host:
        msg = bot.send_message(chat_id, "❌ <b>Host খালি রাখা যাবে না!</b> আবার লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_nineproxyapi_setgateway_host_step); return
    msg = bot.send_message(chat_id,
        f"🔌 <b>এখন Port লিখুন</b>\n\n<i>উদাহরণ: 2333</i>\n\n(Host: <code>{host}</code>)",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_setgateway_port_step(m, host))


def admin_nineproxyapi_setgateway_port_step(message, host):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_nineproxyapi_admin_panel(chat_id); return
    port = (message.text or "").strip()
    if not port:
        msg = bot.send_message(chat_id, "❌ <b>Port খালি রাখা যাবে না!</b> আবার লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_setgateway_port_step(m, host)); return
    set_nineproxy_gateway(host, port)
    bot.send_message(chat_id, f"✅ <b>Server/Port সেভ হয়েছে!</b>\n\n🖥 <code>{host}:{port}</code>",
        parse_mode="HTML")
    show_nineproxyapi_admin_panel(chat_id)


def admin_nineproxyapi_add_step1(message):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_nineproxyapi_admin_panel(chat_id); return
    name = (message.text or "").strip()
    if not name:
        msg = bot.send_message(chat_id, "❌ <b>নাম খালি রাখা যাবে না!</b> আবার লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_nineproxyapi_add_step1); return
    msg = bot.send_message(chat_id,
        f"📶 <b>এই প্যাকেজে কত MB থাকবে?</b>\n\n(শুধু সংখ্যা লিখুন, যেমন: 100)",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_add_step2(m, name))


def admin_nineproxyapi_add_step2(message, name):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_nineproxyapi_admin_panel(chat_id); return
    try:
        mb = _parse_num_text(message.text)
        if mb <= 0:
            raise ValueError
        if mb == int(mb):
            mb = int(mb)
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid MB!</b> একটা সংখ্যা লিখুন (যেমন: 100):",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_add_step2(m, name)); return
    # ✅ নোট: User-Pass API (/client/v1/user-passes/create) তে কোনো ন্যূনতম MB নেই
    # (আগের /client/v1/subs/create endpoint এর ১০০০MB restriction এখানে প্রযোজ্য না),
    # তাই 100MB/200MB এর মতো ছোট প্যাকেজও নির্দ্বিধায় যোগ করা যাবে।
    msg = bot.send_message(chat_id, f"💰 <b>'{name}' এর Price লিখুন (BDT):</b>",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_add_step3(m, name, mb))


def admin_nineproxyapi_add_step3(message, name, mb):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_nineproxyapi_admin_panel(chat_id); return
    try:
        price = _parse_num_text(message.text)
        if price <= 0:
            raise ValueError
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid price!</b> একটা সংখ্যা লিখুন (যেমন: 50):",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_add_step3(m, name, mb)); return
    packages = get_nineproxy_api_packages()
    packages.append({"name": name, "mb": mb, "price": price})
    save_nineproxy_api_packages(packages)
    bot.send_message(chat_id,
        f"✅ <b>নতুন প্যাকেজ যোগ হয়েছে!</b>\n\n📦 {name}\n📶 {mb} MB\n💵 {price} BDT",
        parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    show_nineproxyapi_admin_panel(chat_id)


def admin_nineproxyapi_rename_step(message, idx):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_nineproxyapi_admin_panel(chat_id); return
    new_name = (message.text or "").strip()
    if not new_name:
        msg = bot.send_message(chat_id, "❌ <b>নাম খালি রাখা যাবে না!</b> আবার লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_nineproxyapi_rename_step(m, idx)); return
    packages = get_nineproxy_api_packages()
    try:
        i = int(idx) - 1
        packages[i]["name"] = new_name
    except Exception:
        bot.send_message(chat_id, "❌ প্যাকেজ পাওয়া যায়নি!"); show_nineproxyapi_admin_panel(chat_id); return
    save_nineproxy_api_packages(packages)
    bot.send_message(chat_id, f"✅ <b>নাম পরিবর্তন হয়েছে:</b> {new_name}",
        parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    show_nineproxyapi_admin_panel(chat_id)


