# ═══════════════════════════════════════════════════════════
# 🛠️ 711PROXY API MANAGEMENT — Admin Panel Section
# ✅ Admin এখান থেকে 711Proxy sub-account auto-delivery API ON/OFF করতে
#    পারবেন, EAPI Bearer Token ও (ঐচ্ছিক) Host সেট করতে পারবেন, আর প্যাকেজ
#    (নাম + কত MB + দাম) Add/Edit/Delete করতে পারবেন।
# ⚠️ NOTE: catch-all "func=lambda call: True" handler এর আগে define করা।
# ═══════════════════════════════════════════════════════════
def _p711proxyapi_admin_guard(call):
    return is_admin(call.message.chat.id)


def show_p711proxyapi_admin_panel(chat_id, edit_message_id=None):
    import html as _html_p711
    db = load_db()
    enabled = is_p711proxy_api_enabled(db)
    packages = get_p711proxy_api_packages(db)
    username_cred, passwd_cred = get_p711proxy_credentials(db)
    host = get_p711proxy_host(db)
    status_txt = "🟢 চালু (ON)" if enabled else "🔴 বন্ধ (OFF)"
    toggle_label = "🔴 API বন্ধ করুন (OFF করতে ক্লিক করুন)" if enabled else "🟢 API চালু করুন (ON করতে ক্লিক করুন)"
    # ✅ FIX: username/host admin নিজে টাইপ করে সেট করেন — এতে <, >, & থাকলে
    # HTML parse_mode এ পাঠাতে গিয়ে Telegram পুরো মেসেজ reject করে দিত এবং
    # bot crash করতো ("Something went wrong")। তাই এখন escape করে দেওয়া হচ্ছে।
    username_safe = _html_p711.escape(username_cred) if username_cred else ""
    host_safe = _html_p711.escape(host) if host else ""
    creds_txt = f"✅ {username_safe}" if (username_cred and passwd_cred) else "⚠️ এখনো সেট করা হয়নি"
    host_txt = host_safe or "⚠️ (ঐচ্ছিক, খালি থাকলে 711Proxy নিজে বেছে নেবে)"

    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(InlineBtn(toggle_label, style="danger" if enabled else "success",
                          callback_data="admin_p711proxyapi_toggle"))
    markup.add(InlineBtn(f"👤 Username/Password সেট করুন ({username_cred and passwd_cred and '✅' or '⚠️'})",
                          style="primary", callback_data="admin_p711proxyapi_setcreds"))
    markup.add(InlineBtn(f"🖥 Host সেট করুন ({host or '⚠️ (ঐচ্ছিক)'})",
                          style="primary", callback_data="admin_p711proxyapi_sethost"))
    markup.add(InlineBtn("?? Balance চেক করুন", style="primary", callback_data="admin_p711proxyapi_checkbalance"))
    for i, pkg in enumerate(packages, start=1):
        mb = pkg.get("mb", 0)
        price = pkg.get("price", 0)
        markup.add(InlineBtn(f"⚙️ {pkg.get('name','Package')} — {mb}MB — {price}BDT",
                              style="primary", callback_data=f"admin_p711proxyapi_pkg_{i}"))
    markup.add(InlineBtn("➕ Add New Package", style="success", callback_data="admin_p711proxyapi_add"))
    markup.add(InlineBtn("🔙 Back to Providers", style="primary", callback_data="admin_proxyprov_manage"))

    text = (
        f"⚡ <b>711Proxy — Auto API Settings</b>\n"
        f"┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄\n"
        f"🔧 <b>বর্তমান অবস্থা:</b> {status_txt}\n"
        f"👤 <b>Login:</b> {creds_txt}\n"
        f"🖥 <b>Host:</b> <code>{host_txt}</code>\n\n"
        f"<i>API ON থাকলে — ইউজার \"7️⃣ 711Proxy\" বাটনে ক্লিক করলে local stock এর বদলে "
        f"নিচের প্যাকেজ গুলো দেখবে। একটা প্যাকেজে ক্লিক করলেই সাথে সাথে 711Proxy EAPI দিয়ে "
        f"sub-account তৈরি হয়ে Username/Password/Host/Port ডেলিভার হয়ে যাবে — কোনো ইনপুট "
        f"লাগে না, 711Proxy নিজেই সব জেনারেট করে।\n\n"
        f"API OFF থাকলে আগের মতোই local stock (.xlsx) থেকে ডেলিভারি হবে।</i>\n\n"
        f"⚠️ <i>প্রথমে \"👤 Username/Password সেট করুন\" বাটন দিয়ে আপনার 711Proxy লগইন "
        f"username ও password বসিয়ে দিন — bot নিজেই সেটা দিয়ে টোকেন জেনারেট করে নিবে "
        f"এবং মেয়াদ শেষ হলে নিজে থেকেই আবার নতুন টোকেন আনবে, কিছু ম্যানুয়ালি করতে হবে না। "
        f"এটা ছাড়া কোনো অর্ডার তৈরি হবে না।</i>\n\n"
        f"📦 <b>প্যাকেজ:</b> {len(packages) if packages else 'এখনো কোনো প্যাকেজ নেই'}"
    )
    # ✅ FIX: HTML parse ব্যর্থ হলে (কোনো অজানা কারণে) পুরো panel না দেখিয়ে
    # crash করার বদলে — plain text (parse_mode ছাড়া) দিয়ে fallback পাঠানো হয়,
    # যাতে admin অন্তত panel টা দেখতে ও ব্যবহার করতে পারেন।
    if edit_message_id:
        try:
            bot.edit_message_text(text, chat_id=chat_id, message_id=edit_message_id,
                                   parse_mode="HTML", reply_markup=markup)
            return
        except Exception:
            pass
    try:
        bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        logging.error(f"show_p711proxyapi_admin_panel HTML send failed, falling back to plain text: {e}")
        plain_text = re.sub(r"<[^>]+>", "", text)
        bot.send_message(chat_id, plain_text, reply_markup=markup)


def show_p711proxyapi_admin_package_detail(chat_id, idx, edit_message_id=None):
    import html as _html_p711b
    packages = get_p711proxy_api_packages()
    try:
        i = int(idx) - 1
        pkg = packages[i]
    except Exception:
        bot.send_message(chat_id, "❌ প্যাকেজ পাওয়া যায়নি! আবার চেষ্টা করুন।")
        show_p711proxyapi_admin_panel(chat_id); return
    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(InlineBtn("✏️ নাম পরিবর্তন (Rename)", style="primary", callback_data=f"admin_p711proxyapi_rename_{idx}"))
    markup.add(InlineBtn("📶 MB পরিবর্তন", style="primary", callback_data=f"admin_p711proxyapi_editmb_{idx}"))
    markup.add(InlineBtn("💰 Price পরিবর্তন", style="primary", callback_data=f"admin_p711proxyapi_editprice_{idx}"))
    markup.add(InlineBtn("🗑️ Delete Package", style="danger", callback_data=f"admin_p711proxyapi_delconfirm_{idx}"))
    markup.add(InlineBtn("🔙 Back to List", style="primary", callback_data="admin_p711proxyapi_manage"))
    pkg_name_safe = _html_p711b.escape(str(pkg.get('name', 'Package')))
    text = (
        f"⚡ <b>{pkg_name_safe}</b>\n\n"
        f"📶 <b>Traffic:</b> {pkg.get('mb',0)} MB\n"
        f"💵 <b>Price:</b> {pkg.get('price',0)} BDT\n\n"
        f"একটা অপশন বেছে নিন 👇"
    )
    if edit_message_id:
        try:
            bot.edit_message_text(text, chat_id=chat_id, message_id=edit_message_id,
                                   parse_mode="HTML", reply_markup=markup)
            return
        except Exception:
            pass
    try:
        bot.send_message(chat_id, text, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        logging.error(f"show_p711proxyapi_admin_package_detail HTML send failed, falling back to plain text: {e}")
        plain_text = re.sub(r"<[^>]+>", "", text)
        bot.send_message(chat_id, plain_text, reply_markup=markup)


@bot.callback_query_handler(func=lambda call: call.data.startswith("admin_p711proxyapi_") or call.data == "admin_p711proxyapi_manage")
def handle_admin_p711proxyapi_callback(call):
    if not _p711proxyapi_admin_guard(call):
        bot.answer_callback_query(call.id, "❌ Admin access only!", show_alert=True)
        return
    bot.answer_callback_query(call.id)  # ⚡ Instant ACK
    _EXECUTOR.submit(_handle_admin_p711proxyapi_callback_worker, call)


def _handle_admin_p711proxyapi_callback_worker(call):
    try:
        _handle_admin_p711proxyapi_callback_worker_impl(call)
    except Exception as e:
        _cw_generic_crash_handler(call, "handle_admin_p711proxyapi_callback", e)


def _handle_admin_p711proxyapi_callback_worker_impl(call):
    chat_id = call.message.chat.id
    mid = call.message.message_id
    if not enforce_join_gate(str(chat_id), call):
        return
    data = call.data

    if data == "admin_p711proxyapi_manage":
        show_p711proxyapi_admin_panel(chat_id, mid); return

    if data == "admin_p711proxyapi_toggle":
        db = load_db()
        current = is_p711proxy_api_enabled(db)
        set_p711proxy_api_enabled(not current)
        show_p711proxyapi_admin_panel(chat_id, mid); return

    if data == "admin_p711proxyapi_setcreds":
        msg = bot.send_message(chat_id,
            "👤 <b>711Proxy লগইন Username/Email লিখুন</b>\n\n"
            "<i>(এটা দিয়ে bot নিজেই \"GET TOKEN\" এন্ডপয়েন্ট থেকে টোকেন জেনারেট করে নিবে)</i>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_p711proxyapi_setcreds_step1)
        return

    if data == "admin_p711proxyapi_sethost":
        msg = bot.send_message(chat_id,
            "🖥 <b>711Proxy Host লিখুন</b>\n\n<i>(ঐচ্ছিক — খালি পাঠাতে চাইলে শুধু - লিখুন, "
            "তাহলে 711Proxy নিজেই একটা host বেছে নেবে)</i>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_p711proxyapi_sethost_step)
        return

    if data == "admin_p711proxyapi_checkbalance":
        flow_bytes, err = p711proxy_get_balance()
        if err:
            bot.send_message(chat_id, f"❌ <b>Balance চেক করতে সমস্যা হয়েছে:</b>\n<code>{err}</code>",
                parse_mode="HTML")
        else:
            mb = flow_bytes / P711PROXY_BYTES_PER_MB
            gb = mb / 1000
            bot.send_message(chat_id,
                f"🔍 <b>711Proxy EAPI Enterprise Balance</b>\n\n"
                f"📦 <b>Raw:</b> <code>{flow_bytes}</code> bytes\n"
                f"📶 <b>≈ {mb:,.2f} MB</b> (≈ {gb:,.3f} GB)\n\n"
                f"<i>এটা EAPI Enterprise pool-এর ব্যালেন্স — ওয়েবসাইট ড্যাশবোর্ডের "
                f"\"Residential Proxies-GB\" balance থেকে আলাদা হতে পারে। অর্ডার ফেইল "
                f"(\"flow not enough\") হলে এখানে balance যথেষ্ট আছে কিনা আগে চেক করুন।</i>",
                parse_mode="HTML")
        show_p711proxyapi_admin_panel(chat_id); return

    if data == "admin_p711proxyapi_add":
        msg = bot.send_message(chat_id,
            "🆕 <b>নতুন প্যাকেজের নাম লিখুন</b>\n\n<i>উদাহরণ: 1GB Package</i>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_p711proxyapi_add_step1)
        return

    if data.startswith("admin_p711proxyapi_pkg_"):
        idx = data[len("admin_p711proxyapi_pkg_"):]
        show_p711proxyapi_admin_package_detail(chat_id, idx, mid); return

    if data.startswith("admin_p711proxyapi_rename_"):
        idx = data[len("admin_p711proxyapi_rename_"):]
        msg = bot.send_message(chat_id, "✏️ <b>নতুন নাম লিখুন:</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_rename_step(m, idx))
        return

    if data.startswith("admin_p711proxyapi_editmb_"):
        idx = data[len("admin_p711proxyapi_editmb_"):]
        msg = bot.send_message(chat_id, "📶 <b>নতুন MB লিখুন (শুধু সংখ্যা, যেমন: 1000):</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_editmb_step(m, idx))
        return

    if data.startswith("admin_p711proxyapi_editprice_"):
        idx = data[len("admin_p711proxyapi_editprice_"):]
        msg = bot.send_message(chat_id, "💰 <b>নতুন Price লিখুন (BDT):</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_editprice_step(m, idx))
        return

    if data.startswith("admin_p711proxyapi_delconfirm_"):
        idx = data[len("admin_p711proxyapi_delconfirm_"):]
        markup = types.InlineKeyboardMarkup(row_width=2)
        markup.add(
            InlineBtn("✅ হ্যাঁ, Delete করো", style="danger", callback_data=f"admin_p711proxyapi_delyes_{idx}"),
            InlineBtn("❌ না, Cancel", style="primary", callback_data=f"admin_p711proxyapi_pkg_{idx}"),
        )
        bot.send_message(chat_id, "⚠️ <b>নিশ্চিত করুন</b>\n\n🗑️ এই প্যাকেজটা চিরতরে ডিলিট করবেন?",
            parse_mode="HTML", reply_markup=markup)
        return

    if data.startswith("admin_p711proxyapi_delyes_"):
        idx = data[len("admin_p711proxyapi_delyes_"):]
        packages = get_p711proxy_api_packages()
        try:
            i = int(idx) - 1
            del packages[i]
        except Exception:
            pass
        save_p711proxy_api_packages(packages)
        bot.send_message(chat_id, "🗑️ <b>প্যাকেজ ডিলিট হয়েছে!</b>", parse_mode="HTML")
        show_p711proxyapi_admin_panel(chat_id); return


def admin_p711proxyapi_setcreds_step1(message):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_p711proxyapi_admin_panel(chat_id); return
    username = (message.text or "").strip()
    if not username:
        msg = bot.send_message(chat_id, "❌ <b>Username খালি রাখা যাবে না!</b> আবার লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_p711proxyapi_setcreds_step1); return
    msg = bot.send_message(chat_id,
        "🔒 <b>711Proxy লগইন Password লিখুন</b>",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_setcreds_step2(m, username))


def admin_p711proxyapi_setcreds_step2(message, username):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_p711proxyapi_admin_panel(chat_id); return
    passwd = (message.text or "").strip()
    if not passwd:
        msg = bot.send_message(chat_id, "❌ <b>Password খালি রাখা যাবে না!</b> আবার লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_setcreds_step2(m, username)); return

    # ⚡ Username/Password সেভ হওয়ার সাথে সাথেই একবার টেস্ট করে দেখা হয় যে
    # 711Proxy থেকে টোকেন আনা যাচ্ছে কিনা — যাতে ভুল credentials সাথে সাথেই ধরা পড়ে।
    set_p711proxy_credentials(username, passwd)
    token, err = p711proxy_fetch_new_token(username, passwd)
    if token:
        _save_p711proxy_token_cache(token)
        bot.send_message(chat_id,
            "✅ <b>711Proxy Username/Password সেট হয়েছে এবং টোকেন সফলভাবে জেনারেট হয়েছে!</b>\n\n"
            "<i>এখন থেকে bot নিজেই মেয়াদ শেষ হলে নতুন টোকেন এনে নিবে — আপনাকে আর কিছু করতে হবে না।</i>",
            parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    else:
        bot.send_message(chat_id,
            f"⚠️ <b>Username/Password সেভ হয়েছে, কিন্তু টোকেন জেনারেট করতে সমস্যা হয়েছে:</b>\n"
            f"<code>{err}</code>\n\n"
            f"<i>Username/Password ঠিক আছে কিনা চেক করে আবার সেট করুন।</i>",
            parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    show_p711proxyapi_admin_panel(chat_id)


def admin_p711proxyapi_sethost_step(message):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_p711proxyapi_admin_panel(chat_id); return
    host = (message.text or "").strip()
    if host == "-":
        host = ""
    set_p711proxy_host(host)
    bot.send_message(chat_id, f"✅ <b>Host সেট হয়েছে:</b> {host or '(খালি — 711Proxy নিজে বেছে নেবে)'}",
        parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    show_p711proxyapi_admin_panel(chat_id)


def admin_p711proxyapi_add_step1(message):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_p711proxyapi_admin_panel(chat_id); return
    name = (message.text or "").strip()
    if not name:
        msg = bot.send_message(chat_id, "❌ <b>নাম খালি রাখা যাবে না!</b> আবার লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, admin_p711proxyapi_add_step1); return
    msg = bot.send_message(chat_id,
        f"📶 <b>এই প্যাকেজে কত MB থাকবে?</b>\n\n(শুধু সংখ্যা লিখুন, যেমন: 1000)",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_add_step2(m, name))


def admin_p711proxyapi_add_step2(message, name):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_p711proxyapi_admin_panel(chat_id); return
    try:
        mb = _parse_num_text(message.text)
        if mb <= 0:
            raise ValueError
        if mb == int(mb):
            mb = int(mb)
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid MB!</b> একটা সংখ্যা লিখুন (যেমন: 1000):",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_add_step2(m, name)); return
    msg = bot.send_message(chat_id, f"💰 <b>'{name}' এর Price লিখুন (BDT):</b>",
        parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
    bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_add_step3(m, name, mb))


def admin_p711proxyapi_add_step3(message, name, mb):
    chat_id = message.chat.id
    if message.text in ("❌ Cancel", "❌ বাতিল"):
        show_p711proxyapi_admin_panel(chat_id); return
    try:
        price = _parse_num_text(message.text)
        if price <= 0:
            raise ValueError
    except ValueError:
        msg = bot.send_message(chat_id, "❌ <b>Invalid price!</b> একটা সংখ্যা লিখুন (যেমন: 50):",
            parse_mode="HTML", reply_markup=get_cancel_button(chat_id))
        bot.register_next_step_handler(msg, lambda m: admin_p711proxyapi_add_step3(m, name, mb)); return
    packages = get_p711proxy_api_packages()
    packages.append({"name": name, "mb": mb, "price": price})
    save_p711proxy_api_packages(packages)
    bot.send_message(chat_id,
        f"✅ <b>নতুন প্যাকেজ যোগ হয়েছে!</b>\n\n📦 {name}\n📶 {mb} MB\n💵 {price} BDT",
        parse_mode="HTML", reply_markup=get_main_menu(str(chat_id)))
    show_p711proxyapi_admin_panel(chat_id)


