def _proxy_write_quick_stock(product_name, qty, content_text):
    """একই content_text দিয়ে qty সংখ্যক row generate করে xlsx stock file এ append/merge করে —
    Single-column xlsx: heading='Proxy Info', প্রতি row = content_text।"""
    stock_lock = get_stock_lock(product_name)
    with stock_lock:
        path = os.path.join(STOCK_DIR, f"{product_name}.xlsx")
        if os.path.exists(path):
            wb = openpyxl.load_workbook(path)
            ws = wb.active
        else:
            wb = openpyxl.Workbook()
            ws = wb.active
            ws.append(["Proxy Info"])
        for _ in range(qty):
            ws.append([content_text])
        wb.save(path)
        wb.close()
    invalidate_stock_cache(product_name)


