# ══════════════════════════════════════════════════════
# 💲 STATIC PRICE LIST — Golden / Silver / Turbo Package
# ══════════════════════════════════════════════════════
# এই প্রাইসগুলো Real Proxy API থেকে না এনে সরাসরি হার্ডকোড করা —
# প্যাকেজের নাম (case-insensitive, partial match) দিয়ে মিলিয়ে দেখানো হয়।
# key: প্যাকেজ নামের একটা অংশ (lowercase) → value: [(duration_label, usd_price), ...]
REALPROXY_STATIC_PRICES = {
    "golden": [
        ("2 hour", 0.25),
        ("12 hour", 0.45),
        ("1 day", 0.7),
        ("3 day", 2.0),
        ("7 day", 4.0),
        ("15 day", 7.5),
        ("30 day", 14.5),
    ],
    "silver": [
        ("2 day", 1.1),
        ("7 day", 3.0),
        ("30 day", 10.0),
    ],
    "turbo": [
        ("12 hour", 0.7),
        ("1 day", 1.1),
        ("7 day", 7.0),
        ("15 day", 14.0),
        ("30 day", 25.0),
    ],
}

def _rp_static_price_key(package_name):
    """package_name এর মধ্যে golden/silver/turbo এর কোনটা আছে কিনা চেক করে key রিটার্ন করে।"""
    name = (package_name or "").lower()
    for key in REALPROXY_STATIC_PRICES:
        if key in name:
            return key
    return None

# ══════════════════════════════════════════════════════
# 💲 REAL PROXY — ADMIN-EDITABLE PACKAGE PRICE (both display + actual charge)
# ══════════════════════════════════════════════════════
def _rp_parse_duration_label(label):
    """'2 hour' / '1 day' ইত্যাদি label থেকে (days, hours) সংখ্যা বের করে — Real Proxy
    live API-এর days/hours ফিল্ডের সাথে ম্যাচ করানোর জন্য।"""
    import re as _re
    m = _re.match(r"\s*(\d+(?:\.\d+)?)\s*(hour|day)", (label or "").lower())
    if not m:
        return (0.0, 0.0)
    val = float(m.group(1))
    unit = m.group(2)
    return (val, 0.0) if unit == "day" else (0.0, val)

def get_realproxy_static_price(static_key, label):
    """একটা নির্দিষ্ট প্যাকেজ+duration এর বর্তমান admin-সেট USD price রিটার্ন করে (না থাকলে None)।"""
    for lbl, usd in REALPROXY_STATIC_PRICES.get(static_key, []):
        if lbl == label:
            return usd
    return None

def set_realproxy_static_price(static_key, label, new_usd):
    """Admin panel থেকে একটা প্যাকেজ+duration এর USD price বদলায় — ইন-মেমরি dict আপডেট
    করে এবং পুরো REALPROXY_STATIC_PRICES টেবিল MySQL এ persist করে (restart এর পরও মনে থাকে)।"""
    entries = REALPROXY_STATIC_PRICES.get(static_key)
    if entries is None:
        return False
    updated = False
    for i, (lbl, _usd) in enumerate(entries):
        if lbl == label:
            entries[i] = (lbl, new_usd)
            updated = True
            break
    if not updated:
        return False
    _save_realproxy_static_prices()
    return True

def _save_realproxy_static_prices():
    """REALPROXY_STATIC_PRICES পুরো টেবিল settings এ targeted write করে।"""
    serializable = {k: [[lbl, usd] for lbl, usd in v] for k, v in REALPROXY_STATIC_PRICES.items()}
    update_db_path("/settings/realproxy_custom_prices", serializable)

def _load_realproxy_static_prices():
    """Bot startup এ MySQL থেকে admin-সেট প্রাইস টেবিল load করে (থাকলে) — ডিফল্টের উপর override করে।"""
    try:
        db = load_db()
        saved = db.get("settings", {}).get("realproxy_custom_prices", {})
        for key, entries in (saved or {}).items():
            if key in REALPROXY_STATIC_PRICES and isinstance(entries, list):
                REALPROXY_STATIC_PRICES[key] = [(e[0], e[1]) for e in entries if isinstance(e, (list, tuple)) and len(e) == 2]
        print(f"✅ Real Proxy package prices loaded: {saved or '(defaults)'}")
    except Exception as e:
        logging.error(f"_load_realproxy_static_prices error: {e}")

def _rp_apply_price_overrides(static_key, prices):
    """Real Proxy live API থেকে আসা duration/price লিস্টে admin-সেট price
    (REALPROXY_STATIC_PRICES) থাকলে সেটা দিয়ে override করে — যেটা দেখানো হয় সেটাই
    আসলে কেনার সময় চার্জ হবে। days/hours মিলিয়ে ম্যাচ করা হয়; ম্যাচ না পেলে
    API-এর original price-ই থাকে (নিরাপদ fallback)।"""
    if not static_key or static_key not in REALPROXY_STATIC_PRICES:
        return prices
    parsed_overrides = [(_rp_parse_duration_label(lbl), usd) for lbl, usd in REALPROXY_STATIC_PRICES[static_key]]
    out = []
    for pr in prices:
        pr = dict(pr)  # shallow copy — মূল API response mutate করা হয় না
        days = float(pr.get("days", 0) or 0)
        hours = float(pr.get("hours", 0) or 0)
        for (o_days, o_hours), o_usd in parsed_overrides:
            if abs(o_days - days) < 0.001 and abs(o_hours - hours) < 0.001:
                pr["price"] = o_usd
                break
        out.append(pr)
    return out

