def _remember_last_account_from_dict(user_id, d, product=None, order_id=None):
    """ডেলিভারি dict (Email/Password/Token/Full_Data ইত্যাদি যেকোনো heading) থেকে
    token/full data খুঁজে বের করে Get OTP এর জন্য মনে রাখে।"""
    try:
        if not isinstance(d, dict):
            return
        full_data = ""
        for k, v in d.items():
            if str(k).strip().lower().replace(" ", "_") in ("full_data", "fulldata", "token"):
                sv = str(v or "").strip()
                if sv.count("|") >= 3:
                    full_data = sv
                    break
        if not full_data:
            for v in d.values():
                sv = str(v or "").strip()
                if sv.count("|") >= 3 and "@" in sv.split("|")[0]:
                    full_data = sv
                    break
        email = ""
        for k, v in d.items():
            if "mail" in str(k).lower() and "@" in str(v or ""):
                email = str(v).strip()
                break
        if not email and full_data:
            email = full_data.split("|")[0].strip()
        _remember_last_account(user_id, email=email, full_data=full_data, product=product, order_id=order_id)
    except Exception as _e:
        logging.warning(f"_remember_last_account_from_dict error: {_e}")

