def show_user_orders(user_id, db):
    all_orders = [o for o in db["users"].get(user_id, {}).get("orders", []) if isinstance(o, dict)]

    # আজকের date বের করো (BD timezone)
    today_str = datetime.now(BD_TZ).strftime("%d/%m/%y")

    # আজকের orders filter করো
    today_orders = [
        o for o in all_orders
        if today_str in str(o.get("date", ""))
    ]

    # আজকের না থাকলে সর্বশেষ orders দেখাই
    if today_orders:
        display_orders = today_orders[-5:]
        header = t(user_id, "orders_title")
    else:
        display_orders = all_orders[-5:]
        lang = get_user_lang(user_id)
        header = ("📂 <b>Recent Orders (Last 5)</b>\n" if lang == "en"
                  else "📂 <b>সর্বশেষ ৫টি অর্ডার</b>\n")

    if not display_orders:
        bot.send_message(user_id, t(user_id, "no_orders"), parse_mode="HTML")
        return

    lang_o = get_user_lang(user_id, db)
    display = header + "\n"
    for order in display_orders:
        # 🔧 BUG FIX: Real Proxy অর্ডারের ফরম্যাট আলাদা (id বদলে order_id, product_name বদলে
        # product, quantity বদলে duration) — আগে এখানে সরাসরি order["quantity"]/order["id"]/
        # order["product_name"] অ্যাক্সেস করা হতো, যেটা Real Proxy অর্ডারে না থাকায় KeyError
        # দিয়ে পুরো "My Orders" ফাংশনটাই ক্র্যাশ করে ফেলত।
        if order.get("type") == "real_proxy":
            oid = order.get("order_id", "N/A")
            dur_label = order.get("duration_label") or (f"{order.get('duration','?')}")
            total = order.get("price", 0)
            date = order.get("date", "")
            if lang_o == "bn":
                display += (
                    f"🆔 <code>{oid}</code>\n📦 <b>পণ্য:</b> Real Proxy\n"
                    f"⏱️ <b>মেয়াদ:</b> {dur_label} | 💰 <b>মোট:</b> {total} BDT\n"
                    f"📅 <b>তারিখ:</b> {date}\n"
                )
            else:
                display += (
                    f"🆔 <code>{oid}</code>\n📦 <b>Product:</b> Real Proxy\n"
                    f"⏱️ <b>Duration:</b> {dur_label} | 💰 <b>Total:</b> {total} BDT\n"
                    f"📅 <b>Date:</b> {date}\n"
                )
        else:
            display += t(user_id, "order_item",
                id=order.get("id", "N/A"), product=_vpn_display_name(order.get("product_name", "?")),
                qty=order.get("quantity", "?"), total=order.get("total", 0), date=order.get("date", ""))
        display += "\n"

    bot.send_message(user_id, display, parse_mode="HTML")

def _flash_loading(user_id, delay=0.1):
    """ছোট্ট "⏳ Loading..." মেসেজ দেখায়, delay সেকেন্ড অপেক্ষা করে, তারপর
    মুছে দেয় — এরপর আসল কনটেন্ট পাঠানো হয়। কোনো কারণে ব্যর্থ হলে নীরবে বাদ
    দেয় (মূল ফিচার কখনো আটকায় না)।"""
    try:
        _lg = _lang_cache.get(user_id, "en")
        _txt = "⏳ <b>লোড হচ্ছে...</b>" if _lg == "bn" else "⏳ <b>Loading...</b>"
        _lm = bot.send_message(user_id, _txt, parse_mode="HTML")
        import time as _fl_time
        _fl_time.sleep(delay)
        try:
            bot.delete_message(user_id, _lm.message_id)
        except Exception:
            pass
    except Exception:
        pass

