# 💱 DOLLAR BUY / SELL  (More Option → Dollar($) Buy/Sell)
# ═══════════════════════════════════════════════════════════════════
# 🔴 Sell Dollar  → ইউজার Binance এ USDT পাঠায় → Admin ইউজারের bKash/Nagad/Rocket এ টাকা দেয়
# 🟢 Buy Dollar   → ইউজার bKash/Nagad/Rocket এ টাকা পাঠায় → Admin ইউজারের Binance এ ডলার দেয়
#
# ✅ রেট: ৩টা রেঞ্জ (0.5-5$, 5.1-10$, 10.1-100+$) — প্রতিটার Buy ও Sell রেট আলাদা,
#    Admin Panel → 💱 Dollar Buy/Sell Manager থেকে সেট হয়। রেট সেট না থাকলে ইউজার
#    সেই রেঞ্জে অর্ডার করতে পারবে না (কোনো অনুমানের রেটে লেনদেন হয় না)।
# ✅ সব অর্ডার db["dollar_orders"] এ থাকে; Admin এর কাছে স্ক্রিনশটসহ Paid/Sent ও Reject বাটন যায়।
# ✅ Callback prefix: dlr_ (ইউজার/অ্যাডমিন অ্যাকশন) ও admin_dlr_ (Admin Manager) —
#    _callback_worker_impl থেকে handle_dollar_callback() এ রাউট হয়।
# ═══════════════════════════════════════════════════════════════════
import html as _dlr_html
import math as _dlr_math

DLR_MIN_USD   = 0.5
DLR_MAX_USD   = 100000
DLR_STATE_TTL = 1800   # ৩০ মিনিট — অসম্পূর্ণ অর্ডার সেশন এরপর মুছে যায়

# (range_no, label)
DLR_RANGES = [
    (1, "0.5$ – 5$"),
    (2, "5.1$ – 10$"),
    (3, "10.1$ – 100+$"),
]
# key → (নাম, emoji, style)
DLR_METHODS = {
    "bkash":  ("Bkash",  "🟠", "primary"),
    "nagad":  ("Nagad",  "🟢", "success"),
    "rocket": ("Rocket", "🔴", "danger"),
}

_dlr_state = {}
_dlr_state_lock = threading.Lock()


def _dl(user_id, bn, en):
    """ইউজারের ভাষা অনুযায়ী বাংলা/ইংরেজি টেক্সট বেছে নেয়।"""
    try:
        return bn if get_user_lang(user_id) == "bn" else en
    except Exception:
        return bn


def _dlr_esc(x):
    return _dlr_html.escape(str(x if x is not None else ""))


def _dlr_num(x):
    """1.0 → '1', 7.5 → '7.5', 7.25 → '7.25'"""
    x = round(float(x), 2)
    if x == int(x):
        return str(int(x))
    return f"{x:.2f}".rstrip("0").rstrip(".")


# ── ইউজারের চলমান অর্ডার সেশন ──
def _dlr_set(user_id, **kw):
    with _dlr_state_lock:
        st = _dlr_state.get(user_id)
        if not st:
            st = {}
            _dlr_state[user_id] = st
        st.update(kw)
        st["ts"] = _time_module.time()
        return st


def _dlr_get(user_id):
    with _dlr_state_lock:
        st = _dlr_state.get(user_id)
        if not st:
            return None
        if _time_module.time() - st.get("ts", 0) > DLR_STATE_TTL:
            _dlr_state.pop(user_id, None)
            return None
        return st


def _dlr_clear(user_id):
    with _dlr_state_lock:
        _dlr_state.pop(user_id, None)


# ── Config (Admin সেট) ──
def _dlr_cfg(db=None):
    if db is None:
        db = load_db()
    raw = (db.get("settings", {}) or {}).get("dollar_trade", {}) or {}
    if not isinstance(raw, dict):
        raw = {}

    def _rates(side):
        r = raw.get(side, {})
        if not isinstance(r, dict):
            r = {}
        out = {}
        for n in (1, 2, 3):
            try:
                v = float(r.get(f"r{n}", 0) or 0)
            except (TypeError, ValueError):
                v = 0.0
            out[n] = v if v > 0 else 0.0
        return out

    return {
        "enabled":    raw.get("enabled", True) is not False,
        "buy":        _rates("buy"),
        "sell":       _rates("sell"),
        "binance_id": str(raw.get("binance_id") or BINANCE_ID),
        "bkash":      str(raw.get("bkash") or BKASH_NUMBER),
        "nagad":      str(raw.get("nagad") or NAGAD_NUMBER),
        "rocket":     str(raw.get("rocket") or ROCKET_NUMBER),
    }


def _dlr_save_raw(mutator):
    """settings/dollar_trade dict টা পড়ে mutator দিয়ে বদলে সেভ করে।"""
    db = load_db()
    db.setdefault("settings", {})
    raw = db["settings"].get("dollar_trade", {})
    if not isinstance(raw, dict):
        raw = {}
    raw = dict(raw)
    mutator(raw)
    db["settings"]["dollar_trade"] = raw
    update_db_path("/settings/dollar_trade", raw)
    return raw


def _dlr_range_for(usd):
    return 1 if usd <= 5 else (2 if usd <= 10 else 3)


def _dlr_rate_table(user_id, side, cfg):
    lines = []
    for n, label in DLR_RANGES:
        r = cfg[side][n]
        val = (f"<b>{_dlr_num(r)} BDT</b>" if r > 0
               else _dl(user_id, "<i>সেট করা নেই</i>", "<i>not set</i>"))
        lines.append(f"• <code>{label}</code>  →  1$ = {val}")
    return "\n".join(lines)


