def show_dollar_menu(user_id, db=None):
    """More Option → Dollar($) Buy/Sell বাটনে ক্লিক করলে।"""
    _dlr_clear(user_id)
    cfg = _dlr_cfg(db)
    if not cfg["enabled"]:
        bot.send_message(user_id, _dl(user_id,
            "💱 <b>Dollar Buy / Sell</b>\n\n🔒 এই সার্ভিসটি এখন সাময়িকভাবে বন্ধ আছে। একটু পরে আবার চেষ্টা করুন।",
            "💱 <b>Dollar Buy / Sell</b>\n\n🔒 This service is temporarily closed. Please try again later."),
            parse_mode="HTML", reply_markup=get_dollar_menu(user_id))
        return
    text = (
        "💵 <b>Welcome to Virtual Shop</b>\n"
        "<b>Dollar Trading Centre</b>\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        "Buy and sell US dollars quickly, securely and at transparent rates, "
        "backed by fast and professional service."
    )
    bot.send_message(user_id, text, parse_mode="HTML", reply_markup=get_dollar_menu(user_id))


# ── ধাপের শুরুতে Cancel / অন্য মেনু বাটন ধরার guard ──
def _dlr_guard(message):
    """(user_id, text) রিটার্ন করে। Cancel/মেনু বাটন হলে ফ্লো বন্ধ করে None রিটার্ন করে।"""
    user_id = str(message.chat.id)
    text = (message.text or "").strip()
    if text and text in ("❌ Cancel", LANG["en"]["cancel"], LANG["bn"]["cancel"]):
        _dlr_clear(user_id)
        bot.send_message(user_id, _dl(user_id, "❌ বাতিল করা হয়েছে।", "❌ Cancelled."),
                         reply_markup=get_dollar_menu(user_id))
        return None
    if text and _is_menu_navigation_text(user_id, text):
        _dlr_clear(user_id)
        _text_message_worker(message)
        return None
    return user_id, text


def _dlr_expired(user_id):
    bot.send_message(user_id, _dl(user_id,
        "⌛ সেশন শেষ হয়ে গেছে। অনুগ্রহ করে নিচের বাটন থেকে আবার শুরু করুন।",
        "⌛ Session expired. Please start again from the buttons below."),
        reply_markup=get_dollar_menu(user_id))


def _dlr_cancel_inline(user_id):
    m = types.InlineKeyboardMarkup()
    m.add(InlineBtn(_dl(user_id, "❌ বাতিল", "❌ Cancel"), style="danger", callback_data="dlr_cancel"))
    return m


# ── ধাপ ১: পরিমাণ ──
def start_dollar_flow(user_id, side, db=None):
    cfg = _dlr_cfg(db)
    if not cfg["enabled"]:
        show_dollar_menu(user_id, db); return
    if not any(cfg[side][n] > 0 for n in (1, 2, 3)):
        bot.send_message(user_id, _dl(user_id,
            "⚠️ এই মুহূর্তে এই সার্ভিসের রেট সেট করা নেই। একটু পরে আবার চেষ্টা করুন।",
            "⚠️ The rate for this service isn't set yet. Please try again later."),
            reply_markup=get_dollar_menu(user_id))
        return
    _dlr_set(user_id, side=side, step="amount")
    if side == "sell":
        text = _dl(user_id,
            "💰 <b>Sell Dollar</b>  •  ধাপ 1/4\n\n{table}\n\n"
            "কত ডলার বিক্রি করতে চান? সংখ্যায় লিখুন 👇\n"
            "<i>ন্যূনতম 0.5$ • যেমন: 7 অথবা 12.5</i>",
            "💰 <b>Sell Dollar</b>  •  Step 1/4\n\n{table}\n\n"
            "How many dollars do you want to sell? Send a number 👇\n"
            "<i>Minimum 0.5$ • e.g. 7 or 12.5</i>")
    else:
        text = _dl(user_id,
            "🛒 <b>Buy Dollar</b>  •  ধাপ 1/4\n\n{table}\n\n"
            "কত ডলার কিনতে চান? সংখ্যায় লিখুন 👇\n"
            "<i>ন্যূনতম 0.5$ • যেমন: 7 অথবা 12.5</i>",
            "🛒 <b>Buy Dollar</b>  •  Step 1/4\n\n{table}\n\n"
            "How many dollars do you want to buy? Send a number 👇\n"
            "<i>Minimum 0.5$ • e.g. 7 or 12.5</i>")
    msg = bot.send_message(user_id, text.format(table=_dlr_rate_table(user_id, side, cfg)),
                           parse_mode="HTML", reply_markup=get_cancel_button(user_id))
    bot.register_next_step_handler(msg, lambda m: _dlr_amount_step(m, side))


def _dlr_amount_step(message, side):
    g = _dlr_guard(message)
    if g is None:
        return
    user_id, text = g
    st = _dlr_get(user_id)
    if not st or st.get("side") != side:
        _dlr_expired(user_id); return

    def _reask(err_bn, err_en):
        msg = bot.send_message(user_id, _dl(user_id, err_bn, err_en), parse_mode="HTML")
        bot.register_next_step_handler(msg, lambda m: _dlr_amount_step(m, side))

    try:
        usd = float(text.replace(",", ".").replace("$", "").strip())
    except (ValueError, TypeError):
        usd = None
    if usd is None or not _dlr_math.isfinite(usd):
        _reask("❌ শুধু সংখ্যা লিখুন। যেমন: <code>7</code> অথবা <code>12.5</code>",
               "❌ Please send a number only. e.g. <code>7</code> or <code>12.5</code>")
        return
    usd = round(usd, 2)
    if usd < DLR_MIN_USD:
        _reask(f"❌ ন্যূনতম <b>{_dlr_num(DLR_MIN_USD)}$</b> লিখতে হবে।",
               f"❌ Minimum amount is <b>{_dlr_num(DLR_MIN_USD)}$</b>.")
        return
    if usd > DLR_MAX_USD:
        _reask("❌ এত বড় অ্যামাউন্ট একসাথে সম্ভব না। সাপোর্টে যোগাযোগ করুন।",
               "❌ That amount is too large. Please contact support.")
        return

    cfg = _dlr_cfg()
    n = _dlr_range_for(usd)
    rate = cfg[side][n]
    if rate <= 0:
        _reask("⚠️ এই রেঞ্জের রেট এখনো সেট করা নেই। অন্য একটা পরিমাণ লিখুন।",
               "⚠️ The rate for this range isn't set yet. Please send a different amount.")
        return
    bdt = round(usd * rate, 2)
    _dlr_set(user_id, side=side, usd=usd, rate=rate, range_no=n, bdt=bdt, step="method")

    if side == "sell":
        head = _dl(user_id, "💰 <b>Sell Dollar</b>  •  ধাপ 2/4", "💰 <b>Sell Dollar</b>  •  Step 2/4")
        calc = _dl(user_id,
            "🧾 <b>হিসাব</b>\n💵 ডলার: <b>{usd}$</b>\n📈 রেট: 1$ = {rate} BDT\n💰 আপনি পাবেন: <b>{bdt} BDT</b>\n\n"
            "📱 কোন মাধ্যমে টাকা নিতে চান? 👇",
            "🧾 <b>Calculation</b>\n💵 Dollars: <b>{usd}$</b>\n📈 Rate: 1$ = {rate} BDT\n💰 You will get: <b>{bdt} BDT</b>\n\n"
            "📱 Where do you want to receive the money? 👇")
    else:
        head = _dl(user_id, "🛒 <b>Buy Dollar</b>  •  ধাপ 2/4", "🛒 <b>Buy Dollar</b>  •  Step 2/4")
        calc = _dl(user_id,
            "🧾 <b>হিসাব</b>\n💵 ডলার: <b>{usd}$</b>\n📈 রেট: 1$ = {rate} BDT\n💰 আপনাকে দিতে হবে: <b>{bdt} BDT</b>\n\n"
            "📱 কোন মাধ্যমে টাকা পাঠাবেন? 👇",
            "🧾 <b>Calculation</b>\n💵 Dollars: <b>{usd}$</b>\n📈 Rate: 1$ = {rate} BDT\n💰 You need to pay: <b>{bdt} BDT</b>\n\n"
            "📱 Which method will you pay with? 👇")
    calc = calc.format(usd=_dlr_num(usd), rate=_dlr_num(rate), bdt=fmt_bdt_precise(bdt))

    markup = types.InlineKeyboardMarkup(row_width=2)
    markup.row(
        InlineBtn("🟠 Bkash", style="primary", callback_data="dlr_m_bkash"),
        InlineBtn("🟢 Nagad", style="success", callback_data="dlr_m_nagad"),
    )
    markup.row(InlineBtn("🔴 Rocket", style="danger", callback_data="dlr_m_rocket"))
    markup.row(InlineBtn(_dl(user_id, "❌ বাতিল", "❌ Cancel"), style="danger", callback_data="dlr_cancel"))
    bot.send_message(user_id, f"{head}\n\n{calc}", parse_mode="HTML", reply_markup=markup)


# ── ধাপ ২: মাধ্যম বাছাই (inline callback) ──
def _dlr_method_chosen(call, user_id, method):
    st = _dlr_get(user_id)
    if not st or st.get("step") != "method" or method not in DLR_METHODS:
        _dlr_expired(user_id); return
    side = st["side"]
    mname, memoji, _s = DLR_METHODS[method]
    _dlr_set(user_id, method=method)

    # বাছাই করা মেসেজ থেকে বাটন সরিয়ে দাও (দুইবার ক্লিক ঠেকাতে)
    try:
        bot.edit_message_reply_markup(user_id, call.message.message_id, reply_markup=None)
    except Exception:
        pass

    if side == "sell":
        _dlr_set(user_id, step="number")
        msg = bot.send_message(user_id, _dl(user_id,
            f"{memoji} <b>{mname}</b> বাছাই করেছেন  •  ধাপ 3/4\n\n"
            f"আপনার <b>{mname}</b> নম্বরটি লিখুন (যেখানে টাকা পাবেন) 👇\n"
            f"<i>যেমন: 01XXXXXXXXX</i>",
            f"{memoji} <b>{mname}</b> selected  •  Step 3/4\n\n"
            f"Send your <b>{mname}</b> number (where you'll receive the money) 👇\n"
            f"<i>e.g. 01XXXXXXXXX</i>"),
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, _dlr_number_step)
    else:
        _dlr_set(user_id, step="binance")
        msg = bot.send_message(user_id, _dl(user_id,
            f"{memoji} <b>{mname}</b> বাছাই করেছেন  •  ধাপ 3/4\n\n"
            f"🏦 যে <b>Binance Pay ID</b> (অথবা USDT Wallet Address) এ ডলার নিতে চান সেটা লিখুন 👇\n"
            f"<i>ভুল ID দিলে ডলার হারিয়ে যেতে পারে — ভালোভাবে দেখে লিখুন।</i>",
            f"{memoji} <b>{mname}</b> selected  •  Step 3/4\n\n"
            f"🏦 Send the <b>Binance Pay ID</b> (or USDT wallet address) where you want to receive the dollars 👇\n"
            f"<i>A wrong ID can mean lost funds — double-check it.</i>"),
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, _dlr_binance_step)


# ── Sell: ইউজারের payout নম্বর ──
def _dlr_normalize_bd_number(text):
    s = re.sub(r"[\s\-]", "", text or "")
    if s.startswith("+880"):
        s = "0" + s[4:]
    elif s.startswith("880") and len(s) == 13:
        s = "0" + s[3:]
    return s if re.fullmatch(r"01[3-9]\d{8}", s) else None


