# ── ধাপ ৪: স্ক্রিনশট ──
def _dlr_shot_step(message):
    user_id = str(message.chat.id)
    st = _dlr_get(user_id)

    if message.content_type == "text":
        g = _dlr_guard(message)
        if g is None:
            return
        file_id, ftype = None, None
    elif message.content_type == "photo" and message.photo:
        file_id, ftype = message.photo[-1].file_id, "photo"
    elif (message.content_type == "document" and message.document
          and str(message.document.mime_type or "").startswith("image/")):
        file_id, ftype = message.document.file_id, "document"
    else:
        file_id, ftype = None, None

    if not st or st.get("step") != "shot":
        _dlr_expired(user_id); return

    if not file_id:
        msg = bot.send_message(user_id, _dl(user_id,
            "📸 অনুগ্রহ করে পেমেন্টের <b>স্ক্রিনশট (ছবি)</b> পাঠান।",
            "📸 Please send the payment <b>screenshot (image)</b>."), parse_mode="HTML")
        bot.register_next_step_handler(msg, _dlr_shot_step)
        return
    _dlr_submit_order(user_id, st, file_id, ftype)


def _dlr_order_view(rec):
    """অর্ডারের ডিটেইলস (Admin ক্যাপশনের জন্য)।"""
    side = rec["side"]
    mname, memoji, _s = DLR_METHODS.get(rec.get("method"), (rec.get("method", "?"), "💳", "primary"))
    label = dict(DLR_RANGES).get(rec.get("range_no"), "")
    uname = get_cached_username(rec["user_id"])
    if side == "sell":
        head = "🔴 <b>DOLLAR SELL ORDER</b> (User ডলার দিচ্ছে)"
        body = (f"💰 <b>User কে দিতে হবে: {fmt_bdt_precise(rec['bdt'])} BDT</b>\n"
                f"{memoji} {mname}: <code>{_dlr_esc(rec['number'])}</code>\n"
                f"🏦 User এর পাঠানোর Binance ID: <code>{_dlr_esc(rec['binance_id'])}</code>")
        todo = "👉 Binance এ USDT এসেছে যাচাই করে টাকা পাঠান, তারপর <b>Paid</b> চাপুন।"
    else:
        head = "🟢 <b>DOLLAR BUY ORDER</b> (User ডলার কিনছে)"
        body = (f"💰 <b>User দিয়েছে: {fmt_bdt_precise(rec['bdt'])} BDT</b> ({memoji} {mname} → <code>{_dlr_esc(rec['number'])}</code>)\n"
                f"🏦 ডলার পাঠাতে হবে: <code>{_dlr_esc(rec['binance_id'])}</code>")
        todo = "👉 পেমেন্ট এসেছে যাচাই করে ডলার পাঠান, তারপর <b>Sent</b> চাপুন।"
    return (f"{head}\n━━━━━━━━━━━━━━\n"
            f"🆔 <code>{rec['id']}</code>\n"
            f"👤 <code>{rec['user_id']}</code> (@{_dlr_esc(uname)})\n"
            f"💵 <b>{_dlr_num(rec['usd'])}$</b>  •  রেট: {_dlr_num(rec['rate'])} ({label})\n"
            f"{body}\n📅 {rec['date']}\n━━━━━━━━━━━━━━\n{todo}")


def _dlr_submit_order(user_id, st, file_id, ftype):
    db = load_db()
    if user_id in db.get("banned_users", []):
        _dlr_clear(user_id)
        bot.send_message(user_id, LANG["en"]["banned"], parse_mode="HTML")
        return
    side = st["side"]
    cfg = _dlr_cfg(db)
    oid = "DL" + datetime.now(BD_TZ).strftime("%d%H%M%S") + uuid.uuid4().hex[:3].upper()
    if side == "sell":
        number, binance_id = st["number"], cfg["binance_id"]
    else:
        number, binance_id = cfg[st["method"]], st["binance_id"]
    rec = {
        "id": oid, "user_id": user_id, "side": side,
        "usd": st["usd"], "rate": st["rate"], "range_no": st["range_no"], "bdt": st["bdt"],
        "method": st["method"], "number": number, "binance_id": binance_id,
        "screenshot": file_id, "file_type": ftype,
        "status": "pending", "date": get_now(),
    }
    db.setdefault("dollar_orders", {})[oid] = rec
    update_db_path(f"/dollar_orders/{oid}", rec)
    _dlr_clear(user_id)

    # ── ইউজারকে কনফার্মেশন ──
    if side == "sell":
        u_text = _dl(user_id,
            "✅ <b>অর্ডার জমা হয়েছে!</b>\n\n🆔 <code>{oid}</code>\n💵 {usd}$  →  💰 <b>{bdt} BDT</b>\n\n"
            "⏳ আমরা Binance এ আপনার ডলার যাচাই করে {mname} এ টাকা পাঠিয়ে দেব। সম্পন্ন হলে এখানেই জানানো হবে। 🙏",
            "✅ <b>Order submitted!</b>\n\n🆔 <code>{oid}</code>\n💵 {usd}$  →  💰 <b>{bdt} BDT</b>\n\n"
            "⏳ We'll verify your dollars on Binance and send the money to your {mname}. You'll be notified here. 🙏")
    else:
        u_text = _dl(user_id,
            "✅ <b>অর্ডার জমা হয়েছে!</b>\n\n🆔 <code>{oid}</code>\n💰 {bdt} BDT  →  💵 <b>{usd}$</b>\n\n"
            "⏳ আমরা আপনার {mname} পেমেন্ট যাচাই করে Binance এ ডলার পাঠিয়ে দেব। সম্পন্ন হলে এখানেই জানানো হবে। 🙏",
            "✅ <b>Order submitted!</b>\n\n🆔 <code>{oid}</code>\n💰 {bdt} BDT  →  💵 <b>{usd}$</b>\n\n"
            "⏳ We'll verify your {mname} payment and send the dollars to your Binance. You'll be notified here. 🙏")
    mname = DLR_METHODS[st["method"]][0]
    bot.send_message(user_id, u_text.format(oid=oid, usd=_dlr_num(st["usd"]),
                     bdt=fmt_bdt_precise(st["bdt"]), mname=mname),
                     parse_mode="HTML", reply_markup=get_dollar_menu(user_id))

    # ── Admin কে স্ক্রিনশটসহ নোটিফিকেশন ──
    markup = types.InlineKeyboardMarkup()
    done_label = "✅ টাকা পাঠিয়েছি (Paid)" if side == "sell" else "✅ ডলার পাঠিয়েছি (Sent)"
    markup.add(InlineBtn(done_label, style="success", callback_data=f"dlr_done_{oid}"),
               InlineBtn("❌ Reject", style="danger", callback_data=f"dlr_rej_{oid}"))
    caption = _dlr_order_view(rec)
    try:
        if ftype == "document":
            bot.send_document(ADMIN_ID, file_id, caption=caption, parse_mode="HTML", reply_markup=markup)
        else:
            bot.send_photo(ADMIN_ID, file_id, caption=caption, parse_mode="HTML", reply_markup=markup)
    except Exception as e:
        logging.error(f"dollar order admin notify (media) failed: {e}")
        try:
            bot.send_message(ADMIN_ID, caption + "\n\n⚠️ (স্ক্রিনশট পাঠানো যায়নি)", parse_mode="HTML", reply_markup=markup)
        except Exception as e2:
            logging.error(f"dollar order admin notify failed: {e2}")
    log_action("DOLLAR_ORDER", user_id,
               f"{side} {st['usd']}$ @ {st['rate']} = {st['bdt']} BDT via {st['method']} | {oid}")


# ── Admin: Paid / Sent / Reject ──
def _dlr_edit_admin_msg(call, rec, status_line):
    text = _dlr_order_view(rec).rsplit("━━━━━━━━━━━━━━", 1)[0] + "━━━━━━━━━━━━━━\n" + status_line
    try:
        if call.message.content_type in ("photo", "document"):
            bot.edit_message_caption(caption=text, chat_id=call.message.chat.id,
                                     message_id=call.message.message_id, parse_mode="HTML", reply_markup=None)
        else:
            bot.edit_message_text(text, call.message.chat.id, call.message.message_id,
                                  parse_mode="HTML", reply_markup=None)
    except Exception as e:
        logging.error(f"dollar admin msg edit failed: {e}")


def _dlr_admin_done(call, admin_id, oid):
    db = load_db()
    rec = db.get("dollar_orders", {}).get(oid)
    if not rec:
        bot.send_message(admin_id, "❌ অর্ডার পাওয়া যায়নি।"); return
    if rec.get("status") != "pending":
        bot.send_message(admin_id, f"⚠️ এই অর্ডার আগেই প্রসেস হয়েছে ({rec.get('status')})।"); return
    rec["status"] = "completed"
    rec["done_by"] = admin_id
    rec["done_date"] = get_now()
    update_db_path(f"/dollar_orders/{oid}", rec)
    _dlr_edit_admin_msg(call, rec, f"✅ <b>COMPLETED</b> — {rec['done_date']}")

    uid = rec["user_id"]
    mname = DLR_METHODS.get(rec["method"], (rec["method"],))[0]
    if rec["side"] == "sell":
        u_text = _dl(uid,
            "✅ <b>টাকা পাঠানো হয়েছে!</b>\n\n🆔 <code>{oid}</code>\n💰 <b>{bdt} BDT</b> আপনার {mname} নম্বরে "
            "(<code>{num}</code>) পাঠানো হয়েছে।\n\nআমাদের সাথে লেনদেনের জন্য ধন্যবাদ! 🙏",
            "✅ <b>Money sent!</b>\n\n🆔 <code>{oid}</code>\n💰 <b>{bdt} BDT</b> has been sent to your {mname} "
            "(<code>{num}</code>).\n\nThanks for trading with us! 🙏")
    else:
        u_text = _dl(uid,
            "✅ <b>ডলার পাঠানো হয়েছে!</b>\n\n🆔 <code>{oid}</code>\n💵 <b>{usd}$</b> আপনার Binance ID তে "
            "(<code>{num}</code>) পাঠানো হয়েছে। Binance এ চেক করে নিন।\n\nআমাদের সাথে লেনদেনের জন্য ধন্যবাদ! 🙏",
            "✅ <b>Dollars sent!</b>\n\n🆔 <code>{oid}</code>\n💵 <b>{usd}$</b> has been sent to your Binance ID "
            "(<code>{num}</code>). Please check Binance.\n\nThanks for trading with us! 🙏")
    try:
        bot.send_message(uid, u_text.format(oid=oid, bdt=fmt_bdt_precise(rec["bdt"]), usd=_dlr_num(rec["usd"]),
                         mname=mname, num=_dlr_esc(rec["number"] if rec["side"] == "sell" else rec["binance_id"])),
                         parse_mode="HTML")
    except Exception as e:
        bot.send_message(admin_id, f"⚠️ ইউজারকে মেসেজ পাঠানো যায়নি: {e}")
    log_action("DOLLAR_COMPLETED", admin_id, f"{oid} → user {uid}")


def _dlr_admin_reject_ask(call, admin_id, oid):
    db = load_db()
    rec = db.get("dollar_orders", {}).get(oid)
    if not rec:
        bot.send_message(admin_id, "❌ অর্ডার পাওয়া যায়নি।"); return
    if rec.get("status") != "pending":
        bot.send_message(admin_id, f"⚠️ এই অর্ডার আগেই প্রসেস হয়েছে ({rec.get('status')})।"); return
    msg = bot.send_message(admin_id,
        f"❌ <b>Reject — {oid}</b>\n\nইউজারকে দেখানোর কারণ লিখুন (কারণ ছাড়া reject করতে <code>-</code> লিখুন):",
        parse_mode="HTML", reply_markup=get_cancel_button(admin_id))
    bot.register_next_step_handler(msg, lambda m: _dlr_admin_reject_step(m, call, oid))


def _dlr_admin_reject_step(message, call, oid):
    admin_id = str(message.chat.id)
    text = (message.text or "").strip()
    if text in ("❌ Cancel", LANG["en"]["cancel"], LANG["bn"]["cancel"]):
        bot.send_message(admin_id, "↩️ Reject বাতিল।", reply_markup=get_main_menu(admin_id)); return
    db = load_db()
    rec = db.get("dollar_orders", {}).get(oid)
    if not rec or rec.get("status") != "pending":
        bot.send_message(admin_id, "⚠️ অর্ডারটি আর pending নেই।", reply_markup=get_main_menu(admin_id)); return
    reason = "" if text in ("-", "") else text[:300]
    rec["status"] = "rejected"
    rec["reject_reason"] = reason
    rec["done_by"] = admin_id
    rec["done_date"] = get_now()
    update_db_path(f"/dollar_orders/{oid}", rec)
    _dlr_edit_admin_msg(call, rec, f"❌ <b>REJECTED</b> — {rec['done_date']}" + (f"\n📝 {_dlr_esc(reason)}" if reason else ""))
    uid = rec["user_id"]
    u_text = _dl(uid,
        "❌ <b>অর্ডার বাতিল করা হয়েছে</b>\n\n🆔 <code>{oid}</code>\n{reason}"
        "কোনো সমস্যা থাকলে সাপোর্টে যোগাযোগ করুন: @{sup}",
        "❌ <b>Order rejected</b>\n\n🆔 <code>{oid}</code>\n{reason}"
        "If you have any problem, contact support: @{sup}").format(
        oid=oid,
        reason=(_dl(uid, "📝 কারণ: ", "📝 Reason: ") + _dlr_esc(reason) + "\n\n") if reason else "\n",
        sup=SUPPORT_USERNAME)
    try:
        bot.send_message(uid, u_text, parse_mode="HTML")
    except Exception as e:
        bot.send_message(admin_id, f"⚠️ ইউজারকে মেসেজ পাঠানো যায়নি: {e}")
    bot.send_message(admin_id, f"✅ {oid} rejected।", reply_markup=get_main_menu(admin_id))
    log_action("DOLLAR_REJECTED", admin_id, f"{oid} → user {uid} | {reason}")


# ═══════════════ ADMIN PANEL → 💱 Dollar Buy/Sell Manager ═══════════════
def show_dollar_admin_menu(admin_id, db=None):
    cfg = _dlr_cfg(db)

    def _tbl(side):
        out = []
        for n, label in DLR_RANGES:
            r = cfg[side][n]
            out.append(f"• <code>{label}</code> → " + (f"<b>{_dlr_num(r)} BDT</b>" if r > 0 else "<i>❗ সেট করা নেই</i>"))
        return "\n".join(out)

    text = (
        "💱 <b>Dollar Buy/Sell Manager</b>\n\n"
        f"📶 Status: {'🟢 ON' if cfg['enabled'] else '🔴 OFF'}\n\n"
        f"🔴 <b>Sell Rate</b> (User ডলার দিলে আপনি BDT দেবেন)\n{_tbl('sell')}\n\n"
        f"🟢 <b>Buy Rate</b> (User BDT দিলে আপনি ডলার দেবেন)\n{_tbl('buy')}\n\n"
        f"🏦 Binance Pay ID: <code>{_dlr_esc(cfg['binance_id'])}</code>\n"
        f"🟠 Bkash: <code>{_dlr_esc(cfg['bkash'])}</code>\n"
        f"🟢 Nagad: <code>{_dlr_esc(cfg['nagad'])}</code>\n"
        f"🔴 Rocket: <code>{_dlr_esc(cfg['rocket'])}</code>\n\n"
        "<i>রেট সেট করতে নিচের বাটনে চাপুন 👇</i>"
    )
    markup = types.InlineKeyboardMarkup(row_width=2)
    for n, label in DLR_RANGES:
        markup.row(
            InlineBtn(f"🔴 Sell {label}", style="danger", callback_data=f"admin_dlr_rate_sell_{n}"),
            InlineBtn(f"🟢 Buy {label}", style="success", callback_data=f"admin_dlr_rate_buy_{n}"),
        )
    markup.row(
        InlineBtn("🏦 Binance ID", style="primary", callback_data="admin_dlr_set_binance_id"),
        InlineBtn("🟠 Bkash No", style="primary", callback_data="admin_dlr_set_bkash"),
    )
    markup.row(
        InlineBtn("🟢 Nagad No", style="primary", callback_data="admin_dlr_set_nagad"),
        InlineBtn("🔴 Rocket No", style="primary", callback_data="admin_dlr_set_rocket"),
    )
    markup.row(InlineBtn("🔒 Service OFF করুন" if cfg["enabled"] else "🔓 Service ON করুন",
                         style="primary", callback_data="admin_dlr_toggle"))
    markup.row(InlineBtn("🔙 Admin Panel", style="primary", callback_data="back_admin"))
    bot.send_message(admin_id, text, parse_mode="HTML", reply_markup=markup)


def _dlr_admin_rate_step(message, side, n):
    admin_id = str(message.chat.id)
    text = (message.text or "").strip()
    if text in ("❌ Cancel", LANG["en"]["cancel"], LANG["bn"]["cancel"]):
        bot.send_message(admin_id, "↩️ বাতিল।", reply_markup=get_main_menu(admin_id))
        show_dollar_admin_menu(admin_id); return
    try:
        rate = float(text.replace(",", "."))
    except (ValueError, TypeError):
        rate = None
    if rate is None or not _dlr_math.isfinite(rate) or rate < 10 or rate > 1000:
        msg = bot.send_message(admin_id,
            "❌ সঠিক রেট লিখুন (10 থেকে 1000 এর মধ্যে, যেমন: <code>122.5</code>)।", parse_mode="HTML")
        bot.register_next_step_handler(msg, lambda m: _dlr_admin_rate_step(m, side, n))
        return
    rate = round(rate, 2)

    def _mut(raw):
        d = raw.get(side, {})
        d = dict(d) if isinstance(d, dict) else {}
        d[f"r{n}"] = int(rate) if rate == int(rate) else rate
        raw[side] = d
    _dlr_save_raw(_mut)
    label = dict(DLR_RANGES)[n]
    bot.send_message(admin_id,
        f"✅ <b>{'Sell' if side == 'sell' else 'Buy'}</b> রেট আপডেট হয়েছে!\n📊 {label} → <b>1$ = {_dlr_num(rate)} BDT</b>",
        parse_mode="HTML", reply_markup=get_main_menu(admin_id))
    show_dollar_admin_menu(admin_id)


_DLR_FIELD_LABELS = {
    "binance_id": "🏦 Binance Pay ID",
    "bkash":      "🟠 Bkash নম্বর",
    "nagad":      "🟢 Nagad নম্বর",
    "rocket":     "🔴 Rocket নম্বর",
}


def _dlr_admin_field_step(message, field):
    admin_id = str(message.chat.id)
    text = (message.text or "").strip()
    if text in ("❌ Cancel", LANG["en"]["cancel"], LANG["bn"]["cancel"]):
        bot.send_message(admin_id, "↩️ বাতিল।", reply_markup=get_main_menu(admin_id))
        show_dollar_admin_menu(admin_id); return
    if field != "binance_id":
        val = _dlr_normalize_bd_number(text) or (text if re.fullmatch(r"\d{3,20}", text or "") else None)
    else:
        val = text if 3 <= len(text) <= 100 and "\n" not in text and " " not in text else None
    if not val:
        msg = bot.send_message(admin_id, "❌ সঠিক মান লিখুন (স্পেস ছাড়া)।")
        bot.register_next_step_handler(msg, lambda m: _dlr_admin_field_step(m, field))
        return
    _dlr_save_raw(lambda raw: raw.__setitem__(field, val))
    bot.send_message(admin_id, f"✅ {_DLR_FIELD_LABELS[field]} আপডেট হয়েছে: <code>{_dlr_esc(val)}</code>",
                     parse_mode="HTML", reply_markup=get_main_menu(admin_id))
    show_dollar_admin_menu(admin_id)


# ═══════════════ CALLBACK ROUTER (dlr_* / admin_dlr_*) ═══════════════
def handle_dollar_callback(call, user_id, callback_data):
    def _deny():
        try:
            bot.answer_callback_query(call.id, "❌ Admin access only!", show_alert=True)
        except Exception:
            pass

    # ── ইউজার ──
    if callback_data == "dlr_cancel":
        _dlr_clear(user_id)
        try:
            bot.edit_message_reply_markup(user_id, call.message.message_id, reply_markup=None)
        except Exception:
            pass
        bot.send_message(user_id, _dl(user_id, "❌ বাতিল করা হয়েছে।", "❌ Cancelled."),
                         reply_markup=get_dollar_menu(user_id))
        return
    if callback_data.startswith("dlr_m_"):
        _dlr_method_chosen(call, user_id, callback_data[len("dlr_m_"):])
        return

    # ── Admin ──
    if not is_admin(user_id):
        _deny(); return
    if callback_data.startswith("dlr_done_"):
        _dlr_admin_done(call, user_id, callback_data[len("dlr_done_"):]); return
    if callback_data.startswith("dlr_rej_"):
        _dlr_admin_reject_ask(call, user_id, callback_data[len("dlr_rej_"):]); return
    if callback_data == "admin_dlr_menu":
        show_dollar_admin_menu(user_id); return
    if callback_data == "admin_dlr_toggle":
        cfg = _dlr_cfg()
        _dlr_save_raw(lambda raw: raw.__setitem__("enabled", not cfg["enabled"]))
        show_dollar_admin_menu(user_id); return
    if callback_data.startswith("admin_dlr_rate_"):
        try:
            _, _, _, side, n = callback_data.split("_")
            n = int(n)
        except Exception:
            return
        if side not in ("buy", "sell") or n not in (1, 2, 3):
            return
        cfg = _dlr_cfg()
        cur = cfg[side][n]
        msg = bot.send_message(user_id,
            f"💱 <b>{'Sell' if side == 'sell' else 'Buy'} Rate — {dict(DLR_RANGES)[n]}</b>\n\n"
            f"বর্তমান: <b>{(_dlr_num(cur) + ' BDT') if cur > 0 else 'সেট করা নেই'}</b>\n\n"
            f"নতুন রেট লিখুন (1$ = কত BDT, যেমন: <code>122</code>):",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, lambda m: _dlr_admin_rate_step(m, side, n))
        return
    if callback_data.startswith("admin_dlr_set_"):
        field = callback_data[len("admin_dlr_set_"):]
        if field not in _DLR_FIELD_LABELS:
            return
        cfg = _dlr_cfg()
        msg = bot.send_message(user_id,
            f"{_DLR_FIELD_LABELS[field]}\n\nবর্তমান: <code>{_dlr_esc(cfg[field])}</code>\n\nনতুন মান লিখুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, lambda m: _dlr_admin_field_step(m, field))
        return


