def _deep_merge_dict(base, overlay):
    """base dict-এর উপর overlay dict recursively merge করো।
    overlay-তে না থাকা key গুলো base-এই অক্ষত থাকবে — তাই পুরনো
    backup restore করলে পরে যোগ হওয়া product/setting মুছে যায় না।"""
    if not isinstance(base, dict) or not isinstance(overlay, dict):
        return overlay
    merged = dict(base)
    for k, v in overlay.items():
        if k in merged and isinstance(merged.get(k), dict) and isinstance(v, dict):
            merged[k] = _deep_merge_dict(merged[k], v)
        else:
            merged[k] = v
    return merged

