def _get_extra_admins_fresh():
    """সবসময় fresh DB থেকে extra_admins list (normalized) রিটার্ন করে।"""
    db = load_db()
    extra = db.get("extra_admins", [])
    if isinstance(extra, dict):
        extra = list(extra.values())
    return [str(a) for a in extra if a]

def show_admin_management(user_id, message_id=None):
    """Owner-only স্ক্রিন — বর্তমান admin list দেখায়, Add/Remove বাটন সহ।"""
    extra = _get_extra_admins_fresh()

    text = (
        f"\n👑 <b>Admin Management</b>\n"
        f"\n\n"
        f"🔑 <b>Owner:</b> <code>{ADMIN_ID}</code> <i>(সবসময় admin, remove করা যাবে না)</i>\n"
    )
    if extra:
        text += "\n👤 <b>Added Admins:</b>\n"
        for aid in extra:
            text += f"  • <code>{aid}</code>\n"
    else:
        text += "\n<i>এখনো কোনো extra admin যোগ করা হয়নি।</i>\n"

    markup = types.InlineKeyboardMarkup(row_width=1)
    markup.add(InlineBtn("➕ Add Admin", style="success", callback_data="admin_add_admin_start"))
    if extra:
        markup.add(InlineBtn("🗑️ Delete Admin", style="danger", callback_data="admin_remove_admin_start"))
    markup.add(InlineBtn("🔙 Back", style="primary", callback_data="back_admin"))

    if message_id:
        try:
            bot.edit_message_text(text, user_id, message_id, reply_markup=markup, parse_mode="HTML")
            return
        except Exception:
            pass
    bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)

def admin_add_admin_step(message):
    """Owner এর টাইপ করা Chat ID কে extra_admins list এ যোগ করো।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return
    if not is_owner(user_id):
        return  # ⚠️ Security: শুধু owner এই স্টেপে ঢুকতে পারবে

    new_admin_id = message.text.strip()
    if not new_admin_id.lstrip('-').isdigit():
        msg = bot.send_message(user_id,
            "❌ <b>Invalid Chat ID!</b>\n\nশুধু numeric Telegram Chat ID দিন (যেমন: 123456789)।\nআবার চেষ্টা করুন:",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, admin_add_admin_step); return

    if new_admin_id == str(ADMIN_ID):
        bot.send_message(user_id, "⚠️ <b>এটা তো আপনারই (Owner) Chat ID — ইতিমধ্যে Admin!</b>", parse_mode="HTML")
        show_admin_management(user_id); return

    extra = _get_extra_admins_fresh()
    if new_admin_id in extra:
        bot.send_message(user_id, "⚠️ <b>ইনি ইতিমধ্যে Admin!</b>", parse_mode="HTML")
        show_admin_management(user_id); return

    extra.append(new_admin_id)
    update_db_path("/extra_admins", extra)
    _invalidate_admin_list_cache()

    bot.send_message(user_id,
        f"✅ <b>নতুন Admin যোগ করা হয়েছে!</b>\n\n👤 <b>Chat ID:</b> <code>{new_admin_id}</code>",
        parse_mode="HTML")
    try:
        bot.send_message(new_admin_id,
            "🎉 <b>অভিনন্দন!</b>\n\nআপনাকে এই বটের <b>Admin</b> করা হয়েছে।\n"
            "নিচে /start দিয়ে বট শুরু করুন — এখন থেকে আপনি Admin Panel দেখতে পাবেন।",
            parse_mode="HTML")
    except Exception:
        pass
    show_admin_management(user_id)

