# ═══════════════════════════════════════════════════════════
# 🦉 OWL PROXY MB CHECKER (RTKProxy API) — main.py থেকে পোর্ট করা
# ═══════════════════════════════════════════════════════════
# Proxy Checker মেনুর "🦉 Owl proxy MB" বাটন → ইউজার একটা বা অনেকগুলো proxy
# (টেক্সট / .txt / .csv / .xlsx) পাঠায় → RTKProxy API দিয়ে প্রতিটার MB চেক →
# Live / Dead / Error সামারি + Top Live + আলাদা .txt ফাইল।
# Railway Variable: RTKPROXY_API_KEY (না দিলে main.py এর key ব্যবহার হবে)
import time as _owlmb_time
import html as _owlmb_html
from urllib.parse import quote as _owlmb_quote

OWLMB_API_KEY = os.environ.get("RTKPROXY_API_KEY", "owl_res_20b29f5080de").strip()
OWLMB_CHECK_URL = os.environ.get("RTKPROXY_CHECK_URL", "https://rtkproxy.com/check")
OWLMB_TIMEOUT = float(os.environ.get("OWLMB_API_TIMEOUT", "15"))
OWLMB_CONCURRENCY = max(1, int(os.environ.get("OWLMB_CONCURRENCY", "20")))
OWLMB_MAX_PROXIES = max(1, int(os.environ.get("OWLMB_MAX_PROXIES", "300")))
_owlmb_active = set()
_owlmb_active_lock = threading.Lock()

_OWLMB_PROTO_RE = re.compile(r"^(https?|socks4|socks5)://", re.IGNORECASE)
_OWLMB_IPV6_RE = re.compile(r"^\[(.+)\]:(\d+)$")


def _owlmb_fields_to_proxy(fields):
    fields = [str(x).strip() for x in fields]
    if len(fields) == 2:
        host, port = fields
        user = password = None
    elif len(fields) == 4:
        host, port, user, password = fields
    else:
        return None
    if not host or not port.isdigit():
        return None
    if "." not in host and ":" not in host:
        return None
    if not 1 <= int(port) <= 65535:
        return None
    return {"host": host, "port": int(port), "user": user or None, "password": password or None}


def _owlmb_parse_line(line):
    s = (line or "").strip()
    if not s or s.startswith("#"):
        return None
    protocol = None
    m = _OWLMB_PROTO_RE.match(s)
    if m:
        protocol = m.group(1).lower()
        s = s[m.end():].strip()
    if "@" in s:
        creds, hostport = s.rsplit("@", 1)
        user, password = (creds.split(":", 1) + [None])[:2] if ":" in creds else (creds, None)
        parsed = None
        v6 = _OWLMB_IPV6_RE.match(hostport)
        if v6:
            parsed = _owlmb_fields_to_proxy([v6.group(1), v6.group(2)])
        else:
            hp = hostport.rsplit(":", 1)
            if len(hp) == 2:
                parsed = _owlmb_fields_to_proxy([hp[0], hp[1]])
        if parsed:
            parsed["user"] = user or None
            parsed["password"] = password or None
            parsed["protocol"] = protocol
            parsed["raw"] = line.strip()
            return parsed
    parts = s.split(":")
    parsed = _owlmb_fields_to_proxy(parts)
    if not parsed and len(parts) >= 2:
        parsed = _owlmb_fields_to_proxy([parts[0], parts[1]])
    if not parsed:
        for sep in (";", "|", ","):
            if sep in s:
                parsed = _owlmb_fields_to_proxy([x.strip() for x in s.split(sep) if x.strip()])
                if parsed:
                    break
    if not parsed:
        parts = s.split()
        if len(parts) in (2, 4):
            parsed = _owlmb_fields_to_proxy(parts)
    if not parsed:
        return None
    parsed["protocol"] = protocol
    parsed["raw"] = line.strip()
    return parsed


def _owlmb_normalize(parsed):
    protocol = parsed.get("protocol") or "http"
    auth = ""
    if parsed.get("user") is not None:
        auth = _owlmb_quote(str(parsed["user"]), safe="")
        if parsed.get("password") is not None:
            auth += ":" + _owlmb_quote(str(parsed["password"]), safe="")
        auth += "@"
    return f"{protocol}://{auth}{parsed['host']}:{parsed['port']}"


def _owlmb_canonical(parsed):
    base = f"{parsed['host']}:{parsed['port']}"
    if parsed.get("user") is not None:
        base += f":{parsed['user']}"
        if parsed.get("password") is not None:
            base += f":{parsed['password']}"
    return base


_OWLMB_HEADER_MAP = {
    "host": {"server", "host", "ip", "address", "proxy", "proxy ip", "ip address", "hostname"},
    "port": {"port"},
    "user": {"username", "user", "login", "user name", "proxy user"},
    "pass": {"password", "pass", "pwd", "proxy password"},
    "proxy": {"proxy", "proxy string", "proxy address"},
}


def _owlmb_cell(v):
    if v is None:
        return ""
    if isinstance(v, float) and v.is_integer():
        return str(int(v))
    return str(v).strip()


def _owlmb_lines_from_xlsx(data):
    wb = openpyxl.load_workbook(BytesIO(data), read_only=True, data_only=True)
    out = []
    for ws in wb.worksheets:
        rows = list(ws.iter_rows(values_only=True))
        if not rows:
            continue
        mapping = {}
        for idx, cell in enumerate(rows[0] or []):
            if cell is None:
                continue
            key = str(cell).strip().lower()
            for field, names in _OWLMB_HEADER_MAP.items():
                if key in names and field not in mapping:
                    mapping[field] = idx
        if not ("proxy" in mapping or ("host" in mapping and "port" in mapping)):
            mapping = {}
        data_rows = rows[1:] if mapping else rows
        if not mapping:
            mapping = {"host": 0, "port": 1, "user": 2, "pass": 3}
        for row in data_rows:
            if not row:
                continue
            if "proxy" in mapping:
                if mapping["proxy"] < len(row):
                    v = _owlmb_cell(row[mapping["proxy"]])
                    if v:
                        out.append(v)
                continue
            hi, pi = mapping.get("host"), mapping.get("port")
            if hi is None or pi is None or hi >= len(row):
                continue
            host = _owlmb_cell(row[hi])
            port = _owlmb_cell(row[pi]) if pi < len(row) else ""
            ui, pw = mapping.get("user"), mapping.get("pass")
            user = _owlmb_cell(row[ui]) if ui is not None and ui < len(row) else ""
            pwd = _owlmb_cell(row[pw]) if pw is not None and pw < len(row) else ""
            if not host or not port:
                continue
            line = f"{host}:{port}"
            if user:
                line += f":{user}"
                if pwd:
                    line += f":{pwd}"
            out.append(line)
    return out


def _owlmb_extract_lines(filename, data):
    ext = os.path.splitext(filename or "")[1].lower()
    if ext in (".xlsx", ".xlsm"):
        candidates = _owlmb_lines_from_xlsx(data)
    else:
        candidates = data.decode("utf-8", errors="ignore").splitlines()
    seen, out = set(), []
    for raw in candidates:
        line = str(raw).strip()
        if not line:
            continue
        parsed = _owlmb_parse_line(line)
        if parsed:
            key = _owlmb_normalize(parsed)
            if key not in seen:
                seen.add(key)
                out.append(line)
            continue
        for token in re.split(r"[\s,;|]+", line):
            p = _owlmb_parse_line(token)
            if p:
                key = _owlmb_normalize(p)
                if key not in seen:
                    seen.add(key)
                    out.append(token)
    return out


# ── RTKProxy response → MB / status ──
_OWLMB_DEAD_RE = re.compile(
    r"expired|expire|depleted|exhausted|out of (?:mb|data|traffic|bandwidth)|"
    r"no (?:traffic|data|mb|bandwidth|balance)|used up|finished|inactive|\bdead\b|not active", re.I)
_OWLMB_LIVE_RE = re.compile(r"\b(?:live|alive|active|success|ok|valid|available|working)\b", re.I)
_OWLMB_ERR_RE = re.compile(
    r"error|invalid (?:key|api|proxy|format)|unauthori[sz]ed|forbidden|not found|rate limit|"
    r"too many|bad request|failed|denied", re.I)
_OWLMB_UNIT_RE = re.compile(r"(-?\d+(?:\.\d+)?)\s*(tb|gb|mb|kb)?", re.I)
_OWLMB_TEXT_MB_RE = re.compile(r"(\d+(?:\.\d+)?)\s*(tb|gb|mb|kb)\b", re.I)
_OWLMB_KEYVAL_RE = re.compile(
    r"(?:remaining|remain|left|balance|traffic)[_\s-]*(?:mb)?\s*[:=]\s*(\d+(?:\.\d+)?)", re.I)
_OWLMB_SKIP_KEYS = ("used", "usage", "total", "spent", "consumed", "speed", "mbps",
                    "ping", "latency", "port", "code", "time", "expire")


def _owlmb_to_mb(value, key=""):
    if isinstance(value, bool):
        return None
    key = str(key).lower()
    unit = None
    if isinstance(value, (int, float)):
        num = float(value)
    elif isinstance(value, str):
        m = _OWLMB_UNIT_RE.search(value.replace(",", ""))
        if not m:
            return None
        num = float(m.group(1))
        unit = (m.group(2) or "").lower() or None
    else:
        return None
    if not unit:
        unit = ("tb" if "tb" in key else "gb" if "gb" in key else "kb" if "kb" in key
                else "b" if "byte" in key else "mb")
    factor = {"tb": 1024 * 1024, "gb": 1024, "mb": 1, "kb": 1 / 1024, "b": 1 / (1024 * 1024)}[unit]
    return num * factor


def _owlmb_fmt(value):
    return f"{float(value):.2f}".rstrip("0").rstrip(".") or "0"


def _owlmb_key_score(key):
    k = str(key).lower()
    if any(x in k for x in _OWLMB_SKIP_KEYS):
        return 0
    score = 0
    if any(x in k for x in ("remain", "left", "balance", "rest", "available")):
        score += 3
    if any(x in k for x in ("mb", "gb", "traffic", "bandwidth", "data", "flow", "byte", "quota")):
        score += 2
    return score


def _owlmb_walk(obj):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (dict, list)):
                yield from _owlmb_walk(v)
            else:
                yield str(k), v
    elif isinstance(obj, list):
        for v in obj[:20]:
            yield from _owlmb_walk(v)


def _owlmb_find_mb(payload):
    best, best_score = None, 0
    for key, value in _owlmb_walk(payload):
        score = _owlmb_key_score(key)
        if score > best_score:
            mb = _owlmb_to_mb(value, key)
            if mb is not None:
                best, best_score = mb, score
    return best


def _owlmb_flag_status(payload):
    for key, value in _owlmb_walk(payload):
        if not isinstance(value, bool):
            continue
        k = key.lower()
        if k in ("success", "ok") and value is False:
            return "error"
        if k in ("live", "alive", "active", "valid", "working", "online"):
            return "live" if value else "expired"
        if k in ("expired", "dead", "exhausted") and value is True:
            return "expired"
    return None


def _owlmb_classify(payload, body):
    body_text = json.dumps(payload, ensure_ascii=False) if payload is not None else (body or "")
    mb = _owlmb_find_mb(payload) if payload is not None else None
    if mb is None:
        m = _OWLMB_TEXT_MB_RE.search(body_text.replace(",", ""))
        if m:
            mb = _owlmb_to_mb(m.group(0))
    if mb is None:
        m = _OWLMB_KEYVAL_RE.search(body_text)
        if m:
            mb = float(m.group(1))
    if isinstance(payload, dict):
        parts = []
        for k in ("status", "state", "result", "message", "msg", "error", "proxy_status"):
            v = payload.get(k)
            if isinstance(v, (str, int, float)) and not isinstance(v, bool):
                parts.append(str(v))
        status_text = " | ".join(parts)
        has_error_key = bool(payload.get("error"))
    else:
        status_text = body_text[:300]
        has_error_key = False
    flag = _owlmb_flag_status(payload) if payload is not None else None
    haystack = status_text or body_text[:300]
    if mb is not None:
        status = "live" if mb > 0 else "expired"
    elif has_error_key or flag == "error" or _OWLMB_ERR_RE.search(haystack):
        status = "error"
    elif flag:
        status = flag
    elif _OWLMB_DEAD_RE.search(haystack):
        status = "expired"
    elif _OWLMB_LIVE_RE.search(haystack):
        status = "live"
    else:
        status = "unknown"
    message = " ".join((status_text or body_text).split())[:300]
    return status, (_owlmb_fmt(mb) if mb is not None else None), message


_OWLMB_IGNORE_TOKENS = {"time", "ts", "date", "port", "code", "speed", "mbps", "ping", "latency", "id", "uid"}


def _owlmb_tokens(key):
    k = re.sub(r"([a-z])([A-Z])", r"\1 \2", str(key)).lower()
    return re.findall(r"[a-z]+", k)


def _owlmb_slot(key):
    """key এর নাম দেখে বোঝে এটা remaining / total / used কোনটা (না বুঝলে None)।"""
    toks = _owlmb_tokens(key)
    if not toks or any(t in _OWLMB_IGNORE_TOKENS or t.startswith("expir") for t in toks):
        return None
    def has(prefixes, exact=()):
        return any(t.startswith(prefixes) or t in exact for t in toks)
    if has(("remain", "left", "balanc", "availab"), exact=("rest",)):
        return "remaining"
    if has(("total", "quota", "limit", "purchas", "accumulat", "allocat", "initial"), exact=("cap",)):
        return "total"
    if has(("used", "usage", "consum", "spent")):
        return "used"
    return None


def _owlmb_extract_usage(payload):
    """API রেসপন্স থেকে (total_mb, used_mb, remaining_mb) বের করে; না পেলে None।
    শুধু API যা সত্যি পাঠায় সেটাই নেয়; দুটো জানা থাকলে তৃতীয়টা হিসাব করে।"""
    found = {"remaining": None, "total": None, "used": None}
    if payload is None:
        return found
    for key, value in _owlmb_walk(payload):
        slot = _owlmb_slot(key)
        if slot and found[slot] is None:
            mb = _owlmb_to_mb(value, key)
            if mb is not None and mb >= 0:
                found[slot] = mb
    t, u, r = found["total"], found["used"], found["remaining"]
    if r is None:
        r = _owlmb_find_mb(payload)
    if t is None and u is not None and r is not None:
        t = u + r
    if u is None and t is not None and r is not None:
        u = max(0.0, t - r)
    if r is None and t is not None and u is not None:
        r = max(0.0, t - u)
    return {"total": t, "used": u, "remaining": r}


def _owlmb_call_api(proxy_value):
    started = _owlmb_time.monotonic()
    resp = http_requests.get(
        OWLMB_CHECK_URL,
        params={"proxy": proxy_value, "key": OWLMB_API_KEY},
        timeout=OWLMB_TIMEOUT,
        headers={"User-Agent": "MB-Checker/1.1"},
    )
    body = resp.text
    try:
        payload = json.loads(body)
    except Exception:
        payload = None
    status, mb, message = _owlmb_classify(payload, body)
    if resp.status_code >= 400 and status in ("unknown", "live", "expired") and mb is None:
        status = "error"
    usage = _owlmb_extract_usage(payload)
    return {"status": status, "mb": mb, "message": message or f"HTTP {resp.status_code}",
            "usage": usage, "http_status": resp.status_code,
            "latency_ms": int((_owlmb_time.monotonic() - started) * 1000)}


def _owlmb_check_one(proxy_line):
    parsed = _owlmb_parse_line(proxy_line)
    if not parsed:
        return {"proxy": proxy_line, "status": "error", "mb": None, "message": "Invalid proxy format"}
    candidates = []
    for value in (_owlmb_canonical(parsed), _owlmb_normalize(parsed)):
        if value not in candidates:
            candidates.append(value)
    result = None
    for value in candidates:
        try:
            result = _owlmb_call_api(value)
        except http_requests.exceptions.Timeout:
            result = {"status": "error", "mb": None, "message": "API timeout"}
        except Exception as exc:
            result = {"status": "error", "mb": None, "message": f"{type(exc).__name__}: {exc}"[:200]}
        result["proxy"] = proxy_line
        if result["status"] in ("live", "expired"):
            return result
        if result.get("http_status") in (401, 403):
            break
    return result


def _owlmb_mbf(r):
    try:
        return float(r.get("mb"))
    except (TypeError, ValueError):
        return 0.0


def _owlmb_make_files(results):
    """২টা ফাইল: live_mb.txt (Live + Error/Unknown) এবং dead_mb.txt (Dead)।"""
    live = sorted((r for r in results if r["status"] == "live"), key=_owlmb_mbf, reverse=True)
    dead = [r for r in results if r["status"] == "expired"]
    err = [r for r in results if r["status"] not in ("live", "expired")]

    live_lines = [f"{r['proxy']} | {r['mb']} MB" if r.get("mb") is not None else r["proxy"] for r in live]
    live_lines += [f"{r['proxy']} | ERROR: {r.get('message', '')}" for r in err]
    dead_lines = [f"{r['proxy']} | 0 MB" for r in dead]

    files = []
    if live_lines:
        buf = BytesIO("\n".join(live_lines).encode("utf-8"))
        files.append(("live_mb.txt", buf, f"🟢 <b>LIVE</b> — {len(live)}"
                                          + (f"\n⚠️ <b>ERROR</b> — {len(err)}" if err else "")))
    if dead_lines:
        buf = BytesIO("\n".join(dead_lines).encode("utf-8"))
        files.append(("dead_mb.txt", buf, f"🔴 <b>DEAD</b> — {len(dead)}"))
    return files


def _owlmb_single_card(r):
    """১টা proxy চেক করলে 9Proxy Usage Checker কার্ডের মতো ডিজাইন (English)।"""
    esc = _owlmb_html.escape
    u = r.get("usage") or {}
    status = r["status"]
    parsed = _owlmb_parse_line(r["proxy"]) or {}
    username = parsed.get("user") or "—"
    status_txt = {"live": "🟢 Active", "expired": "🔴 Expired"}.get(status, "⚠️ Error")
    mb2 = lambda x: f"{float(x):.2f} MB"

    lines = ["🦉 <b>Owl Proxy — Usage Checker</b>",
             "━━━━━━━━━━━━━━━━━━━━",
             f"👤 <b>Username:</b> <code>{esc(str(username))}</code>",
             f"📶 <b>Status:</b> {status_txt}",
             "━━━━━━━━━━━━━━━━━━━━"]
    if status in ("live", "expired"):
        rem = u.get("remaining")
        if rem is None and r.get("mb") is not None:
            rem = float(r["mb"])
        if rem is None:
            rem = 0.0
        total, used = u.get("total"), u.get("used")
        if total is not None:
            lines.append(f"🎯 <b>Total:</b> <code>{mb2(total)}</code>")
        if used is not None:
            lines.append(f"📊 <b>Used:</b> <code>{mb2(used)}</code>")
        lines.append(f"{'🟢' if rem > 0 else '🔴'} <b>Remaining:</b> <code>{mb2(max(0.0, rem))}</code>")
        if total and total > 0 and used is not None:
            lines.append(_nineproxy_progress_bar(used, total))
    else:
        lines.append(f"⚠️ <b>Reason:</b> {esc(str(r.get('message') or 'Unknown error')[:200])}")
    return "\n".join(lines)


def _owlmb_run(user_id, lines):
    """ব্যাকগ্রাউন্ডে সব proxy চেক করে ফলাফল পাঠায়।"""
    try:
        total = len(lines)
        prog = None
        try:
            txt = ("⏳ <b>Checking your Owl Proxy usage...</b>\n<i>Please wait a moment.</i>" if total == 1 else
                   f"⏳ <b>Checking {total} Owl Proxies...</b>\n<i>Please wait a moment.</i>")
            prog = bot.send_message(user_id, txt, parse_mode="HTML")
        except Exception:
            pass
        results = [None] * total
        done = 0
        last_edit = 0.0
        with ThreadPoolExecutor(max_workers=min(OWLMB_CONCURRENCY, total)) as ex:
            futs = {ex.submit(_owlmb_check_one, ln): i for i, ln in enumerate(lines)}
            for fut in as_completed(futs):
                i = futs[fut]
                try:
                    results[i] = fut.result()
                except Exception as exc:
                    results[i] = {"proxy": lines[i], "status": "error", "mb": None,
                                  "message": f"{type(exc).__name__}"}

        if prog:
            try:
                bot.delete_message(prog.chat.id, prog.message_id)
            except Exception:
                pass

        if total == 1:
            bot.send_message(user_id, _owlmb_single_card(results[0]),
                             parse_mode="HTML", reply_markup=get_main_menu(user_id))
            return

        files = _owlmb_make_files(results)
        for idx, (name, buf, caption) in enumerate(files):
            try:
                bot.send_document(user_id, buf, caption=caption, parse_mode="HTML",
                                  visible_file_name=name,
                                  reply_markup=get_main_menu(user_id) if idx == len(files) - 1 else None)
            except Exception as exc:
                logging.warning(f"owlmb send_document failed: {exc}")
    except Exception as exc:
        logging.exception(f"owlmb run failed: {exc}")
        try:
            bot.send_message(user_id, "❌ <b>Something went wrong. Please try again.</b>",
                             parse_mode="HTML", reply_markup=get_main_menu(user_id))
        except Exception:
            pass
    finally:
        with _owlmb_active_lock:
            _owlmb_active.discard(user_id)


def _owlmb_prompt(user_id):
    return bot.send_message(user_id,
        "🦉 <b>OWL PROXY MB CHECK</b>\n\n"
        "একটি proxy অথবা একসাথে অনেকগুলো proxy পাঠান।\n\n"
        "<b>Supported examples:</b>\n"
        "📌 <code>host:port:user:pass</code>\n"
        "📌 <code>user:pass@host:port</code>\n"
        "📌 <code>socks5://user:pass@host:port</code>\n"
        "📌 <code>host:port</code>\n\n"
        "<b>Or upload:</b> .txt / .csv / .xlsx\n\n"
        f"⏳ Checking will start automatically. (Max {OWLMB_MAX_PROXIES} proxies per check)",
        parse_mode="HTML", reply_markup=get_cancel_button(user_id))


@bot.callback_query_handler(func=lambda call: call.data == "proxychk_owlmb")
def handle_proxychk_owlmb(call):
    """'🦉 Owl proxy MB' ইনলাইন বাটন। ⚠️ catch-all callback handler এর *আগে* register হতে হবে।"""
    try:
        bot.answer_callback_query(call.id)
    except Exception:
        pass
    user_id = str(call.from_user.id)
    if not OWLMB_API_KEY:
        bot.send_message(user_id, "⚠️ Owl MB checker এখনো সেটআপ করা হয়নি। এডমিনের সাথে যোগাযোগ করুন।")
        return
    msg = _owlmb_prompt(user_id)
    bot.register_next_step_handler(msg, process_owlmb_input)


def process_owlmb_input(message):
    user_id = str(message.chat.id)
    L = LANG[get_user_lang(user_id)]
    text = (message.text or "").strip()

    if text and text in (L["cancel"], L.get("back", ""), "❌ Cancel"):
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML")
        return
    if text and _is_menu_navigation_text(user_id, text):
        _text_message_worker(message)
        return

    lines = []
    try:
        if message.content_type == "document" and message.document:
            doc = message.document
            fname = doc.file_name or "upload.txt"
            if os.path.splitext(fname)[1].lower() not in (".txt", ".csv", ".xlsx", ".xlsm"):
                msg = bot.send_message(user_id, "❌ <b>Unsupported file.</b>\nAllowed: .txt, .csv, .xlsx",
                                       parse_mode="HTML")
                bot.register_next_step_handler(msg, process_owlmb_input)
                return
            if doc.file_size and doc.file_size > 15 * 1024 * 1024:
                msg = bot.send_message(user_id, "❌ <b>File is larger than 15 MB.</b>", parse_mode="HTML")
                bot.register_next_step_handler(msg, process_owlmb_input)
                return
            info = bot.get_file(doc.file_id)
            lines = _owlmb_extract_lines(fname, bot.download_file(info.file_path))
        elif text:
            lines = _owlmb_extract_lines("message.txt", text.encode("utf-8"))
    except Exception as exc:
        logging.warning(f"owlmb input parse error: {exc}")
        msg = bot.send_message(user_id, "❌ <b>Could not read the input.</b> Try again.", parse_mode="HTML")
        bot.register_next_step_handler(msg, process_owlmb_input)
        return

    if not lines:
        msg = bot.send_message(user_id,
            "❌ <b>No valid proxy found.</b>\nPlease check the format and send again 👇",
            parse_mode="HTML")
        bot.register_next_step_handler(msg, process_owlmb_input)
        return

    with _owlmb_active_lock:
        if user_id in _owlmb_active:
            bot.send_message(user_id, "⏳ আপনার আগের চেক এখনো চলছে, শেষ হওয়া পর্যন্ত অপেক্ষা করুন।")
            return
        _owlmb_active.add(user_id)

    if len(lines) > OWLMB_MAX_PROXIES:
        bot.send_message(user_id,
            f"⚠️ প্রথম <b>{OWLMB_MAX_PROXIES}</b>টা proxy চেক করা হবে (মোট {len(lines)}টা দিয়েছেন)।",
            parse_mode="HTML")
        lines = lines[:OWLMB_MAX_PROXIES]

    _EXECUTOR.submit(_owlmb_run, user_id, lines)


@bot.callback_query_handler(func=lambda call: call.data in ("2fa_refresh", "2fa_newcode", "2fa_close"))
def handle_2fa_action_callback(call):
    """2FA code card এর Refresh / New Code / Close বাটন হ্যান্ডেল করে।
    ⚠️ FIX: catch-all callback handler (নিচে func=lambda call: True) এর *আগে*
    রেজিস্টার হতে হবে — pyTelegramBotAPI প্রথম যেই handler match করে শুধু
    সেটাই কল করে, catch-all এর পরে থাকলে Refresh/New Code/Close বাটনে ক্লিক
    করলে catch-all সেটা গিলে ফেলে আর কিছুই হয় না।"""
    user_id = str(call.message.chat.id)
    if not enforce_join_gate(user_id, call):
        return
    if call.data == "2fa_refresh":
        secret = _last_2fa_secret.get(user_id)
        if not secret:
            bot.answer_callback_query(call.id,
                "⚠️ Secret key পাওয়া যায়নি, আবার /2fa_key দিয়ে key দিন।", show_alert=True)
            return
        bot.answer_callback_query(call.id, "🔄 Refreshed")
        generate_and_send_2fa(user_id, secret,
            edit_chat_id=call.message.chat.id, edit_message_id=call.message.message_id)
    elif call.data == "2fa_newcode":
        bot.answer_callback_query(call.id)
        _last_2fa_secret.pop(user_id, None)
        try:
            bot.delete_message(call.message.chat.id, call.message.message_id)
        except Exception:
            pass
        start_2fa_key_flow(user_id)
    elif call.data == "2fa_close":
        bot.answer_callback_query(call.id)
        try:
            bot.delete_message(call.message.chat.id, call.message.message_id)
        except Exception:
            pass

@bot.callback_query_handler(func=lambda call: call.data.startswith("2fa_showcode_"))
def handle_2fa_showcode_fallback(call):
    """পুরনো pyTelegramBotAPI ভার্সনে copy_text সাপোর্ট না থাকলে এই fallback
    popup এ code দেখায়, যাতে ইউজার manually select করে copy করতে পারে।"""
    code = call.data.replace("2fa_showcode_", "", 1)
    bot.answer_callback_query(call.id, f"Code: {code}", show_alert=True)


