        _dash_prods1 = get_dashboard_products()   # ✅ FIX: Product-ID কানেক্টেড item গুলোও অন্তর্ভুক্ত
        _pre_stock1 = _prefetch_live_stocks(_dash_prods1)
        for _idx_stk1, ap in enumerate(_dash_prods1):
            if ap in _pre_stock1:
                api_stock = _pre_stock1[ap]
            else:
                if _idx_stk1 > 0:
                    _time_stk1.sleep(0.3)  # ⚡ hotmail143 rate-limit এড়াতে ছোট gap
                api_stock = get_live_api_stock(ap)  # 🔧 FIX: source অনুযায়ী সঠিক API তে রাউট
            local_path = os.path.join(STOCK_DIR, ap + ".xlsx")
            local_stock = 0
            if os.path.exists(local_path):
                try:
                    _wb = openpyxl.load_workbook(local_path, read_only=True)
                    _ws = _wb.active
                    for _ri, _row in enumerate(_ws.iter_rows(values_only=True), start=1):
                        if _ri == 1: continue
                        if any(c is not None and str(c).strip() != "" for c in _row):
                            local_stock += 1
                    _wb.close()
                except Exception:
                    pass
            total = (0 if api_stock < 0 else api_stock) + local_stock
            price = db["products"].get(ap, 0)
            icon = "\U0001f4e7" if "Mail" in ap else "\U0001f4e9"
            ast = str(api_stock) if api_stock >= 0 else _api_err_hint(ap)
            row = [
                icon + " <b>" + ap + "</b>",
                "   Website Stock: <code>" + ast + "</code>",
                "   Local Stock: <code>" + str(local_stock) + "</code>",
                "   Total: <code>" + str(total) + "</code> | Price: <code>" + str(price) + " BDT</code>",
            ]
            lines_stock.append("\n".join(row))
