def admin_shoprename_step(message, item_key):
    """✏️ Buy Mail বাটনের নাম বদলানোর next-step handler।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return
    raw = (message.text or "").strip()
    db = load_db()
    if raw.lower() == "reset" and item_key not in (PRODUCT1_ORDER_KEY, PRODUCT2_ORDER_KEY, PRODUCT3BULK_ORDER_KEY):
        _shop_set_btn_label(item_key, None, db)
        bot.send_message(user_id, "✅ <b>ডিফল্ট নামে ফিরিয়ে আনা হয়েছে।</b>", parse_mode="HTML")
    else:
        if not raw or len(raw) > 60 or raw.startswith("/"):
            msg = bot.send_message(user_id, "❌ <b>সঠিক নাম দিন</b> (১–৬০ অক্ষর, / দিয়ে শুরু নয়):",
                parse_mode="HTML", reply_markup=get_cancel_button(user_id))
            bot.register_next_step_handler(msg, lambda m: admin_shoprename_step(m, item_key)); return
        # অন্য কোনো বাটন/প্রোডাক্টের নামের সাথে মিলে গেলে ইউজার ভুল জায়গায় যাবে — আটকাও
        _taken = {_shop_item_display_label(k, db) for k in get_shop_button_order(db) if k != item_key}
        _taken |= {k for k in db.get("products", {}) if k != item_key}
        if raw in _taken:
            msg = bot.send_message(user_id, "❌ <b>এই নামে আরেকটা বাটন/প্রোডাক্ট আছে।</b> অন্য নাম দিন:",
                parse_mode="HTML", reply_markup=get_cancel_button(user_id))
            bot.register_next_step_handler(msg, lambda m: admin_shoprename_step(m, item_key)); return
        old = _shop_item_display_label(item_key, db)
        _shop_set_btn_label(item_key, raw, db)
        bot.send_message(user_id, f"✅ <b>নাম আপডেট হয়েছে!</b>\n\n{old} → {raw}", parse_mode="HTML")
    db = load_db()
    _o = get_shop_button_order(db)
    _mk = types.InlineKeyboardMarkup(row_width=1)
    for _i, _k in enumerate(_o):
        _mk.add(InlineBtn(f"✏️ {_i + 1}. {_shop_item_display_label(_k, db)}", style="primary",
                          callback_data=f"admin_shoprename_pick_{_i}"))
    _mk.add(InlineBtn("🔙 Admin Panel", style="primary", callback_data="back_admin"))
    bot.send_message(user_id, "✏️ <b>আরও কোনো বাটনের নাম বদলাবেন?</b>", parse_mode="HTML", reply_markup=_mk)

def admin_shoporder_set_position_step(message, item_key):
    """🔢 Shop Button Order — admin এর লেখা নতুন পজিশন নাম্বার অনুযায়ী
    item_key বাটনটাকে সেই অবস্থানে নিয়ে যায়।"""
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel":
        show_admin_panel(user_id); return
    raw = (message.text or "").strip()
    if not raw.lstrip("-").isdigit():
        msg = bot.send_message(user_id, "❌ <b>শুধু সংখ্যা লিখুন (যেমন: 1):</b>",
            parse_mode="HTML", reply_markup=get_cancel_button(user_id))
        bot.register_next_step_handler(msg, lambda m: admin_shoporder_set_position_step(m, item_key)); return
    db = load_db()
    order = set_shop_button_position(item_key, int(raw), db)
    label = _shop_item_display_label(item_key, db)
    final_pos = (order.index(item_key) + 1) if item_key in order else int(raw)
    bot.send_message(user_id,
        f"✅ <b>{label}</b> এখন <b>{final_pos}</b> নাম্বার অবস্থানে চলে গেছে!",
        parse_mode="HTML")
    text_so, markup_so = _shop_order_mgr_view(db)
    bot.send_message(user_id, text_so, parse_mode="HTML", reply_markup=markup_so)

