def admin_trx_block_step(message, mode):
    user_id = str(message.chat.id)
    if message.text == "❌ Cancel" or message.text == LANG[get_user_lang(user_id)]["cancel"]:
        show_admin_panel(user_id); return
    raw = (message.text or "").strip()
    if not raw or len(raw) > 120:
        msg = bot.send_message(user_id, "❌ <b>সঠিক ID পাঠান:</b>", parse_mode="HTML")
        bot.register_next_step_handler(msg, admin_trx_block_step, mode); return
    if mode == "add":
        key = admin_block_trx_id(raw)
        bot.send_message(user_id, f"🚫 <b>ব্লক করা হয়েছে:</b> <code>{key}</code>", parse_mode="HTML",
                         reply_markup=get_main_menu(user_id))
    else:
        key = admin_unblock_trx_id(raw)
