# 📧 FEATURE: /code COMMAND — Get OTP via OAuth2 (dongvanfb)
# ═══════════════════════════════════════════════════════════

_code_session = {}

def _is_menu_navigation_text(user_id, text):
    """
    যেকোনো step-by-step input flow এর মাঝে (যেমন /code বা /2fa_key data
    দেওয়ার অপেক্ষায় থাকা অবস্থায়) ইউজার যদি ভুলে অন্য কোনো menu বাটনে
    ক্লিক করে ফেলে, সেটা detect করার জন্য একটা common helper।

    ⚠️ আগে প্রতিটা flow (code/2fa ইত্যাদি) নিজে নিজে হাতে গোনা কয়েকটা
    বাটন-টেক্সট (shop/deposit/balance...) hardcode করে রাখত, ফলে buy_proxy,
    other, language, বা যেকোনো product বাটনে ক্লিক করলে সেটা মিস হয়ে
    "format ভুল" error দেখাত এবং বাটনটা কাজ করত না। এখন এই একটা জায়গায়
    সব ধরনের navigation text (menu বাটন, product নাম, slash command)
    চেক করা হয়, যাতে যেকোনো ফিচার-ইনপুট flow থেকে যেকোনো বাটনে গেলেই
    সেই বাটন ঠিকমতো কাজ করে।
    """
    text = (text or "").strip()
    if not text:
        return False
    if text.startswith("/"):
        return True
    if text in ("💻 Code</>", "🔙 Back"):
        return True
    _nav_keys = ("shop", "buy_proxy", "balance", "deposit", "other", "admin",
                 "back", "cancel", "orders", "refer", "support", "twofa",
                 "edu_reader", "single_buy", "bulk_buy")
    for _l in (LANG.get("en", {}), LANG.get("bn", {})):
        for k in _nav_keys:
            if _l.get(k) and text == _l[k]:
                return True
    for _role_label, _default in KB_BUTTON_ROLES.values():
        if text == _role_label:
            return True
    try:
        db_quick = load_db()
        if text in db_quick.get("products", {}):
            return True
    except Exception:
        pass
    return False

@bot.message_handler(commands=['code'])
def handle_code_command(message):
    user_id = str(message.chat.id)
    # ⏳ ছোট্ট লোডিং মুহূর্ত — ইউজারের আকর্ষণের জন্য, তারপর আসল প্রম্পটে এডিট হয়ে যায়
    loading_msg = bot.send_message(user_id, "⏳ <b>Loading...</b>", parse_mode="HTML")
    try:
        import time as _code_load_time
        _code_load_time.sleep(0.4)
    except Exception:
        pass
    prompt = (
        "📧 <b>OTP Fetcher</b>\n\n"
        "Send your complete Hotmail full data:\n\n"
        "<code>email|pass|refresh_token|client_id</code>\n\n"
    )
    try:
        bot.edit_message_text(prompt, chat_id=loading_msg.chat.id,
            message_id=loading_msg.message_id, parse_mode="HTML")
        msg = loading_msg
    except Exception:
        msg = bot.send_message(user_id, prompt, parse_mode="HTML")
    bot.register_next_step_handler(msg, process_code_input)


def process_code_input(message):
    user_id = str(message.chat.id)
    lang = get_user_lang(user_id)
    L = LANG[lang]

    if message.text in (L["cancel"], L.get("back", ""), "❌ Cancel"):
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML")
        return

    # ⚡ Main menu থেকে অন্য কোনো বাটনে ক্লিক করলে — সেই বাটনের কাজ করবে,
    # "format ভুল" error দেখাবে না (loop এ আটকে থাকবে না)
    if _is_menu_navigation_text(user_id, message.text):
        _text_message_worker(message)
        return

    text = (message.text or "").strip()
    parts = text.split("|")

    if len(parts) < 4:
        msg = bot.send_message(
            user_id,
            "❌ <b>Format ভুল!</b>\n\n"
            "সঠিক format:\n"
            "<code>email|pass|refresh_token|client_id</code>\n\n"
            "আবার চেষ্টা করুন:",
            parse_mode="HTML",
            reply_markup=get_main_menu(user_id)
        )
        bot.register_next_step_handler(msg, process_code_input)
        return

    email         = parts[0].strip()
    password      = parts[1].strip()
    refresh_token = parts[2].strip()
    client_id     = parts[3].strip()

    _code_session[user_id] = {
        "email": email,
        "password": password,
        "refresh_token": refresh_token,
        "client_id": client_id
    }

    _EXECUTOR.submit(_do_code_fetch, user_id, email, refresh_token, client_id)


def _detect_service_type(*texts):
    """
    Link, content, sender, subject — যেকোনো text থেকে service detect করো।
    একাধিক text দিলে সবগুলো check করে প্রথম match return করে।
    """
    services = [
        ("Facebook",   ["facebook.com", "fb.com", "fb.me", "facebook", "facebookmail"]),
        ("Instagram",  ["instagram.com", "instagr.am", "instagram"]),
        ("TikTok",     ["tiktok.com", "tik.tok", "tiktok"]),
        ("Telegram",   ["telegram.org", "t.me", "telegram.me", "telegram"]),
        ("Twitter/X",  ["twitter.com", "x.com", "t.co", "twitter"]),
        ("Google",     ["google.com", "accounts.google", "gmail.com", "google", "noreply@accounts"]),
        ("Apple",      ["apple.com", "icloud.com", "appleid", "apple"]),
        ("Microsoft",  ["microsoft.com", "live.com", "hotmail.com", "outlook.com", "microsoft"]),
        ("Amazon",     ["amazon.com", "amazon.", "amzn.", "amazon"]),
        ("Netflix",    ["netflix.com", "netflix"]),
        ("Snapchat",   ["snapchat.com", "snap.com", "snapchat"]),
        ("LinkedIn",   ["linkedin.com", "linkedin"]),
        ("Reddit",     ["reddit.com", "redd.it", "reddit"]),
        ("Discord",    ["discord.com", "discord.gg", "discord"]),
        ("Spotify",    ["spotify.com", "spotify"]),
        ("PayPal",     ["paypal.com", "paypal"]),
        ("Binance",    ["binance.com", "binance"]),
        ("Twitch",     ["twitch.tv", "twitch"]),
        ("Yahoo",      ["yahoo.com", "yahoo"]),
        ("Talkatone",  ["talkatone.com", "talkatone"]),
        ("Textme",     ["textme.com", "textmeapp", "textme"]),
        ("Textnow",    ["textnow.com", "textnow"]),
        ("Roblox",     ["roblox.com", "roblox"]),
        ("Steam",      ["steampowered.com", "steam"]),
        ("Uber",       ["uber.com", "uber"]),
        ("Airbnb",     ["airbnb.com", "airbnb"]),
        ("Dropbox",    ["dropbox.com", "dropbox"]),
        ("Adobe",      ["adobe.com", "adobe"]),
        ("GitHub",     ["github.com", "github"]),
    ]
    for text in texts:
        if not text:
            continue
        t = str(text).lower()
        for name, keywords in services:
            for kw in keywords:
                if kw in t:
                    return name
    return None


def _do_code_fetch(user_id, email, refresh_token, client_id):
    import time as _time

    # ✅ API key সেট করা না থাকলে সরাসরি জানিয়ে দাও — ৩০ সেকেন্ড
    # অযথা wait করানোর দরকার নেই, ওই সময় ধরে সবসময় fail হবে
    if not DONGVANFB_API_KEY:
        bot.send_message(user_id,
            "⚠️ <b>OTP service সাময়িক বন্ধ আছে।</b>\n\nAdmin কে জানান।",
            parse_mode="HTML", reply_markup=get_main_menu(user_id))
        try:
            bot.send_message(ADMIN_ID,
                "🚨 <b>DONGVANFB_API_KEY সেট করা নেই!</b>\n\nCode fetch feature কাজ করবে না যতক্ষণ না এই environment variable সেট করা হয়।",
                parse_mode="HTML")
        except Exception:
            pass
        return

    wait_msg = bot.send_message(
        user_id,
        "⏳ <b>Fetching code...</b>\n\n"
        "⏱ Wait for OTP max <b>30s</b>",
        parse_mode="HTML"
    )

    url = "https://tools.dongvanfb.net/api/get_code_oauth2"
    payload = {
        "email": email,
        "refresh_token": refresh_token,
        "client_id": client_id,
        "type": "all",
        "apikey": DONGVANFB_API_KEY
    }
    headers = {
        "Content-Type": "application/json"
    }

    found = None
    elapsed = 0
    _last_debug = ""

    while elapsed < 30:
        try:
            resp = http_requests.post(url, json=payload, headers=headers, timeout=10)
            data = resp.json()
            # ⚡ প্রতিটা attempt এর raw response log করো — কোনো OTP না
            # পাওয়া গেলে exact কারণ (wrong key/token, provider error,
            # rate limit ইত্যাদি) log থেকে বোঝা যাবে
            _last_debug = f"HTTP={resp.status_code} body={str(data)[:300]}"
            logging.info(f"dongvanfb code fetch [{email}]: {_last_debug}")
            # code অথবা content যেকোনো একটা থাকলেই found ধরো
            if data.get("status") and (
                data.get("code") or data.get("content") or data.get("data")
            ):
                found = data
                break
        except Exception as e:
            _last_debug = f"exception: {e}"
            logging.warning(f"Code fetch error [{email}]: {e}")
        _time.sleep(5)
        elapsed += 5

    try:
        bot.delete_message(user_id, wait_msg.message_id)
    except:
        pass

    if found:
        code    = (found.get("code") or "").strip()
        content = (found.get("content") or "").strip()
        subject = (found.get("subject") or found.get("title") or "").strip()
        sender  = (found.get("sender") or found.get("from") or "").strip()

        # data field এ থাকলে সেখান থেকেও বের করো
        if not code and not content and found.get("data"):
            raw_data = found["data"]
            if isinstance(raw_data, list) and raw_data:
                first = raw_data[0]
                if isinstance(first, dict):
                    code    = (first.get("code") or "").strip()
                    content = (first.get("content") or first.get("body") or "").strip()
                    subject = (first.get("subject") or first.get("title") or subject).strip()
                    sender  = (first.get("sender") or first.get("from") or sender).strip()
            elif isinstance(raw_data, dict):
                code    = (raw_data.get("code") or "").strip()
                content = (raw_data.get("content") or raw_data.get("body") or "").strip()
                subject = (raw_data.get("subject") or raw_data.get("title") or subject).strip()
                sender  = (raw_data.get("sender") or raw_data.get("from") or sender).strip()
            elif isinstance(raw_data, str):
                content = raw_data.strip()

        links = re.findall(r'https?://\S+', content) if content else []

        # Service detect: sender > subject > link > content > email (priority order)
        service = _detect_service_type(sender, subject, links[0] if links else None, content, email)
        service_line = f"🏷️ <b>Type :</b> {service}\n" if service else ""

        if code:
            bot.send_message(
                user_id,
                f"✅ <b>OTP Found!</b>\n\n"
                f"📧 <b>Email :</b> <code>{email}</code>\n"
                f"{service_line}"
                f"🔑 <b>OTP :</b> <code>{code}</code>",
                parse_mode="HTML",
                reply_markup=get_main_menu(user_id)
            )
        elif links:
            bot.send_message(
                user_id,
                f"✅ <b>Link Found!</b>\n\n"
                f"📧 <b>Email :</b> <code>{email}</code>\n"
                f"{service_line}"
                f"🔗 <b>Link :</b> {links[0]}",
                parse_mode="HTML",
                reply_markup=get_main_menu(user_id)
            )
        elif content:
            bot.send_message(
                user_id,
                f"✅ <b>Message Found!</b>\n\n"
                f"📧 <b>Email :</b> <code>{email}</code>\n"
                f"{service_line}"
                f"📨 <b>Content :</b> {content[:500]}",
                parse_mode="HTML",
                reply_markup=get_main_menu(user_id)
            )
        else:
            bot.send_message(
                user_id,
                f"⚠️ <b>Response পাওয়া গেছে কিন্তু code/link খালি!</b>\n\n"
                f"📧 <b>Email :</b> <code>{email}</code>\n\n"
                f"Inbox এ নতুন mail নেই বা code/link নেই।",
                parse_mode="HTML",
                reply_markup=get_main_menu(user_id)
            )
    else:
        bot.send_message(
            user_id,
            f"❌ <b>Code পাওয়া যায়নি!</b>\n\n"
            f"📧 <b>Email :</b> <code>{email}</code>\n\n"
            f"⏱ 30 সেকেন্ডে কোনো code আসেনি।\n"
            f"একটু পরে আবার চেষ্টা করুন।",
            parse_mode="HTML",
            reply_markup=get_main_menu(user_id)
        )
        # ⚡ Admin কে actual API response পাঠাও — silent fail এর বদলে
        # আসল কারণ (wrong key/token, provider error, inbox empty ইত্যাদি) দেখা যাবে
        try:
            bot.send_message(ADMIN_ID,
                f"🔍 <b>Code Fetch Debug</b>\n\n"
                f"📧 Email: <code>{email}</code>\n"
                f"👤 User: <code>{user_id}</code>\n"
                f"📄 Last API response: <code>{_last_debug[:500]}</code>",
                parse_mode="HTML")
        except Exception:
            pass

