# FIX: clicks.textnow.com (এবং যেকোনো *.textnow.com subdomain) ধরার জন্য প্রথমে
# email body থেকে সম্পূর্ণ domain-token বের করা হয় (scheme/www ঐচ্ছিক) — তারপর
# প্রতিটা টোকেনের আসল host _is_textnow_link() দিয়ে strict ভাবে যাচাই হয়। এভাবে
# আংশিক substring match এড়ানো যায় (যেমন spoofed "fake-textnow.com.evil.com"
# ভুলবশত textnow.com হিসেবে ধরা পড়বে না, কারণ পুরো token নিয়ে host চেক হয়)।
# সব required variant match করে:
#   https://clicks.textnow.com/...  |  http://clicks.textnow.com/...
#   clicks.textnow.com/...          |  https://www.clicks.textnow.com/...
_TEXTNOW_LINK_RE = re.compile(
    r'(?:https?://)?(?:www\.)?[a-z0-9-]+(?:\.[a-z0-9-]+)+(?:/[^\s"\'<>]*)?',
    re.IGNORECASE
)

def _is_textnow_link(url: str) -> bool:
    """FIX: URL এর আসল host *.textnow.com কিনা strict ভাবে যাচাই করে (শুধু string
    এ 'textnow' শব্দ থাকলেই না) — spoofed/lookalike ডোমেইন ঠেকানোর জন্য।"""
    try:
        candidate = url if re.match(r'^https?://', url, re.IGNORECASE) else f"https://{url}"
        host = (_urlparse(candidate).netloc or "").lower().split(':')[0]
        return host == "textnow.com" or host.endswith(".textnow.com")
    except Exception:
        return False

def _normalize_textnow_url(url: str) -> str:
    """FIX: scheme ছাড়া লিংক (যেমন 'clicks.textnow.com/xyz') হলে সামনে https:// জুড়ে দেয়,
    যাতে পরের requests.get() / Telegram button url সঠিকভাবে কাজ করে।"""
    url = url.strip()
    if not re.match(r'^https?://', url, re.IGNORECASE):
        return f"https://{url}"
    return url

_TN_VERIFY_UA = ("Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                 "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36")

def _resolve_textnow_final_url(url: str):
    """FIX: clicks.textnow.com নিজেই প্রায়ই একটা redirect/tracking link — তাই এখানে
    আসল GET রিকোয়েস্ট পাঠিয়ে redirect চেইন follow করে (allow_redirects=True) শেষ
    পর্যন্ত কোন URL এ ল্যান্ড করে সেটা বের করা হয়। timeout, real-browser User-Agent,
    আর SSL/timeout/connection error handling সহ — কোনো কারণে fetch ব্যর্থ হলেও
    original link দিয়েই fallback করে, পুরো verification আটকে যায় না।
    রিটার্ন করে: (final_url, status_code বা None, error_type বা None)
    """
    try:
        resp = http_requests.get(
            url,
            allow_redirects=True,     # FIX: redirect চেইন শেষ পর্যন্ত follow করবে
            timeout=15,                # FIX: hang হয়ে থাকবে না
            headers={"User-Agent": _TN_VERIFY_UA},  # FIX: bare/no-UA request কিছু সার্ভার ব্লক করে
        )
        return (resp.url or url), resp.status_code, None
    except http_requests.exceptions.SSLError as e:
        logging.warning(f"TN verify SSL error resolving {url}: {e}")
        return url, None, "ssl_error"
    except http_requests.exceptions.Timeout as e:
        logging.warning(f"TN verify timeout resolving {url}: {e}")
        return url, None, "timeout"
    except http_requests.exceptions.RequestException as e:
        logging.warning(f"TN verify request error resolving {url}: {e}")
        return url, None, "request_error"


# FIX: "Verify your email to finish setup" মেইলে সাধারণত একাধিক লিংক থাকে
# (header logo, footer legal/help links ইত্যাদি) — আসল verify বাটনটা নির্দিষ্টভাবে
# "Verify my email" লেখা <a> ট্যাগ থেকে বের করার জন্য এই হেল্পার। href এবং সেই
# ট্যাগের ভেতরের visible text (nested span/strong ট্যাগ থাকলেও) আলাদাভাবে ধরা হয়।
_TN_ANCHOR_RE = re.compile(
    r'<a\b[^>]*?\shref=["\']([^"\']+)["\'][^>]*>((?:(?!</a>).)*)</a>',
    re.IGNORECASE | re.DOTALL
)
_TAG_STRIP_RE = re.compile(r'<[^>]+>')

def _find_verify_my_email_link(body: str):
    """FIX: body-তে 'Verify your email to finish setup' মেইলের ভেতরে
    'Verify my email' লেখা বাটনের href সুনির্দিষ্টভাবে খুঁজে বের করে।
    না পেলে None রিটার্ন করে (তখন caller পুরনো generic *.textnow.com
    matching এ fallback করবে)।
    ⚠️ FIX: আগে document-এ যে <a> ট্যাগ **প্রথম** পাওয়া যেত সেটাই নেওয়া হতো —
    কিন্তু অনেক email template-এ Outlook (MSO) compatibility এর জন্য একই
    "Verify my email" টেক্সট দিয়ে **দুইটা আলাদা <a> ট্যাগ** থাকে: একটা
    `<!--[if mso]>...<![endif]-->` কমেন্টের ভেতরে ছোট direct fallback লিংক
    (raw HTML এ সাধারণত আগে আসে), আরেকটা আসল লম্বা tracked
    clicks.textnow.com লিংক। প্রথমটা নিলে ছোট/অসম্পূর্ণ-দেখানো লিংক চলে
    আসত। তাই এখন সব matching <a> ট্যাগ collect করে যেটার href সবচেয়ে
    **লম্বা** সেটা বেছে নেওয়া হয় — clicks.textnow.com এর tracked লিংক
    স্বভাবতই অনেক বড় (encrypted token সহ), তাই longest-href heuristic
    সঠিক আসল লিংকটাই বেছে নেয়।"""
    candidates = []
    for href, inner_html in _TN_ANCHOR_RE.findall(body):
        inner_text = _TAG_STRIP_RE.sub(' ', inner_html)
        inner_text = ' '.join(inner_text.split()).strip().lower()
        if 'verify my email' in inner_text:
            href = href.strip().rstrip('.,)"\'>&;')
            candidates.append(href)

    if not candidates:
        return None
    return max(candidates, key=len)  # FIX: সবচেয়ে লম্বা (most complete) href বেছে নেওয়া


def _do_tn_verify_fetch(user_id, email, refresh_token, client_id):
    import time as _time

    wait_msg = bot.send_message(
        user_id,
        "⏳ <b>Inbox check করা হচ্ছে...</b>\n\n"
        "⏱ Wait for link max <b>30s</b>",
        parse_mode="HTML"
    )

    url = "https://tools.dongvanfb.net/api/get_messages_oauth2"
    payload = {
        "email": email,
        "refresh_token": refresh_token,
        "client_id": client_id,
        "list_mail": "all"
    }
    headers = {"Content-Type": "application/json"}

    found_link    = None
    found_subject = None
    found_sender_name = None  # sender এর name (যেমন: "Facebook", "Instagram")
    found_otp     = None      # TextNow verify email এ OTP থাকলে সেটাও ধরা হবে
    elapsed = 0

    SKIP_KEYWORDS = ["open_log_pic", "pixel", "track", "beacon", "1x1", "spacer",
                     "unsubscribe", "email_open_log", "logo", ".png", ".jpg", ".gif"]

    while elapsed < 30:
        try:
            resp = http_requests.post(url, json=payload, headers=headers, timeout=10)
            data = resp.json()
            logging.info(f"TN verify API response: status={data.get('status')} keys={list(data.keys())}")

            if data.get("status") is True or data.get("status") == "true" or data.get("status") == 1:
                # API documentation অনুযায়ী: messages → list
                messages = data.get("messages") or data.get("data") or data.get("emails") or data.get("list") or []

                if isinstance(messages, list):
                    for mail in messages:
                        if not isinstance(mail, dict):
                            continue

                        # FIX: আগে শুধু প্রথম যেই field non-empty পাওয়া যেত সেটাই নেওয়া
                        # হতো (message OR body OR content OR text) — কিন্তু mail API
                        # অনেক সময় "text" field এ ছোট snippet আর "html"/"message" field এ
                        # আসল পুরো HTML (পূর্ণ লিংক সহ) আলাদাভাবে পাঠায়। তাই এখন সব
                        # সম্ভাব্য field একসাথে জোড়া লাগানো হচ্ছে, যাতে যেকোনো একটাতে
                        # পূর্ণ লিংক থাকলেও সেটা মিস না হয়।
                        _body_parts = [
                            mail.get("message"), mail.get("body"), mail.get("html"),
                            mail.get("html_body"), mail.get("content"), mail.get("text"),
                        ]
                        body = " ".join(str(p) for p in _body_parts if p)
                        subject = str(mail.get("subject") or mail.get("title") or "")

                        # FIX: raw body এর length লগ করা হচ্ছে — যদি TextNow verify লিংক
                        # ছোট মনে হয়, এই লগ দেখে বোঝা যাবে API আসলেই truncated snippet
                        # পাঠাচ্ছে, নাকি এটা ওই ইমেইলের প্রকৃত (ছোট) token।
                        logging.info(f"TN verify: mail body length={len(body)} subject={subject[:60]!r}")

                        # sender name বের করো (name field, address নয়)
                        from_field = mail.get("from") or mail.get("sender") or []
                        s_name = ""
                        if isinstance(from_field, list) and from_field:
                            first = from_field[0]
                            if isinstance(first, dict):
                                # name আগে, address পরে
                                s_name = first.get("name") or first.get("address") or ""
                            else:
                                s_name = str(first)
                        elif isinstance(from_field, str):
                            s_name = from_field

                        # 🔗 Link খোঁজা (href → fallback plain text)
                        # ⚠️ TextNow দুই ধরনের আলাদা মেইল পাঠায় — একটাতে শুধু
                        # verify link (button), আরেকটাতে শুধু OTP code।
                        # তাই link আর OTP প্রতিটা মেইলে আলাদাভাবে খুঁজতে হবে,
                        # একই মেইলে দুটো একসাথে থাকবে এমন ধরে নেওয়া যাবে না।
                        if not found_link:
                            # FIX: "Verify your email to finish setup" — এই টেক্সট যেই
                            # মেইলে আছে, সেই মেইলের ভেতর থেকে নির্দিষ্টভাবে "Verify my
                            # email" বাটনের সম্পূর্ণ href বের করা হচ্ছে — এটাই সবচেয়ে
                            # নির্ভরযোগ্য, কারণ এই মেইলে একাধিক অপ্রয়োজনীয় লিংক (logo,
                            # help center, unsubscribe ইত্যাদি) থাকতে পারে, যেগুলো generic
                            # domain-matching এ ভুলবশত ধরা পড়ে যেতে পারত।
                            verify_setup_link = None
                            search_blob = f"{subject} {body}".lower()
                            if "verify your email to finish setup" in search_blob:
                                anchor_href = _find_verify_my_email_link(body)
                                if anchor_href:
                                    verify_setup_link = _normalize_textnow_url(anchor_href)

                            if verify_setup_link:
                                # FIX: এই href টা textnow ডোমেইনের কিনা যাচাই করে (স্প্যাম/স্পুফ
                                # ঠেকাতে), তারপর GET করে (allow_redirects=True) server-side
                                # verification trigger করা হয় — বাটনে তবুও সম্পূর্ণ original
                                # href-ই বসে, resolve করা ছোট URL না।
                                if _is_textnow_link(verify_setup_link):
                                    _f_url, _st, err = _resolve_textnow_final_url(verify_setup_link)
                                    if err:
                                        logging.warning(f"TN verify: 'Verify my email' GET failed ({err}), link still shown as-is")
                                    found_link        = verify_setup_link
                                    found_subject     = subject
                                    found_sender_name = s_name

                        if not found_link:
                            # FIX: আগে শুধু generic href/plain-text regex দিয়ে "প্রথম যে
                            # ৩০ ক্যারেক্টারের বেশি লম্বা লিংক পাওয়া যায়" সেটাই নেওয়া হতো —
                            # domain না মিলিয়ে। ফলে ইমেইলের অন্য লিংক (logo, help center,
                            # ইত্যাদি) ভুলবশত বেছে নেওয়া হতো এবং আসল clicks.textnow.com
                            # verify লিংক কখনো ধরাই পড়ত না। এখন আগে *.textnow.com domain
                            # বিশেষভাবে খোঁজা হয় (scheme/www থাকুক বা না থাকুক)।
                            textnow_matches = _TEXTNOW_LINK_RE.findall(body)
                            textnow_link = None
                            for cand in textnow_matches:
                                cand = cand.strip().rstrip('.,)"\'>&;')
                                if any(sk in cand.lower() for sk in SKIP_KEYWORDS):
                                    continue
                                if _is_textnow_link(cand):
                                    textnow_link = _normalize_textnow_url(cand)
                                    break

                            if textnow_link:
                                # FIX: clicks.textnow.com লিংকে GET রিকোয়েস্ট পাঠিয়ে
                                # (allow_redirects=True) verification server-side trigger করা
                                # হচ্ছে — কিন্তু ইউজারকে/বাটনে সবসময় **সম্পূর্ণ original
                                # clicks.textnow.com লিংকটাই** দেখানো হয়, redirect-এর পর
                                # পাওয়া (অনেক সময় অনেক ছোট) destination URL নয়। আগে ভুলবশত
                                # সেই ছোট resolved URL বাটনে বসানো হচ্ছিল — এখন ফিক্স করা হলো।
                                _final_url, _status, err = _resolve_textnow_final_url(textnow_link)
                                if err:
                                    logging.warning(f"TN verify: GET/verify request failed ({err}), link still shown as-is")
                                found_link        = textnow_link   # FIX: সম্পূর্ণ original link, resolved/shortened URL না
                                found_subject     = subject
                                found_sender_name = s_name
                            else:
                                # FIX: fallback — body তে সরাসরি textnow.com ডোমেইন না পেলে,
                                # আগের generic href/plain-text regex দিয়ে খোঁজা হয় (compatibility
                                # বজায় রাখতে, অন্য কোনো mail format ভেঙে না যায় সেজন্য)
                                links = re.findall(r'href=["\']?(https?://[^"\'>\s]+)', body)
                                if not links:
                                    links = re.findall(r'https?://\S+', body)

                                for lnk in links:
                                    lnk = lnk.rstrip('.,)"\'>&;')
                                    # image/tracker link বাদ দাও
                                    if any(sk in lnk.lower() for sk in SKIP_KEYWORDS):
                                        continue
                                    if len(lnk) > 30:
                                        found_link        = lnk
                                        found_subject     = subject
                                        found_sender_name = s_name
                                        break

                        # 🔑 OTP খোঁজা — যে মেইলে link আছে সেটাতে নাও থাকতে পারে,
                        # তাই এটা link এর for-loop থেকে সম্পূর্ণ আলাদা করে চেক করা হচ্ছে
                        if not found_otp:
                            body_no_links = re.sub(r'https?://\S+', ' ', body)
                            search_text = f"{subject} {body_no_links}"
                            otp_match = re.search(
                                r'(?:verification\s*code|otp|pin\s*code|code\s*is|code)\D{0,10}(\d{4,8})\b',
                                search_text, re.IGNORECASE
                            )
                            if otp_match:
                                found_otp = otp_match.group(1)

                        if found_link and found_otp:
                            break

            if found_link:
                break

        except Exception as e:
            logging.warning(f"TN verify fetch error: {e}")

        _time.sleep(5)
        elapsed += 5

    try:
        bot.delete_message(user_id, wait_msg.message_id)
    except:
        pass

    if found_link:
        # Type = sender name (যেমন: Facebook, Instagram, Claude)
        type_line = "🏷️ <b>Type :</b> TextNow\n"
        otp_line  = f"🔑 <b>OTP :</b> <code>{found_otp}</code>\n" if found_otp else ""

        markup = types.InlineKeyboardMarkup()
        markup.add(InlineBtn("textnow verify link 🖇️", url=found_link))

        bot.send_message(
            user_id,
            f"✅ <b>Link Found!</b>\n\n"
            f"📧 <b>Email :</b> <code>{email}</code>\n"
            f"{type_line}"
            f"{otp_line}",
            parse_mode="HTML",
            reply_markup=markup
        )
        # নিচে main menu keyboard আলাদাভাবে পাঠানো — inline বাটনের সাথে
        # reply keyboard একসাথে একই মেসেজে দেওয়া যায় না
        bot.send_message(
            user_id,
            t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id),
            parse_mode="HTML"
        )
    else:
        bot.send_message(
            user_id,
            f"❌ <b>Link পাওয়া যায়নি!</b>\n\n"
            f"📧 <b>Email:</b> <code>{email}</code>\n\n"
            f"⏱ 30 সেকেন্ডে inbox এ কোনো link আসেনি।\n"
            f"একটু পরে আবার চেষ্টা করুন।",
            parse_mode="HTML",
            reply_markup=get_main_menu(user_id)
        )


