@bot.message_handler(commands=['kbcolor_debug'])
def cmd_kbcolor_debug(message):
    """Admin only — একটা role এর KeyboardButton আসলে কী JSON তৈরি করছে
    সেটা raw দেখায়। এটা দিয়ে বোঝা যাবে 'style' ফিল্ড সত্যিই payload এ
    যাচ্ছে কিনা, নাকি সমস্যাটা library/Telegram app version এর।"""
    if not is_admin(message.chat.id):
        return
    parts = message.text.strip().split(maxsplit=1)
    role = parts[1].strip() if len(parts) > 1 else "code"
    if role not in KB_BUTTON_ROLES:
        bot.send_message(message.chat.id,
            f"❌ Unknown role: <code>{role}</code>\n\nValid roles:\n" +
            ", ".join(f"<code>{r}</code>" for r in KB_BUTTON_ROLES),
            parse_mode="HTML")
        return
    label = KB_BUTTON_ROLES[role][0]
    current_color = get_kb_button_color(role)
    btn = KbBtn(label, role=role)
    try:
        raw_json = btn.to_json()
    except Exception as e:
        raw_json = f"to_json() failed: {e}"
    bot.send_message(message.chat.id,
        f"🔎 <b>KB Button Debug — {role}</b>\n\n"
        f"Current color setting: <code>{current_color}</code>\n\n"
        f"Actual JSON sent to Telegram:\n<code>{raw_json}</code>\n\n"
        f"যদি JSON এ <code>\"style\"</code> key দেখা যায়, তার মানে code ঠিক আছে "
        f"— তাহলে সমস্যা pyTelegramBotAPI ভার্সন বা Telegram app ভার্সনে। "
        f"<code>\"style\"</code> key না থাকলে সেটা code-লেভেল বাগ।",
        parse_mode="HTML")

@bot.message_handler(commands=['otpdebug'])
def cmd_otpdebug(message):
    """Admin only — সর্বশেষ কেনা মেইলের জন্য inbox-read ও get-inbox এর raw ফলাফল দেখায়
    (কয়টা মেসেজ, subject, code, error)। Get OTP কাজ না করলে কারণ খুঁজতে।"""
    if not is_admin(message.chat.id):
        return
    uid = str(message.chat.id)
    info = _get_last_account(uid)
    if not info or not info.get("full_data"):
        bot.send_message(uid, "⚠️ আগে Single Buy দিয়ে একটা মেইল কিনুন।")
        return
    fd = info["full_data"]
    def _brief(msgs):
        rows = []
        for m in (msgs or [])[:5]:
            rows.append(f"• {_hx(str(m.get('from') or '')[:20])} | {_hx(str(m.get('subject') or '')[:45])} | code={_hx(m.get('code') or '-')} | {_hx(m.get('date') or '')}")
        return "\n".join(rows) or "(কোনো মেসেজ নেই)"
    out = [f"📧 <code>{_hx(fd.split('|')[0])}</code> (parts={fd.count('|') + 1})"]
    dvm, dve = _dongvan_get_messages(fd)
    out.append(f"0️⃣ <b>dongvanfb</b> err={_hx(dve)}\ncount={len(dvm)}\n{_brief(dvm)}")
    d, e = mailgen_inbox_read(fd)
    out.append(f"1️⃣ <b>inbox-read</b> err={_hx(e)}\ntotal={(d or {}).get('totalMessages')}\n{_brief((d or {}).get('messages'))}")
    for mode in ("oauth", "graph"):
        ms, e2 = _mailgen_get_inbox_try(fd, mode)
        out.append(f"2️⃣ <b>get-inbox [{mode}]</b> err={_hx(e2)}\ncount={len(ms)}\n{_brief(ms)}")
    allm = (((d or {}).get('messages')) or [])
    found = _otp_scan_messages(dvm) or _otp_scan_messages(allm) or _otp_scan_messages(mailgen_get_inbox_full(fd))
    out.append("🔎 Parser: " + (f"code=<code>{_hx(found[1])}</code> links={len(found[2])}" if found else "কিছু পায়নি"))
    bot.send_message(uid, "\n\n".join(out)[:4000], parse_mode="HTML")

@bot.message_handler(commands=['apidiag'])
def cmd_apidiag(message):
    """Admin only — hotmail143 / bulkmail / codecraft + সাধারণ ইন্টারনেট একসাথে টেস্ট করে
    কারণ (key, DNS, HTTP status, raw response) দেখায়।"""
    if not is_admin(message.chat.id):
        return
    import socket as _sock
    def _mask(k):
        return "❌ খালি / সেট নেই" if not k else (f"<code>{k[:4]}…{k[-3:]}</code> (len {len(k)})" if len(k) > 10 else f"<code>len {len(k)}</code>")
    def _probe(url, params=None, headers=None):
        host = url.split("/")[2]
        try:
            ip = _sock.gethostbyname(host)
        except Exception as e:
            return f"❌ DNS fail ({host}): {type(e).__name__}"
        try:
            r = http_requests.get(url, params=params, headers=headers, timeout=10)
            body = r.text[:220].replace("<", "&lt;").replace(">", "&gt;")
            return f"🌐 {host} → {ip}\nHTTP <b>{r.status_code}</b>\n<code>{body}</code>"
        except Exception as e:
            return f"❌ {host} → {ip}\n{type(e).__name__}: {str(e)[:160]}"
    bot.send_message(message.chat.id, "🔄 <b>API Diagnostic চলছে...</b>", parse_mode="HTML")
    out = []
    out.append("1️⃣ <b>Internet</b>\n" + _probe("https://api.telegram.org"))
    out.append(f"2️⃣ <b>hotmail143</b> key: {_mask(HOTMAIL143_API_KEY)}\n" +
               _probe(f"{HOTMAIL143_BASE_URL}/stock", params={"api_key": HOTMAIL143_API_KEY}))
    _bm_ids = [c.get("product_id") for c in API_PRODUCTS.values() if c.get("source") == "bulkmail"]
    _bm_id = _bm_ids[0] if _bm_ids else 13
    out.append(f"3️⃣ <b>bulkmail</b> key: {_mask(BULKMAIL_API_KEY)}\n" +
               _probe(f"{BULKMAIL_BASE_URL}/stock/check", params={"ids": str(_bm_id)},
                      headers={"Accept": "application/json", "X-API-Key": BULKMAIL_API_KEY}))
    out.append(f"4️⃣ <b>codecraft</b> key: {_mask(CODECRAFT_API_KEY)}\n" +
               _probe(f"{CODECRAFT_BASE_URL}/product.php",
                      params={"api_key": CODECRAFT_API_KEY, "product": EDU_MAIL_1490_ITEM8_PRODUCT_ID}))
    errs = "\n".join(f"• {k}: {v}" for k, v in _API_LAST_ERR.items()) or "নেই"
    out.append(f"📝 <b>Bot এর সর্বশেষ error</b>\n{errs}")
    bot.send_message(message.chat.id, "\n\n".join(out)[:4000], parse_mode="HTML")

@bot.message_handler(commands=['apitest'])
def cmd_apitest(message):
    """Admin only — hotmail143 API raw test."""
    if not is_admin(message.chat.id):
        return
    handle_apitest_command(message)

@bot.message_handler(commands=['channelcheck'])
def cmd_channelcheck(message):
    """🆕 Admin only — Force-join এর জন্য কনফিগার করা CHANNELS গুলো আসলেই কাজ
    করছে কিনা টেস্ট করে। is_subscribed() এর ভেতরে API error হলে fail-open
    (subscribed ধরে নেওয়া) করা হয়, তাই ভুল Channel ID বা bot channel এ Admin
    না থাকলে — force-join চুপচাপ পুরোপুরি bypass হয়ে যায়, কোনো error দেখায় না।
    এই কমান্ড সেই আসল কারণটা খুঁজে বের করতে সাহায্য করে।"""
    chat_id = message.chat.id
    if not is_admin(chat_id):
        return

    lines = ["🔍 <b>Force-Join Channel Diagnostic</b>"]
    try:
        bot_id = bot.get_me().id
    except Exception as e:
        bot_id = None
        lines.append(f"⚠️ bot.get_me() failed: <code>{e}</code>")

    for i, ch in enumerate(CHANNELS, 1):
        lines.append(f"\n<b>Channel {i}</b> — <code>{ch['id']}</code>\nLink: {ch['link']}")

        # ১) এই ID দিয়ে chat resolve হয় কিনা
        try:
            chat_obj = bot.get_chat(ch["id"])
            lines.append(f"✅ get_chat OK — title: {getattr(chat_obj, 'title', '?')}, "
                          f"type: {getattr(chat_obj, 'type', '?')}")
        except Exception as e:
            lines.append(f"❌ get_chat FAILED — <code>{e}</code>")
            lines.append("👉 এই Channel ID ভুল/ভাঙা মনে হচ্ছে, অথবা bot এই chat এ "
                          "একেবারেই access পায়নি। CHANNELS লিস্টে ID টা ঠিক করুন।")
            continue  # bot নিজেই chat access না পেলে বাকি চেকগুলো করে লাভ নেই

        # ২) বট নিজে এই চ্যানেলে Admin কিনা — force-join কাজ করার আবশ্যিক শর্ত
        if bot_id:
            try:
                bot_member = bot.get_chat_member(ch["id"], bot_id)
                lines.append(f"বট নিজের status: <b>{bot_member.status}</b>")
                if bot_member.status not in ("administrator", "creator"):
                    lines.append("❌ বট এই চ্যানেলে Admin না! Force-join কাজ করার জন্য বট-কে "
                                  "অবশ্যই এই চ্যানেলে <b>Administrator</b> হিসেবে Add করতে হবে।")
            except Exception as e:
                lines.append(f"❌ get_chat_member(bot) FAILED — <code>{e}</code>")
                lines.append("👉 এই error-টাই সাধারণত force-join পুরোপুরি bypass হয়ে যাওয়ার "
                              "আসল কারণ — বট Admin না থাকলে বা ID ভুল হলে এই কল fail করে, আর "
                              "কোডে API error হলে (কাউকে ভুলভাবে block না করার জন্য) সবাইকে "
                              "'subscribed' ধরে নেওয়া হয়।")

        # ৩) আপনার (এই admin) নিজের status টেস্ট
        try:
            my_member = bot.get_chat_member(ch["id"], chat_id)
            lines.append(f"আপনার status এই চ্যানেলে: <b>{my_member.status}</b>")
        except Exception as e:
            lines.append(f"❌ get_chat_member(you) FAILED — <code>{e}</code>")

    lines.append("\n⚠️ যেকোনো চ্যানেলে ❌ দেখালে সেটা ঠিক না করা পর্যন্ত force-join "
                  "সব ইউজারের জন্য চুপচাপ bypass হয়ে থাকবে।")
    bot.send_message(chat_id, "\n".join(lines), parse_mode="HTML")

@bot.message_handler(commands=['2fa_key'])
def handle_2fa_command(message):
    user_id = str(message.chat.id)

    parts = message.text.strip().split(maxsplit=1)
    if len(parts) < 2 or not parts[1].strip():
        start_2fa_key_flow(user_id)
        return

    secret_key = parts[1].strip()
    # ⏳ ছোট্ট লোডিং মুহূর্ত — তারপর কোড কার্ড দেখাবে
    loading_msg = bot.send_message(user_id, "⏳ <b>Loading...</b>", parse_mode="HTML")
    try:
        import time as _2fa_cmd_time
        _2fa_cmd_time.sleep(0.9)
    except Exception:
        pass
    generate_and_send_2fa(user_id, secret_key,
        edit_chat_id=loading_msg.chat.id, edit_message_id=loading_msg.message_id)

def start_2fa_key_flow(user_id):
    """/2fa_key কমান্ড আর্গুমেন্ট ছাড়া দিলে যা হয় — ছোট্ট লোডিং দেখিয়ে (ইউজারের
    আকর্ষণের জন্য) তারপর স্টাইলিশ হেডিং সহ Secret Key চেয়ে next-step handler
    বসিয়ে দেয়। "🔐 2FA Code" মেনু বাটন ও এই একই ফাংশন ব্যবহার করে, যাতে বাটন
    আর কমান্ড দুটোই হুবহু একইভাবে কাজ করে।"""
    loading_msg = bot.send_message(user_id, "⏳ <b>Loading...</b>", parse_mode="HTML")
    try:
        import time as _2fa_start_time
        _2fa_start_time.sleep(0.8)
    except Exception:
        pass
    prompt = (
        "🔐 𝟮𝗙𝗔 𝗖𝗢𝗗𝗘 𝗚𝗘𝗡𝗘𝗥𝗔𝗧𝗢𝗥 🥳\n\n"
        "🔑 আপনার <b>Secret Key</b> দিন:\n\n"
        "✏️ উদাহরণ:\n"
        "<code>JBSWY3DPEHPK3PXP</code>\n\n"
        "⚠️ Secret key Base32 format এ হয়।"
    )
    try:
        bot.edit_message_text(prompt, chat_id=loading_msg.chat.id,
            message_id=loading_msg.message_id, parse_mode="HTML")
        msg = loading_msg
    except Exception:
        msg = bot.send_message(user_id, prompt, parse_mode="HTML")
    bot.register_next_step_handler(msg, process_2fa_key_input)

def process_2fa_key_input(message):
    user_id = str(message.chat.id)
    lang = get_user_lang(user_id)
    L = LANG[lang]

    if message.text in (L["cancel"], L.get("back", ""), "❌ Cancel"):
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML")
        return

    # ⚡ 2FA key এর অপেক্ষায় থাকা অবস্থায় অন্য কোনো menu বাটনে ক্লিক করলে
    # সেই বাটনের কাজ করবে, "key খালি" error দেখাবে না
    if _is_menu_navigation_text(user_id, message.text):
        _text_message_worker(message)
        return

    secret_key = (message.text or "").strip()
    if not secret_key:
        msg = bot.send_message(user_id,
            "❌ <b>Key খালি!</b>\n\nআবার দিন:",
            parse_mode="HTML")
        bot.register_next_step_handler(msg, process_2fa_key_input)
        return

    # ⏳ ছোট্ট লোডিং মুহূর্ত — তারপর একই মেসেজ এডিট হয়ে কোড কার্ড দেখাবে
    loading_msg = bot.send_message(user_id, "⏳ <b>Loading...</b>", parse_mode="HTML")
    try:
        import time as _2fa_key_load_time
        _2fa_key_load_time.sleep(0.9)
    except Exception:
        pass
    generate_and_send_2fa(user_id, secret_key,
        edit_chat_id=loading_msg.chat.id, edit_message_id=loading_msg.message_id)

# user_id → সর্বশেষ ব্যবহৃত secret key — শুধু "🔄 Refresh" বাটনের জন্য ইন-মেমরি
# রাখা হয় (DB তে save হয় না, bot restart হলে মুছে যাবে — এটাই safe behavior)।
_last_2fa_secret = {}

def _build_2fa_copy_button(code):
    """'Click to copy' বাটন — pyTelegramBotAPI নতুন ভার্সনে (Bot API 7.11+ সাপোর্ট
    করলে) নেটিভ copy_text বাটন ব্যবহার করে ট্যাপ করলেই clipboard এ কপি হয়ে যাবে।
    পুরনো ভার্সনে library টা copy_text চিনবে না, তখন callback_data দিয়ে popup এ
    code দেখানো fallback ব্যবহার হবে (manually select করে copy করা যাবে)।"""
    try:
        return InlineBtn(
            f"🔗 Click to copy {code}", style=_ik("inline_twofa_code"),
            copy_text=types.CopyTextButton(text=code)
        )
    except Exception:
        return InlineBtn(
            f"🔗 Click to copy {code}", style=_ik("inline_twofa_code"),
            callback_data=f"2fa_showcode_{code}")

def _build_2fa_markup(current_code):
    markup = types.InlineKeyboardMarkup(row_width=2)
    markup.add(_build_2fa_copy_button(current_code))
    markup.add(
        InlineBtn("📍 Refresh", style="primary", callback_data="2fa_refresh"),
        InlineBtn("👥 New Code", style="danger", callback_data="2fa_newcode"),
    )
    markup.add(InlineBtn("❌ Close", style="danger", callback_data="2fa_close"))
    return markup

def generate_and_send_2fa(user_id, secret_key, edit_chat_id=None, edit_message_id=None):
    """2FA (TOTP) code জেনারেট করে card-style UI তে পাঠায় — Click to copy /
    Refresh / New Code / Close বাটন সহ। edit_message_id দেওয়া থাকলে নতুন
    message না পাঠিয়ে পুরনো card-টাই in-place আপডেট করে (Refresh বাটনের জন্য)।"""
    import hmac, hashlib, struct, base64, time as t_lib

    try:
        clean_key = secret_key.strip().upper().replace(" ", "").replace("-", "")
        padding = len(clean_key) % 8
        if padding:
            clean_key += "=" * (8 - padding)

        try:
            key_bytes = base64.b32decode(clean_key, casefold=True)
        except Exception:
            _err_text = (
                "❌ <b>Invalid Secret Key!</b>\n\n"
                "Base32 format এ দিন।\n"
                "উদাহরণ: <code>JBSWY3DPEHPK3PXP</code>"
            )
            if edit_chat_id and edit_message_id:
                try:
                    bot.edit_message_text(_err_text, edit_chat_id, edit_message_id, parse_mode="HTML")
                    return
                except Exception:
                    pass
            bot.send_message(user_id, _err_text, parse_mode="HTML")
            return

        current_time   = int(t_lib.time())
        time_step      = 30
        counter        = current_time // time_step
        secs_remaining = time_step - (current_time % time_step)

        def get_totp(cnt):
            cb = struct.pack(">Q", cnt)
            hr = hmac.new(key_bytes, cb, hashlib.sha1).digest()
            off = hr[-1] & 0x0F
            tr  = struct.unpack(">I", hr[off:off+4])[0] & 0x7FFFFFFF
            return str(tr % 1_000_000).zfill(6)

        current_code = get_totp(counter)
        _last_2fa_secret[str(user_id)] = secret_key

        text = (
            "――――――――――――――――\n"
            "« ⚙️ <b>2FA CODE</b> »\n"
            "――――――――――――――――\n"
            f"⚙️ <b>CODE:</b> <code>{current_code}</code>\n"
            "――――――――――――――――\n"
            f"⏳ <b>EXPIRES IN:</b> {secs_remaining}s"
        )
        markup = _build_2fa_markup(current_code)

        if edit_chat_id and edit_message_id:
            try:
                bot.edit_message_text(text, edit_chat_id, edit_message_id,
                    parse_mode="HTML", reply_markup=markup)
                return
            except Exception:
                pass  # message edit fail করলে (delete/unchanged) নিচে নতুন করে পাঠাবে

        bot.send_message(user_id, text, parse_mode="HTML", reply_markup=markup)

    except Exception as e:
        logging.error(f"2FA error: {e}")
        _crash_text = (
            "❌ <b>Code generate করা যায়নি!</b>\n\n"
            "সঠিক Base32 Secret Key দিন।"
        )
        if edit_chat_id and edit_message_id:
            try:
                bot.edit_message_text(_crash_text, edit_chat_id, edit_message_id, parse_mode="HTML")
                return
            except Exception:
                pass
        bot.send_message(user_id, _crash_text, parse_mode="HTML")



# ═══════════════════════════════════════════════════════════
# 📧 FEATURE 9: EDU READER — MailGen (mailgen.shop) Edu Mail Inbox Reader
# ═══════════════════════════════════════════════════════════
# "More Option" মেনুর ভিতরে "📧 Edu Reader" বাটন। ক্লিক করলে ইউজারকে
# ইংরেজিতে বলা হয় Edu mail (EmailFake) অ্যাড্রেসটা পাঠাতে (password লাগে
# না)। ইউজার ইমেইল পাঠালে mailgen.shop এর POST /api/edu-mail এন্ডপয়েন্টে
# কল করে ইনবক্স read করা হয় — কোনো OTP/SMS পাওয়া গেলে সুন্দর UI card
# আকারে দেখানো হয়, ইনবক্স খালি হলে "Not Found" দেখানো হয়।

def mailgen_read_edu_inbox(email):
    """MailGen (mailgen.shop) API দিয়ে একটা Edu Mail (EmailFake) অ্যাকাউন্টের
    ইনবক্স read করে। রিটার্ন করে (data_dict, error_message)।"""
    try:
        headers = {"Content-Type": "application/json"}
        if MAILGEN_API_KEY:
            headers["X-API-Key"] = MAILGEN_API_KEY

        resp = http_requests.post(
            f"{MAILGEN_BASE_URL}/api/edu-mail",
            json={"email": email},
            headers=headers,
            timeout=20
        )

        try:
            data = resp.json()
        except Exception:
            logging.warning(
                f"mailgen_read_edu_inbox non-JSON response: "
                f"status={resp.status_code} body={resp.text[:300]}"
            )
            return None, "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"

        if not resp.ok:
            return None, data.get("error") or f"API error (status {resp.status_code})"

        if data.get("error"):
            return None, str(data.get("error"))

        return data, None
    except http_requests.exceptions.Timeout:
        return None, "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"mailgen_read_edu_inbox error: {e}")
        return None, str(e)


def start_edu_reader_flow(user_id):
    """/edu_read কমান্ড দিলে ইউজারকে Edu mail অ্যাড্রেস
    পাঠাতে বলা হয় (ইংরেজিতে, যেমনটা চাওয়া হয়েছে)।"""
    msg = bot.send_message(user_id,
        "📧 <b>Edu Mail Reader</b>\n\n"
        "Please send me the Edu Mail address 📩\n"
        "<i>(No password required)</i>\n\n"
        "✏️ Example:\n<code>user@emailfake.com</code>",
        parse_mode="HTML")
    bot.register_next_step_handler(msg, process_edu_reader_input)


def process_edu_reader_input(message):
    user_id = str(message.chat.id)
    lang = get_user_lang(user_id)
    L = LANG[lang]
    text = (message.text or "").strip()

    if text in (L["cancel"], L.get("back", ""), "❌ Cancel"):
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML")
        return

    # ⚡ Email এর অপেক্ষায় থাকা অবস্থায় অন্য কোনো menu বাটনে ক্লিক করলে
    # সেই বাটনের কাজ করবে, ভুল ইমেইল error দেখাবে না
    if _is_menu_navigation_text(user_id, text):
        _text_message_worker(message)
        return

    email = text
    if "@" not in email or "." not in email.split("@")[-1] or " " in email:
        msg = bot.send_message(user_id,
            "❌ <b>Invalid email address!</b>\n\n"
            "Please send a valid Edu Mail address.\n"
            "✏️ Example: <code>user@emailfake.com</code>",
            parse_mode="HTML")
        bot.register_next_step_handler(msg, process_edu_reader_input)
        return

    wait_msg = bot.send_message(user_id,
        "⏳ <b>Checking inbox...</b>\n<i>Please wait a moment.</i>",
        parse_mode="HTML")

    data, err = mailgen_read_edu_inbox(email)

    try:
        bot.delete_message(user_id, wait_msg.message_id)
    except Exception:
        pass

    if err:
        bot.send_message(user_id,
            f"❌ <b>Failed to check inbox!</b>\n\n"
            f"📧 <code>{email}</code>\n"
            f"<i>Please try again later.</i>",
            parse_mode="HTML", reply_markup=get_other_menu(user_id))
        try:
            if not is_admin(user_id):
                bot.send_message(ADMIN_ID, f"🔍 <b>Edu Inbox Error</b>\n👤 <code>{user_id}</code>\n📧 <code>{email}</code>\n<i>{_hx(str(err)[:200])}</i>", parse_mode="HTML")
        except Exception:
            pass
        return

    messages = (data or {}).get("messages") or []

    if not messages:
        bot.send_message(user_id,
            "📭 <b>Edu Mail Reader</b>\n"
            "━━━━━━━━━━━━━━━━━━━━\n"
            f"📧 <b>Email:</b> <code>{email}</code>\n\n"
            "🔍 <b>Not Found</b>\n"
            "<i>No messages in the inbox yet. Try again in a few seconds.</i>",
            parse_mode="HTML", reply_markup=get_other_menu(user_id))
        return

    # সবচেয়ে নতুন মেসেজ বের করার জন্য date দিয়ে sort
    try:
        messages_sorted = sorted(messages, key=lambda m: m.get("date", ""), reverse=True)
    except Exception:
        messages_sorted = messages

    latest = messages_sorted[0]
    sender  = latest.get("from", "Unknown") or "Unknown"
    subject = latest.get("subject", "(No subject)") or "(No subject)"
    date    = latest.get("date", "")
    code    = latest.get("code")

    reply = (
        "📬 <b>Edu Mail Inbox</b>\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"📧 <b>Email:</b> <code>{email}</code>\n"
        "━━━━━━━━━━━━━━━━━━━━\n\n"
        f"✉️ <b>Latest Message</b>\n"
        f"👤 <b>From:</b> {sender}\n"
        f"📝 <b>Subject:</b> {subject}\n"
    )
    if date:
        reply += f"🕒 <b>Time:</b> <code>{date}</code>\n"
    if code:
        reply += f"🔐 <b>OTP Code:</b> <code>{code}</code>\n"

    bot.send_message(user_id, reply.strip(), parse_mode="HTML",
        reply_markup=get_other_menu(user_id))


