def _nineproxy_format_bytes(n):
    """বাইটকে মানুষের সহজে পড়ার মতো MB/GB টেক্সটে কনভার্ট করে।"""
    try:
        n = float(n or 0)
    except Exception:
        n = 0.0
    if n <= 0:
        return "0 MB"
    gb = n / (1000 ** 3)
    if gb >= 1:
        return f"{gb:.2f} GB"
    return f"{n / (1000 ** 2):.2f} MB"


def _nineproxy_progress_bar(used, cap, length=10):
    """একটা সহজ visual প্রোগ্রেস বার তৈরি করে (কতটুকু ব্যবহার হয়ে গেছে)।"""
    try:
        used = float(used or 0)
        cap = float(cap or 0)
        if cap <= 0:
            return "▰" * length + " <i>(Unlimited)</i>"
        pct = max(0.0, min(1.0, used / cap))
    except Exception:
        pct = 0.0
    filled = int(round(pct * length))
    bar = "▰" * filled + "▱" * (length - filled)
    return f"<code>{bar}</code> {pct * 100:.1f}%"


# ✅ ইউজার Proxy Checker-এ যেভাবেই টেক্সট পাঠাক না কেন (শুধু username, নাকি
# পুরো connection username যেমন "relax_sFVW-country-US-ssid-199RVPxqi6",
# নাকি host:port:username:password ফরম্যাটে সম্পূর্ণ ডিটেইল) — বট নিজে
# বুদ্ধি করে তার ভেতর থেকে আসল 9Proxy account username (base_username) খুঁজে
# বের করবে, ইউজারকে কোন অংশটা পাঠাতে হবে তা নিয়ে ভাবতে হবে না।
_NINEPROXY_SUFFIX_RE = re.compile(r"-(?:country|ssid|city|sst|session)-.*$", re.IGNORECASE)


def nineproxy_extract_base_username(raw_text):
    """যেকোনো ফরম্যাটে পাঠানো টেক্সট থেকে আসল 9Proxy sub-account username বের করে আনে:
    - সরাসরি username হলে সেটাই ফেরত দেয় (যেমন: relax_sfvw)
    - delivery/connection username হলে (base-country-US-ssid-XXXX বা base-ssid-XXXX
      ইত্যাদি, suffix যেকোনো ক্রমে থাকলেও) শুধু base অংশটা রাখে
    - host:port:username:password (বা username:password) ফরম্যাটে সম্পূর্ণ ডিটেইল
      পাঠালে সেখান থেকেও username ফিল্ডটা নিজে খুঁজে বের করে।"""
    t = (raw_text or "").strip()
    if not t:
        return ""

    if ":" in t:
        parts = [p.strip() for p in t.split(":") if p.strip()]
        # যেই অংশে -country-/-ssid- suffix আছে সেটাই username, নাহলে
        # host:port:user:pass হলে ৩য় অংশ, user:pass হলে ১ম অংশ ধরে নাও
        suffixed = [p for p in parts if "-country-" in p.lower() or "-ssid-" in p.lower()]
        if suffixed:
            t = suffixed[0]
        elif len(parts) >= 3:
            t = parts[2]
        elif parts:
            t = parts[0]

    t = _NINEPROXY_SUFFIX_RE.sub("", t)
    return t.strip()


def nineproxy_find_subuser(base_username):
    """9Proxy Public API (GET /client/v1/user-passes/get-list) দিয়ে username
    দিয়ে sub-user খুঁজে বের করে। রিটার্ন করে (item_dict, error_message)।
    item না পাওয়া গেলে error_message == "not_found"।"""
    if not NINEPROXY_API_KEY:
        return None, "⚠️ 9Proxy API key এখনো এডমিন সেট করেননি। এডমিনের সাথে যোগাযোগ করুন।"
    try:
        resp = http_requests.get(
            f"{NINEPROXY_BASE_URL}/client/v1/user-passes/get-list",
            params={
                "api-key": NINEPROXY_API_KEY,
                "keyword": base_username,
                "limit": 20,
            },
            timeout=20
        )
        try:
            data = resp.json()
        except Exception:
            logging.warning(
                f"nineproxy_find_subuser non-JSON response: "
                f"status={resp.status_code} body={resp.text[:300]}"
            )
            return None, "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"

        if not resp.ok:
            return None, data.get("message") or f"API error (status {resp.status_code})"

        if data.get("success") is False:
            return None, data.get("message") or "9Proxy API request failed."

        items = ((data.get("result") or {}).get("items")) or []
        if not items:
            return None, "not_found"

        # সবার আগে exact username match খুঁজো, না পেলে প্রথম keyword-match নাও
        needle = base_username.strip().lower()
        for it in items:
            if str(it.get("user_name", "")).strip().lower() == needle:
                return it, None
        return items[0], None
    except http_requests.exceptions.Timeout:
        return None, "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"nineproxy_find_subuser error: {e}")
        return None, str(e)


def process_proxychk_9proxy_input(message):
    user_id = str(message.chat.id)
    lang = get_user_lang(user_id)
    L = LANG[lang]
    text = (message.text or "").strip()

    if text in (L["cancel"], L.get("back", ""), "❌ Cancel"):
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML")
        return

    # ⚡ Username এর অপেক্ষায় থাকা অবস্থায় অন্য কোনো menu বাটনে ক্লিক করলে
    # সেই বাটনের কাজ করবে, ভুল username error দেখাবে না
    if _is_menu_navigation_text(user_id, text):
        _text_message_worker(message)
        return

    # ইউজার শুধু username, বা পুরো connection username (base-country-US-ssid-XXXX),
    # বা host:port:username:password ফরম্যাটে সম্পূর্ণ ডিটেইল — যেভাবেই পাঠাক না
    # কেন, বট নিজেই তার ভেতর থেকে আসল sub-user username বের করে নেয়।
    base_username = nineproxy_extract_base_username(text)
    if not base_username or " " in base_username:
        msg = bot.send_message(user_id,
            "❌ <b>Invalid username!</b>\n\n"
            "Please send a valid 9Proxy username.\n"
            "✏️ Example: <code>virtualshop3_nyzG</code>",
            parse_mode="HTML")
        bot.register_next_step_handler(msg, process_proxychk_9proxy_input)
        return

    wait_msg = bot.send_message(user_id,
        "⏳ <b>Checking your 9Proxy usage...</b>\n<i>Please wait a moment.</i>",
        parse_mode="HTML")

    item, err = nineproxy_find_subuser(base_username)

    try:
        bot.delete_message(user_id, wait_msg.message_id)
    except Exception:
        pass

    if err == "not_found":
        bot.send_message(user_id,
            "🔍 <b>9Proxy — Usage Checker</b>\n"
            "━━━━━━━━━━━━━━━━━━━━\n"
            f"👤 <b>Username:</b> <code>{base_username}</code>\n\n"
            "❌ <b>Not Found</b>\n"
            "<i>No account found with this username. Please double-check and try again.</i>",
            parse_mode="HTML", reply_markup=get_other_menu(user_id))
        return

    if err:
        bot.send_message(user_id,
            "❌ <b>Failed to check usage!</b>\n\n<i>Please try again later.</i>",
            parse_mode="HTML", reply_markup=get_other_menu(user_id))
        try:
            if not is_admin(user_id):
                bot.send_message(ADMIN_ID, f"🔍 <b>9Proxy Usage Check Error</b>\n👤 <code>{user_id}</code>\n<i>{_hx(str(err)[:200])}</i>", parse_mode="HTML")
        except Exception:
            pass
        return

    used   = item.get("data_used", 0) or 0
    cap    = item.get("usage_cap", 0) or 0
    ip_used = item.get("ip_used", 0) or 0
    ip_cap  = item.get("ip_usage_cap", 0) or 0
    status_map = {1: "🟢 Active", 2: "🔴 Disabled", 3: "🚫 Blocked"}
    status_txt = status_map.get(item.get("status"), "❔ Unknown")

    sub_limit_txt = _nineproxy_format_bytes(cap) if cap and cap > 0 else "Unlimited"
    remaining = (cap - used) if (cap and cap > 0) else None

    reply = (
        "🔍 <b>9Proxy — Usage Checker</b>\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"👤 <b>Username:</b> <code>{item.get('user_name', base_username)}</code>\n"
        f"📶 <b>Status:</b> {status_txt}\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"🎯 <b>Sub Limit:</b> <code>{sub_limit_txt}</code>\n"
        f"📊 <b>Used:</b> <code>{_nineproxy_format_bytes(used)}</code>\n"
    )
    if remaining is not None:
        reply += f"🟢 <b>Remaining:</b> <code>{_nineproxy_format_bytes(max(0, remaining))}</code>\n"
    reply += f"{_nineproxy_progress_bar(used, cap)}\n"

    if ip_cap and ip_cap != -1:
        reply += f"\n🌐 <b>IP Used:</b> <code>{ip_used}/{ip_cap}</code>"
    elif ip_used:
        reply += f"\n🌐 <b>IP Used:</b> <code>{ip_used}</code>"

    bot.send_message(user_id, reply.strip(), parse_mode="HTML",
        reply_markup=get_other_menu(user_id))


