# 🦉 OWL PROXY — Balance Checker (OpenAPI, V2 SHA-256 signature)
# ═══════════════════════════════════════════════════════════
# Docs: https://www.owlproxy.com/owlproxy/doc/zh/server/OpenAPI.html
#       https://www.owlproxy.com/owlproxy/doc/zh/server/api-guide.html
# ইউজার নিজেই তার OWLPROXY_ACCESS_KEY ও OWLPROXY_SECRET_KEY বটে পাঠায়।
# 🔒 Key গুলো কোথাও সেভ/লগ করা হয় না — শুধু একবার API কলে ব্যবহার হয়ে
#    মেমরি থেকে চলে যায়, আর ইউজারের পাঠানো মেসেজ চ্যাট থেকে ডিলিট করা হয়।
# Endpoint: GET /owlproxy/api/openApi/vcDynamicGood/queryCurrentTrafficBalance
# Response data: useTraffic / remainingTraffic / accumulatedTraffic (সব MB)
OWLPROXY_BASE_URL   = "https://api.owlproxy.com"
OWLPROXY_BALANCE_PATH = "/owlproxy/api/openApi/vcDynamicGood/queryCurrentTrafficBalance"


def _owlproxy_sign_headers(access_key, secret_key, path, body_or_query=""):
    """signString = SK + X-Timestamp + path + bodyOrQuery → lowerHex(SHA-256)।"""
    import time as _owl_time
    ts = str(int(_owl_time.time()))
    sign = hashlib.sha256(
        (secret_key + ts + path + (body_or_query or "")).encode("utf-8")
    ).hexdigest()
    return {
        "X-Access-Key": access_key,
        "X-Timestamp": ts,
        "X-Sign": sign,
        "Content-Type": "application/json",
    }


def _owlproxy_format_mb(mb):
    """MB কে MB/GB টেক্সটে দেখায় (OwlProxy তে 1GB = 1000MB)।"""
    try:
        mb = float(mb or 0)
    except Exception:
        mb = 0.0
    if mb >= 1000:
        return f"{mb / 1000:.2f} GB ({mb:,.0f} MB)"
    return f"{mb:,.2f} MB"


def owlproxy_get_traffic_balance(access_key, secret_key):
    """রিটার্ন করে (data_dict, error_message)। সফল হলে error_message == None।"""
    try:
        resp = http_requests.get(
            OWLPROXY_BASE_URL + OWLPROXY_BALANCE_PATH,
            headers=_owlproxy_sign_headers(access_key, secret_key, OWLPROXY_BALANCE_PATH, ""),
            timeout=20
        )
        try:
            js = resp.json()
        except Exception:
            logging.warning(f"owlproxy balance non-JSON: status={resp.status_code}")
            return None, "Server থেকে সঠিক response আসেনি। পরে আবার চেষ্টা করুন।"
        if js.get("code") != 200:
            code = js.get("code")
            hint = {2019: "Invalid Secret Key (signature mismatch)",
                    2031: "Invalid Access Key",
                    2032: "Auth headers missing",
                    2033: "Timestamp expired"}.get(code)
            return None, f"Owl Proxy API error ({code}): {hint or js.get('msg') or 'unknown'}"
        data = js.get("data")
        if not isinstance(data, dict):
            return None, "Owl Proxy থেকে balance data পাওয়া যায়নি।"
        return data, None
    except http_requests.exceptions.Timeout:
        return None, "Request timeout হয়ে গেছে। পরে আবার চেষ্টা করুন।"
    except Exception as e:
        logging.error(f"owlproxy_get_traffic_balance error: {type(e).__name__}")
        return None, "Request failed. পরে আবার চেষ্টা করুন।"


def _owl_safe_delete(chat_id, message_id):
    try:
        bot.delete_message(chat_id, message_id)
    except Exception:
        pass


def process_proxychk_owl_access_key(message):
    user_id = str(message.chat.id)
    lang = get_user_lang(user_id)
    L = LANG[lang]
    text = (message.text or "").strip()

    if text in (L["cancel"], L.get("back", ""), "❌ Cancel"):
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML")
        return
    if _is_menu_navigation_text(user_id, text):
        _text_message_worker(message)
        return

    if not text or " " in text or len(text) > 200:
        msg = bot.send_message(user_id,
            "❌ <b>Invalid Access key!</b>\n\nSend your Access key:👇", parse_mode="HTML")
        bot.register_next_step_handler(msg, process_proxychk_owl_access_key)
        return

    _owl_safe_delete(message.chat.id, message.message_id)
    msg = bot.send_message(user_id, "Send your secret key:👇", parse_mode="HTML")
    bot.register_next_step_handler(msg, process_proxychk_owl_secret_key, text)


def process_proxychk_owl_secret_key(message, access_key):
    user_id = str(message.chat.id)
    lang = get_user_lang(user_id)
    L = LANG[lang]
    text = (message.text or "").strip()

    if text in (L["cancel"], L.get("back", ""), "❌ Cancel"):
        bot.send_message(user_id, t(user_id, "main_menu"),
            reply_markup=get_main_menu(user_id), parse_mode="HTML")
        return
    if _is_menu_navigation_text(user_id, text):
        _text_message_worker(message)
        return

    if not text or " " in text or len(text) > 200:
        msg = bot.send_message(user_id,
            "❌ <b>Invalid Secret key!</b>\n\nSend your secret key:👇", parse_mode="HTML")
        bot.register_next_step_handler(msg, process_proxychk_owl_secret_key, access_key)
        return

    secret_key = text
    _owl_safe_delete(message.chat.id, message.message_id)  # secret key চ্যাটে রেখে দেওয়া হয় না

    wait_msg = bot.send_message(user_id,
        "⏳ <b>Checking your Owl Proxy balance...</b>\n<i>Please wait a moment.</i>",
        parse_mode="HTML")

    data, err = owlproxy_get_traffic_balance(access_key, secret_key)
    secret_key = None  # মেমরি থেকে সরিয়ে দাও
    _owl_safe_delete(message.chat.id, wait_msg.message_id)

    markup = types.InlineKeyboardMarkup()
    markup.add(InlineBtn("🔄 Check Again", style="primary", callback_data="proxychk_owl"))

    if err:
        bot.send_message(user_id,
            "🦉 <b>Owl Proxy — Balance Checker</b>\n"
            "━━━━━━━━━━━━━━━━━━━━\n"
            "❌ <b>Failed to fetch balance!</b>\n<i>Please check the key and try again later.</i>",
            parse_mode="HTML", reply_markup=markup)
        try:
            if not is_admin(user_id):
                bot.send_message(ADMIN_ID, f"🔍 <b>Owl Balance Check Error</b>\n👤 <code>{user_id}</code>\n<i>{_hx(str(err)[:200])}</i>", parse_mode="HTML")
        except Exception:
            pass
        return

    used = data.get("useTraffic", 0) or 0
    remaining = data.get("remainingTraffic", 0) or 0
    total = data.get("accumulatedTraffic", 0) or 0
    bot.send_message(user_id,
        "🦉 <b>Owl Proxy — Balance Checker</b>\n"
        "━━━━━━━━━━━━━━━━━━━━\n"
        f"📦 <b>Total:</b> <code>{_owlproxy_format_mb(total)}</code>\n"
        f"📊 <b>Used:</b> <code>{_owlproxy_format_mb(used)}</code>\n"
        f"🟢 <b>Remaining:</b> <code>{_owlproxy_format_mb(remaining)}</code>\n"
        f"{_nineproxy_progress_bar(used, total)}",
        parse_mode="HTML", reply_markup=markup)


