# 🔵 BINANCE AUTO-APPROVE — SMS FORWARDER NOTIFICATION PATH
# ═══════════════════════════════════════════════════════════
# 🔒 Binance notification path আর user-submit path এর মধ্যে race আটকানোর জন্য একটা global lock।
# লক ক্রম সবসময়: _binance_match_lock → get_trx_lock(key) (deadlock এড়াতে)।
_binance_match_lock = threading.RLock()

def _binance_sms_dedup_key(username, amount, utc_time):
    """একই নোটিফিকেশন দুইবার (webhook retry) এলে যেন দুইবার প্রসেস না হয়,
    তার জন্য একটা deterministic key — verified_trxids রেজিস্ট্রির সাথে
    একই মেকানিজম ব্যবহার করা হয় dedup এর জন্য।

    ✅ BUG FIX: MySQL এর key/path এ '.', '#', '$', '[', ']', '/'
    ব্যবহার করা যায় না। আগে amount (যেমন 0.084) সরাসরি key তে বসানো হতো,
    যার ডট (.) থাকার কারণে MySQL path invalid হয়ে যেত এবং
    sms_pending_trxids এ write ব্যর্থ হতো। এখন সব illegal character
    আন্ডারস্কোরে (_) পরিবর্তন করে দেওয়া হচ্ছে।
    """
    raw = f"BNCAUTO-{username}-{amount}-{utc_time}".upper()
    raw = re.sub(r"\s+", "_", raw)
    raw = re.sub(r"[.#$\[\]/]", "_", raw)
    return raw

def _process_binance_auto_sms(sender, body):
    """
    Binance app এর "You have received a payment of X USDT from
    User-XXXX on ... (UTC)" পুশ নোটিফিকেশন (SMS Forwarder app দিয়ে
    /sms এ ফরওয়ার্ড করা) প্রসেস করে।

    ম্যাচিং যুক্তি:
      1) user deposit submit করার সময় USDT amount + (ঐচ্ছিক) masked
         username দিয়েছিল — সেটার সাথে নোটিফিকেশনের amount (± tolerance)
         এবং username (দিলে exact) মেলানো হয়।
      2) একাধিক pending request সমান ভাবে ম্যাচ করলে (ambiguous) —
         auto-approve করা হয় না, admin কে review করতে জানানো হয়।
         ভুল ইউজারের ব্যালেন্সে টাকা ঢুকে যাওয়া থেকে বাঁচানোই এখানে
         সবচেয়ে গুরুত্বপূর্ণ, তাই নিশ্চিত না হলে approve করা হয় না।
    """
    try:
        parsed = extract_binance_payment(body)
        if not parsed:
            logging.warning(f"BinanceAuto SMS parse failed | sender={sender!r} | body={body[:150]}")
            return

        usdt_amount = parsed["amount"]
        currency    = parsed["currency"]
        username    = parsed["username"]
        utc_time    = parsed["utc_time"]
        username_l  = username.strip().lower()

        # 🛡️ শুধু USDT পেমেন্ট auto-approve হবে (BTC/BNB ইত্যাদির amount USDT ধরে ক্রেডিট হওয়া আটকাতে)
        if currency != "USDT":
            logging.warning(f"BinanceAuto non-USDT payment ignored | {usdt_amount} {currency} from {username}")
            try:
                bot.send_message(ADMIN_ID,
                    f"⚠️ <b>Binance পেমেন্ট — USDT নয়, auto-approve হয়নি</b>\n\n"
                    f"💰 {usdt_amount} {currency}\n👤 From: <code>{username}</code>\n🕒 {utc_time} UTC",
                    parse_mode="HTML")
            except Exception:
                pass
            return

        dedup_key = _binance_sms_dedup_key(username_l, usdt_amount, utc_time)

        with _binance_match_lock, get_trx_lock(dedup_key):
            db = load_db()

            if is_trxid_already_used(db, dedup_key):
                logging.warning(f"BinanceAuto duplicate notification ignored | key={dedup_key}")
                return
            # একই notification আবার এলে (webhook retry / forwarder duplicate) — আগেই save করা আছে,
            # তাই আবার save/admin-notify করার দরকার নেই
            if dedup_key in db.get("sms_pending_trxids", {}):
                logging.info(f"BinanceAuto duplicate pending notification ignored | key={dedup_key}")
                return

            candidates = []
            for req_id, req in db.get("deposit_requests", {}).items():
                if req.get("status") != "pending":
                    continue
                if req.get("method") != "BinanceAuto":
                    continue
                req_usdt = float(req.get("usdt_amount", 0) or 0)
                if req_usdt <= 0:
                    continue
                diff_pct = abs(req_usdt - usdt_amount) / req_usdt * 100
                if diff_pct > BINANCE_SMS_AMOUNT_TOLERANCE_PCT:
                    continue
                req_username = (req.get("binance_username") or "").strip().lower()
                if req_username:
                    if req_username == username_l:
                        candidates.append((req_id, req, 0))  # 0 = exact username+amount match
                else:
                    candidates.append((req_id, req, 1))      # 1 = amount-only match (no username given)

            exact_matches = [c for c in candidates if c[2] == 0]
            amount_only_matches = [c for c in candidates if c[2] == 1]

            chosen = None
            if len(exact_matches) == 1:
                chosen = exact_matches[0]
            elif not exact_matches and len(amount_only_matches) == 1:
                chosen = amount_only_matches[0]

            if not chosen:
                # কোনো ম্যাচ নেই, অথবা একাধিক সম্ভাব্য ম্যাচ (ambiguous) —
                # notification সেভ রাখো, admin কে জানাও, auto-approve করো না
                db.setdefault("sms_pending_trxids", {})[dedup_key] = {
                    "method": "BinanceAuto", "amount": usdt_amount, "currency": currency,
                    "username": username, "sender": sender, "body": body[:300], "time": get_now()
                }
                update_db_path(f"/sms_pending_trxids/{dedup_key}", db["sms_pending_trxids"][dedup_key])
                _update_db_cache_in_place(db)

                total_candidates = len(candidates)
                try:
                    if total_candidates == 0:
                        bot.send_message(ADMIN_ID,
                            f"📥 <b>Binance পেমেন্ট নোটিফিকেশন এসেছে (কোনো pending ম্যাচ নেই)</b>\n\n"
                            f"💰 Amount: {usdt_amount} {currency}\n"
                            f"👤 From: <code>{username}</code>\n"
                            f"🕒 {utc_time} UTC\n\n"
                            f"⏳ <i>User পরে deposit submit করলে ম্যাচ হতে পারে।</i>",
                            parse_mode="HTML")
                    else:
                        bot.send_message(ADMIN_ID,
                            f"⚠️ <b>Binance পেমেন্ট — একাধিক সম্ভাব্য ম্যাচ, ম্যানুয়ালি চেক করুন</b>\n\n"
                            f"💰 Amount: {usdt_amount} {currency}\n"
                            f"👤 From: <code>{username}</code>\n"
                            f"🕒 {utc_time} UTC\n"
                            f"🔢 Candidates: {total_candidates}\n\n"
                            f"❗ <i>ভুল ইউজারকে ক্রেডিট এড়াতে auto-approve বন্ধ রাখা হয়েছে।</i>",
                            parse_mode="HTML")
                except Exception:
                    pass
                return

            # ✅ একমাত্র নিশ্চিত ম্যাচ পাওয়া গেছে — auto approve করো
            req_id, req, _priority = chosen
            bdt_amount = round(usdt_amount * get_usd_bdt_rate(db), 2)

            # 🔧 BUG FIX: আগে এখানে auto_approve_deposit() এর *আগেই* mark_trxid_used() হতো,
            # ফলে auto_approve_deposit() এর "already used" চেক True পেয়ে approve না করেই SKIP করত
            # (অথচ admin কে "Auto-Approved" মেসেজ যেত)। auto_approve_deposit() সফল হলে নিজেই mark করে।
            logging.info(
                f"BinanceAuto match found → AUTO APPROVE | req_id={req_id} | "
                f"USDT={usdt_amount} | BDT={bdt_amount} | username={username}"
            )
            auto_approve_deposit(req_id, req, dedup_key, bdt_amount)

            _chk = load_db().get("deposit_requests", {}).get(req_id, {})
            if _chk.get("status") != "approved":
                logging.error(f"BinanceAuto approve did NOT complete | req_id={req_id}")
                return

            try:
                bot.send_message(ADMIN_ID,
                    f"✅ <b>Binance Deposit Auto-Approved (Notification Match)!</b>\n\n"
                    f"🆔 Request: <code>{req_id}</code>\n"
                    f"💰 {usdt_amount} {currency} → {bdt_amount} BDT\n"
                    f"👤 From: <code>{username}</code>\n"
                    f"🕒 {utc_time} UTC",
                    parse_mode="HTML")
            except Exception:
                pass

    except Exception as e:
        logging.error(f"_process_binance_auto_sms CRASH | sender={sender!r} | err={e}", exc_info=True)
        try:
            bot.send_message(ADMIN_ID,
                f"🚨 <b>Binance Auto-SMS Handler Crash!</b>\n\n"
                f"📨 Sender: <code>{sender}</code>\n"
                f"📄 Body: <code>{body[:200]}</code>\n"
                f"❌ Error: <code>{str(e)[:300]}</code>",
                parse_mode="HTML")
        except Exception:
            pass


